(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[10] = {"grade":10,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 10, tập 1","c":[{"t":"Chương I. Mệnh đề và tập hợp","l":[{"t":"Bài 1. Mệnh đề","req":["Nhận biết mệnh đề, mệnh đề phủ định, mệnh đề kéo theo, mệnh đề đảo, mệnh đề tương đương.","Dùng đúng các kí hiệu ∀, ∃ và lập mệnh đề phủ định của mệnh đề chứa kí hiệu ∀, ∃."],"m":[{"t":"Xét tính đúng sai và lập mệnh đề phủ định","w":"Đề cho một câu và hỏi có phải mệnh đề không, đúng hay sai; hoặc yêu cầu phát biểu mệnh đề phủ định, mệnh đề đảo, dùng \"điều kiện cần\", \"điều kiện đủ\".","s":["Kiểm tra câu có phải khẳng định đúng hoặc sai không: câu hỏi, cảm thán, mệnh lệnh thì loại.","Với mệnh đề P ⇒ Q: chỉ sai khi P đúng, Q sai; mệnh đề đảo là Q ⇒ P.","Phủ định: đổi \"có\" thành \"không có\"; đổi ∀ thành ∃ và ngược lại, đồng thời phủ định P(x) (đổi =, >, <, ≥, ≤ thành ≠, ≤, ≥, <, > tương ứng).","Kết luận đúng sai: với mệnh đề ∀ chỉ cần một phản ví dụ là sai; với mệnh đề ∃ chỉ cần một ví dụ là đúng."],"n":["Phủ định của \"x > 2\" là \"x ≤ 2\", không phải \"x < 2\".","P ⇒ Q đúng không suy ra Q ⇒ P đúng.","Mệnh đề chứa biến chưa phải mệnh đề khi chưa gán giá trị cho biến."]}],"sum":["Mệnh đề là một khẳng định đúng hoặc sai (không thể vừa đúng vừa sai). Câu hỏi, câu cảm thán, câu mệnh lệnh không phải là mệnh đề.","Khái niệm: Mệnh đề là một khẳng định đúng hoặc sai (không thể vừa đúng vừa sai).","Mệnh đề chứa biến là câu khẳng…: Mệnh đề chứa biến là câu khẳng định chứa biến, tính đúng sai phụ thuộc vào giá trị của biến.","Mệnh đề phủ định của P kí hiệu là P̄ (đọc là \"không P\"): P đúng thì P̄ sai, P sai thì P̄ đúng.","Mệnh đề kéo theo \"Nếu P thì…: Mệnh đề kéo theo \"Nếu P thì Q\" kí hiệu P ⇒ Q, chỉ sai khi P đúng và Q sai.","Nếu cả P ⇒ Q và Q…: Nếu cả P ⇒ Q và Q ⇒ P đều đúng thì P và Q là hai mệnh đề tương đương, kí hiệu P ⇔ Q, đọc là \"P khi và chỉ khi Q\" hoặc \"P là điều kiện cần và đủ để…"],"e":["Hay nhầm: Câu hỏi không phải mệnh đề.","Hay nhầm: Câu mệnh lệnh không phải mệnh đề.","Hay nhầm: Câu cảm thán không phải mệnh đề.","Hay nhầm: Không phải phủ định của P.","Hay nhầm: Không phải phủ định của P.","Hay nhầm: Khi P sai, P ⇒ Q luôn đúng."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 2. Tập hợp và các phép toán trên tập hợp","req":["Mô tả tập hợp bằng liệt kê phần tử hoặc chỉ ra tính chất đặc trưng; nhận biết tập con, hai tập hợp bằng nhau.","Thực hiện các phép toán giao, hợp, hiệu, phần bù trên tập hợp, đặc biệt trên các tập con của ℝ (khoảng, đoạn, nửa khoảng)."],"m":[{"t":"Tìm giao, hợp, hiệu của các tập con của ℝ","w":"Đề cho các khoảng, đoạn, nửa khoảng và yêu cầu tìm A ∩ B, A ∪ B, A \\ B hoặc C_ℝ A.","s":["Biểu diễn từng tập trên trục số; dùng ngoặc tròn tại đầu mút không thuộc tập, ngoặc vuông tại đầu mút thuộc tập.","Giao: lấy phần chung của hai tập; hợp: gộp hai tập; hiệu A \\ B: lấy phần của A nằm ngoài B.","Xác định đầu mút của kết quả có thuộc tập hay không rồi viết bằng kí hiệu khoảng, đoạn."],"n":["Với giao, đầu mút thuộc kết quả khi thuộc cả hai tập; với hợp, khi thuộc ít nhất một tập.","C_ℝ (a; b) = (−∞; a] ∪ [b; +∞).","Hai khoảng rời nhau thì giao là ∅ và hợp phải viết bằng dấu ∪, không gộp thành một khoảng."]}],"sum":["Tập hợp có thể được mô tả bằng cách liệt kê các phần tử (A = {1; 2;","Khái niệm: Tập hợp có thể được mô tả bằng cách liệt kê các phần tử (A = {1;","Tập con: A ⊂ B nếu mọi phần tử của A đều thuộc B.","Các tập hợp số: ℕ ⊂ ℤ ⊂ ℚ ⊂ ℝ.","Giao A ∩ B gồm các phần tử vừa thuộc A vừa thuộc B: Hợp A ∪ B gồm các phần tử thuộc A hoặc thuộc B."],"e":["Hay nhầm: ℤ chứa ℕ, không phải ngược lại.","Hay nhầm: 4 thuộc A và B nên thuộc giao.","Hay nhầm: 0 thuộc A nên không thuộc phần bù.","Hay nhầm: Khi m > 3 giao khác rỗng.","Lưu ý: Với giao, đầu mút thuộc kết quả khi thuộc cả hai tập; với hợp, khi thuộc ít nhất một tập.","Lưu ý: C_ℝ (a; b) = (−∞; a] ∪ [b; +∞)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương II. Bất phương trình và hệ bất phương trình bậc nhất hai ẩn","l":[{"t":"Bài 3. Bất phương trình bậc nhất hai ẩn","req":["Nhận biết bất phương trình bậc nhất hai ẩn và nghiệm của nó.","Biểu diễn miền nghiệm của bất phương trình bậc nhất hai ẩn trên mặt phẳng toạ độ."],"m":[{"t":"Biểu diễn miền nghiệm của bất phương trình ax + by ≤ c","w":"Đề yêu cầu vẽ miền nghiệm, hoặc hỏi điểm nào thuộc miền nghiệm, hoặc hỏi miền nghiệm nằm phía nào của đường thẳng.","s":["Vẽ đường thẳng d: ax + by = c (tìm hai điểm, thường là giao với hai trục).","Lấy một điểm M₀(x₀; y₀) không thuộc d, thường là gốc O(0; 0) nếu c ≠ 0, và tính ax₀ + by₀.","Nếu ax₀ + by₀ ≤ c thì nửa mặt phẳng chứa M₀ (bờ d) là miền nghiệm; nếu không thì nửa mặt phẳng còn lại là miền nghiệm.","Với dấu < hoặc > thì bỏ bờ d (vẽ nét đứt); với ≤ hoặc ≥ thì lấy cả bờ."],"n":["Nếu d đi qua O (c = 0) thì chọn điểm khác, ví dụ (1; 0) hoặc (0; 1).","Kiểm tra điểm thuộc miền nghiệm chỉ cần thay toạ độ vào bất phương trình."]}],"sum":["Bất phương trình bậc nhất hai ẩn x, y có dạng tổng quát ax + by ≤ c (hoặc ax + by < c, ax + by ≥ c, ax + by > c), trong đó a, b, c là các số thực đã cho, a và b không đồng thời bằng 0.","Khái niệm: Bất phương trình bậc nhất hai ẩn x, y có dạng tổng quát ax + by ≤ c (hoặc ax + by < c, ax + by ≥ c, ax + by > c), trong đó a, b, c là các số thực đã…","Trong mặt phẳng toạ độ Oxy, tập…: Trong mặt phẳng toạ độ Oxy, tập hợp các điểm có toạ độ là nghiệm của bất phương trình gọi là miền nghiệm của nó."],"e":["Hay nhầm: Có x² nên không phải bậc nhất.","Hay nhầm: Đường thẳng là miền nghiệm của phương trình.","Hay nhầm: Không kể bờ ứng với dấu < hoặc >.","Hay nhầm: Có thể dùng đúng 50 nghìn nên dấu ≤.","Lưu ý: Nếu d đi qua O (c = 0) thì chọn điểm khác, ví dụ (1; 0) hoặc (0; 1).","Lưu ý: Kiểm tra điểm thuộc miền nghiệm chỉ cần thay toạ độ vào bất phương trình."],"q":{"n":16,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 4. Hệ bất phương trình bậc nhất hai ẩn","req":["Nhận biết hệ bất phương trình bậc nhất hai ẩn, biểu diễn miền nghiệm trên mặt phẳng toạ độ.","Vận dụng để tìm giá trị lớn nhất, nhỏ nhất của biểu thức F = ax + by trên miền nghiệm và giải bài toán thực tế."],"m":[{"t":"Tìm giá trị lớn nhất, nhỏ nhất của F = ax + by trên miền nghiệm","w":"Đề cho hệ bất phương trình (hoặc bài toán thực tế dẫn đến hệ) và yêu cầu tìm max, min của F = ax + by, hoặc phương án tối ưu.","s":["Nếu là bài thực tế: đặt ẩn x, y, lập các bất phương trình ràng buộc (kể cả x ≥ 0, y ≥ 0) và biểu thức F cần tối ưu.","Vẽ miền nghiệm của hệ, xác định toạ độ các đỉnh của miền đa giác (giải hệ phương trình của từng cặp đường thẳng).","Tính F tại từng đỉnh.","So sánh: giá trị lớn nhất là max F, nhỏ nhất là min F; trả lời theo yêu cầu của bài."],"n":["Miền nghiệm phải bị chặn (đa giác) thì mới chắc chắn có cả max và min.","Bài thực tế thường yêu cầu x, y nguyên; kiểm tra đỉnh có toạ độ nguyên không."]}],"sum":["Hệ bất phương trình bậc nhất hai ẩn là hệ gồm hai hay nhiều bất phương trình bậc nhất hai ẩn x, y.","Khái niệm: Hệ bất phương trình bậc nhất hai ẩn là hệ gồm hai hay nhiều bất phương trình bậc nhất hai ẩn x, y.","Để biểu diễn miền nghiệm của hệ: Vẽ từng đường thẳng, gạch bỏ phần không là miền nghiệm của mỗi bất phương trình; phần còn lại không bị gạch là miền nghiệm của hệ (thường là một…","Giá trị lớn nhất (nhỏ nhất) của…: Giá trị lớn nhất (nhỏ nhất) của biểu thức F(x; y) = ax + by trên một miền đa giác đạt được tại một trong các đỉnh của miền đa giác đó."],"e":["Hay nhầm: Không phải giá trị tại đỉnh.","Hay nhầm: Không phải giá trị tại đỉnh.","Hay nhầm: m = 3 vẫn có nghiệm (1; 2).","Lưu ý: Miền nghiệm phải bị chặn (đa giác) thì mới chắc chắn có cả max và min.","Lưu ý: Bài thực tế thường yêu cầu x, y nguyên; kiểm tra đỉnh có toạ độ nguyên không."],"q":{"n":16,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương III. Hệ thức lượng trong tam giác","l":[{"t":"Bài 5. Giá trị lượng giác của một góc từ 0° đến 180°","req":["Nhận biết giá trị lượng giác sin, côsin, tang, côtang của góc từ 0° đến 180° trên nửa đường tròn đơn vị.","Dùng được mối liên hệ giữa giá trị lượng giác của hai góc bù nhau, hai góc phụ nhau và các hệ thức cơ bản."],"m":[{"t":"Tính giá trị lượng giác của góc tù và biểu thức lượng giác","w":"Đề yêu cầu tính sin, cos, tan của các góc như 120°, 135°, 150°; hoặc cho một giá trị lượng giác và tính các giá trị còn lại; hoặc rút gọn biểu thức có góc bù nhau.","s":["Đưa góc tù về góc nhọn bù với nó: α = 180° − β, dùng sin α = sin β, cos α = −cos β, tan α = −tan β.","Tra bảng giá trị của góc nhọn đặc biệt.","Nếu cho sin α (hoặc cos α): dùng sin²α + cos²α = 1 để tìm giá trị còn lại, chọn dấu theo α nhọn hay tù; rồi tính tan, cot.","Rút gọn biểu thức: thay các góc bù, phụ nhau, dùng các hệ thức cơ bản."],"n":["Với 90° < α < 180° thì cos α < 0, tan α < 0.","Không nhầm: cos(180° − α) đổi dấu, sin(180° − α) giữ nguyên."]}],"sum":["Trên nửa đường tròn đơn vị (tâm O, bán kính 1, nằm phía trên trục hoành), với mỗi góc α (0° ≤ α ≤ 180°) có đúng một điểm M(x₀; y₀) sao cho góc xOM = α.","Khái niệm: Trên nửa đường tròn đơn vị (tâm O, bán kính 1, nằm phía trên trục hoành), với mỗi góc α (0° ≤ α ≤ 180°) có đúng một điểm M(x₀; y₀) sao cho góc xOM =…","Dấu: Với 0° < α < 90°, mọi giá trị lượng giác đều dương; với 90° < α < 180°, sin α > 0 còn cos α, tan α, cot α đều âm. tan 90° và cot 0°, cot 180° không…","Bảng giá trị thường dùng: Sin 0° = 0, sin 30° = 1/2, sin 45° = √2/2, sin 60° = √3/2, sin 90° = 1; cos 0° = 1, cos 30° = √3/2, cos 45° = √2/2, cos 60° = 1/2, cos 90° = 0; tan…"],"e":["Lưu ý: Với 90° < α < 180° thì cos α < 0, tan α < 0.","Lưu ý: Không nhầm: cos(180° − α) đổi dấu, sin(180° − α) giữ nguyên."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 6. Hệ thức lượng trong tam giác","req":["Vận dụng định lí côsin, định lí sin và các công thức tính diện tích tam giác.","Giải tam giác và vận dụng vào bài toán đo đạc thực tế."],"m":[{"t":"Tính cạnh, góc và diện tích tam giác","w":"Đề cho một số cạnh, góc của tam giác và yêu cầu tính cạnh, góc còn lại, diện tích, bán kính R, r; hoặc bài toán đo khoảng cách, chiều cao thực tế.","s":["Vẽ hình, ghi các yếu tố đã biết theo đúng kí hiệu a, b, c đối diện A, B, C.","Chọn công thức: hai cạnh + góc xen giữa hoặc ba cạnh → định lí côsin; một cạnh + hai góc hoặc cần R → định lí sin.","Tính diện tích bằng công thức phù hợp với dữ kiện: ½ab sin C, Heron, pr hoặc abc/(4R).","Suy ra R = abc/(4S), r = S/p nếu đề hỏi; làm tròn theo yêu cầu."],"n":["Góc tù có cos âm; nếu dùng định lí sin tìm góc, chú ý có thể có hai góc bù nhau cùng sin.","Đơn vị độ dài phải thống nhất; diện tích tính theo đơn vị vuông."]}],"sum":["Cho tam giác ABC có BC = a, CA = b, AB = c; R là bán kính đường tròn ngoại tiếp, r là bán kính đường tròn nội tiếp, p = (a + b + c)/2 là nửa chu vi, S là diện tích.","Cho tam giác ABC có BC = a, CA = b, AB = c: R là bán kính đường tròn ngoại tiếp, r là bán kính đường tròn nội tiếp, p = (a + b + c)/2 là nửa chu vi, S là diện tích.","Giải tam giác là tìm các cạnh…: Giải tam giác là tìm các cạnh và góc chưa biết khi biết một số yếu tố."],"e":["Hay nhầm: Công thức với R là abc/(4R).","Hay nhầm: Xác định được dấu của cos A.","Lưu ý: Góc tù có cos âm; nếu dùng định lí sin tìm góc, chú ý có thể có hai góc bù nhau cùng sin.","Lưu ý: Đơn vị độ dài phải thống nhất; diện tích tính theo đơn vị vuông."],"q":{"n":17,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":6,"Nâng cao":2}}}]},{"t":"Chương IV. Vectơ","l":[{"t":"Bài 7. Các khái niệm mở đầu","req":["Nhận biết vectơ, độ dài vectơ, hai vectơ cùng phương, cùng hướng, bằng nhau, vectơ-không.","Biểu thị một số đại lượng trong thực tiễn bằng vectơ."],"m":[{"t":"Nhận biết các vectơ bằng nhau, cùng phương, cùng hướng trong hình","w":"Đề cho hình bình hành, hình chữ nhật, hình vuông, hình lục giác đều, trung điểm... và hỏi các vectơ cùng phương, cùng hướng, bằng nhau, đối nhau hoặc tính độ dài vectơ.","s":["Xác định giá của từng vectơ; các vectơ nằm trên các đường thẳng song song hoặc trùng nhau thì cùng phương.","Xét hướng: cùng chiều mũi tên là cùng hướng, ngược chiều là ngược hướng.","So sánh độ dài: cùng hướng và cùng độ dài thì bằng nhau; ngược hướng và cùng độ dài thì đối nhau.","Độ dài vectơ: tính độ dài đoạn thẳng tương ứng (Pythagore, tính chất hình)."],"n":["→AB = →DC trong hình bình hành ABCD, nhưng →AB ≠ →CD (ngược hướng).","Hai vectơ bằng nhau không cần cùng điểm đầu."]}],"sum":["Vectơ là một đoạn thẳng có hướng. Vectơ có điểm đầu A, điểm cuối B kí hiệu là →AB;","Vectơ là một đoạn thẳng có hướng: Vectơ có điểm đầu A, điểm cuối B kí hiệu là →AB;","Đường thẳng đi qua điểm đầu và…: Đường thẳng đi qua điểm đầu và điểm cuối của một vectơ gọi là giá của vectơ.","Hai vectơ →a và →b bằng nhau…: Hai vectơ →a và →b bằng nhau (→a = →b) nếu chúng cùng hướng và cùng độ dài.","Vectơ-không →0 là vectơ có điểm đầu…: Vectơ-không →0 là vectơ có điểm đầu và điểm cuối trùng nhau (→AA = →BB = →0), có độ dài bằng 0, cùng phương và cùng hướng với mọi vectơ.","Ba điểm phân biệt A, B, C…: Ba điểm phân biệt A, B, C thẳng hàng khi và chỉ khi →AB và →AC cùng phương."],"e":["Hay nhầm: Cùng phương có thể ngược hướng.","Hay nhầm: →AD không cùng phương với →AB.","Hay nhầm: Hai vectơ không cùng hướng.","Hay nhầm: Có thể ngược hướng (A nằm giữa) vẫn thẳng hàng.","Hay nhầm: Khác hướng nên không bằng nhau.","Hay nhầm: Ngược hướng nên không bằng nhau."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 8. Tổng và hiệu của hai vectơ","req":["Thực hiện phép cộng, trừ vectơ bằng quy tắc ba điểm, quy tắc hình bình hành và quy tắc hiệu.","Vận dụng tính chất trung điểm, trọng tâm và áp dụng vào bài toán vật lí (hợp lực)."],"m":[{"t":"Chứng minh đẳng thức vectơ và tính độ dài tổng, hiệu","w":"Đề yêu cầu chứng minh →AB + →CD = →AD + →CB, tính |→AB + →AD|, |→AB − →AC| trong hình vuông, tam giác đều, hình chữ nhật; hoặc tìm hợp lực.","s":["Dùng quy tắc ba điểm để chèn điểm: →AB = →AM + →MB; dùng quy tắc hiệu →OB − →OA = →AB.","Dùng quy tắc hình bình hành để gộp hai vectơ chung gốc thành đường chéo.","Để tính độ dài: biến đổi tổng/hiệu về một vectơ duy nhất rồi tính độ dài đoạn thẳng tương ứng (Pythagore, tính chất hình).","Với trung điểm, trọng tâm: dùng các hệ thức →MA + →MB = →0, →GA + →GB + →GC = →0."],"n":["|→a + →b| nói chung khác |→a| + |→b|; chỉ bằng khi hai vectơ cùng hướng.","→AB − →AC = →CB (quy tắc hiệu), không phải →BC."]}],"sum":["Tổng của hai vectơ: với ba điểm A, B, C bất kì, →AB + →BC = →AC (quy tắc ba điểm). Nếu ABCD là hình bình hành thì →AB + →AD = →AC (quy tắc hình bình hành).","Tổng của hai vectơ: Với ba điểm A, B, C bất kì, →AB + →BC = →AC (quy tắc ba điểm).","Phép cộng vectơ có tính chất giao…: Phép cộng vectơ có tính chất giao hoán →a + →b = →b + →a, kết hợp (→a + →b) + →c = →a + (→b + →c), và →a + →0 = →a.","Hiệu của hai vectơ: →a − →b = →a + (−→b).","Trong vật lí, hợp lực của hai…: Trong vật lí, hợp lực của hai lực →F₁, →F₂ cùng tác dụng vào một vật là →F = →F₁ + →F₂; nếu hai lực vuông góc thì |→F|² = |→F₁|² + |→F₂|²."],"e":["Hay nhầm: Hai vectơ ngược hướng, không bằng nhau.","Hay nhầm: Chỉ đúng nếu ngược hướng.","Lưu ý: |→a + →b| nói chung khác |→a| + |→b|; chỉ bằng khi hai vectơ cùng hướng.","Lưu ý: →AB − →AC = →CB (quy tắc hiệu), không phải →BC."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 9. Tích của một vectơ với một số","req":["Thực hiện phép nhân vectơ với một số và dùng các tính chất của nó.","Dùng điều kiện cùng phương, thẳng hàng; phân tích một vectơ theo hai vectơ không cùng phương."],"m":[{"t":"Phân tích vectơ và chứng minh ba điểm thẳng hàng","w":"Đề cho tam giác, hình bình hành với các điểm chia đoạn theo tỉ số; yêu cầu biểu diễn một vectơ theo hai vectơ cho trước, hoặc chứng minh ba điểm thẳng hàng, hai đường thẳng song song.","s":["Chọn hai vectơ gốc không cùng phương (thường là hai cạnh chung đỉnh, ví dụ →AB, →AC).","Dùng quy tắc ba điểm và giả thiết tỉ số (→AM = k→AB, trung điểm, trọng tâm) để viết các vectơ cần thiết theo hai vectơ gốc.","Để chứng minh M, N, P thẳng hàng: tính →MN và →MP theo hai vectơ gốc rồi tìm k sao cho →MN = k→MP.","Kết luận và nêu tỉ số (nếu đề hỏi)."],"n":["Hệ số phân tích là duy nhất, nên có thể so sánh hệ số để tìm ẩn.","Nếu →AM = k→AB với k < 0 thì M nằm ngoài đoạn AB về phía A."]}],"sum":["Tích của vectơ →a ≠ →0 với số thực k ≠ 0 là vectơ k→a, cùng hướng với →a nếu k > 0, ngược hướng với →a nếu k < 0, và có độ dài |k→a| = |k|·|→a|.","Khái niệm: Tích của vectơ →a ≠ →0 với số thực k ≠ 0 là vectơ k→a, cùng hướng với →a nếu k > 0, ngược hướng với →a nếu k < 0, và có độ dài |k→a| = |k|·|→a|.","Trung điểm và trọng tâm: Nếu I là trung điểm AB thì với mọi điểm M, →MA + →MB = 2→MI.","Điều kiện cùng phương: →b cùng phương với →a (→a ≠ →0) khi và chỉ khi tồn tại số k sao cho →b = k→a.","Phân tích vectơ: Cho hai vectơ →a, →b không cùng phương."],"e":["Hay nhầm: Đó là hệ số của trọng tâm.","Hay nhầm: Cùng phương vì →v = −2→u.","Hay nhầm: Chỉ là trường hợp A là trung điểm.","Hay nhầm: Trọng tâm ứng với hệ số 1, 1, 1.","Lưu ý: Hệ số phân tích là duy nhất, nên có thể so sánh hệ số để tìm ẩn.","Lưu ý: Nếu →AM = k→AB với k < 0 thì M nằm ngoài đoạn AB về phía A."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 10. Vectơ trong mặt phẳng toạ độ","req":["Xác định toạ độ của vectơ, của điểm; biểu thị vectơ qua →i, →j.","Tính toạ độ của tổng, hiệu, tích với một số; tính độ dài vectơ, khoảng cách hai điểm, toạ độ trung điểm, trọng tâm."],"m":[{"t":"Tính toán với toạ độ vectơ","w":"Đề cho toạ độ các điểm hoặc vectơ và yêu cầu tìm toạ độ vectơ tổng, hiệu, tích; tìm điểm thoả mãn đẳng thức vectơ; xét ba điểm thẳng hàng; tính độ dài, chu vi; tìm trung điểm, trọng tâm.","s":["Viết toạ độ từng vectơ cần dùng: →AB = (x_B − x_A; y_B − y_A).","Thay vào biểu thức, tính theo từng toạ độ (hoành độ với hoành độ, tung độ với tung độ).","Nếu tìm điểm M(x; y) chưa biết: viết đẳng thức vectơ thành hệ hai phương trình theo x, y rồi giải.","Độ dài dùng công thức căn bậc hai; thẳng hàng kiểm tra tỉ lệ toạ độ."],"n":["Chú ý dấu khi lấy hiệu toạ độ: điểm cuối trừ điểm đầu.","Hình bình hành ABCD thì →AB = →DC (không phải →AB = →CD).","Khi x = 0 hoặc y = 0 không chia, dùng điều kiện x·y′ − x′·y = 0 cho cùng phương."]}],"sum":["Trên mặt phẳng toạ độ Oxy, →i và →j là hai vectơ đơn vị trên hai trục Ox, Oy. Với mỗi vectơ →u có duy nhất cặp số (x; y) sao cho →u = x→i + y→j; cặp số đó gọi là toạ độ của →u, viết →u = (x; y) hoặc…","Khái niệm: Trên mặt phẳng toạ độ Oxy, →i và →j là hai vectơ đơn vị trên hai trục Ox, Oy.","Toạ độ của điểm M là toạ độ của vectơ →OM: Nếu A(x_A; y_A) và B(x_B; y_B) thì →AB = (x_B − x_A; y_B − y_A).","→v cùng phương với →u ≠ →0…: →v cùng phương với →u ≠ →0 khi và chỉ khi có số k để x′ = kx, y′ = ky (khi x, y khác 0 có thể viết x′/x = y′/y)."],"e":["Hay nhầm: Hoành độ đã bằng nhau; cần tung độ bằng nhau.","Lưu ý: Chú ý dấu khi lấy hiệu toạ độ: điểm cuối trừ điểm đầu.","Lưu ý: Hình bình hành ABCD thì →AB = →DC (không phải →AB = →CD).","Lưu ý: Khi x = 0 hoặc y = 0 không chia, dùng điều kiện x·y′ − x′·y = 0 cho cùng phương."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 11. Tích vô hướng của hai vectơ","req":["Xác định góc giữa hai vectơ; tính tích vô hướng bằng định nghĩa và bằng toạ độ.","Dùng tích vô hướng để tính độ dài, góc, chứng minh vuông góc và giải bài toán hình học."],"m":[{"t":"Tính tích vô hướng và góc giữa hai vectơ","w":"Đề cho toạ độ các vectơ, điểm, hoặc cho độ dài và góc; hỏi →a·→b, góc giữa hai vectơ, điều kiện vuông góc, hoặc tính độ dài qua đẳng thức vectơ.","s":["Nếu có toạ độ: tính →a·→b = xx′ + yy′, |→a|, |→b| rồi suy ra cos của góc.","Nếu có độ dài và góc: dùng định nghĩa →a·→b = |→a||→b|cos α; chú ý góc giữa →AB và →AC là góc A, nhưng góc giữa →AB và →CA là 180° − A.","Bài tìm tham số để vuông góc: cho tích vô hướng bằng 0 rồi giải.","Bài độ dài: bình phương vô hướng, khai triển hằng đẳng thức vectơ rồi thay →a², →b², →a·→b."],"n":["Tích vô hướng là một số, không phải vectơ.","cos âm cho góc tù, cos dương cho góc nhọn.","Vuông góc dùng dấu hiệu tích vô hướng bằng 0, không cần tính góc."]}],"sum":["Góc giữa hai vectơ →a, →b khác →0: lấy điểm O bất kì, vẽ →OA = →a, →OB = →b, khi đó góc AOB (từ 0° đến 180°) là góc giữa hai vectơ, kí hiệu (→a, →b).","Khái niệm: Góc giữa hai vectơ →a, →b khác →0: lấy điểm O bất kì, vẽ →OA = →a, →OB = →b, khi đó góc AOB (từ 0° đến 180°) là góc giữa hai vectơ, kí hiệu (→a, →b).","Biểu thức toạ độ: Nếu →a = (x; y), →b = (x′; y′) thì →a·→b = xx′ + yy′.","Ứng dụng: Tích vô hướng cho phép tính độ dài đoạn thẳng, số đo góc, kiểm tra hai đường thẳng vuông góc; trong vật lí công của lực →F làm vật dịch chuyển →d là…"],"e":["Hay nhầm: Tích vô hướng bằng 0 nên góc 90°.","Hay nhầm: Không có phép nhân này ở lớp 10.","Hay nhầm: Chỉ đúng khi cùng phương.","Lưu ý: Tích vô hướng là một số, không phải vectơ.","Lưu ý: cos âm cho góc tù, cos dương cho góc nhọn.","Lưu ý: Vuông góc dùng dấu hiệu tích vô hướng bằng 0, không cần tính góc."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương V. Các số đặc trưng của mẫu số liệu không ghép nhóm","l":[{"t":"Bài 12. Số gần đúng và sai số","req":["Hiểu số gần đúng, sai số tuyệt đối, độ chính xác, sai số tương đối.","Quy tròn số gần đúng theo độ chính xác cho trước; xác định số quy tròn."],"m":[{"t":"Quy tròn số gần đúng theo độ chính xác","w":"Đề cho ā = a ± d và yêu cầu số quy tròn của a, hoặc cho kết quả đo và hỏi sai số tuyệt đối, sai số tương đối.","s":["Tìm hàng của chữ số khác 0 đầu tiên của d (ví dụ d = 0,004 ở hàng phần nghìn).","Quy tròn a đến hàng liền trước (cao hơn) hàng đó: d ở hàng phần nghìn thì quy tròn a đến hàng phần trăm.","Sai số tương đối: lấy d chia |a|, đổi ra phần trăm nếu cần."],"n":["Nếu d = 0,5 (hàng phần mười) thì quy tròn đến hàng đơn vị.","Chữ số bỏ đi từ 5 trở lên thì làm tròn lên."]}],"sum":["Trong đo đạc, tính toán ta thường chỉ nhận được số gần đúng a của số đúng ā. Sai số tuyệt đối của số gần đúng a là Δ_a = |a − ā|.","Khái niệm: Trong đo đạc, tính toán ta thường chỉ nhận được số gần đúng a của số đúng ā.","Sai số tương đối của số gần đúng a là δ_a = Δ_a/|a| ≤ d/|a|: Sai số tương đối càng nhỏ thì phép đo càng chính xác; thường viết dưới dạng phần trăm.","Quy tròn số: Khi quy tròn số đến một hàng nào đó thì sai số tuyệt đối không vượt quá nửa đơn vị của hàng đó.","Xác định số quy tròn của số gần đúng với độ chính xác cho trước: Quy tròn a đến hàng cao hơn hàng của d một đơn vị (hàng thấp nhất mà d nhỏ hơn nửa đơn vị của hàng đó)."],"e":["Hay nhầm: Phải lấy giá trị tuyệt đối.","Hay nhầm: Hàng phần nghìn chưa đủ tin cậy.","Lưu ý: Nếu d = 0,5 (hàng phần mười) thì quy tròn đến hàng đơn vị.","Lưu ý: Chữ số bỏ đi từ 5 trở lên thì làm tròn lên."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 13. Các số đặc trưng đo xu thế trung tâm","req":["Tính số trung bình, trung vị, tứ phân vị, mốt của mẫu số liệu không ghép nhóm.","Chọn số đặc trưng phù hợp và giải thích ý nghĩa."],"m":[{"t":"Tìm số trung bình, trung vị, tứ phân vị và mốt","w":"Đề cho dãy số liệu (có thể kèm bảng tần số) và hỏi các số đặc trưng, hoặc hỏi nên dùng số nào để đại diện.","s":["Sắp xếp số liệu theo thứ tự không giảm, đếm n.","Trung bình: cộng tất cả rồi chia n (với bảng tần số thì nhân giá trị với tần số).","Trung vị: n lẻ lấy số giữa, n chẵn lấy trung bình hai số giữa.","Tứ phân vị: tách hai nửa (bỏ trung vị khi n lẻ) rồi tìm trung vị mỗi nửa.","Mốt: giá trị có tần số lớn nhất."],"n":["Khi mẫu có giá trị bất thường, trung vị đại diện tốt hơn trung bình.","Q₂ chính là trung vị M_e.","Phải sắp xếp trước khi tìm trung vị, tứ phân vị."]}],"sum":["Số trung bình của mẫu số liệu x₁, x₂, ..., x_n là x̄ = (x₁ + x₂ + ... + x_n)/n. Nếu giá trị x_i xuất hiện với tần số m_i thì x̄ = (m₁x₁ + m₂x₂ + ... + m_kx_k)/n.","Khái niệm: Số trung bình của mẫu số liệu x₁, x₂, ..., x_n là x̄ = (x₁ + x₂ + ... + x_n)/n.","Trung vị M_e: Sắp xếp mẫu theo thứ tự không giảm.","Tứ phân vị: Sắp xếp mẫu không giảm.","Mốt M_o là giá trị xuất hiện với tần số lớn nhất trong mẫu: Một mẫu có thể có nhiều mốt hoặc không có mốt (khi mọi giá trị có cùng tần số)."],"e":["Hay nhầm: Trung bình bị kéo theo giá trị bất thường.","Hay nhầm: Tổng thay đổi theo mọi giá trị.","Hay nhầm: Trung vị không bị ảnh hưởng.","Hay nhầm: Cỡ trung bình có thể không ai mang.","Hay nhầm: Không phản ánh cỡ bán chạy.","Hay nhầm: Không phản ánh cỡ bán chạy."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 14. Các số đặc trưng đo độ phân tán","req":["Tính khoảng biến thiên, khoảng tứ phân vị, phương sai, độ lệch chuẩn.","Phát hiện giá trị bất thường bằng khoảng tứ phân vị; so sánh độ phân tán của hai mẫu."],"m":[{"t":"Tính phương sai, độ lệch chuẩn và tìm giá trị bất thường","w":"Đề cho mẫu số liệu, hỏi khoảng biến thiên, khoảng tứ phân vị, phương sai, độ lệch chuẩn hoặc giá trị bất thường; hoặc so sánh độ ổn định của hai mẫu.","s":["Tính x̄; lập bảng (x_i − x̄)² rồi cộng lại, chia n để được s²; s = √s².","Khoảng biến thiên lấy max trừ min; khoảng tứ phân vị tìm Q₁, Q₃ rồi trừ.","Giá trị bất thường: tính Q₁ − 1,5Δ_Q và Q₃ + 1,5Δ_Q, giá trị nằm ngoài là bất thường.","So sánh hai mẫu cùng trung bình: độ lệch chuẩn nhỏ hơn thì ổn định hơn."],"n":["Có thể dùng công thức s² = (x₁² + ... + x_n²)/n − x̄² cho nhanh.","Phương sai không âm; bằng 0 khi mọi số liệu bằng nhau."]}],"sum":["Khoảng biến thiên R = x_max − x_min là hiệu giữa giá trị lớn nhất và nhỏ nhất của mẫu. R dễ tính nhưng chỉ dùng hai giá trị đầu mút nên bị ảnh hưởng mạnh bởi giá trị bất thường.","Khái niệm: Khoảng biến thiên R = x_max − x_min là hiệu giữa giá trị lớn nhất và nhỏ nhất của mẫu.","Khoảng tứ phân vị Δ_Q = Q₃…: Khoảng tứ phân vị Δ_Q = Q₃ − Q₁ đo độ phân tán của 50% số liệu ở giữa, không bị ảnh hưởng bởi giá trị bất thường.","Phương sai và độ lệch chuẩn đo…: Phương sai và độ lệch chuẩn đo mức độ phân tán của số liệu quanh số trung bình: càng lớn thì số liệu càng phân tán.","Giá trị bất thường: Giá trị x được coi là bất thường nếu x < Q₁ − 1,5Δ_Q hoặc x > Q₃ + 1,5Δ_Q."],"e":["Lưu ý: Có thể dùng công thức s² = (x₁² + ... + x_n²)/n − x̄² cho nhanh.","Lưu ý: Phương sai không âm; bằng 0 khi mọi số liệu bằng nhau."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]},{"t":"Toán 10, tập 2","c":[{"t":"Chương VI. Hàm số, đồ thị và ứng dụng","l":[{"t":"Bài 15. Hàm số","req":["Nhận biết hàm số, tập xác định, tập giá trị; tính giá trị của hàm số.","Xét sự đồng biến, nghịch biến; đọc và mô tả đồ thị hàm số."],"m":[{"t":"Tìm tập xác định của hàm số","w":"Đề cho công thức hàm số chứa phân thức hoặc căn bậc hai và hỏi tập xác định; hoặc hỏi giá trị của hàm số tại một điểm.","s":["Phân thức: cho mẫu khác 0.","Căn bậc hai: cho biểu thức dưới căn ≥ 0; căn ở mẫu thì biểu thức dưới căn > 0.","Kết hợp các điều kiện, viết tập xác định dưới dạng khoảng, đoạn hoặc ℝ \\ {…}.","Giá trị tại x₀: thay x₀ vào công thức."],"n":["Hàm đa thức có tập xác định ℝ.","Kiểm tra x₀ thuộc tập xác định trước khi tính f(x₀)."]}],"sum":["Cho tập D ⊂ ℝ khác rỗng. Nếu với mỗi giá trị x thuộc D có đúng một giá trị tương ứng y thuộc ℝ thì ta có một hàm số; x là biến số, y = f(x) là hàm số của x;","Cho tập D ⊂ ℝ khác rỗng: Nếu với mỗi giá trị x thuộc D có đúng một giá trị tương ứng y thuộc ℝ thì ta có một hàm số; x là biến số, y = f(x) là hàm số của x;","Hàm số có thể cho bằng bảng, biểu đồ hoặc công thức: Khi cho bằng công thức mà không chỉ rõ tập xác định, ta quy ước tập xác định là tập tất cả các số thực x sao cho biểu thức f(x) có nghĩa (mẫu khác…","Đồ thị của hàm số y =…: Đồ thị của hàm số y = f(x) xác định trên D là tập hợp các điểm M(x; f(x)) với x thuộc D.","Đồ thị hàm số đồng biến đi…: Đồ thị hàm số đồng biến đi lên từ trái sang phải, đồ thị hàm số nghịch biến đi xuống từ trái sang phải."],"e":["Lưu ý: Hàm đa thức có tập xác định ℝ.","Lưu ý: Kiểm tra x₀ thuộc tập xác định trước khi tính f(x₀)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 16. Hàm số bậc hai","req":["Nhận biết hàm số bậc hai; xác định đỉnh, trục đối xứng, bề lõm, bảng biến thiên và vẽ parabol.","Tìm giá trị lớn nhất, nhỏ nhất; xác định hàm số bậc hai từ điều kiện cho trước; ứng dụng thực tiễn."],"m":[{"t":"Xác định đỉnh, giá trị lớn nhất, nhỏ nhất của hàm số bậc hai","w":"Đề cho hàm số bậc hai và hỏi toạ độ đỉnh, trục đối xứng, khoảng đồng biến nghịch biến, GTLN/GTNN; hoặc bài toán thực tế (độ cao lớn nhất, diện tích lớn nhất, doanh thu lớn nhất).","s":["Xác định a, b, c; tính x_I = −b/(2a).","Tính y_I = f(x_I) (hoặc −Δ/(4a)).","a > 0: GTNN là y_I; a < 0: GTLN là y_I; chiều biến thiên đổi tại x_I.","Bài thực tế: lập hàm bậc hai theo biến thích hợp rồi tìm đỉnh; chú ý điều kiện của biến."],"n":["Dấu của a quyết định bề lõm và loại cực trị.","Tìm hàm số từ điều kiện: thay toạ độ điểm vào y = ax² + bx + c để lập hệ."]}],"sum":["Hàm số bậc hai là hàm số cho bởi công thức y = ax² + bx + c với a, b, c là hằng số và a ≠ 0.","Khái niệm: Hàm số bậc hai là hàm số cho bởi công thức y = ax² + bx + c với a, b, c là hằng số và a ≠ 0.","Đồ thị hàm số bậc hai là…: Đồ thị hàm số bậc hai là một parabol có đỉnh I, trục đối xứng là đường thẳng x = −b/(2a), bề lõm quay lên trên nếu a > 0 và quay xuống dưới nếu a < 0.","Bảng biến thiên: Nếu a > 0, hàm số nghịch biến trên (−∞; −b/(2a)), đồng biến trên (−b/(2a); +∞) và đạt giá trị nhỏ nhất −Δ/(4a) tại x = −b/(2a).","Vẽ parabol: Xác định đỉnh, trục đối xứng, giao điểm với trục tung, giao điểm với trục hoành (nếu có) và điểm đối xứng với giao điểm trục tung qua trục đối xứng,…"],"e":["Hay nhầm: Không đồng biến trên toàn ℝ.","Lưu ý: Dấu của a quyết định bề lõm và loại cực trị.","Lưu ý: Tìm hàm số từ điều kiện: thay toạ độ điểm vào y = ax² + bx + c để lập hệ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 17. Dấu của tam thức bậc hai","req":["Xét dấu tam thức bậc hai; giải bất phương trình bậc hai một ẩn.","Tìm điều kiện của tham số để tam thức luôn dương, luôn âm; ứng dụng."],"m":[{"t":"Xét dấu tam thức và giải bất phương trình bậc hai","w":"Đề cho tam thức hoặc bất phương trình bậc hai; hỏi dấu trên từng khoảng, tập nghiệm, số nghiệm nguyên, hoặc tham số m để bất phương trình nghiệm đúng với mọi x.","s":["Tính Δ (hoặc Δ′) và nghiệm nếu có; xác định dấu a.","Lập bảng xét dấu theo quy tắc trong trái ngoài cùng.","Chọn khoảng thoả mãn chiều bất phương trình; chú ý lấy hoặc không lấy nghiệm (≥, ≤ thì lấy).","Bài tham số \"với mọi x\": dùng điều kiện về a và Δ."],"n":["Khi a < 0 có thể nhân hai vế với −1 và đổi chiều để đưa về a > 0.","Nếu hệ số a chứa tham số, xét riêng trường hợp a = 0."]}],"sum":["Tam thức bậc hai là biểu thức f(x) = ax² + bx + c với a ≠ 0. Nghiệm của phương trình ax² + bx + c = 0 gọi là nghiệm của tam thức;","Tam thức bậc hai là biểu thức f(x) = ax² + bx + c với a ≠ 0: Nghiệm của phương trình ax² + bx + c = 0 gọi là nghiệm của tam thức;","Định lí về dấu: Nếu Δ < 0 thì f(x) cùng dấu với a với mọi x.","Bất phương trình bậc hai một ẩn…: Bất phương trình bậc hai một ẩn có dạng ax² + bx + c > 0 (hoặc ≥, <, ≤) với a ≠ 0."],"e":["Lưu ý: Khi a < 0 có thể nhân hai vế với −1 và đổi chiều để đưa về a > 0.","Lưu ý: Nếu hệ số a chứa tham số, xét riêng trường hợp a = 0."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 18. Phương trình quy về phương trình bậc hai","req":["Giải phương trình dạng √(ax² + bx + c) = √(dx² + ex + f) và √(ax² + bx + c) = dx + e.","Vận dụng giải bài toán thực tiễn, biết thử lại nghiệm."],"m":[{"t":"Giải phương trình chứa căn bậc hai","w":"Đề cho phương trình có căn bậc hai một hoặc hai vế, hoặc bài toán thực tế dẫn đến phương trình chứa căn.","s":["Nhận dạng: hai căn bằng nhau (dạng 1) hay căn bằng biểu thức bậc nhất (dạng 2).","Bình phương hai vế, chuyển về phương trình bậc hai (hoặc bậc nhất) và giải.","Thử lại từng nghiệm: dạng 1 cần biểu thức dưới căn ≥ 0; dạng 2 cần vế phải ≥ 0.","Kết luận tập nghiệm; với bài thực tế loại thêm nghiệm không phù hợp (âm, quá lớn)."],"n":["Không được \"chia hai vế cho x\" khi x có thể bằng 0.","Nghiệm ngoại lai thường xuất hiện ở dạng 2 khi vế phải âm."]}],"sum":["Dạng 1: √(ax² + bx + c) = √(dx² + ex + f). Bình phương hai vế đưa về ax² + bx + c = dx² + ex + f, giải tìm x rồi thử lại: chỉ nhận nghiệm làm cả hai biểu thức dưới căn không âm.","Dạng 1: √(ax² + bx + c) = √(dx² + ex + f).","Dạng 2: √(ax² + bx + c) = dx + e.","Vì phép bình phương có thể tạo…: Vì phép bình phương có thể tạo nghiệm ngoại lai, luôn phải thử lại nghiệm vào phương trình ban đầu (hoặc kiểm tra điều kiện) trước khi kết luận."],"e":["Hay nhầm: Thiếu điều kiện có thể sinh nghiệm ngoại lai.","Hay nhầm: Không được chia khi chưa chắc x ≠ 0.","Lưu ý: Không được \"chia hai vế cho x\" khi x có thể bằng 0.","Lưu ý: Nghiệm ngoại lai thường xuất hiện ở dạng 2 khi vế phải âm."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương VII. Phương pháp toạ độ trong mặt phẳng","l":[{"t":"Bài 19. Phương trình đường thẳng","req":["Xác định vectơ chỉ phương, vectơ pháp tuyến của đường thẳng.","Lập phương trình tổng quát và phương trình tham số của đường thẳng; chuyển đổi giữa hai dạng."],"m":[{"t":"Lập phương trình đường thẳng","w":"Đề cho một điểm và một vectơ (pháp tuyến hoặc chỉ phương), hoặc hai điểm, hoặc yêu cầu đường thẳng song song, vuông góc với đường thẳng cho trước; hỏi phương trình tổng quát hoặc tham số.","s":["Xác định một điểm M₀ thuộc đường thẳng.","Xác định vectơ pháp tuyến →n (nếu cần tổng quát) hoặc chỉ phương →u (nếu cần tham số); đổi qua lại bằng cách đảo toạ độ và đổi dấu một thành phần.","Song song với ax + by + c = 0 thì dùng cùng →n = (a; b); vuông góc thì dùng →n = (b; −a).","Viết phương trình và rút gọn."],"n":["Đường thẳng có vô số vectơ pháp tuyến, chỉ phương (cùng phương với nhau).","Kiểm tra điểm thuộc đường thẳng bằng cách thay toạ độ."]}],"sum":["Vectơ →n ≠ →0 gọi là vectơ pháp tuyến của đường thẳng Δ nếu giá của →n vuông góc với Δ. Vectơ →u ≠ →0 gọi là vectơ chỉ phương của Δ nếu giá của →u song song hoặc trùng với Δ.","Khái niệm: Vectơ →n ≠ →0 gọi là vectơ pháp tuyến của đường thẳng Δ nếu giá của →n vuông góc với Δ.","Đường thẳng đi qua M₀(x₀; y₀) và…: Đường thẳng đi qua M₀(x₀; y₀) và có vectơ pháp tuyến →n = (a; b) có phương trình a(x − x₀) + b(y − y₀) = 0.","Mỗi giá trị t cho một điểm trên đường thẳng: Đường thẳng qua hai điểm A, B có vectơ chỉ phương →AB."],"e":["Hay nhầm: Đó là vectơ chỉ phương (ngược).","Hay nhầm: (−2; −1) vẫn là vectơ chỉ phương; đáp án này sai vì phủ định.","Lưu ý: Đường thẳng có vô số vectơ pháp tuyến, chỉ phương (cùng phương với nhau).","Lưu ý: Kiểm tra điểm thuộc đường thẳng bằng cách thay toạ độ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 20. Vị trí tương đối giữa hai đường thẳng. Góc và khoảng cách","req":["Xét vị trí tương đối của hai đường thẳng bằng hệ phương trình hoặc vectơ.","Tính góc giữa hai đường thẳng và khoảng cách từ một điểm đến một đường thẳng."],"m":[{"t":"Tính góc và khoảng cách","w":"Đề cho hai đường thẳng (tổng quát hoặc tham số) hỏi vị trí tương đối, giao điểm, góc; hoặc cho điểm và đường thẳng hỏi khoảng cách, diện tích tam giác, bán kính đường tròn tiếp xúc.","s":["Đưa các đường thẳng về dạng tổng quát để lấy →n.","Vị trí tương đối: so sánh tỉ lệ a₁/a₂, b₁/b₂, c₁/c₂ hoặc giải hệ.","Góc: dùng công thức cos với giá trị tuyệt đối ở tử.","Khoảng cách: thay toạ độ điểm vào phương trình, lấy giá trị tuyệt đối chia √(a² + b²)."],"n":["Hai đường thẳng vuông góc khi a₁a₂ + b₁b₂ = 0, không cần tính góc.","Điểm nằm trên đường thẳng thì khoảng cách bằng 0."]}],"sum":["Cho Δ₁: a₁x + b₁y + c₁ = 0 và Δ₂: a₂x + b₂y + c₂ = 0. Xét hệ hai phương trình: hệ có nghiệm duy nhất thì hai đường thẳng cắt nhau tại điểm có toạ độ là nghiệm; hệ vô nghiệm thì song song; hệ có vô…","Cho Δ₁: A₁x + b₁y + c₁ = 0 và Δ₂: a₂x + b₂y + c₂ = 0.","Dùng vectơ pháp tuyến: →n₁, →n₂ không cùng phương thì cắt nhau; cùng phương thì song song hoặc trùng (kiểm tra một điểm).","Góc giữa hai đường thẳng là góc…: Góc giữa hai đường thẳng là góc không tù tạo bởi chúng; có thể tính qua vectơ pháp tuyến hoặc vectơ chỉ phương (công thức tương tự với toạ độ các…"],"e":["Hay nhầm: Pháp tuyến không cùng phương.","Hay nhầm: Đó là góc giữa hai vectơ.","Lưu ý: Hai đường thẳng vuông góc khi a₁a₂ + b₁b₂ = 0, không cần tính góc.","Lưu ý: Điểm nằm trên đường thẳng thì khoảng cách bằng 0."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 21. Đường tròn trong mặt phẳng toạ độ","req":["Lập phương trình đường tròn khi biết tâm và bán kính, hoặc các điều kiện khác; nhận dạng phương trình đường tròn.","Viết phương trình tiếp tuyến của đường tròn tại một điểm thuộc đường tròn."],"m":[{"t":"Lập phương trình đường tròn và tiếp tuyến","w":"Đề cho tâm và bán kính, tâm và một điểm, đường kính AB, ba điểm, hoặc tâm và đường thẳng tiếp xúc; hoặc hỏi tiếp tuyến tại một điểm.","s":["Xác định tâm I: trung điểm đường kính, điểm cho trước, hoặc giải hệ từ ba điểm (dạng x² + y² − 2ax − 2by + c = 0).","Xác định R: khoảng cách từ tâm đến một điểm trên đường tròn, hoặc khoảng cách từ tâm đến đường thẳng tiếp xúc.","Viết (x − a)² + (y − b)² = R².","Tiếp tuyến tại M₀: dùng →IM₀ làm pháp tuyến."],"n":["Từ dạng khai triển, hệ số của x là −2a nên a = −(hệ số)/2.","Kiểm tra a² + b² − c > 0 trước khi kết luận là đường tròn."]}],"sum":["Đường tròn tâm I(a; b), bán kính R là tập hợp các điểm M(x; y) sao cho IM = R.","Khái niệm: Đường tròn tâm I(a; b), bán kính R là tập hợp các điểm M(x; y) sao cho IM = R.","Phương trình x² + y² − 2ax…: Phương trình x² + y² − 2ax − 2by + c = 0 là phương trình đường tròn khi và chỉ khi a² + b² − c > 0; khi đó tâm là I(a; b) và bán kính R = √(a² + b²…","Tiếp tuyến của đường tròn tâm I…: Tiếp tuyến của đường tròn tâm I tại điểm M₀(x₀; y₀) thuộc đường tròn là đường thẳng đi qua M₀ và nhận →IM₀ = (x₀ − a; y₀ − b) làm vectơ pháp tuyến."],"e":["Lưu ý: Từ dạng khai triển, hệ số của x là −2a nên a = −(hệ số)/2.","Lưu ý: Kiểm tra a² + b² − c > 0 trước khi kết luận là đường tròn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 22. Ba đường conic","req":["Nhận biết elip, hypebol, parabol và phương trình chính tắc của chúng.","Xác định tiêu điểm, đỉnh, độ dài trục, tiêu cự; lập phương trình chính tắc từ điều kiện cho trước."],"m":[{"t":"Xác định các yếu tố của conic từ phương trình chính tắc","w":"Đề cho phương trình chính tắc và hỏi tiêu điểm, đỉnh, độ dài trục, tiêu cự; hoặc cho các yếu tố và yêu cầu lập phương trình chính tắc.","s":["Đưa phương trình về đúng dạng chính tắc (vế phải bằng 1 hoặc dạng y² = 2px).","Đọc a², b² (hoặc p); tính c² = a² − b² với elip, c² = a² + b² với hypebol.","Suy ra tiêu điểm (±c; 0), đỉnh, độ dài các trục, tiêu cự 2c.","Lập phương trình: tìm a, b (hoặc p) từ các điều kiện rồi thay vào."],"n":["Với elip a > b; với hypebol không cần a > b.","Điểm thuộc conic thì toạ độ thoả mãn phương trình: dùng để lập phương trình."]}],"sum":["Elip: cho hai điểm F₁, F₂ cố định với F₁F₂ = 2c > 0 và số a > c. Tập hợp các điểm M sao cho MF₁ + MF₂ = 2a là elip;","Elip: Cho hai điểm F₁, F₂ cố định với F₁F₂ = 2c > 0 và số a > c.","Hypebol: Cho F₁F₂ = 2c và số a với 0 < a < c.","Parabol: Cho điểm F và đường thẳng Δ không đi qua F."],"e":["Hay nhầm: Đó là đường chuẩn x = −3.","Hay nhầm: Đó là hoành độ tiêu điểm.","Hay nhầm: Đường chuẩn song song Oy.","Lưu ý: Với elip a > b; với hypebol không cần a > b.","Lưu ý: Điểm thuộc conic thì toạ độ thoả mãn phương trình: dùng để lập phương trình."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương VIII. Đại số tổ hợp","l":[{"t":"Bài 23. Quy tắc đếm","req":["Vận dụng quy tắc cộng và quy tắc nhân để đếm số phương án, số cách chọn.","Dùng sơ đồ hình cây để mô tả và đếm."],"m":[{"t":"Đếm bằng quy tắc cộng và quy tắc nhân","w":"Đề hỏi số cách chọn, số số tự nhiên lập được, số đường đi, số cách sắp xếp đơn giản.","s":["Phân tích công việc: các phương án loại trừ nhau (cộng) hay các bước nối tiếp (nhân).","Với bài lập số: xét từng chữ số từ ràng buộc chặt nhất (chữ số đầu khác 0, chữ số cuối chẵn/lẻ), nhân số cách lại.","Nếu các trường hợp khác nhau về cách đếm thì chia trường hợp rồi cộng.","Bài \"ít nhất\" thì dùng phần bù."],"n":["Chữ số hàng cao nhất khác 0.","\"Đôi một khác nhau\" làm số lựa chọn giảm dần sau mỗi bước."]}],"sum":["Quy tắc cộng: một công việc có thể thực hiện theo một trong hai phương án; phương án thứ nhất có m cách, phương án thứ hai có n cách (không trùng nhau) thì công việc có m + n cách thực hiện.","Quy tắc cộng: Một công việc có thể thực hiện theo một trong hai phương án; phương án thứ nhất có m cách, phương án thứ hai có n cách (không trùng nhau) thì công…","Quy tắc nhân: Một công việc gồm hai công đoạn liên tiếp; công đoạn thứ nhất có m cách, với mỗi cách đó công đoạn thứ hai có n cách thì công việc có m·n cách thực…","Sơ đồ hình cây: Vẽ các nhánh ứng với từng lựa chọn ở mỗi công đoạn; số đường đi từ gốc đến ngọn là số kết quả.","Phần bù: Đếm số kết quả không thoả mãn rồi lấy tổng trừ đi, thường gọn hơn khi điều kiện có từ \"ít nhất\"."],"e":["Hay nhầm: Nhân dùng cho các bước nối tiếp.","Lưu ý: Chữ số hàng cao nhất khác 0.","Lưu ý: \"Đôi một khác nhau\" làm số lựa chọn giảm dần sau mỗi bước."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 24. Hoán vị, chỉnh hợp và tổ hợp","req":["Phân biệt và tính số hoán vị, chỉnh hợp, tổ hợp.","Vận dụng vào bài toán đếm thực tế."],"m":[{"t":"Chọn công thức đếm phù hợp","w":"Đề hỏi số cách xếp, chọn người vào các chức vụ, chọn nhóm, lập số, chọn đường chéo, tam giác… từ một tập hợp.","s":["Hỏi \"có kể thứ tự không?\": lấy hết và xếp → hoán vị; lấy một phần và xếp → chỉnh hợp; lấy một phần không xếp → tổ hợp.","Xác định n (tổng số phần tử) và k (số phần tử lấy).","Tính theo công thức; với bài có điều kiện kèm theo, kết hợp quy tắc cộng, nhân.","Kiểm tra lại bằng cách thử với số nhỏ nếu nghi ngờ."],"n":["C_n^k = C_n^(n−k) giúp tính nhanh.","Chọn ban cán sự gồm các chức vụ khác nhau là chỉnh hợp; chọn tổ trực nhật là tổ hợp."]}],"sum":["Hoán vị: mỗi cách sắp xếp n phần tử (n ≥ 1) theo một thứ tự là một hoán vị của n phần tử. Số hoán vị là P_n = n! = n(n − 1)···2·1.","Hoán vị: Mỗi cách sắp xếp n phần tử (n ≥ 1) theo một thứ tự là một hoán vị của n phần tử.","Chỉnh hợp: Mỗi cách lấy k phần tử từ n phần tử (1 ≤ k ≤ n) và sắp xếp chúng theo một thứ tự là một chỉnh hợp chập k của n.","Tổ hợp: Mỗi cách lấy k phần tử từ n phần tử (0 ≤ k ≤ n) không kể thứ tự là một tổ hợp chập k của n.","Phân biệt: Có sắp thứ tự (chức vụ khác nhau, xếp hàng, lập số) thì dùng chỉnh hợp hoặc hoán vị; chỉ chọn ra một nhóm không phân biệt vai trò thì dùng tổ hợp."],"e":["Lưu ý: C_n^k = C_n^(n−k) giúp tính nhanh.","Lưu ý: Chọn ban cán sự gồm các chức vụ khác nhau là chỉnh hợp; chọn tổ trực nhật là tổ hợp."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 25. Nhị thức Newton","req":["Khai triển (a + b)ⁿ với n = 4, 5 bằng công thức nhị thức Newton và tam giác Pascal.","Tìm hệ số, số hạng trong khai triển; tính tổng các hệ số."],"m":[{"t":"Tìm hệ số của một số hạng trong khai triển","w":"Đề cho (ax + b)ⁿ hoặc (x + c/x)ⁿ với n ≤ 5 và hỏi hệ số của xᵏ, số hạng không chứa x, hoặc tổng các hệ số.","s":["Viết số hạng tổng quát C_n^k (ax)ⁿ⁻ᵏ bᵏ.","Rút gọn thành hệ số · x^(số mũ); lập phương trình số mũ bằng giá trị đề hỏi để tìm k.","Thay k vào để tính hệ số (nhớ dấu nếu có −).","Tổng hệ số: thay x = 1."],"n":["Hệ số khác với số hạng: số hạng chứa cả x.","Với (a − b)ⁿ chú ý dấu (−1)ᵏ."]}],"sum":["Tổng quát (a + b)ⁿ = C_n^0 aⁿ + C_n^1 aⁿ⁻¹b + C_n^2 aⁿ⁻²b² + ... + C_n^n bⁿ. Số hạng thứ k + 1 là C_n^k aⁿ⁻ᵏ bᵏ.","Công thức","Tổng quát (a + b)ⁿ = C_n^0…: Tổng quát (a + b)ⁿ = C_n^0 aⁿ + C_n^1 aⁿ⁻¹b + C_n^2 aⁿ⁻²b² + ... + C_n^n bⁿ.","Khai triển (a − b)ⁿ: Thay b bằng −b, dấu các số hạng đan xen + −."],"e":["Lưu ý: Hệ số khác với số hạng: số hạng chứa cả x.","Lưu ý: Với (a − b)ⁿ chú ý dấu (−1)ᵏ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương IX. Tính xác suất theo định nghĩa cổ điển","l":[{"t":"Bài 26. Biến cố và định nghĩa cổ điển của xác suất","req":["Mô tả không gian mẫu, biến cố, biến cố đối của một phép thử.","Tính xác suất theo định nghĩa cổ điển."],"m":[{"t":"Tính xác suất theo định nghĩa cổ điển","w":"Đề mô tả một phép thử (gieo xúc xắc, đồng xu, rút thẻ, chọn người) và hỏi xác suất của một biến cố.","s":["Xác định không gian mẫu và đếm n(Ω) (liệt kê hoặc dùng quy tắc đếm).","Mô tả biến cố A bằng tập hợp hoặc điều kiện; đếm n(A).","P(A) = n(A)/n(Ω), rút gọn phân số.","Nếu A phức tạp (\"ít nhất\"), tính P(Ā) rồi lấy 1 trừ đi."],"n":["Gieo hai xúc xắc: n(Ω) = 36 và các cặp (i; j) có thứ tự.","Kết quả phải đồng khả năng mới dùng được định nghĩa cổ điển."]}],"sum":["Phép thử ngẫu nhiên là một thí nghiệm hay hành động mà kết quả không đoán trước được nhưng biết được tập hợp tất cả các kết quả có thể.","Khái niệm: Phép thử ngẫu nhiên là một thí nghiệm hay hành động mà kết quả không đoán trước được nhưng biết được tập hợp tất cả các kết quả có thể.","Biến cố là một tập con của không gian mẫu: Biến cố xảy ra khi kết quả của phép thử thuộc tập con đó.","Biến cố đối của A, kí hiệu Ā, là biến cố \"A không xảy ra\": Ā = Ω \\ A.","Khi các kết quả của phép thử…: Khi các kết quả của phép thử đồng khả năng, xác suất của biến cố A bằng số kết quả thuận lợi cho A chia cho tổng số kết quả có thể."],"e":["Lưu ý: Gieo hai xúc xắc: n(Ω) = 36 và các cặp (i; j) có thứ tự.","Lưu ý: Kết quả phải đồng khả năng mới dùng được định nghĩa cổ điển."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 27. Thực hành tính xác suất theo định nghĩa cổ điển","req":["Dùng phương pháp tổ hợp, sơ đồ hình cây để tính xác suất.","Dùng xác suất của biến cố đối để tính xác suất của biến cố \"ít nhất\"."],"m":[{"t":"Tính xác suất bằng tổ hợp và biến cố đối","w":"Đề cho hộp bi, nhóm người, bộ thẻ… và hỏi xác suất chọn được nhóm thoả điều kiện, hoặc \"ít nhất\", \"có đủ\", \"không có\".","s":["n(Ω) = C_n^k khi chọn k trong n không kể thứ tự.","Đếm n(A) bằng cách chia theo thành phần (ví dụ 2 đỏ và 1 xanh: C_a^2·C_b^1); nếu có nhiều trường hợp thì cộng.","Với \"ít nhất một\": tính P(không có) rồi lấy 1 trừ.","Rút gọn phân số."],"n":["Không cộng các trường hợp trùng nhau.","Kiểm tra n(A) ≤ n(Ω)."]}],"sum":["Phương pháp tổ hợp: khi phép thử là chọn ngẫu nhiên k phần tử từ n phần tử (không kể thứ tự) thì n(Ω) = C_n^k; số kết quả thuận lợi cũng đếm bằng tổ hợp kết hợp quy tắc nhân.","Phương pháp tổ hợp: Khi phép thử là chọn ngẫu nhiên k phần tử từ n phần tử (không kể thứ tự) thì n(Ω) = C_n^k; số kết quả thuận lợi cũng đếm bằng tổ hợp kết hợp quy tắc…","Sơ đồ hình cây: Khi phép thử gồm nhiều giai đoạn với ít kết quả mỗi giai đoạn (gieo đồng xu vài lần, bốc thẻ lần lượt), vẽ sơ đồ hình cây để liệt kê đầy đủ không…","Với biến cố dạng \"có ít nhất…: Với biến cố dạng \"có ít nhất một ...\" hoặc \"không phải tất cả ...\", biến cố đối thường dễ đếm hơn: \"không có ... nào\" hoặc \"tất cả đều ...\".","Lưu ý khi đếm: \"lấy đồng thời\" hoặc \"lấy ngẫu nhiên k vật\" dùng tổ hợp;"],"e":["Hay nhầm: Thiếu các trường hợp 2, 3, 4 lần.","Lưu ý: Không cộng các trường hợp trùng nhau.","Lưu ý: Kiểm tra n(A) ≤ n(Ω)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 10","c":[{"t":"Chương I. Mở đầu","l":[{"t":"Bài 1. Làm quen với Vật lí","req":["Nêu được đối tượng nghiên cứu, mục tiêu của Vật lí và các phương pháp nghiên cứu.","Nêu được ảnh hưởng của Vật lí đối với đời sống và sự phát triển của khoa học, công nghệ."],"sum":["Đối tượng nghiên cứu của Vật lí là các dạng vận động của vật chất và năng lượng. Mục tiêu của Vật lí là khám phá ra các quy luật tổng quát nhất chi phối sự vận động của vật chất và năng lượng, cũng…","Khái niệm: Đối tượng nghiên cứu của Vật lí là các dạng vận động của vật chất và năng lượng.","Các lĩnh vực của Vật lí: Cơ học, điện học, quang học, nhiệt học, âm học, vật lí nguyên tử và hạt nhân, thiên văn học...","Phương pháp nghiên cứu: Phương pháp thực nghiệm (quan sát, đặt giả thuyết, thiết kế và tiến hành thí nghiệm kiểm tra, rút ra kết luận) và phương pháp lí thuyết (dùng ngôn…","Quá trình phát triển của Vật lí: Giai đoạn tiền Vật lí (từ năm 350 TCN với Aristotle), giai đoạn Vật lí cổ điển (từ thế kỉ XVII với Galilei, Newton), và Vật lí hiện đại (từ cuối thế…","Ảnh hưởng của Vật lí: Là cơ sở của khoa học tự nhiên và công nghệ; các cuộc cách mạng công nghiệp gắn với thành tựu vật lí (máy hơi nước – lần 1;"],"e":["Hay nhầm: Lí thuyết dùng suy luận toán học.","Hay nhầm: Chưa có thí nghiệm lúc dự đoán.","Hay nhầm: Vật lí nghiên cứu cả vi mô.","Hay nhầm: Không so sánh được khối lượng."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 2. Các quy tắc an toàn trong phòng thực hành Vật lí","req":["Nhận biết các nguy cơ mất an toàn khi làm thí nghiệm với điện, nhiệt, hoá chất, vật sắc nhọn, phóng xạ.","Thực hiện được các quy tắc an toàn và hiểu ý nghĩa các biển báo trong phòng thực hành."],"sum":["Các nguy cơ mất an toàn trong phòng thực hành: điện giật (dây điện hở, nguồn điện cao áp), bỏng (nguồn nhiệt, nước sôi), cháy nổ (chất dễ cháy, bình khí nén), chấn thương do vật sắc nhọn hoặc vật…","Các nguy cơ mất an toàn trong phòng thực hành: Điện giật (dây điện hở, nguồn điện cao áp), bỏng (nguồn nhiệt, nước sôi), cháy nổ (chất dễ cháy, bình khí nén), chấn thương do vật sắc nhọn hoặc vật…","Quy tắc an toàn khi dùng điện: Đọc kĩ hướng dẫn và kiểm tra thiết bị trước khi dùng; chỉ cắm điện khi đã lắp mạch đúng và được giáo viên cho phép; không chạm vào phần kim loại hở;…","Quy tắc khi dùng nguồn nhiệt và hoá chất: Dùng kẹp, găng tay khi tiếp xúc vật nóng; không nếm, ngửi trực tiếp hoá chất;","Quy tắc chung: Mặc trang phục gọn gàng, buộc tóc; không ăn uống, đùa nghịch; làm thí nghiệm đúng hướng dẫn, dưới sự giám sát của giáo viên; biết vị trí bình chữa…","Biển báo an toàn: Biển cấm (viền đỏ, hình tròn: cấm lửa, cấm chạm tay), biển cảnh báo (tam giác vàng viền đen: điện cao áp, nhiệt độ cao, chất độc, phóng xạ), biển…"],"e":["Hay nhầm: Biển cấm hình tròn viền đỏ.","Hay nhầm: Biển chỉ dẫn hình chữ nhật xanh lá.","Hay nhầm: Có thể gây nổ hơi nước, bỏng.","Hay nhầm: Nước dẫn điện, nguy hiểm."],"q":{"n":12,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 3. Thực hành tính sai số trong phép đo. Ghi kết quả đo","req":["Phân biệt phép đo trực tiếp và gián tiếp; sai số hệ thống và sai số ngẫu nhiên.","Tính sai số tuyệt đối, sai số tỉ đối và ghi kết quả đo đúng quy tắc."],"m":[{"t":"Tính sai số và ghi kết quả đo","w":"Đề cho bảng các lần đo một đại lượng, độ chia nhỏ nhất của dụng cụ; yêu cầu tính giá trị trung bình, sai số và viết kết quả; hoặc tính sai số của đại lượng đo gián tiếp.","s":["Tính giá trị trung bình Ā.","Tính sai số tuyệt đối từng lần |A_i − Ā| rồi lấy trung bình được ΔĀ.","Cộng sai số dụng cụ: ΔA = ΔĀ + ΔA_dc; tính δA = ΔA/Ā·100%.","Làm tròn và ghi A = Ā ± ΔA. Với đại lượng gián tiếp dùng quy tắc cộng sai số tuyệt đối (tổng, hiệu) hoặc cộng sai số tỉ đối (tích, thương)."],"n":["Sai số dụng cụ không bỏ qua khi đề cho.","Số chữ số thập phân của Ā phải khớp với ΔA."]}],"sum":["Phép đo trực tiếp: đo đại lượng bằng dụng cụ đo và đọc kết quả trực tiếp (đo chiều dài bằng thước).","Phép đo trực tiếp: Đo đại lượng bằng dụng cụ đo và đọc kết quả trực tiếp (đo chiều dài bằng thước).","Sai số hệ thống: Do dụng cụ đo (độ chia nhỏ nhất, dụng cụ sai lệch) hoặc do cách đo, có giá trị và dấu xác định, thường làm kết quả lệch về một phía; khắc phục bằng…","Sai số của phép đo gián tiếp: Nếu A = B + C hoặc A = B − C thì ΔA = ΔB + ΔC.","Quy tắc ghi kết quả: Sai số tuyệt đối làm tròn đến một hoặc hai chữ số có nghĩa; giá trị trung bình làm tròn đến cùng hàng với sai số."],"e":["Hay nhầm: Gián tiếp phải tính qua công thức.","Hay nhầm: Hệ thống lệch về một phía, không triệt tiêu khi lấy trung bình.","Hay nhầm: Không giảm khi đo nhiều lần.","Hay nhầm: Một lần không giảm sai số ngẫu nhiên.","Lưu ý: Sai số dụng cụ không bỏ qua khi đề cho.","Lưu ý: Số chữ số thập phân của Ā phải khớp với ΔA."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương II. Động học","l":[{"t":"Bài 4. Độ dịch chuyển và quãng đường đi được","req":["Phân biệt vị trí, quãng đường đi được và độ dịch chuyển; nêu được độ dịch chuyển là đại lượng vectơ.","Xác định độ dịch chuyển tổng hợp và quãng đường trong các bài toán đơn giản."],"m":[{"t":"Xác định quãng đường và độ dịch chuyển","w":"Đề mô tả hành trình gồm nhiều đoạn (đi, quay lại, rẽ vuông góc) và hỏi quãng đường, độ dịch chuyển.","s":["Vẽ sơ đồ hành trình, chọn gốc và chiều dương.","Quãng đường: cộng độ dài tất cả các đoạn.","Độ dịch chuyển: nối điểm đầu với điểm cuối; cùng phương thì cộng có dấu, vuông góc thì dùng Pythagore; nêu cả hướng.","So sánh và kết luận."],"n":["Vật về đúng chỗ cũ thì độ dịch chuyển bằng 0 dù quãng đường khác 0.","Độ dịch chuyển có thể âm khi chọn chiều dương ngược lại."]}],"sum":["Để xác định vị trí của vật, ta chọn một vật làm gốc (mốc), hệ trục toạ độ gắn với mốc và một mốc thời gian (đồng hồ).","Khái niệm: Để xác định vị trí của vật, ta chọn một vật làm gốc (mốc), hệ trục toạ độ gắn với mốc và một mốc thời gian (đồng hồ).","Quãng đường đi được s là độ…: Quãng đường đi được s là độ dài của đường đi mà vật vạch ra; là đại lượng vô hướng, không âm, luôn tăng khi vật chuyển động.","Độ dịch chuyển →d là vectơ nối…: Độ dịch chuyển →d là vectơ nối vị trí đầu với vị trí cuối của vật; cho biết vật dịch chuyển bao xa theo hướng nào.","Khi hai độ dịch chuyển vuông góc…: Khi hai độ dịch chuyển vuông góc nhau, độ lớn độ dịch chuyển tổng hợp tính bằng định lí Pythagore: d = √(d₁² + d₂²)."],"e":["Hay nhầm: Độ dịch chuyển có hướng, có thể âm.","Lưu ý: Vật về đúng chỗ cũ thì độ dịch chuyển bằng 0 dù quãng đường khác 0.","Lưu ý: Độ dịch chuyển có thể âm khi chọn chiều dương ngược lại."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 5. Tốc độ và vận tốc","req":["Phân biệt tốc độ trung bình, tốc độ tức thời, vận tốc trung bình, vận tốc tức thời.","Tính tốc độ, vận tốc; tổng hợp vận tốc trong trường hợp cùng phương và vuông góc."],"m":[{"t":"Tính vận tốc trung bình và tổng hợp vận tốc","w":"Đề cho hành trình nhiều đoạn với thời gian hoặc tốc độ từng đoạn, hoặc bài thuyền – dòng nước, máy bay – gió.","s":["Tốc độ trung bình: tổng quãng đường chia tổng thời gian (không lấy trung bình cộng các tốc độ).","Vận tốc trung bình: độ dịch chuyển chia tổng thời gian.","Tổng hợp vận tốc: xác định ba vật (vật, môi trường, bờ), viết →v₁₃ = →v₁₂ + →v₂₃ rồi cộng theo phương.","Đổi đơn vị thống nhất (m/s hoặc km/h)."],"n":["Đi hai đoạn bằng nhau với tốc độ v₁, v₂ thì tốc độ trung bình là 2v₁v₂/(v₁ + v₂).","Ngược dòng thì vận tốc so với bờ nhỏ hơn."]}],"sum":["Tốc độ trung bình cho biết mức độ nhanh chậm của chuyển động, là đại lượng vô hướng. Vận tốc trung bình cho biết cả mức độ nhanh chậm và hướng chuyển động, là đại lượng vectơ.","Công thức","Tốc độ trung bình cho biết mức…: Tốc độ trung bình cho biết mức độ nhanh chậm của chuyển động, là đại lượng vô hướng.","Tốc độ tức thời là tốc độ…: Tốc độ tức thời là tốc độ tại một thời điểm (số chỉ tốc kế); vận tốc tức thời là vận tốc tại một thời điểm, có hướng của chuyển động tại thời điểm…","Đơn vị: M/s, km/h;","Cùng chiều: V₁₃ = v₁₂ + v₂₃ (thuyền xuôi dòng); ngược chiều: v₁₃ = |v₁₂ − v₂₃| (thuyền ngược dòng); vuông góc: v₁₃ = √(v₁₂² + v₂₃²) (thuyền bơi ngang sông)."],"e":["Lưu ý: Đi hai đoạn bằng nhau với tốc độ v₁, v₂ thì tốc độ trung bình là 2v₁v₂/(v₁ + v₂).","Lưu ý: Ngược dòng thì vận tốc so với bờ nhỏ hơn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 6. Thực hành: Đo tốc độ của vật chuyển động","req":["Mô tả cách đo tốc độ bằng đồng hồ bấm giây, cổng quang điện và đồng hồ đo thời gian hiện số.","Tính tốc độ trung bình, tốc độ tức thời từ số liệu và đánh giá sai số."],"m":[{"t":"Xử lí số liệu đo tốc độ","w":"Đề cho bảng số liệu quãng đường, thời gian (nhiều lần đo), hoặc bề rộng tấm chắn và thời gian chắn cổng; hỏi tốc độ và sai số.","s":["Tính thời gian trung bình t̄ và sai số Δt.","v̄ = s/t̄ (tốc độ trung bình) hoặc v = d/Δt (tốc độ tức thời).","Sai số tỉ đối δv = δs + δt; Δv = δv · v̄.","Ghi kết quả v = v̄ ± Δv với đúng số chữ số."],"n":["Đổi mm, cm về m để tốc độ ra m/s.","Thời gian chắn cổng càng ngắn thì giá trị càng gần tốc độ tức thời."]}],"sum":["Đo tốc độ trung bình: đo quãng đường s bằng thước và thời gian t bằng đồng hồ bấm giây; v = s/t.","Đo tốc độ trung bình: Đo quãng đường s bằng thước và thời gian t bằng đồng hồ bấm giây; v = s/t.","Cổng quang điện gồm một nguồn phát…: Cổng quang điện gồm một nguồn phát tia hồng ngoại và một cảm biến thu; khi vật chắn tia, cổng gửi tín hiệu đến đồng hồ đo thời gian hiện số để bắt…","Đo tốc độ tức thời: Dùng một cổng quang điện và một tấm chắn sáng có bề rộng nhỏ d gắn trên xe.","Đồng hồ đo thời gian hiện số có các chế độ MODE: A (đo thời gian chắn cổng A), B, A + B (tổng), A ↔ B (thời gian từ cổng A đến cổng B).","Thiết kế phương án đo: Chọn dụng cụ, bố trí máng, xe, cổng quang; tiến hành đo nhiều lần (ít nhất 3 lần) ở cùng điều kiện; tính giá trị trung bình, sai số; viết kết quả v…"],"e":["Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: Đó là tốc độ trung bình trên đoạn dài.","Hay nhầm: Sai số đồng hồ hiện số rất nhỏ.","Hay nhầm: Sai thước gây sai số hệ thống, không gây lệch giữa các lần.","Lưu ý: Đổi mm, cm về m để tốc độ ra m/s.","Lưu ý: Thời gian chắn cổng càng ngắn thì giá trị càng gần tốc độ tức thời."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 7. Đồ thị độ dịch chuyển – thời gian","req":["Vẽ và đọc đồ thị độ dịch chuyển – thời gian của chuyển động thẳng.","Tính vận tốc từ độ dốc của đồ thị; mô tả chuyển động từ đồ thị."],"m":[{"t":"Đọc đồ thị độ dịch chuyển – thời gian","w":"Đề cho đồ thị d – t gồm các đoạn thẳng, hỏi vận tốc từng giai đoạn, quãng đường, độ dịch chuyển, thời điểm gặp nhau, mô tả chuyển động.","s":["Chia đồ thị thành các đoạn thẳng; mỗi đoạn là một giai đoạn vận tốc không đổi.","Vận tốc mỗi đoạn = độ dốc = (d cuối − d đầu)/(t cuối − t đầu), kèm dấu.","Quãng đường = tổng độ lớn các độ dịch chuyển; độ dịch chuyển tổng = d cuối − d đầu.","Hai vật gặp nhau tại giao điểm hai đồ thị (cùng d, cùng t)."],"n":["Đoạn nằm ngang là đứng yên, không phải vận tốc bằng hằng số khác 0.","Độ dốc âm nghĩa là vật đi ngược chiều dương, tốc độ vẫn dương."]}],"sum":["Chuyển động thẳng đều là chuyển động thẳng có vận tốc không đổi (tốc độ không đổi, không đổi chiều).","Khái niệm: Chuyển động thẳng đều là chuyển động thẳng có vận tốc không đổi (tốc độ không đổi, không đổi chiều).","Đồ thị độ dịch chuyển – thời…: Đồ thị độ dịch chuyển – thời gian (d – t) của chuyển động thẳng đều là một đường thẳng.","Từ đồ thị có thể đọc được…: Từ đồ thị có thể đọc được vị trí tại mỗi thời điểm, thời điểm hai vật gặp nhau (giao điểm hai đồ thị), quãng đường và độ dịch chuyển trong một…","Vận tốc tức thời tại một thời…: Vận tốc tức thời tại một thời điểm trên đồ thị cong bằng độ dốc của tiếp tuyến với đồ thị tại điểm đó."],"e":["Hay nhầm: Độ dốc đồ thị v – t mới là gia tốc.","Hay nhầm: Cùng vận tốc thì song song.","Lưu ý: Đoạn nằm ngang là đứng yên, không phải vận tốc bằng hằng số khác 0.","Lưu ý: Độ dốc âm nghĩa là vật đi ngược chiều dương, tốc độ vẫn dương."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 8. Chuyển động biến đổi. Gia tốc","req":["Nêu được khái niệm gia tốc, công thức và đơn vị; phân biệt chuyển động nhanh dần, chậm dần.","Vẽ và đọc đồ thị vận tốc – thời gian; tính gia tốc từ đồ thị."],"m":[{"t":"Tính gia tốc từ số liệu hoặc đồ thị v – t","w":"Đề cho vận tốc tại hai thời điểm, hoặc đồ thị v – t gồm các đoạn thẳng; hỏi gia tốc, loại chuyển động, độ dịch chuyển.","s":["Xác định v₀, v và khoảng thời gian Δt (đổi về m/s, s).","a = (v − v₀)/Δt, giữ dấu; so dấu a với dấu v để kết luận nhanh dần hay chậm dần.","Trên đồ thị v – t: a mỗi đoạn là độ dốc; độ dịch chuyển là diện tích hình thang hoặc tam giác dưới đồ thị.","Đổi km/h sang m/s trước khi tính."],"n":["a âm không có nghĩa là chậm dần; phải so với dấu của v.","Diện tích dưới trục t mang dấu âm (độ dịch chuyển âm)."]}],"sum":["Chuyển động biến đổi là chuyển động có vận tốc thay đổi theo thời gian. Chuyển động biến đổi đều có vận tốc thay đổi đều (độ biến thiên vận tốc trong những khoảng thời gian bằng nhau là như nhau).","Khái niệm: Chuyển động biến đổi là chuyển động có vận tốc thay đổi theo thời gian.","Gia tốc là đại lượng vectơ, cùng…: Gia tốc là đại lượng vectơ, cùng hướng với độ biến thiên vận tốc Δ→v.","Đồ thị vận tốc – thời gian (v – t): Độ dốc của đồ thị bằng gia tốc.","Gia tốc tức thời tại một thời…: Gia tốc tức thời tại một thời điểm bằng độ dốc của tiếp tuyến với đồ thị v – t tại điểm đó."],"e":["Hay nhầm: Diện tích mới là độ dịch chuyển.","Lưu ý: a âm không có nghĩa là chậm dần; phải so với dấu của v.","Lưu ý: Diện tích dưới trục t mang dấu âm (độ dịch chuyển âm)."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 9. Chuyển động thẳng biến đổi đều","req":["Vận dụng các công thức của chuyển động thẳng biến đổi đều: v = v₀ + at, d = v₀t + at²/2, v² − v₀² = 2ad.","Giải bài toán về xe tăng tốc, hãm phanh, quãng đường, thời gian."],"m":[{"t":"Giải bài toán chuyển động thẳng biến đổi đều","w":"Đề cho một số trong các đại lượng v₀, v, a, t, d và hỏi đại lượng còn lại; bài xe tăng tốc, hãm phanh, quãng đường trong giây thứ n.","s":["Chọn chiều dương là chiều chuyển động; ghi rõ v₀, v, a (dấu), t, d đã biết.","Chọn công thức không chứa đại lượng chưa biết và không cần: không có t dùng v² − v₀² = 2ad; không có d dùng v = v₀ + at; không có v dùng d = v₀t + ½at².","Giải và kiểm tra dấu: quãng đường, thời gian phải dương.","Quãng đường trong giây thứ n: d(n) − d(n − 1)."],"n":["Chậm dần đều: a âm khi chiều dương theo v₀.","Đổi km/h ra m/s trước khi tính."]}],"sum":["Chuyển động thẳng biến đổi đều là chuyển động thẳng có gia tốc không đổi (độ lớn và hướng).","Khái niệm: Chuyển động thẳng biến đổi đều là chuyển động thẳng có gia tốc không đổi (độ lớn và hướng).","Trong các công thức trên, chọn chiều…: Trong các công thức trên, chọn chiều dương là chiều chuyển động ban đầu: v₀ > 0; nhanh dần đều thì a > 0, chậm dần đều thì a < 0.","Đồ thị v – t là đường thẳng có độ dốc a: Đồ thị d – t là một nhánh parabol.","Khi vật chậm dần đều đến dừng lại: Thời gian dừng t = −v₀/a, quãng đường dừng d = −v₀²/(2a) (với a < 0)."],"e":["Lưu ý: Chậm dần đều: a âm khi chiều dương theo v₀.","Lưu ý: Đổi km/h ra m/s trước khi tính."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 10. Sự rơi tự do","req":["Nêu được đặc điểm của sự rơi tự do và gia tốc rơi tự do.","Vận dụng công thức rơi tự do để tính thời gian rơi, vận tốc chạm đất, độ cao."],"m":[{"t":"Bài toán rơi tự do","w":"Đề cho độ cao, thời gian rơi hoặc vận tốc chạm đất và hỏi các đại lượng còn lại; quãng đường trong giây cuối; so sánh hai vật thả cách nhau một khoảng thời gian.","s":["Chọn gốc tại vị trí thả, chiều dương hướng xuống, v₀ = 0, a = g.","Dùng h = ½gt², v = gt, v² = 2gh tuỳ dữ kiện.","Quãng đường trong giây cuối: h(t) − h(t − 1).","Với bài ném thẳng đứng dùng v₀ ≠ 0 và a = −g nếu chọn chiều dương hướng lên."],"n":["Rơi tự do không phụ thuộc khối lượng.","Lấy g theo đề (9,8 hoặc 10 m/s²)."]}],"sum":["Trong không khí, các vật rơi nhanh chậm khác nhau chủ yếu do lực cản của không khí. Trong chân không (ống Newton), mọi vật rơi như nhau.","Khái niệm: Trong không khí, các vật rơi nhanh chậm khác nhau chủ yếu do lực cản của không khí.","Đặc điểm: Rơi tự do là chuyển động thẳng nhanh dần đều theo phương thẳng đứng, chiều từ trên xuống, với gia tốc rơi tự do g.","Vật rơi tự do từ độ cao…: Vật rơi tự do từ độ cao h chạm đất sau thời gian t = √(2h/g) với vận tốc v = √(2gh).","Đo gia tốc rơi tự do: Thả vật qua hai cổng quang điện hoặc đo thời gian rơi trên quãng đường h đã biết, rồi tính g = 2h/t²."],"e":["Lưu ý: Rơi tự do không phụ thuộc khối lượng.","Lưu ý: Lấy g theo đề (9,8 hoặc 10 m/s²)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 11. Thực hành: Đo gia tốc rơi tự do","req":["Thiết kế và thực hiện phương án đo gia tốc rơi tự do bằng cổng quang điện và đồng hồ đo thời gian hiện số.","Xử lí số liệu, tính g và sai số của phép đo."],"m":[{"t":"Tính g và sai số từ số liệu thực hành","w":"Đề cho h, các lần đo t; hỏi ḡ, Δg hoặc so sánh với giá trị 9,8 m/s².","s":["Tính t̄ và Δt.","ḡ = 2h/t̄².","δg = δh + 2δt (vì g tỉ lệ nghịch với t²); Δg = δg·ḡ.","Ghi g = ḡ ± Δg, so sánh với 9,8 m/s²."],"n":["Sai số của t được nhân đôi.","h là khoảng cách từ vị trí xuất phát của bi đến cổng quang."]}],"sum":["Cơ sở lí thuyết: vật rơi tự do từ trạng thái nghỉ đi được quãng đường h trong thời gian t thì h = ½gt², suy ra g = 2h/t².","Cơ sở lí thuyết: Vật rơi tự do từ trạng thái nghỉ đi được quãng đường h trong thời gian t thì h = ½gt², suy ra g = 2h/t².","Dụng cụ: Giá đỡ thẳng đứng có thước, nam châm điện giữ viên bi thép, cổng quang điện, đồng hồ đo thời gian hiện số (chế độ A ↔ B hoặc nam châm → cổng quang),…","Tiến hành: Điều chỉnh giá thẳng đứng bằng dây dọi;","Xử lí: Với mỗi h tính t̄, ḡ = 2h/t̄², sai số δg = δh + 2δt.","Nguyên nhân sai số: Giá không thẳng đứng, bi không rơi từ nghỉ (còn vận tốc đầu do nam châm nhả chậm), đo h không chính xác (từ tâm bi đến tia cổng quang), lực cản…"],"e":["Hay nhầm: Có vận tốc đầu, sai số lớn.","Hay nhầm: Dùng để chỉnh thẳng đứng.","Hay nhầm: Bi thép nặng, lực cản nhỏ.","Hay nhầm: g không thay đổi nhiều như vậy.","Lưu ý: Sai số của t được nhân đôi.","Lưu ý: h là khoảng cách từ vị trí xuất phát của bi đến cổng quang."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}},{"t":"Bài 12. Chuyển động ném","req":["Mô tả chuyển động ném ngang như tổng hợp của chuyển động thẳng đều theo phương ngang và rơi tự do theo phương thẳng đứng.","Tính thời gian rơi, tầm xa, vận tốc chạm đất của vật ném ngang; mô tả định tính chuyển động ném xiên."],"m":[{"t":"Bài toán ném ngang","w":"Đề cho độ cao và vận tốc ném ngang (hoặc tầm xa) và hỏi thời gian, tầm xa, vận tốc chạm đất, vị trí sau t giây.","s":["Chọn gốc tại điểm ném, Ox ngang theo v₀, Oy hướng xuống.","Thời gian rơi từ phương đứng: t = √(2h/g).","Tầm xa từ phương ngang: L = v₀t; ngược lại v₀ = L/t.","Vận tốc tại thời điểm t: v_x = v₀, v_y = gt, v = √(v_x² + v_y²); góc với phương ngang: tan β = v_y/v_x."],"n":["Thời gian rơi không phụ thuộc v₀.","Đổi km/h ra m/s."]}],"sum":["Chuyển động ném ngang: vật được ném với vận tốc đầu →v₀ theo phương ngang từ độ cao h, chỉ chịu tác dụng của trọng lực (bỏ qua lực cản).","Chuyển động ném ngang: Vật được ném với vận tốc đầu →v₀ theo phương ngang từ độ cao h, chỉ chịu tác dụng của trọng lực (bỏ qua lực cản).","Thời gian rơi của vật ném ngang…: Thời gian rơi của vật ném ngang bằng thời gian rơi tự do từ cùng độ cao, không phụ thuộc v₀.","Chuyển động ném xiên: Vật ném với →v₀ hợp với phương ngang góc α."],"e":["Lưu ý: Thời gian rơi không phụ thuộc v₀.","Lưu ý: Đổi km/h ra m/s."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chương III. Động lực học","l":[{"t":"Bài 13. Tổng hợp và phân tích lực. Cân bằng lực","req":["Tổng hợp hai lực đồng quy bằng quy tắc hình bình hành; phân tích một lực thành hai lực thành phần vuông góc.","Nêu điều kiện cân bằng của chất điểm; vận dụng để tính lực."],"m":[{"t":"Tổng hợp lực và bài toán cân bằng","w":"Đề cho hai lực đồng quy và góc giữa chúng, hỏi hợp lực; hoặc vật cân bằng dưới tác dụng của nhiều lực, hỏi lực chưa biết.","s":["Vẽ hình, xác định các lực và góc giữa chúng.","Hai lực: dùng F² = F₁² + F₂² + 2F₁F₂cos α hoặc các trường hợp đặc biệt.","Nhiều lực, cân bằng: chọn hệ trục Ox, Oy; chiếu mọi lực lên hai trục; cho tổng hình chiếu bằng 0 trên mỗi trục rồi giải.","Kiểm tra: hợp lực nằm trong khoảng |F₁ − F₂| đến F₁ + F₂."],"n":["Ba lực cân bằng thì một lực bằng và ngược chiều với hợp lực của hai lực còn lại.","Góc giữa hai lực, không phải góc với phương ngang."]}],"sum":["Lực là đại lượng vectơ đặc trưng cho tác dụng của vật này lên vật khác, làm vật biến dạng hoặc thay đổi vận tốc.","Khái niệm: Lực là đại lượng vectơ đặc trưng cho tác dụng của vật này lên vật khác, làm vật biến dạng hoặc thay đổi vận tốc.","Tổng hợp lực là thay thế nhiều…: Tổng hợp lực là thay thế nhiều lực đồng thời tác dụng lên vật bằng một lực có tác dụng giống hệt (hợp lực).","Trường hợp đặc biệt: Cùng chiều F = F₁ + F₂; ngược chiều F = |F₁ − F₂|; vuông góc F = √(F₁² + F₂²).","Phân tích lực là thay một lực…: Phân tích lực là thay một lực bằng hai hay nhiều lực có tác dụng giống hệt lực đó; thường phân tích theo hai phương vuông góc: F_x = F·cos α, F_y =…"],"e":["Lưu ý: Ba lực cân bằng thì một lực bằng và ngược chiều với hợp lực của hai lực còn lại.","Lưu ý: Góc giữa hai lực, không phải góc với phương ngang."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 14. Định luật 1 Newton","req":["Phát biểu định luật 1 Newton; nêu được quán tính và mức quán tính phụ thuộc khối lượng.","Giải thích các hiện tượng liên quan đến quán tính trong đời sống."],"sum":["Trước Galilei, người ta cho rằng muốn vật chuyển động thì phải có lực tác dụng (Aristotle).","Khái niệm: Trước Galilei, người ta cho rằng muốn vật chuyển động thì phải có lực tác dụng (Aristotle).","Định luật 1 Newton: Nếu một vật không chịu tác dụng của lực nào hoặc chịu tác dụng của các lực có hợp lực bằng 0 thì vật đang đứng yên sẽ tiếp tục đứng yên, đang chuyển…","Quán tính là tính chất của mọi…: Quán tính là tính chất của mọi vật có xu hướng bảo toàn vận tốc cả về hướng và độ lớn.","Khối lượng là đại lượng đặc trưng cho mức quán tính của vật: Vật có khối lượng càng lớn thì quán tính càng lớn, càng khó thay đổi vận tốc.","Ví dụ quán tính: Xe phanh gấp, người ngả về phía trước; xe tăng tốc đột ngột, người ngả về phía sau; giũ quần áo cho sạch bụi; tra cán búa bằng cách gõ cán xuống đất."],"e":["Hay nhầm: Newton phát biểu định luật sau đó.","Hay nhầm: Chuyển động đều không cần lực.","Hay nhầm: Có trọng lực và phản lực.","Hay nhầm: Mọi vật đều có quán tính."],"q":{"n":13,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 15. Định luật 2 Newton","req":["Phát biểu và vận dụng định luật 2 Newton; nêu được đơn vị niutơn.","Giải bài toán tìm gia tốc, lực, khối lượng của vật chuyển động thẳng."],"m":[{"t":"Vận dụng định luật 2 Newton","w":"Đề cho lực và khối lượng hỏi gia tốc, vận tốc, quãng đường; hoặc cho chuyển động (vận tốc, thời gian, quãng đường) hỏi lực.","s":["Chọn chiều dương (thường theo chiều chuyển động); vẽ các lực tác dụng lên vật.","Viết →F_hl = m→a; chiếu lên chiều dương để được F_hl = ma (lực ngược chiều mang dấu âm).","Nếu thiếu a, tính từ công thức động học; nếu biết a, dùng động học tìm v, d, t.","Đổi đơn vị: g → kg, km/h → m/s."],"n":["F_hl là hợp lực, không phải một lực riêng lẻ.","Lực hãm làm a âm theo chiều chuyển động."]}],"sum":["Định luật 2 Newton: Gia tốc của một vật cùng hướng với lực tác dụng lên vật. Độ lớn của gia tốc tỉ lệ thuận với độ lớn của lực và tỉ lệ nghịch với khối lượng của vật.","Định luật 2 Newton: Gia tốc của một vật cùng hướng với lực tác dụng lên vật.","Trường hợp vật chịu nhiều lực, →F…: Trường hợp vật chịu nhiều lực, →F là hợp lực của tất cả các lực tác dụng lên vật.","Từ định luật 2 thấy: Cùng một lực, vật khối lượng lớn thì gia tốc nhỏ (khó thay đổi vận tốc) – đúng với ý nghĩa khối lượng là mức quán tính.","Kết hợp với động học: Tính a = F/m rồi dùng v = v₀ + at, d = v₀t + ½at², v² − v₀² = 2ad; hoặc ngược lại tìm a từ động học rồi tính lực F = ma."],"e":["Hay nhầm: A nhẹ hơn nên quán tính nhỏ hơn.","Lưu ý: F_hl là hợp lực, không phải một lực riêng lẻ.","Lưu ý: Lực hãm làm a âm theo chiều chuyển động."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 16. Định luật 3 Newton","req":["Phát biểu định luật 3 Newton; nêu đặc điểm của lực và phản lực.","Vận dụng định luật 3 giải thích hiện tượng và tính lực tương tác."],"m":[{"t":"Vận dụng định luật 3 Newton","w":"Đề mô tả hai vật tương tác (va chạm, đẩy nhau, kéo nhau) và hỏi lực hoặc gia tốc của vật còn lại; hoặc nhận diện cặp lực – phản lực.","s":["Xác định hai vật tương tác và lực mỗi vật chịu.","Độ lớn: F_AB = F_BA.","Gia tốc mỗi vật: a = F/m, ngược chiều nhau; nếu biết thời gian tương tác thì Δv = aΔt.","Cặp lực – phản lực phải đặt lên hai vật khác nhau, cùng bản chất."],"n":["Lực và phản lực không triệt tiêu nhau.","Vật nhẹ hơn chịu gia tốc lớn hơn."]}],"sum":["Định luật 3 Newton: Trong mọi trường hợp, khi vật A tác dụng lên vật B một lực thì vật B cũng tác dụng lại vật A một lực.","Định luật 3 Newton: Trong mọi trường hợp, khi vật A tác dụng lên vật B một lực thì vật B cũng tác dụng lại vật A một lực.","Một trong hai lực gọi là lực…: Một trong hai lực gọi là lực tác dụng, lực kia gọi là phản lực.","Phân biệt với cặp lực cân bằng: Hai lực cân bằng đặt vào cùng một vật và có thể khác loại (trọng lực và phản lực của bàn lên sách).","Vì lực bằng nhau nhưng khối lượng…: Vì lực bằng nhau nhưng khối lượng khác nhau nên gia tốc của hai vật khác nhau: m_A·a_A = m_B·a_B."],"e":["Hay nhầm: Không cân bằng vì đặt vào hai vật.","Hay nhầm: Quán tính không làm tăng tốc.","Hay nhầm: Đó là cặp cân bằng với trọng lực.","Hay nhầm: Đó là phản lực của lực bàn đẩy sách.","Hay nhầm: Hoạt động cả trong chân không.","Lưu ý: Lực và phản lực không triệt tiêu nhau."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 17. Trọng lực và lực căng","req":["Nêu được trọng lực, trọng tâm, trọng lượng; phân biệt khối lượng và trọng lượng.","Nêu đặc điểm của lực căng dây; vận dụng tính lực căng khi vật cân bằng."],"m":[{"t":"Tính trọng lượng và lực căng","w":"Đề cho khối lượng và g, hỏi trọng lượng; hoặc vật treo bằng một hay nhiều dây (đứng yên hoặc chuyển động có gia tốc), hỏi lực căng.","s":["Vẽ các lực tác dụng lên vật: trọng lực hướng xuống, lực căng dọc dây.","Vật cân bằng: tổng các lực bằng 0, chiếu lên phương thẳng đứng (và ngang nếu nhiều dây).","Vật chuyển động có gia tốc: dùng định luật 2, chọn chiều dương theo chiều gia tốc.","Đổi khối lượng về kg."],"n":["Kéo lên nhanh dần: T > mg; hạ xuống nhanh dần: T < mg.","Trọng lượng khác khối lượng: P = mg."]}],"sum":["Trọng lực là lực hấp dẫn của Trái Đất tác dụng lên vật, có phương thẳng đứng, chiều từ trên xuống, đặt tại trọng tâm của vật.","Khái niệm: Trọng lực là lực hấp dẫn của Trái Đất tác dụng lên vật, có phương thẳng đứng, chiều từ trên xuống, đặt tại trọng tâm của vật.","Trọng lượng là độ lớn của trọng…: Trọng lượng là độ lớn của trọng lực, đo bằng lực kế, đơn vị N.","Lực căng là lực mà dây (sợi…: Lực căng là lực mà dây (sợi, xích, thanh mảnh) tác dụng lên vật khi dây bị kéo căng.","Với dây nhẹ, không dãn, lực căng…: Với dây nhẹ, không dãn, lực căng có độ lớn bằng nhau tại mọi điểm trên dây."],"e":["Lưu ý: Kéo lên nhanh dần: T > mg; hạ xuống nhanh dần: T < mg.","Lưu ý: Trọng lượng khác khối lượng: P = mg."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 18. Lực ma sát","req":["Nêu được đặc điểm của lực ma sát nghỉ, ma sát trượt; công thức F = μN.","Vận dụng định luật 2 Newton giải bài toán có ma sát; nêu lợi ích và tác hại của ma sát."],"m":[{"t":"Bài toán có lực ma sát trượt","w":"Đề cho vật kéo trượt trên mặt ngang hoặc trượt tự do do quán tính, có hệ số ma sát; hỏi gia tốc, lực kéo, quãng đường, thời gian.","s":["Vẽ các lực: trọng lực, phản lực, lực kéo, ma sát (ngược chiều chuyển động).","Tính N từ phương vuông góc mặt tiếp xúc (mặt ngang, kéo ngang: N = mg).","F_mst = μN; viết F_hl = F − F_mst = ma theo chiều chuyển động.","Kết hợp động học tìm v, d, t."],"n":["Vật trượt chỉ do quán tính: a = −μg.","Kéo xiên góc α lên trên thì N = mg − F·sin α."]}],"sum":["Lực ma sát nghỉ xuất hiện ở mặt tiếp xúc khi vật chịu tác dụng của ngoại lực nhưng chưa trượt; cân bằng với thành phần ngoại lực song song mặt tiếp xúc; có độ lớn thay đổi, cực đại khi vật bắt đầu…","Khái niệm: Lực ma sát nghỉ xuất hiện ở mặt tiếp xúc khi vật chịu tác dụng của ngoại lực nhưng chưa trượt; cân bằng với thành phần ngoại lực song song mặt tiếp…","Lực ma sát trượt xuất hiện khi…: Lực ma sát trượt xuất hiện khi vật trượt trên bề mặt vật khác; ngược chiều với vận tốc tương đối;","Μ là hệ số ma sát trượt, không có đơn vị, thường nhỏ hơn 1: Ma sát lăn nhỏ hơn ma sát trượt rất nhiều nên người ta dùng ổ bi, bánh xe.","Ma sát có lợi: Giúp đi lại, cầm nắm, phanh xe, đánh diêm, dây curoa truyền chuyển động."],"e":["Hay nhầm: Ma sát không phụ thuộc diện tích.","Lưu ý: Vật trượt chỉ do quán tính: a = −μg.","Lưu ý: Kéo xiên góc α lên trên thì N = mg − F·sin α."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Bài 19. Lực cản và lực nâng","req":["Nêu được đặc điểm của lực cản của chất lưu và lực nâng (lực đẩy Archimedes).","Giải thích chuyển động của vật rơi trong chất lưu, đạt tốc độ giới hạn; tính lực đẩy Archimedes."],"m":[{"t":"Tính lực đẩy Archimedes và xét nổi chìm","w":"Đề cho thể tích vật (hoặc phần chìm), khối lượng riêng chất lỏng, trọng lượng vật; hỏi lực đẩy, số chỉ lực kế, phần thể tích chìm.","s":["Đổi thể tích về m³ (1 dm³ = 10⁻³ m³, 1 cm³ = 10⁻⁶ m³).","Tính F_A = ρgV với V là thể tích phần chìm.","So sánh F_A với P để kết luận nổi, chìm; vật nhúng treo lực kế thì số chỉ = P − F_A.","Vật nổi cân bằng: P = F_A ⇒ V_chìm = m/ρ_lỏng."],"n":["Chỉ tính thể tích phần chìm.","ρ nước = 1000 kg/m³."]}],"sum":["Chất lưu là chất có thể chảy được (chất lỏng và chất khí). Vật chuyển động trong chất lưu chịu lực cản ngược chiều chuyển động.","Chất lưu là chất có thể chảy được (chất lỏng và chất khí): Vật chuyển động trong chất lưu chịu lực cản ngược chiều chuyển động.","Vật có hình dạng khí động học…: Vật có hình dạng khí động học (thuôn, nhọn phía trước như thân cá, máy bay, tàu cao tốc) chịu lực cản nhỏ.","Vật rơi trong không khí: Ban đầu tốc độ tăng, lực cản tăng dần; khi lực cản bằng trọng lực thì hợp lực bằng 0, vật chuyển động đều với tốc độ giới hạn (tốc độ cuối).","Lực nâng (lực đẩy Archimedes): Vật nhúng trong chất lỏng (hay chất khí) chịu lực đẩy hướng thẳng đứng lên trên, có độ lớn bằng trọng lượng của phần chất lỏng bị vật chiếm chỗ.","Điều kiện nổi, chìm: F_A > P thì vật nổi lên;"],"e":["Lưu ý: Chỉ tính thể tích phần chìm.","Lưu ý: ρ nước = 1000 kg/m³."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 20. Một số ví dụ về cách giải các bài toán thuộc phần động lực học","req":["Vận dụng phương pháp động lực học (định luật 2 Newton kết hợp động học) để giải bài toán một vật và hệ vật nối dây.","Giải bài toán vật trên mặt phẳng nghiêng, vật chịu lực kéo xiên."],"m":[{"t":"Giải bài toán động lực học","w":"Đề cho vật trên mặt ngang hoặc mặt nghiêng, có hoặc không có ma sát, hoặc hệ hai vật nối dây; hỏi gia tốc, lực căng, vận tốc, quãng đường, lực kéo.","s":["Chọn chiều dương, vẽ đủ các lực lên mỗi vật.","Viết định luật 2 cho vật (hoặc hệ): ΣF = ma; chiếu lên trục song song và vuông góc mặt tiếp xúc.","Từ phương vuông góc tìm N (để tính ma sát); từ phương chuyển động tìm a.","Dùng động học để tìm v, d, t."],"n":["Trên mặt nghiêng: N = mg·cos α (khi không có lực xiên).","Hệ nối dây: lực căng là nội lực."]}],"sum":["Phương pháp động lực học gồm hai dạng bài toán: (1) biết lực tác dụng, tìm chuyển động (gia tốc, vận tốc, quãng đường);","Phương pháp động lực học gồm hai dạng bài toán: Biết lực tác dụng, tìm chuyển động (gia tốc, vận tốc, quãng đường)","Các bước giải: Chọn vật (hệ vật) khảo sát và hệ quy chiếu (trục toạ độ, chiều dương thường theo chiều chuyển động).","Với hệ vật nối dây không dãn, các vật có cùng độ lớn gia tốc: Có thể coi cả hệ là một vật (nội lực – lực căng – triệt tiêu) để tìm a, sau đó xét riêng từng vật để tìm lực căng."],"e":["Hay nhầm: Đó là ma sát trên mặt ngang.","Lưu ý: Trên mặt nghiêng: N = mg·cos α (khi không có lực xiên).","Lưu ý: Hệ nối dây: lực căng là nội lực."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":1}}},{"t":"Bài 21. Moment lực. Cân bằng của vật rắn","req":["Nêu được khái niệm moment lực, ngẫu lực và quy tắc moment.","Vận dụng quy tắc moment và điều kiện cân bằng của vật rắn để tính lực, khoảng cách."],"m":[{"t":"Vận dụng quy tắc moment","w":"Đề cho đòn bẩy, thanh, cánh cửa, bập bênh có trục quay; hỏi lực cần tác dụng, vị trí đặt vật, phản lực ở trục.","s":["Xác định trục quay và các lực tác dụng (kể cả trọng lực của thanh đặt tại trọng tâm).","Tính cánh tay đòn của mỗi lực: khoảng cách từ trục đến giá của lực.","Viết quy tắc moment: tổng moment theo chiều kim đồng hồ bằng tổng moment ngược chiều; giải tìm ẩn.","Nếu cần phản lực ở trục: dùng thêm ΣF = 0."],"n":["Lực có giá qua trục có moment bằng 0.","Lực xiên: cánh tay đòn là khoảng cách vuông góc, không phải chiều dài thanh."]}],"sum":["Tác dụng làm quay của lực lên vật có trục quay cố định phụ thuộc độ lớn của lực và khoảng cách từ trục quay đến giá của lực (cánh tay đòn d).","Khái niệm: Tác dụng làm quay của lực lên vật có trục quay cố định phụ thuộc độ lớn của lực và khoảng cách từ trục quay đến giá của lực (cánh tay đòn d).","Quy tắc moment: Muốn một vật có trục quay cố định ở trạng thái cân bằng thì tổng các moment lực có xu hướng làm vật quay theo chiều kim đồng hồ phải bằng tổng các…","Ngẫu lực là hệ hai lực song…: Ngẫu lực là hệ hai lực song song, ngược chiều, có độ lớn bằng nhau và cùng tác dụng vào một vật; chỉ làm vật quay.","Điều kiện cân bằng tổng quát của vật rắn: Tổng các lực tác dụng lên vật bằng 0 (không chuyển động tịnh tiến) và tổng moment lực đối với một trục bất kì bằng 0 (không quay)."],"e":["Lưu ý: Lực có giá qua trục có moment bằng 0.","Lưu ý: Lực xiên: cánh tay đòn là khoảng cách vuông góc, không phải chiều dài thanh."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 22. Thực hành: Tổng hợp lực","req":["Thực hiện thí nghiệm kiểm chứng quy tắc tổng hợp hai lực đồng quy và hai lực song song cùng chiều.","Xử lí số liệu, so sánh kết quả đo với tính toán lí thuyết."],"m":[{"t":"Xử lí số liệu thực hành tổng hợp lực","w":"Đề cho số chỉ lực kế, góc giữa hai lực, khoảng cách; hỏi hợp lực tính toán, sai số so với giá trị đo, vị trí điểm đặt hợp lực song song.","s":["Tính F_tính theo công thức hình bình hành (đồng quy) hoặc F = F₁ + F₂ (song song cùng chiều).","So sánh với F_đo: sai số tỉ đối |F_đo − F_tính|/F_tính.","Hai lực song song: d₁ + d₂ = khoảng cách giữa hai lực, F₁d₁ = F₂d₂.","Kết luận về quy tắc tổng hợp."],"n":["Vẽ các lực theo cùng một tỉ lệ xích.","Điểm đặt hợp lực song song gần lực lớn hơn."]}],"sum":["Dụng cụ: bảng thép đặt thẳng đứng, các lực kế (hoặc quả nặng và ròng rọc), dây mảnh, vòng nhẫn, thước đo góc, thước thẳng, bút, giấy.","Dụng cụ: Bảng thép đặt thẳng đứng, các lực kế (hoặc quả nặng và ròng rọc), dây mảnh, vòng nhẫn, thước đo góc, thước thẳng, bút, giấy.","Tổng hợp hai lực đồng quy: Móc hai lực kế vào vòng nhẫn kéo theo hai phương, ghi độ lớn F₁, F₂ và phương của chúng.","Tổng hợp hai lực song song cùng chiều: Treo hai vật P₁, P₂ ở hai điểm trên thanh nhẹ, dùng lực kế treo thanh ở điểm O sao cho thanh nằm ngang.","Nguyên nhân sai số: Ma sát giữa dây và bảng, lực kế không thẳng hàng với dây, đọc vạch chia, đo góc chưa chính xác."],"e":["Hay nhầm: Chỉ khi hai lực bằng nhau.","Hay nhầm: Ngẫu nhiên lệch hai phía.","Lưu ý: Vẽ các lực theo cùng một tỉ lệ xích.","Lưu ý: Điểm đặt hợp lực song song gần lực lớn hơn."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}}]},{"t":"Chương IV. Năng lượng, công, công suất","l":[{"t":"Bài 23. Năng lượng. Công cơ học","req":["Nêu được các dạng năng lượng, sự truyền và chuyển hoá năng lượng; định luật bảo toàn năng lượng.","Tính công của lực trong trường hợp lực không đổi; phân biệt công phát động và công cản."],"m":[{"t":"Tính công của lực","w":"Đề cho lực, độ dịch chuyển và góc giữa chúng; hoặc vật được kéo trên mặt ngang/mặt nghiêng có ma sát; hỏi công của từng lực, tổng công.","s":["Xác định độ lớn lực F, độ dịch chuyển d và góc α giữa →F và →d.","A = F·d·cos α; chú ý dấu.","Công của trọng lực: A = mg·Δh (dương khi đi xuống); công ma sát: −F_ms·d.","Tổng công bằng tổng đại số các công thành phần (hoặc công của hợp lực)."],"n":["α là góc giữa lực và hướng dịch chuyển, không phải với phương thẳng đứng.","Phản lực vuông góc mặt phẳng không sinh công."]}],"sum":["Năng lượng là đại lượng đặc trưng cho khả năng sinh công hoặc toả nhiệt của vật. Các dạng năng lượng: động năng, thế năng, nhiệt năng, hoá năng, điện năng, quang năng, năng lượng hạt nhân… Đơn vị là…","Khái niệm: Năng lượng là đại lượng đặc trưng cho khả năng sinh công hoặc toả nhiệt của vật.","Năng lượng có thể truyền từ vật…: Năng lượng có thể truyền từ vật này sang vật khác (bằng cách thực hiện công hoặc truyền nhiệt) và chuyển hoá từ dạng này sang dạng khác.","Dấu của công: 0 ≤ α < 90° thì A > 0, công phát động (lực kéo);","Công của trọng lực khi vật dịch chuyển từ độ cao h₁ xuống h₂: A = mg(h₁ − h₂), không phụ thuộc hình dạng đường đi."],"e":["Lưu ý: α là góc giữa lực và hướng dịch chuyển, không phải với phương thẳng đứng.","Lưu ý: Phản lực vuông góc mặt phẳng không sinh công."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 24. Công suất","req":["Nêu được ý nghĩa, công thức và đơn vị của công suất; liên hệ P = F·v.","Tính công suất của người, máy trong các tình huống thực tế."],"m":[{"t":"Tính công suất","w":"Đề cho công và thời gian, hoặc lực kéo và tốc độ, hoặc khối lượng nâng lên độ cao trong thời gian; hỏi công suất, thời gian, lực.","s":["Tính công A (A = Fd, A = mgh…).","P = A/t, đổi thời gian ra giây.","Nếu chuyển động đều với lực kéo F: P = Fv (v tính bằng m/s).","Điện năng tiêu thụ: A = P·t (kWh nếu P tính kW, t tính giờ)."],"n":["Đổi km/h ra m/s khi dùng P = Fv.","Chuyển động đều thì lực kéo bằng lực cản."]}],"sum":["Công suất là đại lượng đặc trưng cho tốc độ sinh công, đo bằng công sinh ra trong một đơn vị thời gian.","Khái niệm: Công suất là đại lượng đặc trưng cho tốc độ sinh công, đo bằng công sinh ra trong một đơn vị thời gian.","Khi lực không đổi và cùng hướng chuyển động với vận tốc v: P = A/t = F·d/t = F·v.","Đơn vị năng lượng thường dùng trong đời sống: Kilôoát giờ (kWh), 1 kWh = 1000 W·3600 s = 3,6·10⁶ J.","Công suất trung bình P = A/t…: Công suất trung bình P = A/t; công suất tức thời P = F·v với v là vận tốc tức thời."],"e":["Lưu ý: Đổi km/h ra m/s khi dùng P = Fv.","Lưu ý: Chuyển động đều thì lực kéo bằng lực cản."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 25. Động năng, thế năng","req":["Nêu được công thức động năng, thế năng trọng trường; định lí động năng.","Tính động năng, thế năng; vận dụng định lí động năng."],"m":[{"t":"Tính động năng, thế năng và dùng định lí động năng","w":"Đề cho khối lượng, vận tốc, độ cao; hỏi động năng, thế năng, lực hãm, quãng đường hãm, công của lực cản.","s":["Đổi đơn vị: g → kg, km/h → m/s.","W_đ = ½mv²; W_t = mgh với h tính từ mốc đã chọn.","Định lí động năng: ½mv₂² − ½mv₁² = tổng công (công lực kéo + công lực cản + công trọng lực…).","Giải tìm lực hoặc quãng đường."],"n":["Vận tốc tăng gấp đôi thì động năng tăng gấp bốn.","Thế năng có thể âm nếu vật dưới mốc."]}],"sum":["Động năng là dạng năng lượng mà vật có được do chuyển động. Động năng là đại lượng vô hướng, không âm, phụ thuộc hệ quy chiếu.","Động năng là dạng năng lượng mà vật có được do chuyển động: Động năng là đại lượng vô hướng, không âm, phụ thuộc hệ quy chiếu.","Định lí động năng: Độ biến thiên động năng của vật bằng tổng công của các lực tác dụng lên vật.","Thế năng trọng trường là dạng năng…: Thế năng trọng trường là dạng năng lượng mà vật có được do vị trí của nó trong trọng trường (độ cao so với mốc thế năng).","Ngoài thế năng trọng trường còn có…: Ngoài thế năng trọng trường còn có thế năng đàn hồi của lò xo bị biến dạng (W = ½k(Δl)²) – vật đàn hồi bị biến dạng có khả năng sinh công."],"e":["Hay nhầm: Chỉ khi chỉ có trọng lực.","Lưu ý: Vận tốc tăng gấp đôi thì động năng tăng gấp bốn.","Lưu ý: Thế năng có thể âm nếu vật dưới mốc."],"q":{"n":17,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":2}}},{"t":"Bài 26. Cơ năng và định luật bảo toàn cơ năng","req":["Nêu được cơ năng là tổng động năng và thế năng; điều kiện và nội dung định luật bảo toàn cơ năng.","Vận dụng định luật bảo toàn cơ năng giải bài toán rơi, ném, trượt, con lắc."],"m":[{"t":"Vận dụng định luật bảo toàn cơ năng","w":"Đề cho vật rơi, ném lên, trượt trên máng không ma sát, con lắc đơn; hỏi vận tốc ở một độ cao, độ cao cực đại, vị trí W_đ = nW_t.","s":["Chọn mốc thế năng (thường mặt đất hoặc vị trí thấp nhất).","Viết cơ năng tại vị trí đã biết đủ v và h.","Cho cơ năng bằng nhau tại vị trí cần tìm; giải tìm v hoặc h.","Nếu có ma sát: W₂ = W₁ + A_ms."],"n":["Khối lượng thường triệt tiêu: v = √(2g(h₁ − h₂)) khi rơi từ nghỉ.","Tại vị trí W_đ = W_t thì W_t = W/2."]}],"sum":["Định luật bảo toàn cơ năng: Khi vật chuyển động trong trọng trường và chỉ chịu tác dụng của trọng lực (hoặc lực đàn hồi), cơ năng của vật được bảo toàn.","Công thức","Định luật bảo toàn cơ năng: Khi vật chuyển động trong trọng trường và chỉ chịu tác dụng của trọng lực (hoặc lực đàn hồi), cơ năng của vật được bảo toàn.","Trong quá trình chuyển động, động năng và thế năng chuyển hoá lẫn nhau: Thế năng giảm bao nhiêu thì động năng tăng bấy nhiêu.","Khi có lực cản, ma sát: Cơ năng không bảo toàn;"],"e":["Lưu ý: Khối lượng thường triệt tiêu: v = √(2g(h₁ − h₂)) khi rơi từ nghỉ.","Lưu ý: Tại vị trí W_đ = W_t thì W_t = W/2."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 27. Hiệu suất","req":["Nêu được khái niệm hiệu suất, năng lượng có ích và hao phí.","Tính hiệu suất của động cơ, máy cơ đơn giản, thiết bị điện."],"m":[{"t":"Tính hiệu suất","w":"Đề cho năng lượng (công, công suất) có ích và toàn phần, hoặc máy cơ đơn giản (mặt nghiêng, ròng rọc) với lực kéo và vật nâng; hỏi hiệu suất, năng lượng hao phí, công suất đầu vào.","s":["Xác định đâu là phần có ích (mục đích sử dụng) và toàn phần (năng lượng cung cấp).","H = có ích/toàn phần·100%.","Hao phí = toàn phần − có ích.","Bài ngược: toàn phần = có ích/H."],"n":["Đơn vị năng lượng hai phần phải giống nhau.","H luôn nhỏ hơn 100%."]}],"sum":["Khi chuyển hoá năng lượng, chỉ một phần năng lượng toàn phần được chuyển thành năng lượng có ích (phục vụ mục đích); phần còn lại là năng lượng hao phí (thường chuyển thành nhiệt do ma sát, toả ra…","Khái niệm: Khi chuyển hoá năng lượng, chỉ một phần năng lượng toàn phần được chuyển thành năng lượng có ích (phục vụ mục đích); phần còn lại là năng lượng hao…","W_tp = W_ci + W_hp: Hiệu suất càng cao thì máy càng tiết kiệm năng lượng.","Hiệu suất của mặt phẳng nghiêng, ròng rọc, đòn bẩy: H = (P·h)/(F·s) với P·h là công có ích nâng vật, F·s là công toàn phần của lực kéo.","Tăng hiệu suất: Giảm ma sát (bôi trơn, ổ bi), giảm hao phí nhiệt, chọn thiết bị tiết kiệm năng lượng."],"e":["Lưu ý: Đơn vị năng lượng hai phần phải giống nhau.","Lưu ý: H luôn nhỏ hơn 100%."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương V. Động lượng","l":[{"t":"Bài 28. Động lượng","req":["Nêu được định nghĩa động lượng, đơn vị; liên hệ giữa lực và tốc độ thay đổi động lượng.","Tính động lượng, độ biến thiên động lượng và lực trung bình trong va chạm."],"m":[{"t":"Tính động lượng và lực trung bình","w":"Đề cho khối lượng, vận tốc trước và sau, thời gian va chạm; hỏi động lượng, độ biến thiên động lượng, lực trung bình.","s":["Chọn chiều dương; ghi vận tốc trước và sau kèm dấu.","Δp = m(v₂ − v₁) (chú ý dấu khi bật ngược).","F = Δp/Δt; độ lớn lực bằng |Δp|/Δt.","Động lượng hệ: cộng vectơ (cùng phương cộng có dấu, vuông góc dùng Pythagore)."],"n":["Đổi g ra kg, km/h ra m/s.","Bật ngược lại: |Δp| = m(v₁ + v₂)."]}],"sum":["Động lượng của một vật là đại lượng đo bằng tích khối lượng và vận tốc của vật; là đại lượng vectơ cùng hướng với vận tốc.","Khái niệm: Động lượng của một vật là đại lượng đo bằng tích khối lượng và vận tốc của vật; là đại lượng vectơ cùng hướng với vận tốc.","Động lượng của hệ vật bằng tổng vectơ động lượng của các vật trong hệ: →p = →p₁ + →p₂ + ...","Dạng khác của định luật 2 Newton: Lực tác dụng lên vật bằng tốc độ thay đổi động lượng của vật.","Khi vật đổi chiều chuyển động (bóng…: Khi vật đổi chiều chuyển động (bóng bật lại), độ biến thiên động lượng có độ lớn m(v₁ + v₂) theo phương chuyển động, vì vận tốc đổi dấu."],"e":["Lưu ý: Đổi g ra kg, km/h ra m/s.","Lưu ý: Bật ngược lại: |Δp| = m(v₁ + v₂)."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 29. Định luật bảo toàn động lượng","req":["Nêu được hệ kín và định luật bảo toàn động lượng.","Vận dụng định luật bảo toàn động lượng cho va chạm mềm, chuyển động bằng phản lực, súng giật."],"m":[{"t":"Vận dụng bảo toàn động lượng","w":"Đề cho hai vật va chạm (dính nhau hoặc bật ra), súng bắn đạn, người nhảy khỏi thuyền, vật nổ thành hai mảnh; hỏi vận tốc sau tương tác.","s":["Xác định hệ kín và chọn chiều dương.","Viết tổng động lượng trước = tổng động lượng sau, vận tốc mang dấu.","Giải tìm ẩn; dấu âm nghĩa là ngược chiều dương.","Nếu va chạm mềm: các vật cùng vận tốc sau va chạm."],"n":["Ban đầu đứng yên thì tổng động lượng bằng 0.","Đổi g ra kg."]}],"sum":["Hệ kín (hệ cô lập) là hệ vật không chịu tác dụng của ngoại lực, hoặc tổng các ngoại lực bằng 0, hoặc ngoại lực rất nhỏ so với nội lực trong thời gian tương tác ngắn (va chạm, nổ).","Khái niệm: Hệ kín (hệ cô lập) là hệ vật không chịu tác dụng của ngoại lực, hoặc tổng các ngoại lực bằng 0, hoặc ngoại lực rất nhỏ so với nội lực trong thời…","Định luật bảo toàn động lượng: Tổng động lượng của một hệ kín được bảo toàn.","Va chạm mềm: Sau va chạm hai vật dính nhau, chuyển động cùng vận tốc v: m₁v₁ + m₂v₂ = (m₁ + m₂)v.","Va chạm đàn hồi: Sau va chạm các vật tách rời, cả động lượng và động năng được bảo toàn."],"e":["Lưu ý: Ban đầu đứng yên thì tổng động lượng bằng 0.","Lưu ý: Đổi g ra kg."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 30. Thực hành: Xác định động lượng của vật trước và sau va chạm","req":["Thực hiện thí nghiệm đo vận tốc hai xe trước và sau va chạm bằng cổng quang điện trên đệm khí.","Xử lí số liệu, kiểm chứng định luật bảo toàn động lượng; so sánh động năng trước và sau va chạm."],"m":[{"t":"Xử lí số liệu va chạm","w":"Đề cho khối lượng hai xe, bề rộng tấm chắn, thời gian chắn cổng trước và sau va chạm; hỏi vận tốc, động lượng, sai số, động năng mất mát.","s":["Đổi d ra m; v = d/Δt cho từng lần chắn.","p_trước = Σmv trước; p_sau = Σmv sau (chú ý chiều).","So sánh và tính sai số tỉ đối.","Động năng: W = Σ½mv², so sánh trước và sau."],"n":["Xe đứng yên trước va chạm có v = 0.","Va chạm mềm: hai xe có cùng v′."]}],"sum":["Dụng cụ: đệm khí (hoặc máng ngang) giảm ma sát, hai xe trượt có khối lượng đã biết (có thể gắn thêm quả nặng), tấm chắn sáng có bề rộng d, hai cổng quang điện, đồng hồ đo thời gian hiện số, cân.","Dụng cụ: Đệm khí (hoặc máng ngang) giảm ma sát, hai xe trượt có khối lượng đã biết (có thể gắn thêm quả nặng), tấm chắn sáng có bề rộng d, hai cổng quang…","Đo vận tốc: Mỗi xe gắn tấm chắn sáng rộng d; thời gian chắn cổng Δt cho vận tốc v = d/Δt.","Va chạm mềm: Gắn băng dính (hoặc kim – sáp) để hai xe dính nhau sau va chạm.","Kết quả thí nghiệm cho thấy tổng…: Kết quả thí nghiệm cho thấy tổng động lượng trước và sau va chạm xấp xỉ bằng nhau (sai lệch vài phần trăm do ma sát, đệm khí không hoàn toàn nằm…","Lưu ý khi tiến hành: Chỉnh đệm khí nằm ngang (xe đặt lên đứng yên), đẩy xe nhẹ nhàng, đọc kết quả ngay sau mỗi lần, lặp lại ít nhất 3 lần."],"e":["Hay nhầm: Có sai số và mất động năng.","Lưu ý: Xe đứng yên trước va chạm có v = 0.","Lưu ý: Va chạm mềm: hai xe có cùng v′."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3,"Nâng cao":1}}}]},{"t":"Chương VI. Chuyển động tròn","l":[{"t":"Bài 31. Động học của chuyển động tròn đều","req":["Nêu được radian, độ dịch chuyển góc, tốc độ góc, chu kì, tần số.","Vận dụng v = ωr, T = 2π/ω để tính các đại lượng của chuyển động tròn đều."],"m":[{"t":"Tính các đại lượng của chuyển động tròn đều","w":"Đề cho bán kính và chu kì (tần số, số vòng/phút), hoặc tốc độ; hỏi ω, v, T, f, góc quay, quãng đường.","s":["Đổi số vòng/phút ra vòng/s (chia 60) để được f; ω = 2πf.","v = ωr; T = 1/f.","Góc quay trong thời gian t: θ = ωt; quãng đường s = θ·r = vt.","Đổi độ ra rad khi cần: rad = độ·π/180."],"n":["Bán kính tính bằng m.","Các điểm cùng một vật quay có cùng ω."]}],"sum":["Chuyển động tròn đều là chuyển động có quỹ đạo là đường tròn và tốc độ không đổi. Vectơ vận tốc luôn tiếp tuyến với quỹ đạo, có độ lớn không đổi nhưng hướng thay đổi liên tục.","Khái niệm: Chuyển động tròn đều là chuyển động có quỹ đạo là đường tròn và tốc độ không đổi.","Radian (rad) là số đo góc ở…: Radian (rad) là số đo góc ở tâm chắn cung có độ dài bằng bán kính.","Chu kì là thời gian vật đi…: Chu kì là thời gian vật đi hết một vòng; tần số là số vòng vật đi được trong một giây.","Ví dụ: Kim giây quay một vòng trong 60 s nên ω = 2π/60 ≈ 0,105 rad/s;"],"e":["Lưu ý: Bán kính tính bằng m.","Lưu ý: Các điểm cùng một vật quay có cùng ω."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 32. Lực hướng tâm và gia tốc hướng tâm","req":["Nêu được gia tốc hướng tâm, lực hướng tâm và công thức tính.","Vận dụng định luật 2 Newton cho chuyển động tròn đều trong các tình huống thực tế."],"m":[{"t":"Bài toán lực hướng tâm","w":"Đề cho khối lượng, bán kính, tốc độ (hoặc chu kì, số vòng); hỏi gia tốc hướng tâm, lực hướng tâm, tốc độ tối đa vào cua, lực căng.","s":["Đổi đơn vị: v (m/s), r (m), số vòng/phút → ω.","a_ht = v²/r = ω²r; F_ht = m·a_ht.","Xác định lực nào đóng vai trò hướng tâm: ma sát nghỉ (xe vào cua), lực căng dây, hấp dẫn.","Tốc độ tối đa vào cua phẳng: μmg = mv²/r ⇒ v = √(μgr)."],"n":["Lực hướng tâm là hợp lực, không vẽ thêm như một lực riêng.","Tốc độ tăng gấp đôi thì lực hướng tâm tăng bốn lần."]}],"sum":["Trong chuyển động tròn đều, vận tốc luôn đổi hướng nên vật có gia tốc. Gia tốc này luôn hướng vào tâm quỹ đạo, gọi là gia tốc hướng tâm.","Khái niệm: Trong chuyển động tròn đều, vận tốc luôn đổi hướng nên vật có gia tốc.","Lực (hay hợp lực) tác dụng lên…: Lực (hay hợp lực) tác dụng lên vật chuyển động tròn đều và gây ra gia tốc hướng tâm gọi là lực hướng tâm.","Ví dụ: Lực hấp dẫn giữ Mặt Trăng quay quanh Trái Đất; lực ma sát nghỉ giữ ô tô vào cua trên đường ngang; lực căng dây giữ vật quay tròn.","Khi lực hướng tâm không đủ (hoặc…: Khi lực hướng tâm không đủ (hoặc mất đi), vật có xu hướng văng ra theo phương tiếp tuyến (chuyển động li tâm)."],"e":["Lưu ý: Lực hướng tâm là hợp lực, không vẽ thêm như một lực riêng.","Lưu ý: Tốc độ tăng gấp đôi thì lực hướng tâm tăng bốn lần."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]},{"t":"Chương VII. Biến dạng của vật rắn. Áp suất chất lỏng","l":[{"t":"Bài 33. Biến dạng của vật rắn","req":["Phân biệt biến dạng đàn hồi và biến dạng dẻo; biến dạng kéo và nén.","Phát biểu và vận dụng định luật Hooke; đọc đồ thị lực – độ biến dạng của lò xo."],"m":[{"t":"Vận dụng định luật Hooke","w":"Đề cho lò xo treo vật hoặc chịu lực kéo/nén, chiều dài tự nhiên và chiều dài khi biến dạng; hỏi độ cứng, lực đàn hồi, chiều dài mới, khối lượng vật treo.","s":["Tính Δl = |l − l₀| (đổi ra m).","Vật treo cân bằng: k·Δl = mg.","Từ một trạng thái tìm k, rồi áp dụng cho trạng thái khác: Δl tỉ lệ với lực.","Đồ thị F – Δl: k = độ dốc = F/Δl."],"n":["Chỉ áp dụng trong giới hạn đàn hồi.","Đơn vị k là N/m, Δl phải đổi về m."]}],"sum":["Biến dạng của vật rắn là sự thay đổi hình dạng, kích thước của vật khi chịu tác dụng của lực.","Khái niệm: Biến dạng của vật rắn là sự thay đổi hình dạng, kích thước của vật khi chịu tác dụng của lực.","Biến dạng kéo làm vật dài ra, biến dạng nén làm vật ngắn lại: Độ biến dạng của lò xo: Δl = |l − l₀| với l₀ là chiều dài tự nhiên.","Giới hạn đàn hồi là giới hạn…: Giới hạn đàn hồi là giới hạn mà trong đó vật rắn còn giữ được tính đàn hồi.","Trong giới hạn đàn hồi, độ lớn…: Trong giới hạn đàn hồi, độ lớn lực đàn hồi của lò xo tỉ lệ thuận với độ biến dạng."],"e":["Lưu ý: Chỉ áp dụng trong giới hạn đàn hồi.","Lưu ý: Đơn vị k là N/m, Δl phải đổi về m."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}},{"t":"Bài 34. Khối lượng riêng. Áp suất chất lỏng","req":["Nêu được khối lượng riêng, áp suất; công thức áp suất chất lỏng p = p₀ + ρgh.","Vận dụng tính khối lượng riêng, áp suất, chênh lệch áp suất giữa hai điểm trong chất lỏng."],"m":[{"t":"Tính khối lượng riêng và áp suất chất lỏng","w":"Đề cho khối lượng, thể tích; hoặc độ sâu, khối lượng riêng chất lỏng; hỏi khối lượng riêng, áp suất tại một điểm, chênh lệch áp suất, áp lực lên diện tích.","s":["Đổi đơn vị: g → kg, cm³ → m³ (1 cm³ = 10⁻⁶ m³), cm → m.","ρ = m/V; áp suất do chất lỏng ρgh; áp suất tuyệt đối p₀ + ρgh.","Chênh lệch áp suất giữa hai độ sâu: ρg·Δh.","Áp lực F = p·S."],"n":["Độ sâu h tính từ mặt thoáng xuống.","Nếu đề chỉ hỏi áp suất do chất lỏng gây ra thì không cộng p₀."]}],"sum":["Khối lượng riêng của một chất là khối lượng của một đơn vị thể tích chất đó; ví dụ nước 1000 kg/m³, sắt khoảng 7800 kg/m³, nhôm 2700 kg/m³, không khí khoảng 1,29 kg/m³.","Công thức","Khối lượng riêng của một chất là…: Khối lượng riêng của một chất là khối lượng của một đơn vị thể tích chất đó; ví dụ nước 1000 kg/m³, sắt khoảng 7800 kg/m³, nhôm 2700 kg/m³, không…","Chất lỏng gây áp suất theo mọi…: Chất lỏng gây áp suất theo mọi phương lên đáy bình, thành bình và các vật trong lòng nó.","P₀ là áp suất khí quyển trên mặt thoáng: Áp suất chất lỏng chỉ phụ thuộc độ sâu và khối lượng riêng, không phụ thuộc hình dạng bình."],"e":["Lưu ý: Độ sâu h tính từ mặt thoáng xuống.","Lưu ý: Nếu đề chỉ hỏi áp suất do chất lỏng gây ra thì không cộng p₀."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4,"Nâng cao":1}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 10","c":[{"t":"Chương I. Cấu tạo nguyên tử","l":[{"t":"Bài 1. Thành phần của nguyên tử","req":["Trình bày được thành phần của nguyên tử (hạt nhân gồm proton, neutron; vỏ gồm electron); điện tích, khối lượng mỗi loại hạt.","So sánh được khối lượng electron với proton, neutron; kích thước hạt nhân với kích thước nguyên tử."],"sum":["Nguyên tử gồm hạt nhân mang điện tích dương ở tâm và lớp vỏ gồm các electron mang điện tích âm chuyển động xung quanh.","Khái niệm: Nguyên tử gồm hạt nhân mang điện tích dương ở tâm và lớp vỏ gồm các electron mang điện tích âm chuyển động xung quanh.","Khối lượng electron rất nhỏ (khoảng 1/1837…: Khối lượng electron rất nhỏ (khoảng 1/1837 khối lượng proton), nên khối lượng nguyên tử tập trung hầu hết ở hạt nhân.","Kích thước: Nguyên tử có đường kính khoảng 10⁻¹⁰ m (1 Å), hạt nhân khoảng 10⁻¹⁴ m, nhỏ hơn nguyên tử khoảng 10 000 lần.","Ví dụ: Hạt nhân Na có 11 proton và 12 neutron nên Z = 11, A = 23."],"e":["Hay nhầm: Hạt nhân mang điện dương.","Hay nhầm: Electron có khối lượng nhưng rất nhỏ.","Hay nhầm: Hạt nhân mang điện dương."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 2. Nguyên tố hoá học","req":["Phát biểu được khái niệm nguyên tố hoá học, số hiệu nguyên tử, kí hiệu nguyên tử.","Phát biểu được khái niệm đồng vị, nguyên tử khối; tính được nguyên tử khối trung bình và phần trăm các đồng vị."],"sum":["Nguyên tố hoá học là tập hợp các nguyên tử có cùng số đơn vị điện tích hạt nhân (cùng số proton).","Khái niệm: Nguyên tố hoá học là tập hợp các nguyên tử có cùng số đơn vị điện tích hạt nhân (cùng số proton).","Đồng vị là những nguyên tử của…: Đồng vị là những nguyên tử của cùng một nguyên tố (cùng số proton) nhưng có số neutron khác nhau, do đó số khối khác nhau.","Nguyên tử khối là khối lượng tương…: Nguyên tử khối là khối lượng tương đối của nguyên tử, cho biết nguyên tử nặng gấp bao nhiêu lần 1 amu; có thể coi gần bằng số khối.","Bài toán ngược: Biết Ā và số khối hai đồng vị, gọi phần trăm đồng vị thứ nhất là x thì Ā = [x·A₁ + (100 − x)·A₂]/100, giải tìm x."],"e":["Hay nhầm: Đó là đặc điểm khác nhau của đồng vị."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 3. Cấu trúc lớp vỏ electron nguyên tử","req":["So sánh mô hình Rutherford – Bohr với mô hình hiện đại; nêu khái niệm orbital nguyên tử, hình dạng orbital s, p.","Trình bày cấu trúc lớp, phân lớp electron; viết cấu hình electron và biểu diễn electron trong ô orbital cho 20 nguyên tố đầu; dự đoán tính chất từ số electron lớp ngoài cùng."],"m":[{"t":"Viết cấu hình electron","w":"Đề cho Z (hoặc tổng số hạt), yêu cầu viết cấu hình electron, ô orbital, xác định số electron lớp ngoài cùng, số electron độc thân, dự đoán kim loại hay phi kim.","s":["Xác định Z = số electron.","Điền electron theo thứ tự năng lượng 1s 2s 2p 3s 3p 4s 3d 4p…, mỗi phân lớp không vượt quá số tối đa.","Viết lại theo thứ tự lớp (3d trước 4s) nếu có phân lớp d.","Đếm electron lớp ngoài cùng (n lớn nhất) để kết luận tính chất; vẽ ô orbital theo Hund để đếm electron độc thân."],"n":["Fe (Z = 26): 1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁶ 4s², lớp ngoài cùng có 2e.","Cr và Cu có cấu hình đặc biệt (3d⁵4s¹, 3d¹⁰4s¹) – lớp 10 không bắt buộc."]}],"sum":["Mô hình Rutherford – Bohr: electron chuyển động trên những quỹ đạo tròn xác định quanh hạt nhân, mỗi quỹ đạo có mức năng lượng xác định.","Mô hình Rutherford – Bohr: Electron chuyển động trên những quỹ đạo tròn xác định quanh hạt nhân, mỗi quỹ đạo có mức năng lượng xác định.","Lớp electron gồm các electron có mức…: Lớp electron gồm các electron có mức năng lượng gần bằng nhau, đánh số n = 1, 2, 3, 4… (K, L, M, N…).","Nguyên lí vững bền: Electron chiếm các orbital có mức năng lượng từ thấp đến cao.","Đặc điểm lớp electron ngoài cùng: Nguyên tử có 1, 2, 3 electron lớp ngoài cùng thường là kim loại (trừ H, He, B); có 5, 6, 7 electron thường là phi kim; có 8 electron (và He có 2) là…"],"e":["Hay nhầm: Đó là nguyên lí vững bền.","Lưu ý: Fe (Z = 26): 1s² 2s² 2p⁶ 3s² 3p⁶ 3d⁶ 4s², lớp ngoài cùng có 2e.","Lưu ý: Cr và Cu có cấu hình đặc biệt (3d⁵4s¹, 3d¹⁰4s¹) – lớp 10 không bắt buộc."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 4. Ôn tập chương 1","req":["Hệ thống hoá kiến thức về thành phần nguyên tử, nguyên tố hoá học, đồng vị và cấu trúc lớp vỏ electron.","Vận dụng tổng hợp để giải các bài tập về số hạt, nguyên tử khối trung bình, cấu hình electron."],"m":[{"t":"Giải bài toán tổng hợp về nguyên tử","w":"Đề cho các dữ kiện về tổng số hạt, hiệu số hạt, đồng vị, hoặc cấu hình electron; hỏi Z, A, nguyên tố, phần trăm đồng vị, tính chất.","s":["Đặt ẩn Z, N; lập hệ phương trình từ dữ kiện số hạt.","Với đồng vị: dùng công thức Ā, đặt ẩn phần trăm.","Viết cấu hình electron từ Z, suy ra số electron lớp ngoài cùng và tính chất.","Kiểm tra: 1 ≤ N/Z ≤ 1,5 với các nguyên tố Z ≤ 82 (đồng vị bền)."],"n":["Ion dương mất electron, ion âm nhận electron; số proton không đổi.","Đọc kĩ \"số hạt mang điện\" gồm cả p và e."]}],"e":["Lưu ý: Ion dương mất electron, ion âm nhận electron; số proton không đổi.","Lưu ý: Đọc kĩ \"số hạt mang điện\" gồm cả p và e."],"q":{"n":10,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":4}}}]},{"t":"Chương II. Bảng tuần hoàn các nguyên tố hoá học và định luật tuần hoàn","l":[{"t":"Bài 5. Cấu tạo của bảng tuần hoàn các nguyên tố hoá học","req":["Nêu được lịch sử phát minh bảng tuần hoàn và nguyên tắc sắp xếp các nguyên tố.","Mô tả cấu tạo bảng tuần hoàn: ô, chu kì, nhóm; phân loại nguyên tố theo cấu hình electron (s, p, d, f) và theo tính chất (kim loại, phi kim, khí hiếm)."],"m":[{"t":"Xác định vị trí nguyên tố từ cấu hình electron","w":"Đề cho Z hoặc cấu hình electron, hỏi ô, chu kì, nhóm, loại nguyên tố; hoặc ngược lại từ vị trí suy ra cấu hình.","s":["Viết cấu hình electron theo Z.","Ô = Z; chu kì = số lớp (n lớn nhất).","Nguyên tố s, p: nhóm A, số thứ tự nhóm = số electron lớp ngoài cùng.","Nguyên tố d: nhóm B, dựa vào tổng số electron (n−1)d + ns (3–7: nhóm IIIB–VIIB; 8–10: VIIIB; 11, 12: IB, IIB)."],"n":["He có 2e nhưng thuộc nhóm VIIIA.","Electron cuối điền vào phân lớp nào thì là nguyên tố khối đó."]}],"sum":["Năm 1869, D. I.","Năm 1869, D: I.","Nguyên tắc sắp xếp: Các nguyên tố được xếp theo chiều tăng dần điện tích hạt nhân nguyên tử","Chu kì: Bảng có 7 chu kì; chu kì 1, 2, 3 là chu kì nhỏ (2, 8, 8 nguyên tố), chu kì 4, 5, 6, 7 là chu kì lớn.","Phân loại theo cấu hình: Nguyên tố s (electron cuối điền vào phân lớp s: nhóm IA, IIA và He), nguyên tố p (nhóm IIIA → VIIIA, trừ He), nguyên tố d (nhóm B), nguyên tố f (họ…"],"e":["Hay nhầm: Đó là của Mendeleev ban đầu.","Hay nhầm: Nhóm IA là kim loại kiềm.","Lưu ý: He có 2e nhưng thuộc nhóm VIIIA.","Lưu ý: Electron cuối điền vào phân lớp nào thì là nguyên tố khối đó."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 6. Xu hướng biến đổi một số tính chất của nguyên tử các nguyên tố trong một chu kì và trong một nhóm","req":["Giải thích được xu hướng biến đổi bán kính nguyên tử, độ âm điện trong một chu kì và trong một nhóm A.","Giải thích được xu hướng biến đổi tính kim loại, tính phi kim trong chu kì và nhóm A."],"m":[{"t":"So sánh tính chất các nguyên tố","w":"Đề cho các nguyên tố (Z hoặc kí hiệu), yêu cầu sắp xếp theo bán kính, độ âm điện, tính kim loại, tính phi kim.","s":["Xác định vị trí (chu kì, nhóm) của mỗi nguyên tố.","Các nguyên tố cùng chu kì: so sánh theo Z (trái phải); cùng nhóm: so sánh theo chu kì (trên dưới).","Nguyên tố khác cả chu kì và nhóm: dùng một nguyên tố trung gian cùng chu kì với nguyên tố này và cùng nhóm với nguyên tố kia.","Viết dãy sắp xếp và giải thích."],"n":["Bán kính và tính kim loại biến đổi cùng chiều; độ âm điện và tính phi kim biến đổi cùng chiều.","Khí hiếm thường không xét độ âm điện."]}],"sum":["Bán kính nguyên tử: trong một chu kì, theo chiều tăng điện tích hạt nhân, bán kính nguyên tử giảm dần (số lớp electron không đổi nhưng điện tích hạt nhân tăng, lực hút electron lớp ngoài tăng).","Bán kính nguyên tử: Trong một chu kì, theo chiều tăng điện tích hạt nhân, bán kính nguyên tử giảm dần (số lớp electron không đổi nhưng điện tích hạt nhân tăng, lực hút…","Độ âm điện (χ) đặc trưng cho…: Độ âm điện (χ) đặc trưng cho khả năng hút electron của nguyên tử khi tạo liên kết hoá học.","Tính kim loại là khả năng nguyên…: Tính kim loại là khả năng nguyên tử nhường electron để trở thành ion dương; tính phi kim là khả năng nhận electron để trở thành ion âm.","Kim loại mạnh nhất ở góc dưới…: Kim loại mạnh nhất ở góc dưới bên trái (Cs, Fr); phi kim mạnh nhất ở góc trên bên phải (F, không kể khí hiếm)."],"e":["Lưu ý: Bán kính và tính kim loại biến đổi cùng chiều; độ âm điện và tính phi kim biến đổi cùng chiều.","Lưu ý: Khí hiếm thường không xét độ âm điện."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 7. Xu hướng biến đổi thành phần và một số tính chất của hợp chất trong một chu kì","req":["Nhận xét được xu hướng biến đổi thành phần các oxide cao nhất và hydroxide tương ứng trong chu kì 3.","Nêu và giải thích được xu hướng biến đổi tính acid – base của oxide và hydroxide trong chu kì 3."],"m":[{"t":"Xác định công thức oxide, hydroxide và so sánh tính acid – base","w":"Đề cho nguyên tố hoặc vị trí, hỏi công thức oxide cao nhất, hydroxide, hợp chất khí với hydrogen; so sánh tính acid/base; tìm nguyên tố từ phần trăm khối lượng.","s":["Xác định nhóm A (n) ⇒ oxide cao nhất R₂Oₙ; hợp chất với H: RH₈₋ₙ (phi kim).","So sánh: cùng chu kì, Z lớn hơn thì tính acid mạnh hơn; cùng nhóm, Z lớn hơn thì tính base mạnh hơn.","Bài phần trăm: lập phương trình theo M_R, giải tìm R."],"n":["Al₂O₃, Al(OH)₃ lưỡng tính.","Hoá trị với H của phi kim = 8 − n."]}],"sum":["Trong một chu kì, theo chiều tăng điện tích hạt nhân, hoá trị cao nhất của nguyên tố trong oxide tăng dần từ 1 đến 7 (bằng số thứ tự nhóm A).","Khái niệm: Trong một chu kì, theo chiều tăng điện tích hạt nhân, hoá trị cao nhất của nguyên tố trong oxide tăng dần từ 1 đến 7 (bằng số thứ tự nhóm A).","Tính acid – base của oxide: Na₂O, MgO là oxide base;","Tính acid – base của hydroxide: NaOH là base mạnh (kiềm), Mg(OH)₂ là base yếu, Al(OH)₃ là hydroxide lưỡng tính;","Kết luận: Trong một chu kì, theo chiều tăng điện tích hạt nhân, tính base của oxide và hydroxide giảm dần, tính acid tăng dần – phù hợp với tính kim loại giảm…"],"e":["Lưu ý: Al₂O₃, Al(OH)₃ lưỡng tính.","Lưu ý: Hoá trị với H của phi kim = 8 − n."],"q":{"n":12,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 8. Định luật tuần hoàn. Ý nghĩa của bảng tuần hoàn các nguyên tố hoá học","req":["Phát biểu được định luật tuần hoàn.","Trình bày được ý nghĩa của bảng tuần hoàn: mối liên hệ giữa vị trí với cấu tạo và tính chất; dự đoán tính chất của nguyên tố."],"m":[{"t":"Từ vị trí dự đoán tính chất nguyên tố","w":"Đề cho Z hoặc vị trí, yêu cầu nêu cấu tạo, tính chất cơ bản; hoặc so sánh với nguyên tố lân cận.","s":["Viết cấu hình electron, xác định chu kì, nhóm.","Suy ra loại nguyên tố (kim loại/phi kim/khí hiếm) từ số e lớp ngoài cùng.","Viết oxide cao nhất R₂Oₙ, hydroxide, hợp chất với H (nếu là phi kim) và nêu tính acid/base.","So sánh với nguyên tố lân cận theo quy luật chu kì, nhóm."],"n":["Kim loại nhóm IA, IIA tạo hydroxide base.","Phi kim nhóm VIA, VIIA tạo acid mạnh."]}],"sum":["Định luật tuần hoàn: Tính chất của các nguyên tố và đơn chất, cũng như thành phần và tính chất của các hợp chất tạo nên từ các nguyên tố đó biến đổi tuần hoàn theo chiều tăng của điện tích hạt nhân…","Định luật tuần hoàn: Tính chất của các nguyên tố và đơn chất, cũng như thành phần và tính chất của các hợp chất tạo nên từ các nguyên tố đó biến đổi tuần hoàn theo chiều…","Nguyên nhân: Cấu hình electron lớp ngoài cùng của nguyên tử các nguyên tố biến đổi tuần hoàn khi điện tích hạt nhân tăng dần, mà cấu hình lớp ngoài cùng quyết…","Ý nghĩa: Biết vị trí của một nguyên tố có thể suy ra cấu tạo nguyên tử và dự đoán tính chất: kim loại hay phi kim, hoá trị cao nhất với oxygen, hoá trị với…","Lịch sử: Dựa vào định luật tuần hoàn, Mendeleev đã dự đoán tính chất của các nguyên tố chưa biết như eka-silicon (germanium), eka-aluminium (gallium); các dự…"],"e":["Hay nhầm: Mn thuộc nhóm VIIB, không phải nhóm A.","Lưu ý: Kim loại nhóm IA, IIA tạo hydroxide base.","Lưu ý: Phi kim nhóm VIA, VIIA tạo acid mạnh."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 9. Ôn tập chương 2","req":["Hệ thống hoá kiến thức về cấu tạo bảng tuần hoàn, xu hướng biến đổi tính chất nguyên tố và hợp chất, định luật tuần hoàn.","Vận dụng tổng hợp mối liên hệ vị trí – cấu tạo – tính chất."],"m":[{"t":"Bài toán tìm nguyên tố từ phản ứng","w":"Đề cho khối lượng kim loại (hoặc oxide) và lượng khí, acid tham gia phản ứng; hỏi nguyên tố.","s":["Viết phương trình phản ứng với kim loại hoá trị n (theo nhóm).","Tính số mol chất đã biết (khí: n = V/24,79 ở điều kiện chuẩn).","Suy ra số mol kim loại, M = m/n.","Đối chiếu bảng tuần hoàn để xác định nguyên tố."],"n":["Kim loại nhóm IIA: M + 2HCl → MCl₂ + H₂.","Ở 25 °C, 1 bar: 1 mol khí chiếm 24,79 L."]}],"e":["Lưu ý: Kim loại nhóm IIA: M + 2HCl → MCl₂ + H₂.","Lưu ý: Ở 25 °C, 1 bar: 1 mol khí chiếm 24,79 L."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":4}}}]},{"t":"Chương III. Liên kết hoá học","l":[{"t":"Bài 10. Quy tắc octet","req":["Trình bày được quy tắc octet trong quá trình hình thành liên kết hoá học cho các nguyên tố nhóm A.","Vận dụng quy tắc octet để giải thích sự tạo thành ion và cặp electron dùng chung."],"m":[{"t":"Vận dụng quy tắc octet","w":"Đề cho nguyên tố, yêu cầu viết quá trình tạo ion, xác định điện tích ion, số electron dùng chung để đạt octet.","s":["Viết cấu hình electron, xác định số electron lớp ngoài cùng.","Kim loại: nhường hết electron lớp ngoài cùng; điện tích ion = +số e nhường.","Phi kim: nhận thêm (8 − số e lớp ngoài cùng) electron; điện tích âm tương ứng.","Viết quá trình và cấu hình của ion (giống khí hiếm gần nhất)."],"n":["H chỉ cần 2 electron (giống He).","Ion tạo thành có cấu hình khí hiếm cùng chu kì (ion âm) hoặc chu kì trước (ion dương)."]}],"sum":["Liên kết hoá học là sự kết hợp giữa các nguyên tử tạo thành phân tử hay tinh thể bền vững hơn.","Khái niệm: Liên kết hoá học là sự kết hợp giữa các nguyên tử tạo thành phân tử hay tinh thể bền vững hơn.","Quy tắc octet: Trong quá trình hình thành liên kết hoá học, nguyên tử của các nguyên tố nhóm A có xu hướng tạo thành lớp vỏ có 8 electron ở lớp ngoài cùng (giống…","Kim loại (1, 2, 3 electron lớp…: Kim loại (1, 2, 3 electron lớp ngoài cùng) có xu hướng nhường electron tạo ion dương; phi kim (5, 6, 7 electron lớp ngoài cùng) có xu hướng nhận…","Hạn chế: Quy tắc octet không áp dụng được cho một số trường hợp như BF₃ (B chỉ có 6 electron), PCl₅, SF₆ (P, S có hơn 8 electron), NO (số electron lẻ)."],"e":["Lưu ý: H chỉ cần 2 electron (giống He).","Lưu ý: Ion tạo thành có cấu hình khí hiếm cùng chu kì (ion âm) hoặc chu kì trước (ion dương)."],"q":{"n":13,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 11. Liên kết ion","req":["Trình bày được khái niệm và sự hình thành liên kết ion; nêu được cấu tạo tinh thể NaCl.","Giải thích được vì sao các hợp chất ion thường ở trạng thái rắn, có nhiệt độ nóng chảy cao, dẫn điện khi nóng chảy hoặc tan trong nước."],"m":[{"t":"Mô tả sự hình thành liên kết ion","w":"Đề cho hai nguyên tố (kim loại – phi kim), yêu cầu viết quá trình nhường, nhận electron, công thức hợp chất ion và giải thích tính chất.","s":["Viết cấu hình, xác định số e kim loại nhường (bằng số e lớp ngoài cùng) và phi kim nhận (8 − số e lớp ngoài cùng).","Viết quá trình tạo cation và anion.","Cân bằng điện tích để có công thức: tổng điện tích dương bằng tổng điện tích âm.","Viết phương trình phản ứng tạo hợp chất."],"n":["Công thức MgCl₂, Al₂O₃, Na₂O lấy theo nguyên tắc trung hoà điện.","Hợp chất ion không dẫn điện ở thể rắn."]}],"sum":["Ion là phần tử mang điện. Cation (ion dương) tạo thành khi nguyên tử nhường electron (Na⁺, Mg²⁺, Al³⁺); anion (ion âm) tạo thành khi nguyên tử nhận electron (Cl⁻, O²⁻, S²⁻).","Ion là phần tử mang điện: Cation (ion dương) tạo thành khi nguyên tử nhường electron (Na⁺, Mg²⁺, Al³⁺); anion (ion âm) tạo thành khi nguyên tử nhận electron (Cl⁻, O²⁻, S²⁻).","Liên kết ion là liên kết được…: Liên kết ion là liên kết được hình thành bởi lực hút tĩnh điện giữa các ion mang điện tích trái dấu.","Tinh thể ion: Các ion được sắp xếp luân phiên đều đặn trong mạng tinh thể.","Tính chất hợp chất ion: Ở điều kiện thường là chất rắn, khá rắn nhưng giòn; nhiệt độ nóng chảy, nhiệt độ sôi cao (NaCl nóng chảy ở 801 °C) do lực hút tĩnh điện mạnh; nhiều…"],"e":["Hay nhầm: Ở thể rắn ion không tự do.","Hay nhầm: Nước nguyên chất dẫn điện kém.","Lưu ý: Công thức MgCl₂, Al₂O₃, Na₂O lấy theo nguyên tắc trung hoà điện.","Lưu ý: Hợp chất ion không dẫn điện ở thể rắn."],"q":{"n":13,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":3}}},{"t":"Bài 12. Liên kết cộng hoá trị","req":["Trình bày được khái niệm liên kết cộng hoá trị; viết được công thức Lewis, công thức cấu tạo của một số phân tử đơn giản.","Phân biệt liên kết cộng hoá trị không cực, có cực, liên kết ion dựa vào hiệu độ âm điện; phân biệt liên kết σ, π; nêu được khái niệm năng lượng liên kết."],"m":[{"t":"Xác định loại liên kết và đếm số liên kết σ, π","w":"Đề cho phân tử, yêu cầu viết công thức Lewis/cấu tạo, xác định loại liên kết theo hiệu độ âm điện, đếm liên kết σ và π, so sánh độ bền.","s":["Tính tổng số electron hoá trị, sắp xếp để mỗi nguyên tử đạt octet (H đạt 2e).","Viết công thức cấu tạo, đếm liên kết đơn, đôi, ba.","Mỗi liên kết đơn: 1σ; đôi: 1σ + 1π; ba: 1σ + 2π.","Tính Δχ để phân loại: < 0,4; 0,4 – 1,7; ≥ 1,7."],"n":["Δχ chỉ dùng để dự đoán, có ngoại lệ.","Năng lượng liên kết lớn hơn thì liên kết bền hơn."]}],"sum":["Liên kết cộng hoá trị là liên kết được hình thành giữa hai nguyên tử bằng một hay nhiều cặp electron dùng chung.","Khái niệm: Liên kết cộng hoá trị là liên kết được hình thành giữa hai nguyên tử bằng một hay nhiều cặp electron dùng chung.","Liên kết cho – nhận là liên…: Liên kết cho – nhận là liên kết cộng hoá trị trong đó cặp electron dùng chung do một nguyên tử đóng góp (biểu diễn bằng mũi tên), ví dụ trong NH₄⁺,…","Liên kết cộng hoá trị không cực: Cặp electron chung không lệch về nguyên tử nào (H₂, Cl₂, N₂).","Liên kết σ hình thành do sự…: Liên kết σ hình thành do sự xen phủ trục của hai orbital (s – s, s – p, p – p), bền vững.","Năng lượng liên kết (E_b) của một…: Năng lượng liên kết (E_b) của một liên kết cộng hoá trị là năng lượng cần để phá vỡ 1 mol liên kết đó ở thể khí, tạo thành nguyên tử ở thể khí."],"e":["Hay nhầm: Không liên quan trực tiếp.","Lưu ý: Δχ chỉ dùng để dự đoán, có ngoại lệ.","Lưu ý: Năng lượng liên kết lớn hơn thì liên kết bền hơn."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 13. Liên kết hydrogen và tương tác van der Waals","req":["Nêu được khái niệm liên kết hydrogen; giải thích được ảnh hưởng của liên kết hydrogen đến nhiệt độ sôi, nóng chảy, độ tan của H₂O, NH₃.","Nêu được khái niệm tương tác van der Waals và ảnh hưởng của nó đến nhiệt độ nóng chảy, nhiệt độ sôi."],"m":[{"t":"So sánh nhiệt độ sôi dựa vào lực liên phân tử","w":"Đề cho dãy chất, yêu cầu sắp xếp theo nhiệt độ sôi, nóng chảy hoặc độ tan; giải thích bất thường (H₂O, HF, NH₃).","s":["Xác định chất nào có liên kết hydrogen (có H gắn với F, O, N).","Chất có liên kết hydrogen thường sôi cao hơn chất có khối lượng tương đương không có liên kết hydrogen.","Các chất cùng loại không có liên kết hydrogen: so sánh khối lượng phân tử (tương tác van der Waals).","Kết luận thứ tự."],"n":["HF, H₂O, NH₃ có nhiệt độ sôi cao bất thường.","Hợp chất ion sôi cao nhất."]}],"sum":["Liên kết hydrogen là một loại liên kết yếu, được hình thành giữa nguyên tử H (đã liên kết với nguyên tử có độ âm điện lớn như F, O, N) với một nguyên tử khác có độ âm điện lớn (F, O, N) còn cặp…","Khái niệm: Liên kết hydrogen là một loại liên kết yếu, được hình thành giữa nguyên tử H (đã liên kết với nguyên tử có độ âm điện lớn như F, O, N) với một…","Ảnh hưởng của liên kết hydrogen: Làm tăng nhiệt độ sôi, nhiệt độ nóng chảy (H₂O sôi ở 100 °C trong khi H₂S sôi ở −60 °C); làm tăng độ tan trong nước của các chất tạo được liên kết…","Tương tác van der Waals là tương…: Tương tác van der Waals là tương tác tĩnh điện yếu giữa các lưỡng cực (vĩnh viễn hoặc tạm thời) của các phân tử.","Ảnh hưởng: Trong dãy halogen F₂, Cl₂, Br₂, I₂, khối lượng phân tử tăng nên tương tác van der Waals tăng, nhiệt độ nóng chảy và sôi tăng (F₂, Cl₂ là khí;"],"e":["Lưu ý: HF, H₂O, NH₃ có nhiệt độ sôi cao bất thường.","Lưu ý: Hợp chất ion sôi cao nhất."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 14. Ôn tập chương 3","req":["Hệ thống hoá kiến thức về quy tắc octet, liên kết ion, liên kết cộng hoá trị, liên kết hydrogen, tương tác van der Waals.","Vận dụng để xác định loại liên kết, viết công thức cấu tạo, so sánh tính chất vật lí."],"m":[{"t":"Xác định loại liên kết và tính chất của chất","w":"Đề cho dãy chất hoặc nguyên tố, hỏi loại liên kết, số σ/π, so sánh nhiệt độ sôi, tính dẫn điện.","s":["Xác định nguyên tố, tính Δχ nếu có số liệu.","Kim loại điển hình + phi kim điển hình: ion; hai phi kim: cộng hoá trị.","Đếm σ, π từ công thức cấu tạo.","So sánh nhiệt độ sôi: ion > chất có liên kết hydrogen > chất chỉ có van der Waals (cùng cỡ khối lượng)."],"n":["Phân tử CO₂, CH₄ có liên kết phân cực nhưng phân tử không phân cực.","Liên kết hydrogen là liên kết giữa các phân tử (liên phân tử)."]}],"e":["Lưu ý: Phân tử CO₂, CH₄ có liên kết phân cực nhưng phân tử không phân cực.","Lưu ý: Liên kết hydrogen là liên kết giữa các phân tử (liên phân tử)."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chương IV. Phản ứng oxi hoá – khử","l":[{"t":"Bài 15. Phản ứng oxi hoá – khử","req":["Nêu được khái niệm và xác định được số oxi hoá của nguyên tử các nguyên tố trong hợp chất.","Nêu được khái niệm phản ứng oxi hoá – khử, chất oxi hoá, chất khử, quá trình oxi hoá, quá trình khử; cân bằng phương trình bằng phương pháp thăng bằng electron; nêu ý nghĩa của phản ứng oxi hoá – khử."],"m":[{"t":"Cân bằng phản ứng oxi hoá – khử","w":"Đề cho sơ đồ phản ứng có sự thay đổi số oxi hoá, yêu cầu xác định chất oxi hoá, chất khử và cân bằng bằng thăng bằng electron; hoặc tính lượng chất theo số mol electron.","s":["Xác định số oxi hoá các nguyên tố thay đổi.","Viết quá trình oxi hoá (chất khử nhường e) và quá trình khử (chất oxi hoá nhận e).","Nhân hệ số để số e nhường = số e nhận (bội chung nhỏ nhất).","Đặt hệ số vào chất oxi hoá, chất khử, rồi cân bằng các nguyên tố còn lại (thường H, O sau cùng)."],"n":["Bảo toàn electron: Σn(e nhường) = Σn(e nhận) – dùng để giải bài toán nhanh.","Một chất có thể vừa là chất oxi hoá vừa là chất khử (phản ứng tự oxi hoá – khử)."]}],"sum":["Số oxi hoá của một nguyên tử trong phân tử là điện tích của nguyên tử đó với giả thiết đây là hợp chất ion (cặp electron chung thuộc về nguyên tử có độ âm điện lớn hơn).","Khái niệm: Số oxi hoá của một nguyên tử trong phân tử là điện tích của nguyên tử đó với giả thiết đây là hợp chất ion (cặp electron chung thuộc về nguyên tử có…","Phản ứng oxi hoá – khử là…: Phản ứng oxi hoá – khử là phản ứng hoá học trong đó có sự chuyển electron giữa các chất, hay có sự thay đổi số oxi hoá của một số nguyên tử.","Cân bằng bằng phương pháp thăng bằng electron (nguyên tắc: Tổng số electron chất khử nhường bằng tổng số electron chất oxi hoá nhận) gồm 4 bước:","Ý nghĩa: Phản ứng oxi hoá – khử xảy ra phổ biến trong đời sống và sản xuất: sự cháy của nhiên liệu, quá trình hô hấp, quang hợp, luyện kim (luyện gang thép),…"],"e":["Lưu ý: Bảo toàn electron: Σn(e nhường) = Σn(e nhận) – dùng để giải bài toán nhanh.","Lưu ý: Một chất có thể vừa là chất oxi hoá vừa là chất khử (phản ứng tự oxi hoá – khử)."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 16. Ôn tập chương 4","req":["Hệ thống hoá kiến thức về số oxi hoá và phản ứng oxi hoá – khử.","Vận dụng định luật bảo toàn electron giải bài tập."],"m":[{"t":"Giải bài toán bằng bảo toàn electron","w":"Đề cho kim loại tác dụng với acid có tính oxi hoá (HNO₃, H₂SO₄ đặc) hoặc halogen, hỏi khối lượng kim loại, thể tích khí sản phẩm khử.","s":["Xác định chất nhường e (kim loại) và chất nhận e (N⁺⁵, S⁺⁶, Cl₂…), viết số e trao đổi cho mỗi phân tử/nguyên tử.","Lập phương trình bảo toàn electron.","Giải tìm ẩn; nếu có thể tích khí ở điều kiện chuẩn dùng V = n·24,79."],"n":["NO: N nhận 3e; NO₂: 1e; SO₂: S nhận 2e; H₂: 2H⁺ nhận 2e.","Fe tác dụng HCl tạo Fe²⁺, tác dụng HNO₃ dư tạo Fe³⁺."]}],"e":["Lưu ý: NO: N nhận 3e; NO₂: 1e; SO₂: S nhận 2e; H₂: 2H⁺ nhận 2e.","Lưu ý: Fe tác dụng HCl tạo Fe²⁺, tác dụng HNO₃ dư tạo Fe³⁺."],"q":{"n":7,"lv":{"Biết":1,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chương V. Năng lượng hoá học","l":[{"t":"Bài 17. Biến thiên enthalpy trong các phản ứng hoá học","req":["Trình bày được khái niệm phản ứng toả nhiệt, thu nhiệt; điều kiện chuẩn; enthalpy tạo thành và biến thiên enthalpy chuẩn của phản ứng.","Viết được phương trình nhiệt hoá học, biểu diễn sơ đồ biến thiên enthalpy; tính ΔrH°₂₉₈ từ nhiệt tạo thành và từ năng lượng liên kết."],"m":[{"t":"Tính biến thiên enthalpy của phản ứng","w":"Đề cho bảng nhiệt tạo thành chuẩn hoặc năng lượng liên kết, yêu cầu tính ΔrH°₂₉₈, kết luận toả hay thu nhiệt, tính nhiệt lượng theo lượng chất.","s":["Cân bằng phương trình, ghi trạng thái các chất.","Theo nhiệt tạo thành: lấy tổng (hệ số × ΔfH) sản phẩm trừ tổng chất đầu; đơn chất bền có ΔfH = 0.","Theo năng lượng liên kết: tổng năng lượng liên kết bị phá vỡ (chất đầu) trừ tổng năng lượng liên kết tạo thành (sản phẩm); nhớ nhân số liên kết trong mỗi phân tử.","Nhiệt lượng thực tế = |ΔrH| × (số mol chất / hệ số trong phương trình)."],"n":["Chú ý dấu: hai công thức có thứ tự trừ ngược nhau.","ΔrH < 0: toả nhiệt."]}],"sum":["Phản ứng toả nhiệt là phản ứng giải phóng năng lượng dạng nhiệt ra môi trường (đốt cháy nhiên liệu, phản ứng trung hoà).","Khái niệm: Phản ứng toả nhiệt là phản ứng giải phóng năng lượng dạng nhiệt ra môi trường (đốt cháy nhiên liệu, phản ứng trung hoà).","Biến thiên enthalpy của phản ứng (ΔrH)…: Biến thiên enthalpy của phản ứng (ΔrH) là nhiệt lượng toả ra hay thu vào của phản ứng ở áp suất không đổi.","Phương trình nhiệt hoá học là phương…: Phương trình nhiệt hoá học là phương trình phản ứng có ghi kèm trạng thái của các chất (s, l, g, aq) và giá trị biến thiên enthalpy.","Enthalpy tạo thành chuẩn (nhiệt tạo thành…: Enthalpy tạo thành chuẩn (nhiệt tạo thành chuẩn) ΔfH°₂₉₈ của một chất là biến thiên enthalpy của phản ứng tạo thành 1 mol chất đó từ các đơn chất…"],"e":["Lưu ý: Chú ý dấu: hai công thức có thứ tự trừ ngược nhau.","Lưu ý: ΔrH < 0: toả nhiệt."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 18. Ôn tập chương 5","req":["Hệ thống hoá kiến thức về phản ứng toả nhiệt, thu nhiệt, biến thiên enthalpy và cách tính.","Vận dụng tính ΔrH theo nhiệt tạo thành và năng lượng liên kết."],"m":[{"t":"Tính nhiệt lượng theo lượng chất","w":"Đề cho phương trình nhiệt hoá học và lượng chất (gam, lít khí), hỏi nhiệt lượng toả ra hoặc thu vào, hoặc ngược lại.","s":["Đổi lượng chất ra số mol (m/M hoặc V/24,79).","So sánh với hệ số trong phương trình nhiệt hoá học.","Nhiệt lượng = |ΔrH| × n(chất)/hệ số.","Kết luận toả hay thu dựa theo dấu ΔrH."],"n":["Chú ý ΔrH cho cả phương trình với hệ số đã ghi.","1 mol khí ở điều kiện chuẩn chiếm 24,79 L."]}],"e":["Lưu ý: Chú ý ΔrH cho cả phương trình với hệ số đã ghi.","Lưu ý: 1 mol khí ở điều kiện chuẩn chiếm 24,79 L."],"q":{"n":6,"lv":{"Biết":1,"Hiểu":2,"Vận dụng":3}}}]},{"t":"Chương VI. Tốc độ phản ứng","l":[{"t":"Bài 19. Tốc độ phản ứng","req":["Trình bày được khái niệm tốc độ phản ứng, tốc độ trung bình; viết được biểu thức tốc độ theo định luật tác dụng khối lượng.","Giải thích được ảnh hưởng của nồng độ, áp suất, nhiệt độ, diện tích bề mặt, chất xúc tác đến tốc độ phản ứng; vận dụng hệ số nhiệt độ Van’t Hoff."],"m":[{"t":"Tính tốc độ phản ứng và vận dụng các yếu tố","w":"Đề cho nồng độ tại hai thời điểm, hoặc biểu thức tốc độ, hoặc hệ số nhiệt độ; hỏi tốc độ trung bình, tốc độ thay đổi khi đổi nồng độ, nhiệt độ.","s":["Tốc độ trung bình: lấy |ΔC|/Δt rồi chia cho hệ số của chất trong phương trình.","Đổi nồng độ: viết v = kC_A^a C_B^b, thay nồng độ mới, so sánh tỉ số.","Đổi nhiệt độ: v₂/v₁ = γ^(ΔT/10); tính số lần tăng.","Ngược lại tìm thời gian phản ứng: thời gian tỉ lệ nghịch với tốc độ."],"n":["Chất đầu có ΔC âm nên phải lấy dấu trừ.","Tăng nhiệt độ 10 °C, tốc độ tăng γ lần."]}],"sum":["Tốc độ phản ứng là đại lượng đặc trưng cho sự nhanh chậm của phản ứng, được xác định bằng độ biến thiên nồng độ của một chất phản ứng hoặc sản phẩm trong một đơn vị thời gian.","Khái niệm: Tốc độ phản ứng là đại lượng đặc trưng cho sự nhanh chậm của phản ứng, được xác định bằng độ biến thiên nồng độ của một chất phản ứng hoặc sản phẩm…","Đa số phản ứng có tốc độ…: Đa số phản ứng có tốc độ giảm dần theo thời gian (do nồng độ chất phản ứng giảm).","Ảnh hưởng: Nồng độ tăng thì tốc độ tăng (số va chạm tăng);","Năng lượng hoạt hoá là năng lượng…: Năng lượng hoạt hoá là năng lượng tối thiểu mà các hạt cần có để va chạm dẫn đến phản ứng."],"e":["Hay nhầm: Xúc tác không làm chuyển dịch cân bằng.","Lưu ý: Chất đầu có ΔC âm nên phải lấy dấu trừ.","Lưu ý: Tăng nhiệt độ 10 °C, tốc độ tăng γ lần."],"q":{"n":16,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5}}},{"t":"Bài 20. Ôn tập chương 6","req":["Hệ thống hoá kiến thức về tốc độ phản ứng và các yếu tố ảnh hưởng.","Vận dụng biểu thức tốc độ, quy tắc Van’t Hoff giải bài tập và giải thích hiện tượng thực tiễn."],"m":[{"t":"Giải thích ứng dụng thực tiễn","w":"Đề mô tả một biện pháp trong đời sống, sản xuất; yêu cầu chỉ ra yếu tố ảnh hưởng và giải thích.","s":["Xác định thay đổi: nhiệt độ, nồng độ, áp suất, bề mặt hay xúc tác.","Nêu chiều ảnh hưởng (tăng/giảm tốc độ).","Giải thích bằng số va chạm, va chạm hiệu quả, năng lượng hoạt hoá."],"n":["Ướp lạnh, hút chân không: giảm tốc độ phản ứng gây hỏng thực phẩm.","Thổi không khí vào lò: tăng nồng độ O₂."]}],"e":["Lưu ý: Ướp lạnh, hút chân không: giảm tốc độ phản ứng gây hỏng thực phẩm.","Lưu ý: Thổi không khí vào lò: tăng nồng độ O₂."],"q":{"n":6,"lv":{"Biết":1,"Hiểu":2,"Vận dụng":3}}}]},{"t":"Chương VII. Nguyên tố nhóm halogen","l":[{"t":"Bài 21. Nhóm halogen","req":["Nêu được trạng thái tự nhiên, trạng thái, màu sắc, nhiệt độ nóng chảy, nhiệt độ sôi của các đơn chất halogen; giải thích bằng tương tác van der Waals.","Trình bày xu hướng tạo hợp chất ion, cộng hoá trị; tính oxi hoá của halogen (phản ứng với kim loại, hydrogen, nước, dung dịch kiềm, muối halide); ứng dụng và điều chế."],"m":[{"t":"Bài toán halogen tác dụng với kim loại và muối","w":"Đề cho kim loại tác dụng với Cl₂ (hoặc halogen mạnh đẩy halogen yếu khỏi muối), hỏi khối lượng muối, thể tích khí, xác định kim loại.","s":["Viết phương trình; kim loại nhiều hoá trị (Fe) lên hoá trị cao nhất với Cl₂.","Tính số mol chất đã biết, suy ra theo tỉ lệ.","Có thể dùng tăng giảm khối lượng hoặc bảo toàn khối lượng: m(muối) = m(kim loại) + m(Cl₂).","Đối chiếu nguyên tử khối để tìm kim loại."],"n":["Fe + Cl₂ tạo FeCl₃ (khác Fe + HCl tạo FeCl₂).","Halogen yếu hơn không đẩy được halogen mạnh."]}],"sum":["Nhóm VIIA (halogen) gồm F, Cl, Br, I, At, Ts. Trong tự nhiên halogen chỉ tồn tại ở dạng hợp chất, chủ yếu là muối halide (NaCl trong nước biển, CaF₂ trong khoáng fluorite).","Nhóm VIIA (halogen) gồm F, Cl, Br, I, At, Ts: Trong tự nhiên halogen chỉ tồn tại ở dạng hợp chất, chủ yếu là muối halide (NaCl trong nước biển, CaF₂ trong khoáng fluorite).","Đơn chất halogen là phân tử hai…: Đơn chất halogen là phân tử hai nguyên tử X₂ (liên kết cộng hoá trị không cực).","Nguyên tử halogen có 7 electron lớp…: Nguyên tử halogen có 7 electron lớp ngoài cùng (ns² np⁵), dễ nhận thêm 1 electron tạo ion X⁻ (với kim loại tạo hợp chất ion) hoặc góp chung electron…","Phản ứng với hydrogen: F₂ nổ ngay cả trong bóng tối ở nhiệt độ rất thấp;","Phản ứng của Cl₂ với nước và…: Phản ứng của Cl₂ với nước và kiềm là phản ứng tự oxi hoá – khử (Cl⁰ vừa lên +1/+5 vừa xuống −1)."],"e":["Hay nhầm: Đó là KClO₃ khi đun nóng.","Lưu ý: Fe + Cl₂ tạo FeCl₃ (khác Fe + HCl tạo FeCl₂).","Lưu ý: Halogen yếu hơn không đẩy được halogen mạnh."],"q":{"n":15,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":4}}},{"t":"Bài 22. Hydrogen halide. Muối halide","req":["Mô tả được cấu tạo, tính chất vật lí của hydrogen halide; giải thích sự biến đổi nhiệt độ sôi và tính acid của dãy hydrohalic acid.","Trình bày tính chất hoá học của hydrochloric acid, tính khử của ion halide; nhận biết ion halide bằng AgNO₃; nêu ứng dụng."],"m":[{"t":"Bài toán hydrochloric acid và muối halide","w":"Đề cho kim loại, oxide, muối carbonate tác dụng với HCl, hoặc muối halide tác dụng với AgNO₃; hỏi khối lượng, thể tích, nồng độ, thành phần hỗn hợp.","s":["Viết phương trình phản ứng.","Tính số mol chất đã biết; với hỗn hợp đặt ẩn, lập hệ phương trình theo khối lượng và lượng khí/kết tủa.","Áp dụng bảo toàn khối lượng hoặc bảo toàn nguyên tố Cl khi cần: n(HCl) = 2n(H₂) khi kim loại tác dụng HCl.","Tính đại lượng cần tìm (V = n·24,79; C_M = n/V)."],"n":["Fe tác dụng HCl tạo FeCl₂.","Cu, Ag không tác dụng với HCl."]}],"sum":["Hydrogen halide HX (HF, HCl, HBr, HI) là phân tử có liên kết cộng hoá trị phân cực, ở điều kiện thường là chất khí, tan nhiều trong nước tạo dung dịch hydrohalic acid.","Khái niệm: Hydrogen halide HX (HF, HCl, HBr, HI) là phân tử có liên kết cộng hoá trị phân cực, ở điều kiện thường là chất khí, tan nhiều trong nước tạo dung…","Hydrochloric acid (HCl) có đầy đủ tính chất của acid mạnh: Làm quỳ tím hoá đỏ; tác dụng với kim loại đứng trước H tạo muối và H₂ (Fe + 2HCl → FeCl₂ + H₂); với oxide base, base, muối.","Tính khử của ion halide tăng từ F⁻ đến I⁻: Cl⁻ chỉ bị oxi hoá bởi chất oxi hoá mạnh (MnO₂, KMnO₄);","Ứng dụng: HCl dùng tẩy gỉ kim loại, sản xuất phân bón, dược phẩm, chế biến thực phẩm;"],"e":["Hay nhầm: HCl thể hiện tính oxi hoá (H⁺).","Lưu ý: Fe tác dụng HCl tạo FeCl₂.","Lưu ý: Cu, Ag không tác dụng với HCl."],"q":{"n":14,"lv":{"Biết":5,"Hiểu":5,"Vận dụng":4}}},{"t":"Bài 23. Ôn tập chương 7","req":["Hệ thống hoá kiến thức về đơn chất halogen, hydrogen halide và muối halide.","Vận dụng giải bài tập tổng hợp và nhận biết các chất."],"m":[{"t":"Nhận biết các dung dịch halide","w":"Đề cho các lọ mất nhãn chứa muối halide hoặc acid; yêu cầu chọn thuốc thử và nêu hiện tượng.","s":["Dùng quỳ tím phân biệt acid với muối trung tính.","Dùng AgNO₃: Cl⁻ kết tủa trắng, Br⁻ vàng nhạt, I⁻ vàng, F⁻ không có kết tủa.","Có thể dùng nước chlorine và hồ tinh bột để nhận ra I⁻ (hồ tinh bột hoá xanh).","Viết phương trình minh hoạ."],"n":["AgCl hoá đen ngoài ánh sáng.","I₂ làm hồ tinh bột chuyển xanh tím."]}],"e":["Lưu ý: AgCl hoá đen ngoài ánh sáng.","Lưu ý: I₂ làm hồ tinh bột chuyển xanh tím."],"q":{"n":6,"lv":{"Biết":1,"Hiểu":2,"Vận dụng":3}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Cấu tạo nguyên tử","l":[{"t":"Bài tập nâng cao · Chương I. Cấu tạo nguyên tử (7 câu)","q":{"n":7,"lv":{"Nâng cao":7}}}]},{"t":"Chương II. Bảng tuần hoàn các nguyên tố hoá học và định luật tuần hoàn","l":[{"t":"Bài tập nâng cao · Chương II. Bảng tuần hoàn các nguyên tố hoá học và định luật tuần hoàn (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương III. Liên kết hoá học","l":[{"t":"Bài tập nâng cao · Chương III. Liên kết hoá học (9 câu)","e":["Hay nhầm: Độ bền liên kết không quyết định nhiệt độ sôi."],"q":{"n":9,"lv":{"Nâng cao":9}}}]},{"t":"Chương IV. Phản ứng oxi hoá – khử","l":[{"t":"Bài tập nâng cao · Chương IV. Phản ứng oxi hoá – khử (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chương V. Năng lượng hoá học","l":[{"t":"Bài tập nâng cao · Chương V. Năng lượng hoá học (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chương VI. Tốc độ phản ứng","l":[{"t":"Bài tập nâng cao · Chương VI. Tốc độ phản ứng (5 câu)","q":{"n":5,"lv":{"Nâng cao":5}}}]},{"t":"Chương VII. Nguyên tố nhóm halogen","l":[{"t":"Bài tập nâng cao · Chương VII. Nguyên tố nhóm halogen (7 câu)","q":{"n":7,"lv":{"Nâng cao":7}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 10","c":[{"t":"Phần mở đầu","l":[{"t":"Bài 1. Giới thiệu khái quát môn Sinh học","req":["Nêu được đối tượng và các lĩnh vực nghiên cứu của sinh học.","Trình bày được mục tiêu môn Sinh học.","Phân tích được vai trò của sinh học với đời sống, kinh tế - xã hội và các vấn đề toàn cầu."],"sum":["Sinh học là ngành khoa học nghiên cứu về sự sống. Đối tượng của sinh học là các sinh vật cùng các cấp độ tổ chức của thế giới sống.","Sinh học là ngành khoa học nghiên cứu về sự sống: Đối tượng của sinh học là các sinh vật cùng các cấp độ tổ chức của thế giới sống.","Các lĩnh vực nghiên cứu sinh học…: Các lĩnh vực nghiên cứu sinh học chia thành nghiên cứu cơ bản (cấu trúc, phân loại, cách vận hành và tiến hoá của thế giới sống) và nghiên cứu ứng…","Sinh học liên quan mật thiết tới đời sống: Y - dược (thuốc hướng đích, vaccine mRNA), pháp y (dấu vân tay DNA), nông - lâm - ngư nghiệp (giống năng suất cao, nuôi cấy mô), công nghệ thực phẩm…","Phát triển bền vững là sự phát…: Phát triển bền vững là sự phát triển đáp ứng nhu cầu hiện tại nhưng không làm tổn hại đến khả năng đáp ứng nhu cầu của các thế hệ tương lai.","Sinh học trong tương lai kết hợp…: Sinh học trong tương lai kết hợp với hoá học, tin học, toán học và vật lí, hình thành sinh học hệ thống."],"e":["Hay nhầm: Đó là đối tượng của vật lí.","Hay nhầm: Đó là đối tượng của địa lí.","Hay nhầm: Đó là đối tượng của hoá học vô cơ.","Hay nhầm: Đó là nghiên cứu ứng dụng.","Hay nhầm: Đó là nghiên cứu ứng dụng.","Hay nhầm: Đó là nghiên cứu ứng dụng."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 2. Phương pháp nghiên cứu và học tập môn Sinh học","req":["Trình bày và vận dụng được một số phương pháp nghiên cứu sinh học: quan sát, làm việc trong phòng thí nghiệm, thực nghiệm khoa học.","Nêu được một số thiết bị nghiên cứu và học tập môn Sinh học.","Trình bày được quy trình và các kĩ năng trong tiến trình nghiên cứu khoa học."],"sum":["Mọi nghiên cứu sinh học đều cần phương pháp và thiết bị phù hợp. Các phương pháp chính gồm quan sát, làm việc trong phòng thí nghiệm và thực nghiệm khoa học.","Khái niệm: Mọi nghiên cứu sinh học đều cần phương pháp và thiết bị phù hợp.","1: Phương pháp quan sát: lựa chọn đối tượng và phạm vi quan sát; chọn công cụ (giác quan, kính lúp, thiết bị); ghi chép số liệu đủ lớn, lặp lại nhiều…","2: Làm việc trong phòng thí nghiệm: luôn đảm bảo an toàn (mặc áo choàng, đeo găng tay, kính bảo hộ; không ăn uống, không nếm hoá chất; làm đúng hướng…","3: Phương pháp thực nghiệm: phân loại sinh vật (hình thái, phân tích gene), tách chiết (enzyme, gene, chất có hoạt tính sinh học), nuôi cấy (vi khuẩn,…","4: Thiết bị nghiên cứu: kính hiển vi quang học (độ phóng đại tối đa khoảng 1 500 lần, độ phân giải khoảng 200 nm) và kính hiển vi điện tử (phóng đại…"],"e":["Hay nhầm: Kính lúp không đủ phóng đại.","Hay nhầm: Kính quang học có độ phân giải khoảng 200 nm, không đủ.","Hay nhầm: Pipet dùng để lấy dung dịch.","Hay nhầm: Không phải chức năng của máy li tâm.","Hay nhầm: Đó là chức năng của kính hiển vi.","Hay nhầm: Không phải chức năng của máy li tâm."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 3. Các cấp độ tổ chức của thế giới sống","req":["Phát biểu được khái niệm cấp độ tổ chức sống.","Trình bày được các đặc điểm chung của các cấp độ tổ chức sống.","Phân biệt được các cấp độ tổ chức sống dựa vào sơ đồ."],"sum":["Cấp độ tổ chức sống là cấp độ tổ chức của vật chất có biểu hiện đầy đủ đặc tính của sự sống.","Khái niệm: Cấp độ tổ chức sống là cấp độ tổ chức của vật chất có biểu hiện đầy đủ đặc tính của sự sống.","Quan hệ giữa các cấp độ: Cơ thể gồm mô, cơ quan, hệ cơ quan; quần thể là tập hợp cá thể cùng loài trong một khu vực và thời điểm; quần xã gồm các quần thể của nhiều loài; hệ…","Đặc điểm chung: Được tổ chức theo nguyên tắc thứ bậc, cấp thấp làm nền tảng cho cấp cao, tạo ra đặc tính nổi trội mà cấp thấp không có","Ví dụ: Cơ thể người duy trì thân nhiệt, pH, đường huyết ở mức ổn định; nếu cơ chế tự điều chỉnh bị rối loạn, con người có thể mắc bệnh."],"e":["Hay nhầm: Phân tử chưa có đầy đủ đặc tính sống.","Hay nhầm: Bào quan là thành phần của tế bào.","Hay nhầm: Mô là cấp trung gian, gồm nhiều tế bào.","Hay nhầm: Quần xã gồm nhiều loài khác nhau.","Hay nhầm: Hệ sinh thái gồm quần xã và môi trường.","Hay nhầm: Cơ quan là cấp dưới cơ thể."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}}]},{"t":"Chương 1. Thành phần hoá học của tế bào","l":[{"t":"Bài 4. Các nguyên tố hoá học và nước","req":["Khái quát được học thuyết tế bào; giải thích được tế bào là đơn vị cấu trúc và chức năng của cơ thể sống.","Liệt kê được một số nguyên tố hoá học chính trong tế bào (C, H, O, N, S, P) và vai trò của nguyên tố đa lượng, vi lượng.","Trình bày được vai trò quan trọng của carbon trong tế bào."],"sum":["Năm 1839, Schleiden và Schwann nhận thấy mọi sinh vật đều có cấu trúc tế bào; từ đó hình thành học thuyết tế bào.","Khái niệm: Năm 1839, Schleiden và Schwann nhận thấy mọi sinh vật đều có cấu trúc tế bào; từ đó hình thành học thuyết tế bào. Học thuyết tế bào hiện đại gồm ba…","Trong 92 nguyên tố tự nhiên, khoảng…: Trong 92 nguyên tố tự nhiên, khoảng 20–25% là nguyên tố thiết yếu cho sự sống.","Carbon có vai trò đặc biệt vì…: Carbon có vai trò đặc biệt vì nguyên tử C có 4 electron hoá trị, có thể tạo 4 liên kết cộng hoá trị với C khác và với H, O, N.","Nước là thành phần chính của tế…: Nước là thành phần chính của tế bào (khoảng 70% khối lượng cơ thể người).","Đặc tính vật lí của nước: Sức căng bề mặt lớn (một số sinh vật đi được trên mặt nước); nhiệt dung riêng cao (giúp ổn định nhiệt độ cơ thể và môi trường); nhiệt bay hơi cao…"],"e":["Hay nhầm: Đây là nội dung của học thuyết.","Hay nhầm: Đây là nội dung của học thuyết.","Hay nhầm: Đây là nội dung của học thuyết.","Hay nhầm: Đây là các nguyên tố vi lượng.","Hay nhầm: Nhóm này chiếm tỉ lệ nhỏ hơn.","Hay nhầm: Đây là các nguyên tố vi lượng hoặc đa lượng nhỏ."],"q":{"n":11,"lv":{"Biết":4,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 5. Các phân tử sinh học","req":["Nêu được khái niệm phân tử sinh học.","Trình bày được thành phần cấu tạo và vai trò của carbohydrate, lipid, protein, nucleic acid.","Phân tích được mối quan hệ giữa cấu tạo và chức năng của các phân tử sinh học."],"sum":["Phân tử sinh học là các phân tử hữu cơ được tổng hợp và tồn tại trong tế bào sống. Các phân tử sinh học chính gồm carbohydrate, lipid, protein và nucleic acid.","Khái niệm: Phân tử sinh học là các phân tử hữu cơ được tổng hợp và tồn tại trong tế bào sống.","1: Carbohydrate: gồm C, H, O theo tỉ lệ 1 : 2 : 1, công thức chung Cₙ(H₂O)ₘ.","2: Lipid: nhóm kị nước, rất đa dạng.","3: Protein: đa phân gồm 20 loại amino acid.","4: Nucleic acid: gồm DNA và RNA."],"e":["Hay nhầm: Nước và muối khoáng không phải phân tử sinh học chính.","Hay nhầm: Nước và khí không phải phân tử sinh học chính.","Hay nhầm: Muối khoáng không phải phân tử sinh học chính.","Hay nhầm: Chitin là đường đa; saccharin không phải đường sinh học.","Hay nhầm: Nucleotide cấu tạo nên nucleic acid.","Hay nhầm: Glucose cấu tạo nên đường đa."],"q":{"n":14,"lv":{"Biết":4,"Hiểu":8,"Vận dụng":2}}},{"t":"Bài 6. Thực hành: Nhận biết một số phân tử sinh học","req":["Tiến hành được thí nghiệm nhận biết đường đơn, tinh bột, protein và lipid trong tế bào.","Áp dụng được nguyên lí của các phản ứng hoá học đặc thù để nhận biết từng loại phân tử sinh học.","Có kĩ năng thao tác an toàn trong phòng thí nghiệm: pha hoá chất, sử dụng dụng cụ và đèn cồn."],"sum":["Mục tiêu: nhận biết đường glucose, lipid và protein bằng các phép thử đặc thù. Dụng cụ: ống nghiệm, bình thuỷ tinh chịu nhiệt, pipet, đèn cồn, kẹp ống nghiệm.","Mục tiêu: Nhận biết đường glucose, lipid và protein bằng các phép thử đặc thù.","1: Nhận biết đường glucose (Benedict): dung dịch Benedict có màu xanh.","2: Nhận biết lipid (phép thử nhũ tương): lipid không tan trong nước nhưng tan trong cồn.","3: Nhận biết protein (phép thử Biuret): liên kết peptide chứa nitrogen tạo phức chất với Cu²⁺ trong môi trường kiềm, cho màu xanh tím.","Lưu ý an toàn: Không để dung dịch sôi bắn vào người; cẩn thận khi dùng đèn cồn; rửa tay sau thí nghiệm; thu gom hoá chất đúng nơi quy định."],"e":["Hay nhầm: Biuret nhận biết protein.","Hay nhầm: Cồn dùng để hoà tan lipid.","Hay nhầm: Iodine nhận biết tinh bột.","Hay nhầm: Benedict dùng cho đường đơn.","Hay nhầm: Lipid nhận biết bằng phép thử nhũ tương.","Hay nhầm: Tinh bột nhận biết bằng iodine."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Cấu trúc tế bào","l":[{"t":"Bài 7. Tế bào nhân sơ","req":["Mô tả được kích thước, cấu tạo và chức năng các thành phần của tế bào nhân sơ.","So sánh được đặc điểm tế bào nhân sơ và tế bào nhân thực.","Giải thích được vì sao sinh vật nhân sơ thích nghi tốt và sinh sản nhanh."],"sum":["Mọi sinh vật đều được cấu tạo từ tế bào. Có hai loại tế bào: nhân sơ và nhân thực.","Mọi sinh vật đều được cấu tạo từ tế bào: Có hai loại tế bào: nhân sơ và nhân thực.","Đặc điểm chung: Tế bào nhân sơ có kích thước điển hình 1–5 μm, khoảng 1/10 tế bào nhân thực.","1: Lông, roi và màng ngoài: roi (một hoặc vài chiếc) là cơ quan vận động, cấu tạo từ bó sợi protein.","2: Thành tế bào và màng tế bào: thành cấu tạo từ peptidoglycan, dày 10–20 nm, giữ hình dạng và bảo vệ tế bào.","3: Tế bào chất: gồm bào tương dạng keo lỏng (chứa nước, chất hữu cơ, vô cơ), các hạt dự trữ và khoảng 10 000–100 000 ribosome (nơi tổng hợp protein)."],"e":["Hay nhầm: Đây là đặc điểm của tế bào nhân thực.","Hay nhầm: Tế bào nhân sơ không có bào quan có màng bao.","Hay nhầm: Tế bào nhân sơ không có hệ thống nội màng.","Hay nhầm: Kích thước này thuộc tế bào nhân thực lớn.","Hay nhầm: Kích thước này quá lớn so với tế bào nhân sơ.","Hay nhầm: Kích thước này quá nhỏ, gần cấp phân tử."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 8. Tế bào nhân thực","req":["Nêu được cấu tạo và chức năng của tế bào chất.","Trình bày được cấu trúc của nhân tế bào và chức năng quan trọng của nhân.","Phân tích được mối quan hệ giữa cấu tạo và chức năng của các bào quan trong tế bào."],"sum":["Tế bào nhân thực có kích thước lớn, cấu tạo phức tạp, có nhân với màng nhân, bộ khung xương tế bào, hệ thống nội màng và các bào quan có màng bao bọc.","Khái niệm: Tế bào nhân thực có kích thước lớn, cấu tạo phức tạp, có nhân với màng nhân, bộ khung xương tế bào, hệ thống nội màng và các bào quan có màng bao bọc.","1: Nhân: trung tâm thông tin và điều khiển mọi hoạt động sống.","2: Ribosome: bào quan không màng, gồm rRNA (80–90%) và protein, gồm tiểu đơn vị lớn và nhỏ; là nơi tổng hợp protein.","3: Lưới nội chất: hệ thống ống và túi dẹp thông nhau.","4: Bộ máy Golgi: các túi dẹp xếp song song, nhận protein từ lưới nội chất hạt, gắn thêm chuỗi đường tạo glycoprotein, phân loại, đóng gói trong túi vận…"],"e":["Hay nhầm: Lysosome phân huỷ các chất.","Hay nhầm: Peroxisome phân giải H₂O₂ và chuyển hoá lipid.","Hay nhầm: Không bào điều hoà áp suất thẩm thấu và dự trữ.","Hay nhầm: Lục lạp có thylakoid, thực hiện quang hợp.","Hay nhầm: Ribosome không có màng bao.","Hay nhầm: Trung thể tham gia phân bào."],"q":{"n":13,"lv":{"Biết":4,"Hiểu":7,"Vận dụng":2}}},{"t":"Bài 9. Thực hành: Quan sát tế bào","req":["Làm được tiêu bản và quan sát tế bào nhân sơ (vi khuẩn).","Làm được tiêu bản tế bào nhân thực và quan sát hình dạng nhân, một số bào quan.","Rèn kĩ năng làm tiêu bản tạm thời và sử dụng kính hiển vi quang học."],"sum":["Mục tiêu: rèn kĩ năng làm tiêu bản tạm thời và sử dụng kính hiển vi; quan sát vi khuẩn trong nước dưa muối và tế bào biểu bì vảy hành hoặc lá thài lài tía.","Mục tiêu: Rèn kĩ năng làm tiêu bản tạm thời và sử dụng kính hiển vi; quan sát vi khuẩn trong nước dưa muối và tế bào biểu bì vảy hành hoặc lá thài lài tía.","Dụng cụ chính: Lam kính, lamen, que cấy, kính hiển vi (vật kính 10x, 40x, 100x), xanh methylene, nước cất, nước dưa muối, lá thài lài tía hoặc củ hành tây.","Làm tiêu bản vi khuẩn: Nhỏ nước cất và một giọt nước dưa muối lên lam, dàn mỏng, hong khô, nhuộm xanh methylene 1–2 phút, rửa nhẹ bằng nước, quan sát ở 10x rồi 40x.","Làm tiêu bản tế bào nhân thực: Tách lớp biểu bì mỏng của vảy hành, đặt lên giọt nước cất, nhuộm xanh methylene 2–3 phút, đặt lamen nghiêng 45° để tránh bọt khí, chọn vùng một lớp…","Báo cáo: Mục đích, cách tiến hành, kết quả (vẽ hình tế bào quan sát được, so sánh tế bào nhân sơ và nhân thực), giải thích và trả lời câu hỏi."],"e":["Hay nhầm: Iod không phải thuốc nhuộm trong bài.","Hay nhầm: Nước cất dùng để pha loãng và làm ướt tiêu bản.","Hay nhầm: Ethanol dùng để pha thuốc nhuộm, không nhuộm mẫu.","Hay nhầm: Vật kính 100x dùng sau cùng, khi cần chi tiết.","Hay nhầm: Chưa phải lựa chọn ban đầu.","Hay nhầm: Kính hiển vi cần vật kính để quan sát."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}}]},{"t":"Chương 3. Trao đổi chất qua màng và truyền tin tế bào","l":[{"t":"Bài 10. Trao đổi chất qua màng tế bào","req":["Nêu được khái niệm trao đổi chất qua màng tế bào.","Phân biệt được vận chuyển thụ động và chủ động; nêu ý nghĩa và lấy ví dụ.","Trình bày được hiện tượng nhập bào và xuất bào qua biến dạng của tế bào."],"sum":["Trao đổi chất qua màng là sự vận chuyển các chất ra, vào tế bào qua màng. Màng có tính thấm chọn lọc, cho phép một số chất đi qua và chặn các chất khác.","Khái niệm: Trao đổi chất qua màng là sự vận chuyển các chất ra, vào tế bào qua màng.","1: Vận chuyển thụ động: chất khuếch tán từ nơi nồng độ cao đến nơi nồng độ thấp, xuôi gradient nồng độ, không tốn năng lượng.","Thẩm thấu: Khuếch tán của nước qua màng, từ nơi nồng độ chất tan thấp tới nơi nồng độ chất tan cao.","2: Vận chuyển chủ động: chất đi từ nơi nồng độ thấp tới nơi nồng độ cao, ngược gradient, cần năng lượng ATP.","3: Thực bào, ẩm bào và xuất bào: đại phân tử, protein, DNA hay cả tế bào được màng bao lấy tạo túi vận chuyển."],"e":["Hay nhầm: Đây là đặc điểm của vận chuyển chủ động.","Hay nhầm: Đây là xuất bào, một dạng vận chuyển chủ động.","Hay nhầm: Lysosome không liên quan trực tiếp đến vận chuyển qua màng.","Hay nhầm: Khuếch tán đơn giản không cần protein.","Hay nhầm: Thẩm thấu là khuếch tán của nước.","Hay nhầm: Ẩm bào lấy chất tan theo túi vận chuyển, không phải bơm."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 11. Thực hành: Thí nghiệm co và phản co nguyên sinh","req":["Thực hiện thành thạo kĩ năng sử dụng kính hiển vi và làm tiêu bản.","Quan sát và vẽ được tế bào ở các giai đoạn co nguyên sinh và phản co nguyên sinh.","Điều khiển được sự co nguyên sinh qua mức độ thẩm thấu của nước."],"sum":["Nguyên lí: khi môi trường ngoài có nồng độ chất tan cao hơn trong tế bào, nước thoát ra làm chất nguyên sinh co lại, tách khỏi thành tế bào.","Nguyên lí: Khi môi trường ngoài có nồng độ chất tan cao hơn trong tế bào, nước thoát ra làm chất nguyên sinh co lại, tách khỏi thành tế bào.","Thí nghiệm co nguyên sinh: Tách lớp biểu bì dưới lá thài lài tía, đặt lên giọt dung dịch NaCl loãng rồi đậy lamen, thấm bớt dung dịch thừa.","Thí nghiệm phản co nguyên sinh: Sau khi đã co, nhỏ một giọt nước cất vào mép lamen và dùng giấy thấm hút ở phía đối diện để nước chảy qua tiêu bản.","Báo cáo: Nêu mục đích, cách tiến hành, kết quả quan sát và giải thích."],"e":["Hay nhầm: Nhược trương làm tế bào căng phồng.","Hay nhầm: Ion không phải nguyên nhân trực tiếp.","Hay nhầm: Thành tế bào không bị phá huỷ trong thí nghiệm.","Hay nhầm: Tế bào có màng sinh chất.","Hay nhầm: Ribosome không giúp quan sát rõ.","Hay nhầm: Lục lạp không phải lí do chính trong bài thí nghiệm này."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 12. Truyền tin tế bào","req":["Nêu được khái niệm về truyền tin giữa các tế bào.","Trình bày được quá trình tiếp nhận, truyền tin và đáp ứng.","Giải thích vì sao cùng một tín hiệu gây đáp ứng khác nhau ở các tế bào khác nhau."],"sum":["Truyền tin tế bào là sự phát tán và nhận các phân tử tín hiệu giữa các tế bào. Truyền tin có thể xảy ra giữa tế bào của cùng cơ thể, giữa các cá thể cùng loài hoặc khác loài.","Khái niệm: Truyền tin tế bào là sự phát tán và nhận các phân tử tín hiệu giữa các tế bào.","Tín hiệu giữa các tế bào chủ…: Tín hiệu giữa các tế bào chủ yếu là tín hiệu hoá học như amino acid, peptide, protein, nucleotide, hormone, hoặc khí NO.","Truyền tin trong tế bào gồm ba giai đoạn: Tiếp nhận tín hiệu qua thụ thể trên màng hoặc trong tế bào chất, mỗi thụ thể gắn với một tín hiệu phù hợp như chìa khoá và ổ khoá","Cùng một tín hiệu nhưng gây đáp…: Cùng một tín hiệu nhưng gây đáp ứng khác nhau ở các tế bào khác nhau, vì mỗi loại tế bào biệt hoá có nhóm gene hoạt động khác nhau, nên thụ thể,…"],"e":["Hay nhầm: Đáp ứng là giai đoạn cuối cùng.","Hay nhầm: Truyền tín hiệu diễn ra sau khi tiếp nhận.","Hay nhầm: Phân chia là một đáp ứng có thể xảy ra.","Hay nhầm: Lipid là thành phần cấu tạo màng, không phải thụ thể.","Hay nhầm: Ti thể là bào quan có màng kép.","Hay nhầm: Không đặc trưng cho gan và cơ tim."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 4. Chuyển hoá năng lượng trong tế bào","l":[{"t":"Bài 13. Khái quát về chuyển hoá vật chất và năng lượng. Enzyme","req":["Phân biệt được các dạng năng lượng trong chuyển hoá năng lượng ở tế bào.","Phân tích được cấu tạo và chức năng của ATP về giá trị năng lượng sinh học.","Nêu được khái niệm, cấu trúc và cơ chế tác động của enzyme."],"sum":["Năng lượng là khả năng sinh công hoặc tạo nên sự chuyển động của vật chất. Trong tế bào, năng lượng tồn tại ở hai dạng: động năng (nhiệt năng, cơ năng, điện năng) và thế năng (năng lượng trong liên…","Khái niệm: Năng lượng là khả năng sinh công hoặc tạo nên sự chuyển động của vật chất.","ATP là \"đồng tiền\" năng lượng của tế bào: Gồm adenine, đường ribose và ba gốc phosphate.","Chuyển hoá vật chất là tập hợp…: Chuyển hoá vật chất là tập hợp các phản ứng hoá học làm biến đổi chất; chuyển hoá năng lượng là sự chuyển đổi năng lượng từ dạng này sang dạng khác…","Enzyme là chất xúc tác sinh học…: Enzyme là chất xúc tác sinh học, làm tăng tốc độ phản ứng trong điều kiện sinh lí và không bị biến đổi sau phản ứng.","Trung tâm hoạt động của enzyme có…: Trung tâm hoạt động của enzyme có cấu hình không gian phù hợp với cơ chất."],"e":["Hay nhầm: ATP chứa ribose, không phải deoxyribose; và có ba gốc phosphate.","Hay nhầm: ATP không dự trữ lâu dài; dự trữ dài hạn là glycogen, lipid.","Hay nhầm: ATP có ở mọi tế bào sống.","Hay nhầm: ATP có liên kết cao năng.","Hay nhầm: Lipid không phải enzyme chủ yếu.","Hay nhầm: Ion kim loại chỉ là cofactor đi kèm."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 14. Phân giải và tổng hợp các chất trong tế bào","req":["Phát biểu được khái niệm phân giải và tổng hợp các chất trong tế bào.","Trình bày được các giai đoạn phân giải hiếu khí và lên men.","Nêu được vai trò của quang hợp, hoá tổng hợp và quang khử trong tổng hợp chất và tích luỹ năng lượng."],"sum":["Phân giải là quá trình phá vỡ liên kết trong phân tử sinh học tạo phân tử nhỏ hơn và giải phóng năng lượng, một phần tích luỹ trong ATP, phần còn lại thành nhiệt.","Khái niệm: Phân giải là quá trình phá vỡ liên kết trong phân tử sinh học tạo phân tử nhỏ hơn và giải phóng năng lượng, một phần tích luỹ trong ATP, phần còn…","Hô hấp tế bào hiếu khí phân…: Hô hấp tế bào hiếu khí phân giải glucose hoàn toàn thành CO₂ và H₂O với sự tham gia của O₂.","Lên men phân giải đường không hoàn…: Lên men phân giải đường không hoàn toàn, không cần O₂ và chuỗi truyền electron, chỉ tạo 2 ATP từ mỗi glucose.","Tổng hợp là hình thành hợp chất…: Tổng hợp là hình thành hợp chất phức tạp từ chất đơn giản, tiêu tốn năng lượng.","Quang hợp ở thực vật chuyển năng lượng ánh sáng thành hoá năng: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ với ánh sáng và diệp lục."],"e":["Hay nhầm: Tinh bột không phải sản phẩm hô hấp.","Hay nhầm: Lactate và ethanol là sản phẩm lên men.","Hay nhầm: Glucose là nguyên liệu, không phải sản phẩm.","Hay nhầm: Chu trình Krebs diễn ra ở chất nền ti thể.","Hay nhầm: Pha sáng quang hợp diễn ra ở màng thylakoid.","Hay nhầm: Chuỗi truyền electron diễn ra ở màng trong ti thể."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Thực hành: Phân tích ảnh hưởng của một số yếu tố đến hoạt tính enzyme và kiểm tra enzyme amylase","req":["Quan sát và nhận xét hiệu quả tác dụng của enzyme trong phân huỷ protein và tinh bột.","Nhận xét ảnh hưởng của pH và nhiệt độ đến hoạt tính enzyme phân huỷ protein và tinh bột.","Thực hiện được các bước thí nghiệm theo quy trình."],"sum":["Mục tiêu: đánh giá tác dụng của enzyme phân huỷ protein (từ lõi dứa hoặc dịch đu đủ) với lòng trắng trứng, và enzyme amylase (từ mầm lúa hoặc ngô) với tinh bột; xét ảnh hưởng của nước vôi trong…","Mục tiêu: Đánh giá tác dụng của enzyme phân huỷ protein (từ lõi dứa hoặc dịch đu đủ) với lòng trắng trứng, và enzyme amylase (từ mầm lúa hoặc ngô) với tinh…","Thí nghiệm 1 (protein): Chia dịch enzyme thành 4 ống, thêm nước cất, nước vôi trong, đun sôi hoặc nước đá theo bảng; thêm dung dịch lòng trắng trứng, ghi thời gian dung…","Thí nghiệm 2 (tinh bột): Chuẩn bị đĩa tinh bột từ bột lọc, chia dịch mầm lúa vào 4 ống xử lí như trên; nhỏ dịch lên đĩa, sau 15 phút đo đường kính vết lõm.","Báo cáo cần nêu mục đích, cách…: Báo cáo cần nêu mục đích, cách tiến hành, kết quả (thời gian và đường kính vết lõm), giải thích và trả lời câu hỏi."],"e":["Hay nhầm: Đun sôi là xử lí thử nghiệm nhiệt độ.","Hay nhầm: Nước đá là xử lí nhiệt độ thấp.","Hay nhầm: Nước vôi trong là xử lí pH.","Hay nhầm: Lòng trắng là cơ chất protein.","Hay nhầm: Bột lọc là cơ chất tinh bột.","Hay nhầm: Nước vôi trong là dung dịch kiềm."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 5. Chu kì tế bào và phân bào","l":[{"t":"Bài 16. Chu kì tế bào và nguyên phân","req":["Nêu được khái niệm chu kì tế bào và trình bày các giai đoạn của chu kì ở sinh vật nhân thực.","Giải thích được nguyên phân là cơ chế sinh sản của tế bào dựa trên nhân đôi và phân li NST.","Giải thích được sự phân chia bất thường có thể dẫn đến ung thư."],"sum":["Chu kì tế bào là khoảng thời gian từ khi tế bào được sinh ra, lớn lên đến khi phân chia thành hai tế bào con.","Khái niệm: Chu kì tế bào là khoảng thời gian từ khi tế bào được sinh ra, lớn lên đến khi phân chia thành hai tế bào con.","Hệ thống kiểm soát chu kì có các điểm kiểm soát: G₁/S quyết định có nhân đôi DNA hay không;","Nguyên phân gồm phân chia nhân (kì…: Nguyên phân gồm phân chia nhân (kì đầu, kì giữa, kì sau, kì cuối) và phân chia tế bào chất.","Kết quả: Từ một tế bào mẹ 2n tạo hai tế bào con có bộ NST giống nhau và giống tế bào mẹ.","Ung thư: Tín hiệu kích thích phân bào quá nhiều và kìm hãm quá ít khiến tế bào phân chia quá mức, tạo khối u."],"e":["Hay nhầm: G₁ là pha sinh trưởng ban đầu.","Hay nhầm: G₂ là pha chuẩn bị phân bào.","Hay nhầm: Kì đầu là giai đoạn của nguyên phân.","Hay nhầm: Tách rời xảy ra ở kì sau.","Hay nhầm: Tháo xoắn xảy ra ở kì cuối.","Hay nhầm: NST không nhân đôi ở kì giữa."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 17. Giảm phân","req":["Giải thích được quá trình giảm phân, thụ tinh cùng nguyên phân là cơ sở của sinh sản hữu tính.","Trình bày được một số nhân tố ảnh hưởng đến giảm phân.","Lập được bảng so sánh nguyên phân và giảm phân."],"sum":["Giảm phân là hình thức phân chia của tế bào mầm sinh dục để sản sinh giao tử. Giảm phân gồm hai lần phân bào liên tiếp (giảm phân I và giảm phân II) nhưng chỉ có một lần nhân đôi NST ở kì trung gian…","Khái niệm: Giảm phân là hình thức phân chia của tế bào mầm sinh dục để sản sinh giao tử.","Giảm phân I: Ở kì đầu I, các NST kép tương đồng bắt cặp và có thể trao đổi đoạn;","Kết quả: Từ một tế bào 2n qua giảm phân tạo bốn tế bào n có tổ hợp NST khác nhau (do phân li ngẫu nhiên và trao đổi chéo).","Yếu tố ảnh hưởng: Điều kiện môi trường (ánh sáng, nhiệt độ, nước) ảnh hưởng đến khả năng ra hoa; hormone sinh dục điều khiển sinh sản; tuổi mẹ càng cao, nguy cơ giao…","Ý nghĩa: Giảm phân kết hợp với thụ tinh và nguyên phân giúp duy trì bộ NST 2n đặc trưng của loài; các tổ hợp NST và gene mới tạo biến dị tổ hợp, nguyên liệu…"],"e":["Hay nhầm: Nguyên phân mới tạo hai tế bào con giữ NST.","Hay nhầm: Số NST không gấp đôi trong giảm phân.","Hay nhầm: NST gấp đôi không xảy ra.","Hay nhầm: Không có nhân đôi trong giảm phân.","Hay nhầm: Không có ba lần nhân đôi.","Hay nhầm: Nhân đôi chỉ xảy ra một lần."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 18. Thực hành: Làm và quan sát tiêu bản quá trình nguyên phân và giảm phân","req":["Thực hiện được các bước làm tiêu bản NST để quan sát nguyên phân và giảm phân.","Quan sát và vẽ được các tế bào ở các giai đoạn khác nhau của nguyên phân và giảm phân.","Rèn kĩ năng sử dụng kính hiển vi và làm tiêu bản hiển vi."],"sum":["Mục tiêu: làm tiêu bản NST của rễ hành (nguyên phân) và của ống sinh tinh châu chấu (giảm phân) để quan sát các kì phân bào dưới kính hiển vi quang học.","Mục tiêu: Làm tiêu bản NST của rễ hành (nguyên phân) và của ống sinh tinh châu chấu (giảm phân) để quan sát các kì phân bào dưới kính hiển vi quang học.","Nguyên phân ở rễ hành: Cắt đầu rễ khoảng 5 mm, cố định ít nhất 24 giờ, nhuộm acetocarmine và đun nóng nhẹ 5–8 phút, cắt đoạn rễ khoảng 3 mm từ đầu chóp, đặt lên lam kính,…","Giảm phân ở châu chấu: Mổ châu chấu đực, lấy các ống sinh tinh (màu trắng đục) và ngâm trong dung dịch KCl nhược trương, loại bỏ mỡ.","Báo cáo: Mục đích, cách tiến hành, kết quả tiêu bản (vẽ các kì nguyên phân và giảm phân), giải thích và trả lời câu hỏi, ví dụ vì sao không đun sôi khi…"],"e":["Hay nhầm: Xanh methylene dùng trong bài vi khuẩn.","Hay nhầm: Iod không dùng trong bài này.","Hay nhầm: Fuchsin không phải thuốc nhuộm trong quy trình.","Hay nhầm: Rễ hành dùng cho nguyên phân.","Hay nhầm: Lá thài lài tía dùng cho bài co nguyên sinh.","Hay nhầm: Vảy hành dùng cho bài quan sát tế bào nhân thực."],"q":{"n":5,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":1}}},{"t":"Bài 19. Công nghệ tế bào","req":["Nêu được khái niệm, nguyên lí và một số thành tựu của công nghệ tế bào động vật.","Nêu được khái niệm, nguyên lí và một số thành tựu của công nghệ tế bào thực vật."],"sum":["Công nghệ tế bào động vật là nuôi cấy các loại tế bào động vật và người trong môi trường nhân tạo để tạo lượng lớn tế bào phục vụ nghiên cứu và ứng dụng.","Khái niệm: Công nghệ tế bào động vật là nuôi cấy các loại tế bào động vật và người trong môi trường nhân tạo để tạo lượng lớn tế bào phục vụ nghiên cứu và ứng…","Tế bào gốc phôi (tế bào gốc…: Tế bào gốc phôi (tế bào gốc vạn năng) biệt hoá thành mọi loại tế bào; tế bào gốc trưởng thành (đa tiềm năng) chỉ biệt hoá thành một số loại tế bào…","Ba thành tựu nổi bật: Nhân bản vô tính vật nuôi, tạo cá thể có cùng kiểu gene, như cừu Dolly (1996); có thể tăng số lượng loài nguy cơ tuyệt chủng","Công nghệ tế bào thực vật là…: Công nghệ tế bào thực vật là nuôi cấy tế bào, mô thực vật trong điều kiện vô trùng để tạo cây có kiểu gene giống nhau.","Ba kĩ thuật chủ yếu: Nuôi cấy mô tế bào (nhân nhanh giống quý hiếm, cây sạch bệnh virus), lai tế bào sinh dưỡng (sau khi loại bỏ thành cellulose, tạo cây lai khác loài)…"],"e":["Hay nhầm: Tế bào gốc trưởng thành chỉ biệt hoá thành một số loại.","Hay nhầm: Tế bào đã biệt hoá không còn khả năng này.","Hay nhầm: Tế bào máu không phải tế bào gốc vạn năng.","Hay nhầm: Lai tế bào sinh dưỡng là công nghệ thực vật.","Hay nhầm: Nuôi cấy hạt phấn là kĩ thuật thực vật.","Hay nhầm: Dolly không phải chỉnh sửa gene thực vật."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chương 6. Sinh học vi sinh vật","l":[{"t":"Bài 20. Các nhóm vi sinh vật. Kiểu dinh dưỡng và phương pháp nghiên cứu","req":["Nêu được khái niệm vi sinh vật và kể tên các nhóm vi sinh vật.","Phân biệt được các kiểu dinh dưỡng của vi sinh vật.","Trình bày được một số phương pháp nghiên cứu vi sinh vật."],"sum":["Vi sinh vật là sinh vật có kích thước nhỏ, thường chỉ quan sát được dưới kính hiển vi. Vi sinh vật gồm vi sinh vật nhân sơ (vi khuẩn, Archaea) và vi sinh vật nhân thực (vi tảo, vi nấm, động vật…","Khái niệm: Vi sinh vật là sinh vật có kích thước nhỏ, thường chỉ quan sát được dưới kính hiển vi.","Vi khuẩn Archaea sống ở môi trường…: Vi khuẩn Archaea sống ở môi trường cực đoan, như nơi có áp suất cao, nồng độ muối cao, phóng xạ cao hoặc nhiệt độ cực thấp, cao.","Dựa vào nguồn năng lượng và nguồn…: Dựa vào nguồn năng lượng và nguồn carbon, vi sinh vật có bốn kiểu dinh dưỡng: quang tự dưỡng (ánh sáng, CO₂), hoá tự dưỡng (chất vô cơ, CO₂), quang…","Phương pháp nghiên cứu gồm quan sát…: Phương pháp nghiên cứu gồm quan sát (làm tiêu bản soi tươi, nhuộm đơn, nhuộm Gram), phân lập và nuôi cấy trên môi trường thạch để thu khuẩn lạc…"],"e":["Hay nhầm: Vi khuẩn lam là vi khuẩn, nhân sơ.","Hay nhầm: Không đặc trưng cho tự dưỡng.","Hay nhầm: Ánh sáng không phải tiêu chí duy nhất của tự dưỡng.","Hay nhầm: Chất hữu cơ là nguồn của dị dưỡng.","Hay nhầm: NH₃ là nguồn của hoá tự dưỡng.","Hay nhầm: Fe²⁺ là nguồn của hoá tự dưỡng."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 21. Trao đổi chất, sinh trưởng và sinh sản ở vi sinh vật","req":["Nêu được ví dụ về tổng hợp và phân giải các chất ở vi sinh vật.","Nêu được khái niệm sinh trưởng ở vi sinh vật và đặc điểm các pha sinh trưởng của quần thể vi khuẩn.","Trình bày được các yếu tố ảnh hưởng đến sinh trưởng và ý nghĩa, tác hại của kháng sinh."],"sum":["Vi sinh vật có khả năng tổng hợp đầy đủ các chất như carbohydrate, protein, nucleic acid, lipid.","Khái niệm: Vi sinh vật có khả năng tổng hợp đầy đủ các chất như carbohydrate, protein, nucleic acid, lipid.","Sinh trưởng của quần thể vi sinh…: Sinh trưởng của quần thể vi sinh vật là sự tăng số lượng tế bào.","Nuôi cấy không liên tục có bốn pha: Pha tiềm phát (thích nghi), pha luỹ thừa (phân chia mạnh, đạt cực đại cuối pha), pha cân bằng (số tế bào sinh ra bằng số chết đi) và pha suy vong…","Yếu tố vật lí: Nhiệt độ (ưa lạnh, ưa ấm, ưa nhiệt, siêu ưa nhiệt), độ ẩm, pH, ánh sáng, áp suất thẩm thấu.","Kháng sinh là chất do vi sinh…: Kháng sinh là chất do vi sinh vật tiết ra hoặc tổng hợp nhân tạo, ức chế hoặc tiêu diệt vi khuẩn."],"e":["Hay nhầm: Pha tiềm phát vi khuẩn còn thích nghi.","Hay nhầm: Pha cân bằng số tế bào không tăng nhanh.","Hay nhầm: Pha suy vong số tế bào giảm.","Hay nhầm: Đây là khái niệm tế bào chết, không phải thời gian thế hệ.","Hay nhầm: Không phải thời gian chuẩn bị.","Hay nhầm: Không phải thời gian sống của bào tử."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 22. Vai trò và ứng dụng của vi sinh vật","req":["Phân tích được vai trò của vi sinh vật trong đời sống con người và trong tự nhiên.","Kể tên được một số thành tựu hiện đại của công nghệ vi sinh vật.","Trình bày được cơ sở khoa học và một số ứng dụng của vi sinh vật trong thực tiễn."],"sum":["Vi sinh vật phân giải xác sinh vật và chất thải thành chất khoáng, bảo đảm vòng tuần hoàn vật chất; vi sinh vật tự dưỡng tạo O₂ và chất hữu cơ cho sinh vật khác.","Khái niệm: Vi sinh vật phân giải xác sinh vật và chất thải thành chất khoáng, bảo đảm vòng tuần hoàn vật chất; vi sinh vật tự dưỡng tạo O₂ và chất hữu cơ cho…","Cơ sở khoa học: Kích thước nhỏ, tỉ lệ S/V lớn nên trao đổi chất và sinh trưởng nhanh; sinh sản phân đôi nhanh (E. coli 20 phút/lần);","Ứng dụng nông nghiệp: Vi khuẩn cố định đạm, phân giải lân, tạo phân bón vi sinh và thuốc trừ sâu vi sinh, thân thiện với môi trường.","Ứng dụng y dược: Kháng sinh, vaccine, amino acid, hormone, interferon; insulin và hormone sinh trưởng tạo bằng công nghệ tái tổ hợp ở vi khuẩn và nấm men.","Triển vọng: Kết hợp công nghệ vi sinh với công nghệ nano, thông tin và trí tuệ nhân tạo; nghiên cứu hệ vi sinh vật Trái Đất và của người; sản điện từ vi khuẩn…"],"e":["Hay nhầm: Sữa chua do vi khuẩn lactic.","Hay nhầm: Pho mát do vi khuẩn lactic.","Hay nhầm: Nước mắm do vi sinh vật phân giải protein.","Hay nhầm: Vi sinh vật không tổng hợp nhựa.","Hay nhầm: Vi sinh vật không tạo kim loại nặng.","Hay nhầm: Biofilm làm tắc, đó là tác hại."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 23. Thực hành: Một số phương pháp nghiên cứu vi sinh vật và làm sản phẩm lên men từ vi sinh vật","req":["Thực hiện được một số phương pháp nghiên cứu vi sinh vật thông dụng.","Thực hiện được đúng các bước làm sữa chua, dưa chua và quan sát vi khuẩn trong sữa chua.","Rèn năng lực tổ chức, hợp tác nhóm, viết báo cáo và thuyết trình."],"sum":["Mục tiêu: tìm hiểu một số sản phẩm của công nghệ vi sinh vật như rượu, bia, sữa chua, kháng sinh, vaccine; quan sát vi khuẩn trong sữa chua; làm sữa chua và dưa chua theo quy trình đảm bảo chất lượng.","Mục tiêu: Tìm hiểu một số sản phẩm của công nghệ vi sinh vật như rượu, bia, sữa chua, kháng sinh, vaccine; quan sát vi khuẩn trong sữa chua; làm sữa chua và…","Quan sát vi khuẩn trong sữa chua: Pha loãng một thìa sữa chua không đường (đã ngâm ở 40–45 °C trong 8–12 giờ) với 10 mL nước cất, nhỏ một giọt lên lam kính, đậy lamen, quan sát ở 40x…","Làm sữa chua: Hoà sữa đặc có đường với nước ấm 50–55 °C, thêm một hộp sữa chua, đổ vào lọ, đậy kín và ủ ở khoảng 40 °C trong 8–10 giờ, sau đó cho vào tủ lạnh.","Làm dưa chua: Phơi cải cho hơi héo, cắt khúc khoảng 3 cm; pha nước muối từ 1 lít nước đun sôi để ấm với 3 thìa muối hạt và 1 thìa đường; xếp rau vào lọ, nén bằng…","Báo cáo: Mục đích, cách tiến hành, kết quả (tìm hiểu công nghệ vi sinh vật, quan sát vi khuẩn, sữa chua, dưa chua, rượu), giải thích và trả lời câu hỏi."],"e":["Hay nhầm: Vi khuẩn lam quang hợp, không dùng làm sữa chua.","Hay nhầm: Trùng giày là động vật nguyên sinh.","Hay nhầm: 100 °C sẽ tiêu diệt vi khuẩn.","Hay nhầm: 4 °C là nhiệt độ bảo quản lạnh.","Hay nhầm: Nhiệt độ âm không phù hợp.","Hay nhầm: Phơi héo làm rau mất nước."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 7. Virus","l":[{"t":"Bài 24. Khái quát về virus","req":["Nêu được khái niệm và các đặc điểm của virus.","Trình bày được cấu tạo của virus.","Trình bày được các giai đoạn nhân lên của virus trong tế bào chủ."],"sum":["Virus là thực thể chưa có cấu tạo tế bào, kích thước khoảng 20–300 nm, chỉ nhân lên trong tế bào sống.","Khái niệm: Virus là thực thể chưa có cấu tạo tế bào, kích thước khoảng 20–300 nm, chỉ nhân lên trong tế bào sống.","Cấu tạo chung: Lõi là nucleic acid (DNA hoặc RNA, mạch đơn hoặc kép, một hoặc vài đoạn) và vỏ capsid là protein.","Virus có thể kí sinh ở vi…: Virus có thể kí sinh ở vi khuẩn, nấm, thực vật và động vật; mỗi loại chỉ lây nhiễm một số loài nhất định gọi là phổ vật chủ.","Nhân lên của virus trải qua năm giai đoạn: Hấp phụ lên thụ thể tế bào chủ","Có hai chu kì: Chu kì sinh tan (năm giai đoạn, tế bào bị phá huỷ khi virus được giải phóng) và chu kì tiềm tan (DNA virus tích hợp vào hệ gene tế bào, nhân lên…"],"e":["Hay nhầm: Lõi nucleic acid là thành phần chung.","Hay nhầm: Vỏ capsid là thành phần chung.","Hay nhầm: Vỏ ngoài có ở một số virus động vật.","Hay nhầm: Virus không có cấu tạo tế bào.","Hay nhầm: Virus không tự tổng hợp ATP.","Hay nhầm: ATP không do gai glycoprotein tạo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 25. Một số bệnh do virus và các thành tựu nghiên cứu, ứng dụng virus","req":["Giải thích được cơ chế gây bệnh do virus.","Trình bày được phương thức lây truyền và cách phòng chống một số bệnh do virus ở người, thực vật và động vật.","Giải thích được vì sao các bệnh do virus thường lây lan nhanh, rộng và có nhiều biến thể."],"sum":["Cơ chế gây bệnh chung: virus kiểu sinh tan phá huỷ tế bào, mức độ bệnh phụ thuộc số tế bào bị huỷ và khả năng tái sinh; virus sinh ra độc tố; virus kiểu tiềm tan có thể gây đột biến dẫn đến ung thư…","Cơ chế gây bệnh chung: Virus kiểu sinh tan phá huỷ tế bào, mức độ bệnh phụ thuộc số tế bào bị huỷ và khả năng tái sinh; virus sinh ra độc tố; virus kiểu tiềm tan có thể…","Sốt cao và đau nhức là đáp…: Sốt cao và đau nhức là đáp ứng của hệ miễn dịch chống virus chứ không phải do virus phá huỷ trực tiếp.","HIV tấn công tế bào bạch cầu…: HIV tấn công tế bào bạch cầu T4 và đại thực bào, có vật chất di truyền là RNA với hai enzyme phiên mã ngược, enzyme intergrase.","Virus cúm A gây đại dịch ở…: Virus cúm A gây đại dịch ở người và động vật; virus lây theo giọt bắn khi hắt hơi và tiếp xúc bề mặt có dịch tiết.","Ứng dụng: Vaccine (Jevax phòng viêm não Nhật Bản, Havax phòng viêm gan A, Gene-HBvax phòng viêm gan B); thuốc trừ sâu virus đặc hiệu, không tiêu diệt côn…"],"e":["Hay nhầm: Tích hợp DNA là đặc điểm HIV, không phải cúm.","Hay nhầm: Virus không tự tiêu biến.","Hay nhầm: ATP không do enzyme này tổng hợp.","Hay nhầm: Amylase phân giải tinh bột.","Hay nhầm: HIV lây qua máu, tình dục, mẹ con.","Hay nhầm: HIV không phá huỷ não là nguyên nhân chính."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 26. Thực hành: Điều tra một số bệnh do virus và tuyên truyền phòng chống bệnh","req":["Thực hiện được đề tài điều tra một số bệnh do virus ở người, vật nuôi và cây trồng.","Tuyên truyền được cách phòng chống một số bệnh do virus."],"sum":["Mục tiêu: điều tra một số bệnh do virus ở người, vật nuôi, cây trồng tại địa phương và thiết kế tờ rơi tuyên truyền phòng chống bệnh.","Mục tiêu: Điều tra một số bệnh do virus ở người, vật nuôi, cây trồng tại địa phương và thiết kế tờ rơi tuyên truyền phòng chống bệnh.","Điều tra bệnh ở người: Thu thập thông tin về loại virus, vật trung gian truyền bệnh, con đường lây, triệu chứng và biện pháp phòng tránh.","Điều tra bệnh ở cây trồng: Sưu tầm mẫu vật, hình ảnh cây nhiễm virus như khoai tây, cà chua, cam, chanh tại địa phương; ghi lại đặc điểm virus, vật trung gian, con đường lây…","Báo cáo: Mục đích, cách tiến hành, kết quả điều tra theo bảng (loại virus, vật trung gian, triệu chứng và cách thức truyền, biện pháp phòng chống) và thiết…"],"e":["Hay nhầm: Ruồi nhà không phải vật trung gian chính của bệnh này.","Hay nhầm: Rầy nâu truyền virus sọc lá lúa.","Hay nhầm: Chuột không phải vật trung gian chính.","Hay nhầm: Không lây truyền qua không khí trong ví dụ này.","Hay nhầm: Không truyền qua hạt giống.","Hay nhầm: Ong mật không là vật truyền bệnh này."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Phần mở đầu","l":[{"t":"Bài tập nâng cao · Phần mở đầu (3 câu)","e":["Hay nhầm: Tốc độ phản ứng là biến phụ thuộc.","Hay nhầm: Thời gian thường được giữ cố định hoặc đo lường.","Hay nhầm: Nồng độ enzyme được giữ không đổi.","Hay nhầm: Tế bào thần kinh có vai trò nền tảng.","Hay nhầm: Bộ não được cấu tạo từ tế bào.","Hay nhầm: Các cấp độ có đặc điểm khác nhau."],"q":{"n":3,"lv":{"Nâng cao":3}}}]},{"t":"Chương 1. Thành phần hoá học của tế bào","l":[{"t":"Bài tập nâng cao · Chương 1. Thành phần hoá học của tế bào (3 câu)","e":["Hay nhầm: Hydrogen chiếm khoảng 10%.","Hay nhầm: Nitrogen chiếm khoảng 3%.","Hay nhầm: Calcium chiếm khoảng 1,5%.","Hay nhầm: Dầu không tan trong nước.","Hay nhầm: Kết tủa đỏ gạch là dấu hiệu của đường khử.","Hay nhầm: Màu xanh tím là dấu hiệu của protein."],"q":{"n":3,"lv":{"Nâng cao":3}}}]},{"t":"Chương 2. Cấu trúc tế bào","l":[{"t":"Bài tập nâng cao · Chương 2. Cấu trúc tế bào (3 câu)","e":["Hay nhầm: Ribosome không do plasmid quyết định.","Hay nhầm: Plasmid không tạo thành tế bào.","Hay nhầm: Plasmid không thay thế DNA vùng nhân.","Hay nhầm: Tế bào thực vật có nhân có màng.","Hay nhầm: Tế bào động vật không có thành cellulose.","Hay nhầm: Nấm có chitin, không phải cellulose."],"q":{"n":3,"lv":{"Nâng cao":3}}}]},{"t":"Chương 3. Trao đổi chất qua màng và truyền tin tế bào","l":[{"t":"Bài tập nâng cao · Chương 3. Trao đổi chất qua màng và truyền tin tế bào (3 câu)","e":["Hay nhầm: Thuốc lớn không khuếch tán đơn giản.","Hay nhầm: Xuất bào đưa chất ra ngoài.","Hay nhầm: Thẩm thấu chỉ là khuếch tán nước.","Hay nhầm: Dung dịch đậm làm nước hút vào chậm hơn.","Hay nhầm: Tế bào không vỡ ngay trong điều kiện này.","Hay nhầm: Polysaccharide lớn không qua màng dễ dàng."],"q":{"n":3,"lv":{"Nâng cao":3}}}]},{"t":"Chương 4. Chuyển hoá năng lượng trong tế bào","l":[{"t":"Bài tập nâng cao · Chương 4. Chuyển hoá năng lượng trong tế bào (2 câu)","e":["Hay nhầm: CO₂ được cố định, không giải phóng O₂.","Hay nhầm: Glucose không tạo O₂ trong đường phân.","Hay nhầm: Lactate là sản phẩm lên men, không liên quan đến O₂.","Hay nhầm: Nhiệt cao quá mức làm enzyme mất hoạt tính.","Hay nhầm: 100 °C làm enzyme mất hoạt tính.","Hay nhầm: Nhiệt độ có ảnh hưởng rõ rệt."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chương 5. Chu kì tế bào và phân bào","l":[{"t":"Bài tập nâng cao · Chương 5. Chu kì tế bào và phân bào (4 câu)","e":["Hay nhầm: p53 làm chậm chu kì khi có sai sót.","Hay nhầm: p53 không làm tế bào di chuyển.","Hay nhầm: Vẫn tạo giao tử nhưng bất thường.","Hay nhầm: Cố định không làm NST nhân đôi.","Hay nhầm: Không liên quan đến số lượng tinh trùng.","Hay nhầm: Nhuộm có thể vẫn được nhưng cấu trúc hỏng."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 6. Sinh học vi sinh vật","l":[{"t":"Bài tập nâng cao · Chương 6. Sinh học vi sinh vật (4 câu)","e":["Hay nhầm: Màng ngoài thuộc Gram âm.","Hay nhầm: Penicillin không đổi màu nhuộm.","Hay nhầm: Không nhằm làm chết hàng loạt.","Hay nhầm: Mục tiêu là sinh trưởng ổn định.","Hay nhầm: Đây không phải công nghệ thực vật.","Hay nhầm: Đây không phải nuôi cấy mô động vật."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 7. Virus","l":[{"t":"Bài tập nâng cao · Chương 7. Virus (3 câu)","e":["Hay nhầm: RNA ít ổn định hơn DNA về sao chép.","Hay nhầm: Prion chủ yếu lây qua thức ăn.","Hay nhầm: Prion không phải vi khuẩn.","Hay nhầm: Phổ vật chủ rộng nghĩa là lây nhiều loài.","Hay nhầm: Không chỉ tiêu huỷ người bệnh.","Hay nhầm: Vệ sinh đồng ruộng là cần thiết."],"q":{"n":3,"lv":{"Nâng cao":3}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 10","c":[{"t":"Cụm 1. Unit 1–3 (Ôn tập 1)","l":[{"t":"Unit 1. Family life (Cuộc sống gia đình)","req":["Phân biệt và dùng đúng thì hiện tại đơn và hiện tại tiếp diễn.","Hiểu và dùng từ vựng về cuộc sống gia đình và việc nhà.","Đọc hiểu một đoạn văn về lợi ích của việc nhà đối với trẻ em."],"sum":["Hiện tại đơn: thói quen, sự thật (always, usually, every day). Hiện tại tiếp diễn: đang diễn ra (now, at the moment). Động từ trạng thái không dùng -ing.","Hiện tại đơn: Diễn tả thói quen, việc làm thường xuyên hoặc sự thật hiển nhiên.","Hiện tại tiếp diễn: Diễn tả hành động đang diễn ra ngay lúc nói, hoặc việc đang diễn ra trong giai đoạn hiện tại.","Dấu hiệu nhận biết","Động từ trạng thái: Like, love, need, want, know, agree… không dùng ở tiếp diễn.","Phát âm cụm phụ âm"],"e":["Sai: I am knowing the answer. → Đúng: I know the answer. (know là động từ trạng thái.)","Hay nhầm: Why không đi với to V theo cách này.","Hay nhầm: Whom không phù hợp ở đây.","Hay nhầm: Which one is không đi với to do.","Hay nhầm: Breadwinner là người kiếm tiền nuôi gia đình.","Hay nhầm: Responsibility là trách nhiệm."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. Humans and the environment (Con người và môi trường)","req":["Phân biệt và dùng đúng will và be going to để nói về tương lai.","Dùng đúng câu bị động ở các thì hiện tại đơn, quá khứ đơn và tương lai đơn.","Hiểu và dùng từ vựng về môi trường và lối sống xanh."],"sum":["will: quyết định tức thời, dự đoán chủ quan. be going to: dự định, dự đoán có dấu hiệu. Bị động: be + V3 (+ by O).","Will và be going to","Câu bị động: Dùng khi người / vật thực hiện hành động không quan trọng, không biết, hoặc muốn nhấn mạnh hành động.","Cách đổi sang bị động: Tân ngữ của câu chủ động thành chủ ngữ; động từ đổi sang be + V3 theo đúng thì của động từ gốc.","Phát âm cụm phụ âm"],"e":["Hay nhầm: Carbon footprint là lượng CO₂ do hoạt động con người thải ra.","Hay nhầm: Appliance là thiết bị gia dụng.","Hay nhầm: Litter là rác thải vương vãi.","Hay nhầm: Resources là tài nguyên, không phải thiết bị.","Hay nhầm: Will dùng cho quyết định tại thời điểm nói.","Hay nhầm: Hiện tại đơn không dùng cho dự định tương lai ở đây."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Music (Âm nhạc)","req":["Dùng đúng liên từ and, but, or, so để nối các mệnh đề thành câu ghép.","Phân biệt động từ đi với to-infinitive và bare infinitive.","Hiểu và dùng từ vựng về âm nhạc, các chương trình và sự kiện âm nhạc."],"sum":["Câu ghép: , and / but / or / so. to V sau decide, want, plan, hope…; V (không to) sau make, let, hear.","Câu ghép: Hai mệnh đề độc lập nối bằng liên từ: and (thêm ý), but (đối lập), or (lựa chọn), so (kết quả).","To-infinitive: Đi sau decide, expect, plan, want, promise, agree, hope, ask.","Bare infinitive: Đi sau make, let, hear, notice, help (tùy trường hợp).","Trọng âm từ hai âm tiết","Từ vựng âm nhạc"],"e":["Sai: They made us to wait. → Đúng: They made us wait. (make + O + V không to.)","Hay nhầm: Participant là người tham gia.","Hay nhầm: Performance là buổi biểu diễn.","Hay nhầm: Upload là động từ tải lên.","Hay nhầm: Live concert là buổi hoà nhạc trực tiếp.","Hay nhầm: Musical instrument là nhạc cụ."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 2. Unit 4–5 (Ôn tập 2)","l":[{"t":"Unit 4. For a better community (Vì một cộng đồng tốt đẹp hơn)","req":["Phân biệt và dùng đúng thì quá khứ đơn và quá khứ tiếp diễn với when và while.","Phân biệt hậu tố tính từ -ed/-ing và -ful/-less.","Hiểu và dùng từ vựng về phát triển cộng đồng và hoạt động tình nguyện."],"sum":["While + was/were V-ing, V-ed; V-ed + when + was/were V-ing. Tính từ -ed (cảm xúc người), -ing (sự vật). Hậu tố -ful (có), -less (không có).","Quá khứ tiếp diễn và quá khứ đơn: Quá khứ tiếp diễn diễn tả hành động dài đang diễn ra tại một thời điểm hoặc bị xen vào; quá khứ đơn diễn tả hành động ngắn xảy ra và kết thúc.","Tính từ -ed và -ing","Hậu tố -ful và -less","Trọng âm từ giống chữ"],"e":["Hay nhầm: Donation là khoản quyên góp.","Hay nhầm: Orphanage là trại trẻ mồ côi.","Hay nhầm: Advertisement là quảng cáo.","Hay nhầm: Successful là thành công.","Hay nhầm: Charitable là có tính từ thiện.","Hay nhầm: Sau we cần động từ, không phải cụm danh từ."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Inventions (Các phát minh)","req":["Dùng đúng thì hiện tại hoàn thành với just, already, yet, since, for.","Phân biệt danh động từ (V-ing) và to-infinitive sau các động từ khác nhau.","Hiểu và dùng từ vựng về phát minh, thiết bị và phần cứng máy tính."],"sum":["Hiện tại hoàn thành: have/has + V3. Sau enjoy, avoid, finish dùng V-ing; sau want, decide, allow dùng to V.","Hiện tại hoàn thành","V-ing và to V: V-ing đứng sau enjoy, avoid, finish và làm chủ ngữ. To V đứng sau want, decide, allow và sau tính từ nêu ý kiến.","Trọng âm danh từ ba âm tiết: Thường rơi vào âm tiết đầu, nhưng có ngoại lệ."],"e":["Hay nhầm: Communicate là giao tiếp.","Hay nhầm: Experiment là thí nghiệm.","Hay nhầm: Laboratory là phòng thí nghiệm.","Hay nhầm: Storage space là dung lượng lưu trữ.","Hay nhầm: Yesterday không đi với hiện tại hoàn thành.","Hay nhầm: Quá khứ đơn không nhấn mạnh ảnh hưởng hiện tại."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 3. Unit 6–8 (Ôn tập 3)","l":[{"t":"Unit 6. Gender equality (Bình đẳng giới)","req":["Dùng đúng câu bị động với động từ khuyết thiếu (can, may, must, should, ought to).","Hiểu và dùng từ vựng về bình đẳng giới, nghề nghiệp và các vấn đề xã hội.","Đọc hiểu một đoạn văn về các thách thức đối với bình đẳng giới."],"sum":["Bị động với động từ khuyết thiếu: modal + be + V3 (+ by O). Chỉ có một be.","Modal + be + V3: Với can, could, may, might, must, should, ought to.","Trọng âm từ ba âm tiết","Từ vựng bình đẳng giới"],"e":["Sai: It can be be done. → Đúng: It can be done. (Chỉ có một be sau động từ khuyết thiếu.)","Hay nhầm: Surgeon là bác sĩ phẫu thuật.","Hay nhầm: Parachutist là người nhảy dù.","Hay nhầm: Firefighter là lính cứu hoả.","Hay nhầm: Thiếu be trước V3 sau can.","Hay nhầm: Sau can dùng động từ nguyên mẫu, không tiếp diễn."],"q":{"n":19,"lv":{"Biết":5,"Hiểu":7,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 7. Viet Nam and international organisations (Việt Nam và các tổ chức quốc tế)","req":["Dùng đúng tính từ so sánh hơn và so sánh nhất, gồm các dạng bất quy tắc.","Hiểu và dùng từ vựng về tổ chức quốc tế, thương mại và phát triển.","Đọc hiểu một đoạn văn về hoạt động hỗ trợ giáo dục của UNICEF tại Việt Nam."],"sum":["So sánh hơn: adj-er / more + adj + than. So sánh nhất: the adj-est / the most + adj. Bất quy tắc: good – better – the best.","So sánh hơn: So sánh hai người hoặc hai vật. Tính từ ngắn thêm -er; tính từ dài dùng more / less.","So sánh nhất: So với cả một nhóm.","Bất quy tắc","So sánh bằng và kém","Trọng âm từ dài: Từ ba âm tiết trở lên có trọng âm chính và trọng âm phụ."],"e":["Hay nhầm: Vaccinate là tiêm vắc-xin.","Hay nhầm: Competitive là có tính cạnh tranh.","Hay nhầm: Regional là thuộc khu vực.","Hay nhầm: Không dùng more với tính từ ngắn large.","Hay nhầm: The largest là so sánh nhất.","Hay nhầm: Không dùng -er với tính từ dài."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. New ways to learn (Những cách học mới)","req":["Phân biệt mệnh đề quan hệ xác định và không xác định với who, that, which, whose.","Hiểu và dùng từ vựng về các hình thức học tập như học trực tiếp, học trực tuyến và học kết hợp.","Đọc hiểu một đoạn văn so sánh học trực tiếp và học trực tuyến."],"sum":["Mệnh đề quan hệ: who (người), which (vật), that (cả hai), whose (sở hữu). Xác định: không dấu phẩy. Không xác định: có dấu phẩy, không dùng that.","Mệnh đề quan hệ: Bổ sung thông tin cho danh từ đứng trước.","Xác định và không xác định","Trọng âm câu: Nhấn các từ nội dung (động từ chính, danh từ, tính từ, trạng từ); các từ chức năng (a, the, of, to) đọc nhẹ.","Từ vựng học tập"],"e":["Sai: My uncle, that visited us yesterday, is a doctor. → Đúng: My uncle, who visited us yesterday, is a doctor. (Không dùng that trong mệnh đề không xác định.)","Hay nhầm: Face-to-face là học trực tiếp, không kết hợp.","Hay nhầm: Online chỉ học trên mạng.","Hay nhầm: Traditional là truyền thống.","Hay nhầm: Guide là người hướng dẫn.","Hay nhầm: Focus là tập trung (không đi với for ở đây)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Cụm 4. Unit 9–10 (Ôn tập 4)","l":[{"t":"Unit 9. Protecting the environment (Bảo vệ môi trường)","req":["Chuyển câu trực tiếp sang câu tường thuật (lùi thì, đổi đại từ và trạng từ thời gian).","Hiểu và dùng từ vựng về các vấn đề môi trường và cách bảo vệ môi trường.","Đọc hiểu một đoạn văn về các vấn đề môi trường và phân tích nguyên nhân, hậu quả."],"sum":["Tường thuật: lùi thì một bậc, đổi đại từ và trạng từ. Wh-: giữ từ hỏi, đổi sang trật tự câu kể. Yes/No: dùng if / whether.","Lùi thì","Đổi đại từ và trạng từ","Câu hỏi tường thuật: Wh-: giữ từ để hỏi, đổi sang trật tự câu khẳng định. Yes/No: dùng if hoặc whether.","Động từ tường thuật: Say / tell (thông báo), ask (câu hỏi), suggest, advise (lời khuyên). Tell cần có tân ngữ.","Nhịp điệu: Nhấn các từ nội dung, lướt nhẹ các từ chức năng."],"e":["Sai: He asked me where did I live. → Đúng: He asked me where I lived. (Trật tự câu kể, không đảo trợ động từ.)","Hay nhầm: Habitat là môi trường sống.","Hay nhầm: Heatwave là đợt nắng nóng.","Hay nhầm: Deforestation là nạn phá rừng.","Hay nhầm: Ecosystem là hệ sinh thái.","Hay nhầm: Wildlife là động vật hoang dã."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 10. Ecotourism (Du lịch sinh thái)","req":["Dùng đúng câu điều kiện loại 1 (có thật ở hiện tại/tương lai) và loại 2 (không có thật ở hiện tại).","Hiểu và dùng từ vựng về du lịch sinh thái và các loại hình du lịch.","Đọc hiểu một đoạn văn giới thiệu các loại hình du lịch và tác động đến môi trường."],"sum":["Điều kiện 1: If + hiện tại đơn, will + V (có thể xảy ra). Điều kiện 2: If + quá khứ đơn / were, would + V (không có thật ở hiện tại).","Điều kiện loại 1: Tình huống có thể xảy ra ở hiện tại hoặc tương lai.","Điều kiện loại 2: Tình huống không có thật hoặc khó xảy ra ở hiện tại. Với be dùng were cho mọi chủ ngữ.","Ngữ điệu: Câu khẳng định và câu hỏi Wh- xuống giọng cuối câu; câu hỏi Yes/No lên giọng cuối câu.","Từ vựng du lịch sinh thái"],"e":["Sai: If I was a bird, I will fly. → Đúng: If I were a bird, I would fly. (Loại 2: were + would.)","Hay nhầm: Souvenir là quà lưu niệm.","Hay nhầm: Mass tourism là du lịch đại trà.","Hay nhầm: Ecotourism là loại hình du lịch.","Hay nhầm: Explore là khám phá (động từ).","Hay nhầm: Không dùng will trong mệnh đề if."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 10","c":[{"t":"Chủ đề 1. Lịch sử và Sử học","l":[{"t":"Bài 1. Hiện thực lịch sử và nhận thức lịch sử","req":["Trình bày được khái niệm lịch sử, Sử học.","Nêu được chức năng, nhiệm vụ, đối tượng nghiên cứu, một số nguyên tắc, phương pháp cơ bản của Sử học.","Phân biệt được các nguồn sử liệu, hiện thực lịch sử và nhận thức lịch sử."],"sum":["Lịch sử là những gì đã diễn ra trong quá khứ. Lịch sử loài người là toàn bộ hoạt động của con người từ khi xuất hiện đến nay, gồm cả quá trình con người tương tác với tự nhiên và với nhau.","Lịch sử là những gì đã diễn ra trong quá khứ: Lịch sử loài người là toàn bộ hoạt động của con người từ khi xuất hiện đến nay, gồm cả quá trình con người tương tác với tự nhiên và với nhau.","Từ khoá cần ghi nhớ: Lịch sử; hiện thực lịch sử; nhận thức lịch sử;","Sử học là khoa học nghiên cứu quá khứ của loài người: Đối tượng là toàn bộ quá khứ của một cá nhân, nhóm người, quốc gia, khu vực hoặc nhân loại.","Ba nguyên tắc cơ bản của Sử học: Khách quan: tái hiện đúng hiện thực, không xuyên tạc.","Các phương pháp cơ bản: Phương pháp lịch sử (xem xét sự vật theo giai đoạn phát triển cụ thể, đặt trong bối cảnh lịch sử); phương pháp lôgic (tìm mối liên hệ bên trong, bản…"],"e":["Hay nhầm: Đây là cách phân chia phạm vi, không phải hai nghĩa của khái niệm.","Hay nhầm: Quá khứ và hiện tại là hai thời điểm, không phải hai nghĩa.","Hay nhầm: Đây là cách phân loại sử liệu.","Hay nhầm: Nhân văn là nguyên tắc quan trọng nhưng không phải quan trọng nhất.","Hay nhầm: Tiến bộ là mục đích, không phải nguyên tắc quan trọng nhất.","Hay nhầm: Kinh nghiệm là sản phẩm của sử học, không phải nguyên tắc."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}},{"t":"Bài 2. Tri thức lịch sử và cuộc sống","req":["Nêu được vai trò và ý nghĩa của tri thức lịch sử qua ví dụ cụ thể.","Giải thích được sự cần thiết phải học tập lịch sử suốt đời.","Vận dụng được kiến thức, bài học lịch sử để giải thích một số vấn đề trong thực tiễn ở mức đơn giản."],"sum":["Cuộc sống của mỗi con người, gia đình, dân tộc và nhân loại đều có quá khứ, hiện tại và tương lai, gắn bó chặt chẽ với nhau.","Khái niệm: Cuộc sống của mỗi con người, gia đình, dân tộc và nhân loại đều có quá khứ, hiện tại và tương lai, gắn bó chặt chẽ với nhau.","Từ khoá cần ghi nhớ: Ôn cố, tri tân; cội nguồn;","Tri thức lịch sử cung cấp thông…: Tri thức lịch sử cung cấp thông tin về nguồn gốc, tổ tiên của bản thân, gia đình, dân tộc và nhân loại.","Lịch sử không có điểm dừng nên cần học tập suốt đời: Nhiều sự kiện như xây dựng các kim tự tháp Ai Cập vẫn còn bí ẩn, tạo cơ hội cho thế hệ sau tiếp tục khám phá.","Tri thức lịch sử và văn hoá…: Tri thức lịch sử và văn hoá còn là nguồn cảm hứng cho các ngành công nghiệp văn hoá, du lịch và nhiều nghề nghiệp mới."],"e":["Hay nhầm: Điều này trái với ý nghĩa của câu.","Hay nhầm: Bỏ quá khứ không phù hợp với tinh thần câu nói.","Hay nhầm: Ý nghĩa rộng hơn các triều đại.","Hay nhầm: Tri thức lịch sử không trực tiếp tạo ra của cải.","Hay nhầm: Thời tiết không thuộc lĩnh vực lịch sử.","Hay nhầm: Công nghệ không do tri thức lịch sử quyết định."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chủ đề 2. Vai trò của Sử học","l":[{"t":"Bài 3. Sử học với các lĩnh vực khoa học","req":["Nêu được vai trò của các ngành khoa học tự nhiên và công nghệ đối với nghiên cứu lịch sử.","Phân tích được mối liên hệ giữa Sử học với các ngành khoa học xã hội và nhân văn.","Giải thích được Sử học là môn khoa học liên ngành."],"sum":["Sử học là ngành khoa học nghiên cứu toàn bộ đời sống của loài người trong quá khứ trên mọi lĩnh vực: chính trị, quân sự, kinh tế, xã hội, văn hoá, khoa học, giáo dục.","Khái niệm: Sử học là ngành khoa học nghiên cứu toàn bộ đời sống của loài người trong quá khứ trên mọi lĩnh vực: chính trị, quân sự, kinh tế, xã hội, văn hoá,…","Từ khoá cần ghi nhớ: Liên ngành; khoa học xã hội và nhân văn; khoa học tự nhiên và công nghệ; bối cảnh lịch sử; tương tác hai chiều.","Mối liên hệ với khoa học xã…: Mối liên hệ với khoa học xã hội và nhân văn (ngôn ngữ, văn hoá, văn học, tâm lí, triết học, kinh tế, chính trị, xã hội học, nhân học...) là quan hệ…","Mối liên hệ với khoa học tự nhiên và công nghệ: Sử học xem xét các ngành này ở góc độ lịch sử (thành tựu ra đời trong bối cảnh nào, có tác dụng gì với xã hội).","Ví dụ: Danh thắng Tràng An (Ninh Bình) được ghi danh Di sản văn hoá và thiên nhiên thế giới nhờ nghiên cứu phối hợp lịch sử – văn hoá, địa chất, địa mạo và…"],"e":["Hay nhầm: Sử học dùng nhiều phương pháp.","Hay nhầm: Sử học có quan hệ với nhiều ngành.","Hay nhầm: Sử học nghiên cứu đời sống con người.","Hay nhầm: Vật lí học thuộc khoa học tự nhiên.","Hay nhầm: Sinh học thuộc khoa học tự nhiên.","Hay nhầm: Thiên văn học thuộc khoa học tự nhiên."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 4. Sử học với một số lĩnh vực, ngành nghề hiện đại","req":["Trình bày được tác động của công nghiệp văn hoá đối với việc quảng bá tri thức, truyền thống lịch sử – văn hoá.","Giải thích được vai trò của lịch sử và văn hoá đối với phát triển du lịch qua ví dụ cụ thể.","Phân tích được mối quan hệ giữa Sử học với công tác bảo tồn và phát huy giá trị di sản."],"sum":["Sử học có vai trò quan trọng trong công tác bảo tồn và phát huy giá trị di sản văn hoá, di sản thiên nhiên.","Khái niệm: Sử học có vai trò quan trọng trong công tác bảo tồn và phát huy giá trị di sản văn hoá, di sản thiên nhiên.","Từ khoá cần ghi nhớ: Di sản văn hoá vật thể; di sản văn hoá phi vật thể; di sản thiên nhiên; tính xác thực; tính toàn vẹn; công nghiệp văn hoá; du lịch văn hoá.","Vai trò của bảo tồn: Hạn chế tác động xấu của thiên nhiên và con người với di sản vật thể; giữ gìn và truyền lại di sản phi vật thể qua sưu tầm, truyền nghề, trình diễn;…","Công nghiệp văn hoá là lĩnh vực…: Công nghiệp văn hoá là lĩnh vực sản xuất, phân phối hàng hoá dựa trên việc khai thác giá trị của di sản văn hoá vật thể và phi vật thể, gồm quảng…","Du lịch văn hoá là một ngành của công nghiệp văn hoá: Tài nguyên du lịch văn hoá gồm di tích lịch sử – văn hoá, di tích cách mạng, khảo cổ, lễ hội, văn nghệ dân gian."],"e":["Hay nhầm: Đây là di sản thiên nhiên.","Hay nhầm: Đây là di sản thiên nhiên.","Hay nhầm: Không phải di sản phi vật thể.","Hay nhầm: Không phải loại di sản này.","Hay nhầm: Không phải loại di sản này.","Hay nhầm: Đây là lĩnh vực công nghiệp khác."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 3. Một số nền văn minh thế giới thời kì cổ - trung đại","l":[{"t":"Bài 5. Một số nền văn minh phương Đông thời kì cổ – trung đại","req":["Trình bày được quá trình hình thành, phát triển và các thành tựu tiêu biểu của văn minh Ai Cập, Ấn Độ, Trung Hoa.","Nêu được ý nghĩa, giá trị của các thành tựu văn minh phương Đông và ảnh hưởng đối với Việt Nam."],"sum":["Những tiêu chuẩn cơ bản để nhận diện văn minh là: nhà nước, đô thị, chữ viết, và những tiến bộ về tổ chức xã hội, luân lí, kĩ thuật để cải thiện cuộc sống.","Những tiêu chuẩn cơ bản để nhận diện văn minh là: Nhà nước, đô thị, chữ viết, và những tiến bộ về tổ chức xã hội, luân lí, kĩ thuật để cải thiện cuộc sống.","Từ khoá cần ghi nhớ: Văn minh; văn hoá; văn minh phương Đông; nhà nước; chữ tượng hình;","Ai Cập cổ đại (khoảng 3200 TCN…: Ai Cập cổ đại (khoảng 3200 TCN – năm 30 TCN) hình thành bên sông Nin.","Ấn Độ cổ – trung đại hình thành trên đất Nam Á, với các đặc trưng: Chế độ đẳng cấp Vác-na lâu dài, và là quê hương của Hin-đu giáo và Phật giáo.","Trung Hoa cổ – trung đại hình…: Trung Hoa cổ – trung đại hình thành ở lưu vực Hoàng Hà và Trường Giang, với nền nông nghiệp là cơ sở và Con đường tơ lụa nối Trung Hoa với châu Âu."],"e":["Hay nhầm: Sông Hoàng Hà thuộc Trung Hoa.","Hay nhầm: Chữ Hán có nguồn gốc riêng.","Hay nhầm: Chữ Phạn là chữ của Ấn Độ.","Hay nhầm: Chữ La-tinh xuất hiện sau.","Hay nhầm: Ai Cập không có chế độ này.","Hay nhầm: Trung Hoa có hệ thống khác là quân chủ, quan lại."],"q":{"n":9,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Một số nền văn minh phương Tây thời kì cổ – trung đại","req":["Nêu được ý nghĩa của những thành tựu cơ bản của văn minh Hy Lạp – La Mã cổ đại và văn minh Tây Âu thời Phục hưng.","Phân tích được cơ sở hình thành của các nền văn minh phương Tây."],"sum":["Văn minh Hy Lạp – La Mã cổ đại hình thành trên các bán đảo Nam Âu, quanh Địa Trung Hải. Địa hình nhiều núi, đất khó canh tác nên thủ công nghiệp và thương nghiệp phát triển; biển tạo điều kiện giao…","Khái niệm: Văn minh Hy Lạp – La Mã cổ đại hình thành trên các bán đảo Nam Âu, quanh Địa Trung Hải.","Từ khoá cần ghi nhớ: Thành bang; cộng hoà;","Thành tựu của văn minh Hy Lạp – La Mã: Bảng chữ cái Hy Lạp (24 chữ cái) và chữ La-tinh, nền tảng của chữ viết phương Tây; hệ chữ số La Mã; sử thi I-li-át và Ô-đi-xê; kiến trúc…","Sử học Hy Lạp hình thành từ…: Sử học Hy Lạp hình thành từ thế kỉ V TCN với Hê-rô-đốt và tác phẩm về chiến tranh Hy Lạp – Ba Tư.","Thời kì Phục hưng (thế kỉ XV…: Thời kì Phục hưng (thế kỉ XV – XVII) diễn ra trên cơ sở phục hưng những giá trị của văn minh Hy Lạp – La Mã."],"e":["Hay nhầm: Chữ tượng hình là của Ai Cập, không trực tiếp tạo ra chữ La-tinh.","Hay nhầm: Năm 1896 là lần khôi phục Thế vận hội hiện đại.","Hay nhầm: Năm 753 TCN là năm thành lập La Mã.","Hay nhầm: Năm 27 TCN là năm bắt đầu đế chế La Mã.","Hay nhầm: Thần khúc là tác phẩm thời Phục hưng.","Hay nhầm: Đôn Ki-hô-tê là tiểu thuyết Tây Ban Nha thời Phục hưng."],"q":{"n":8,"lv":{"Biết":4,"Hiểu":3,"Vận dụng":1}}}]},{"t":"Chủ đề 4. Các cuộc cách mạng công nghiệp trong lịch sử thế giới","l":[{"t":"Bài 7. Các cuộc cách mạng công nghiệp thời kì cận đại","req":["Trình bày được bối cảnh lịch sử, thành tựu và ý nghĩa của CMCN lần thứ nhất và lần thứ hai.","Phân tích được tác động của hai cuộc cách mạng đó đối với kinh tế, xã hội và văn hoá."],"sum":["Cách mạng công nghiệp lần thứ nhất diễn ra giữa thế kỉ XVIII, bắt đầu ở Anh. Anh có nhiều thuận lợi: cách mạng tư sản thành công sớm, nguồn tích luỹ tư bản, tài nguyên giàu có, lực lượng lao động từ…","Khái niệm: Cách mạng công nghiệp lần thứ nhất diễn ra giữa thế kỉ XVIII, bắt đầu ở Anh.","Từ khoá cần ghi nhớ: Cách mạng công nghiệp; máy hơi nước; con thoi bay;","Thành tựu của CMCN lần thứ nhất: Con thoi bay (1733) làm tăng gấp đôi năng suất dệt; máy kéo sợi (1769); máy dệt chạy bằng hơi nước (1785) làm năng suất tăng tới 40 lần; máy hơi…","CMCN lần thứ hai diễn ra từ…: CMCN lần thứ hai diễn ra từ giữa thế kỉ XIX đến Chiến tranh thế giới thứ nhất (1914), dựa trên khoa học như Thuyết vạn vật hấp dẫn, Định luật bảo…","Ý nghĩa kinh tế: Thay đổi cách tổ chức sản xuất, tạo nguyên liệu mới, nâng cao năng suất, thúc đẩy nông nghiệp, giao thông, thông tin liên lạc."],"e":["Hay nhầm: Pháp công nghiệp hoá muộn hơn.","Hay nhầm: Máy tính xuất hiện ở CMCN lần thứ ba.","Hay nhầm: Internet thuộc CMCN lần thứ ba.","Hay nhầm: Máy in 3D thuộc CMCN lần thứ tư.","Hay nhầm: Ê-đi-xơn là người hoàn thiện bóng đèn sợi đốt.","Hay nhầm: Pha-ra-đây phát minh động cơ điện."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Các cuộc cách mạng công nghiệp thời kì hiện đại","req":["Trình bày được bối cảnh lịch sử và các thành tựu cơ bản của CMCN lần thứ ba và thứ tư.","Phân tích được ý nghĩa, tác động kinh tế, xã hội và văn hoá của các cuộc cách mạng công nghiệp hiện đại."],"sum":["CMCN lần thứ ba (cách mạng kĩ thuật số) diễn ra trong nửa sau thế kỉ XX, dựa trên thuyết tương đối của Anh-xtanh và nhu cầu chạy đua vũ trang, khan hiếm tài nguyên hoá thạch.","Khái niệm: CMCN lần thứ ba (cách mạng kĩ thuật số) diễn ra trong nửa sau thế kỉ XX, dựa trên thuyết tương đối của Anh-xtanh và nhu cầu chạy đua vũ trang, khan…","Từ khoá cần ghi nhớ: Cách mạng kĩ thuật số; máy tính; internet; tự động hoá; trí tuệ nhân tạo; internet vạn vật; dữ liệu lớn; in 3D; công nghệ na-nô; toàn cầu hoá.","CMCN lần thứ tư (Cách mạng 4.0)…: CMCN lần thứ tư (Cách mạng 4.0) bắt đầu từ những năm đầu thế kỉ XXI và vẫn đang tiếp diễn, trực tiếp kế thừa thành tựu kĩ thuật số.","Ý nghĩa kinh tế: Mở rộng và đa dạng hoá sản xuất, nhà máy thông minh tăng năng suất, thương mại điện tử đưa người tiêu dùng tiếp cận thương mại toàn cầu, thúc đẩy…","Tác động xã hội và văn hoá: Tích cực là giải phóng sức lao động, làm việc từ xa, tìm kiếm thông tin nhanh chóng, giao lưu văn hoá dễ dàng."],"e":["Hay nhầm: Cách mạng hơi nước là CMCN lần thứ nhất.","Hay nhầm: Cách mạng 4.0 là lần thứ tư.","Hay nhầm: Cách mạng nông nghiệp không thuộc các cuộc CMCN.","Hay nhầm: Năm 1903 là năm máy bay anh em nhà Rai bay thử.","Hay nhầm: Năm 1821 là năm phát minh động cơ điện.","Hay nhầm: Năm 1969 là năm con người đặt chân lên Mặt Trăng."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 5. Văn minh Đông Nam Á","l":[{"t":"Bài 9. Cơ sở hình thành và ảnh hưởng của văn minh Đông Nam Á","req":["Phân tích được cơ sở hình thành văn minh Đông Nam Á thời kì cổ – trung đại.","Phân tích được những ảnh hưởng của văn minh Trung Hoa, Ấn Độ đối với văn minh Đông Nam Á."],"sum":["Đông Nam Á gồm các bán đảo và quần đảo nối Thái Bình Dương với Ấn Độ Dương, là \"ngã tư đường\" của các nền văn minh lớn.","Khái niệm: Đông Nam Á gồm các bán đảo và quần đảo nối Thái Bình Dương với Ấn Độ Dương, là \"ngã tư đường\" của các nền văn minh lớn.","Từ khoá cần ghi nhớ: Văn minh nông nghiệp lúa nước; ngã tư đường; làng;","Về xã hội, Đông Nam Á là…: Về xã hội, Đông Nam Á là khu vực đa tộc người, với các ngữ hệ và nhóm ngôn ngữ khác nhau.","Ảnh hưởng của Ấn Độ: Từ đầu Công nguyên, Phật giáo và Hin-đu giáo được truyền vào qua thương mại đường biển;"],"e":["Hay nhầm: Du mục không phải đặc trưng của Đông Nam Á.","Hay nhầm: Khai thác mỏ không phải nền tảng chính.","Hay nhầm: Đánh bắt xa bờ không phải nền tảng chính.","Hay nhầm: Thành thị tư sản xuất hiện ở châu Âu.","Hay nhầm: Vác-na là chế độ của Ấn Độ.","Hay nhầm: Trang viên là đặc trưng châu Âu trung đại."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":1}}},{"t":"Bài 10. Hành trình phát triển và thành tựu của văn minh Đông Nam Á","req":["Trình bày được các thời kì phát triển của văn minh Đông Nam Á trên trục thời gian.","Nêu được một số thành tựu tiêu biểu của văn minh Đông Nam Á."],"sum":["Hành trình phát triển của văn minh Đông Nam Á gồm ba giai đoạn: (1) từ những thế kỉ trước và đầu Công nguyên đến thế kỉ VII, hình thành và phát triển bước đầu các quốc gia như Văn Lang – Âu Lạc, Phù…","Hành trình phát triển của văn minh Đông Nam Á gồm ba giai đoạn: Từ những thế kỉ trước và đầu Công nguyên đến thế kỉ VII, hình thành và phát triển bước đầu các quốc gia như Văn Lang – Âu Lạc, Phù Nam","Từ khoá cần ghi nhớ: Tín ngưỡng bản địa; thần Lúa; phồn thực;","Tín ngưỡng bản địa gồm thờ tự…: Tín ngưỡng bản địa gồm thờ tự nhiên, phồn thực và thờ cúng người đã mất; thần Lúa được thờ ở nhiều nước với tên gọi khác nhau.","Chữ viết và văn học: Từng bước sáng tạo chữ viết riêng như chữ Chăm cổ, Khơ-me cổ, chữ Nôm của người Việt; văn học dân gian phong phú (thần thoại, cổ tích, truyện ngụ…","Kiến trúc và điêu khắc: Quần thể Bô-rô-bu-đua (In-đô-nê-xi-a), Ăng-co Vát và Ăng-co Thom (Cam-pu-chia), tháp Mỹ Sơn (Việt Nam); trống đồng và thạp đồng Đông Sơn là đỉnh cao…"],"e":["Hay nhầm: Đó là giai đoạn hình thành và phát triển bước đầu.","Hay nhầm: Đây là giai đoạn có xâm nhập phương Tây.","Hay nhầm: Đây không thuộc thời kì cổ – trung đại.","Hay nhầm: Bô-rô-bu-đua thuộc In-đô-nê-xi-a.","Hay nhầm: Vạn Lí Trường Thành thuộc Trung Quốc.","Hay nhầm: Riêm Kê là tác phẩm Cam-pu-chia."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 6. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858)","l":[{"t":"Bài 11. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858) – Văn Lang – Âu Lạc, Chăm-pa, Phù Nam","req":["Trình bày được cơ sở hình thành, thành tựu tiêu biểu của văn minh Văn Lang – Âu Lạc, Chăm-pa, Phù Nam.","Nêu được ý nghĩa của các nền văn minh này trong lịch sử Việt Nam."],"sum":["Văn minh Văn Lang – Âu Lạc (văn minh sông Hồng, văn minh Đông Sơn) có nguồn gốc bản địa, hình thành và phát triển từ đầu thiên niên kỉ I TCN đến vài thế kỉ đầu Công nguyên ở Bắc Bộ và Bắc Trung Bộ.","Khái niệm: Văn minh Văn Lang – Âu Lạc (văn minh sông Hồng, văn minh Đông Sơn) có nguồn gốc bản địa, hình thành và phát triển từ đầu thiên niên kỉ I TCN đến vài…","Từ khoá cần ghi nhớ: Văn Lang;","Văn minh Chăm-pa (từ thế kỉ II…: Văn minh Chăm-pa (từ thế kỉ II đến thế kỉ XV) phát triển ở miền Trung và một phần Tây Nguyên, trên nền văn hoá Sa Huỳnh.","Văn minh Phù Nam (khoảng thế kỉ…: Văn minh Phù Nam (khoảng thế kỉ I – thế kỉ VII) có địa bàn chủ yếu ở Nam Bộ, hạ lưu sông Mê Công, có cội nguồn từ văn hoá tiền Óc Eo."],"e":["Hay nhầm: Âu Lạc là nhà nước tiếp nối.","Hay nhầm: Chăm-pa thuộc miền Trung.","Hay nhầm: Phong Châu là kinh đô Văn Lang.","Hay nhầm: Sin-ha-pu-ra là kinh đô Chăm-pa.","Hay nhầm: Óc Eo là cảng thị của Phù Nam.","Hay nhầm: Phù Nam tiếp thu chữ viết Ấn Độ."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":2}}},{"t":"Bài 12. Văn minh Đại Việt","req":["Trình bày được quá trình phát triển của văn minh Đại Việt trên trục thời gian và một số thành tựu tiêu biểu.","Phân tích được cơ sở hình thành và ý nghĩa của văn minh Đại Việt."],"sum":["Văn minh Đại Việt là những sáng tạo vật chất và tinh thần tiêu biểu trong kỉ nguyên độc lập của Việt Nam từ thế kỉ X đến giữa thế kỉ XIX.","Khái niệm: Văn minh Đại Việt là những sáng tạo vật chất và tinh thần tiêu biểu trong kỉ nguyên độc lập của Việt Nam từ thế kỉ X đến giữa thế kỉ XIX.","Từ khoá cần ghi nhớ: Đại Việt; tam giáo đồng nguyên; khoa cử Nho học;","Chính trị và pháp luật: Thiết chế quân chủ trung ương tập quyền, đạt đỉnh cao dưới thời Lê sơ; các cuộc cải cách của Hồ Quý Ly, Lê Thánh Tông, Minh Mạng; bộ luật tiêu biểu…","Tín ngưỡng, tôn giáo: Thờ cúng tổ tiên, thờ Thành hoàng, đạo Mẫu từ thế kỉ XVI.","Giáo dục và khoa cử phát triển từ thời Lý: Lê sơ tổ chức 26 khoa thi, lấy đỗ gần 1 000 tiến sĩ; bia Tiến sĩ ở Văn Miếu ghi tên người đỗ đạt."],"e":["Hay nhầm: Thời Bắc thuộc không thuộc kỉ nguyên độc lập.","Hay nhầm: Đây là thời kì trước khi có Đại Việt.","Hay nhầm: Đây không thuộc thời kì Đại Việt.","Hay nhầm: Năm 938 là năm Ngô Quyền xưng vương.","Hay nhầm: Năm 1428 là năm nhà Lê sơ thành lập.","Hay nhầm: Năm 1802 là năm nhà Nguyễn thành lập."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề 7. Cộng đồng các dân tộc Việt Nam","l":[{"t":"Bài 13. Đời sống vật chất và tinh thần của cộng đồng các dân tộc Việt Nam","req":["Nêu được thành phần dân tộc theo dân số; trình bày được khái niệm ngữ hệ và phân chia tộc người theo ngữ hệ.","Trình bày được nét chính về đời sống vật chất và đời sống tinh thần của cộng đồng các dân tộc Việt Nam.","Có ý thức trân trọng, giữ gìn và phát huy bản sắc văn hoá của cộng đồng các dân tộc Việt Nam."],"sum":["Khái niệm \"dân tộc\" có hai nghĩa: dân tộc – quốc gia (toàn thể cư dân đất nước, dân tộc Việt Nam) và dân tộc – tộc người (cộng đồng có chung ngôn ngữ, văn hoá và ý thức tự giác dân tộc).","Khái niệm \"dân tộc\" có hai nghĩa: Dân tộc – quốc gia (toàn thể cư dân đất nước, dân tộc Việt Nam) và dân tộc – tộc người (cộng đồng có chung ngôn ngữ, văn hoá và ý thức tự giác dân…","Từ khoá cần ghi nhớ: Dân tộc đa số; dân tộc thiểu số; ngữ hệ; nhóm ngôn ngữ; canh tác lúa nước; nương rẫy; ruộng bậc thang; gùi; nhà sàn; lễ thổi tai; tín ngưỡng đa thần.","Theo ngữ hệ, 54 dân tộc Việt…: Theo ngữ hệ, 54 dân tộc Việt Nam được chia thành 5 ngữ hệ và 8 nhóm ngôn ngữ.","Đời sống vật chất: Người Kinh chủ yếu canh tác lúa nước ở đồng bằng, làm thuỷ lợi; các dân tộc thiểu số ở miền núi phát triển nương rẫy, ruộng bậc thang, đi lại và vận…","Đời sống tinh thần: Người Kinh thờ cúng tổ tiên, Thành hoàng, Mẫu, tiếp thu Phật giáo, Công giáo, Tin Lành."],"e":["Hay nhầm: Người Mông là dân tộc thiểu số.","Hay nhầm: Người Chăm là dân tộc thiểu số.","Hay nhầm: Người Khơ-me là dân tộc thiểu số.","Hay nhầm: Làng không phải tiêu chí ngữ hệ.","Hay nhầm: Nghề không phải tiêu chí ngữ hệ.","Hay nhầm: Tôn giáo không phải tiêu chí ngữ hệ."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 14. Khối đại đoàn kết dân tộc trong lịch sử Việt Nam","req":["Nêu được nét chính về sự hình thành khối đại đoàn kết dân tộc trong lịch sử Việt Nam.","Phân tích được vai trò và tầm quan trọng của khối đại đoàn kết dân tộc trong lịch sử và hiện nay.","Nêu được quan điểm nhất quán của Đảng, Nhà nước trong chính sách dân tộc."],"sum":["Khối đại đoàn kết dân tộc hình thành từ rất sớm, từ thời dựng nước Văn Lang – Âu Lạc, khi cộng đồng cần liên kết để trị thuỷ và chống giặc ngoại xâm.","Khái niệm: Khối đại đoàn kết dân tộc hình thành từ rất sớm, từ thời dựng nước Văn Lang – Âu Lạc, khi cộng đồng cần liên kết để trị thuỷ và chống giặc ngoại xâm.","Từ khoá cần ghi nhớ: Khối đại đoàn kết dân tộc;","Từ khi Đảng Cộng sản Việt Nam…: Từ khi Đảng Cộng sản Việt Nam ra đời (1930), khối đại đoàn kết được mở rộng và trở thành nhân tố quyết định thắng lợi của cách mạng.","Vai trò trong lịch sử dựng nước và giữ nước: Khi có ngoại xâm, đại đoàn kết quyết định thành công của các cuộc đấu tranh.","Trong thời kì hiện nay, đại đoàn…: Trong thời kì hiện nay, đại đoàn kết là cơ sở huy động sức mạnh của toàn dân để phát triển kinh tế, văn hoá, giữ ổn định xã hội, bảo vệ chủ quyền và…"],"e":["Hay nhầm: Sơn Tinh – Thuỷ Tinh giải thích hiện tượng lũ lụt.","Hay nhầm: Thánh Gióng ca ngợi tinh thần yêu nước.","Hay nhầm: An Dương Vương là nhân vật thời Âu Lạc.","Hay nhầm: Ngày 2-9-1945 là ngày Tuyên ngôn Độc lập.","Hay nhầm: Ngày 26-3-1986 là ngày Ban Bí thư quyết định Ngày Đại đoàn kết.","Hay nhầm: Ngày 30-4-1975 là ngày thống nhất đất nước."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chủ đề 1. Lịch sử và Sử học","l":[{"t":"Bài tập nâng cao · Chủ đề 1. Lịch sử và Sử học (2 câu)","e":["Hay nhầm: Sử học dùng nhiều phương pháp.","Hay nhầm: Sử học có liên hệ với nhiều ngành.","Hay nhầm: Sử học nghiên cứu đời sống xã hội của con người.","Hay nhầm: Sách in chỉ là một hình thức gần đây.","Hay nhầm: Truyền miệng chỉ là một trong nhiều cách.","Hay nhầm: Tranh vẽ chỉ là một hình thức."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 2. Vai trò của Sử học","l":[{"t":"Bài tập nâng cao · Chủ đề 2. Vai trò của Sử học (2 câu)","e":["Hay nhầm: Các ngành khoa học vẫn tiếp tục phát triển.","Hay nhầm: Lịch sử ngành có giá trị kế thừa.","Hay nhầm: Mục đích là kế thừa kinh nghiệm.","Hay nhầm: Du lịch có thể có tác động tích cực.","Hay nhầm: Hai lĩnh vực có mối quan hệ rõ ràng.","Hay nhầm: Du lịch cũng tác động trở lại bảo tồn."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 3. Một số nền văn minh thế giới thời kì cổ - trung đại","l":[{"t":"Bài tập nâng cao · Chủ đề 3. Một số nền văn minh thế giới thời kì cổ - trung đại (2 câu)","e":["Hay nhầm: Trung Hoa có nhiều lần bị đe doạ.","Hay nhầm: Trung Hoa có chữ viết từ rất sớm.","Hay nhầm: Văn minh này tồn tại rất lâu.","Hay nhầm: Phục hưng không phủ nhận cổ đại, mà phục hưng lại giá trị đó.","Hay nhầm: Phục hưng giảm vai trò tôn giáo.","Hay nhầm: Phục hưng không quay lại chế độ nô lệ."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 4. Các cuộc cách mạng công nghiệp trong lịch sử thế giới","l":[{"t":"Bài tập nâng cao · Chủ đề 4. Các cuộc cách mạng công nghiệp trong lịch sử thế giới (2 câu)","e":["Hay nhầm: Sản xuất tăng chứ không giảm.","Hay nhầm: Có nhiều phát minh quan trọng.","Hay nhầm: Công nghiệp là lĩnh vực được thúc đẩy.","Hay nhầm: Internet có nhiều tác động cần lưu ý.","Hay nhầm: Thông tin không luôn an toàn.","Hay nhầm: Pháp luật áp dụng cả trên mạng."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 5. Văn minh Đông Nam Á","l":[{"t":"Bài tập nâng cao · Chủ đề 5. Văn minh Đông Nam Á (2 câu)","e":["Hay nhầm: Không sao chép nguyên vẹn.","Hay nhầm: Không chỉ tồn tại nhờ châu Âu.","Hay nhầm: Có nhiều thành tựu còn lại.","Hay nhầm: Các thành tựu bản địa vẫn tồn tại."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 6. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858)","l":[{"t":"Bài tập nâng cao · Chủ đề 6. Một số nền văn minh trên đất nước Việt Nam (trước năm 1858) (2 câu)","e":["Hay nhầm: Văn minh có nguồn gốc bản địa.","Hay nhầm: Văn minh tồn tại hàng trăm năm.","Hay nhầm: Điều này không phải hạn chế chính.","Hay nhầm: Thương nghiệp đôi khi không được đề cao.","Hay nhầm: Giáo dục phát triển khá rõ."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 7. Cộng đồng các dân tộc Việt Nam","l":[{"t":"Bài tập nâng cao · Chủ đề 7. Cộng đồng các dân tộc Việt Nam (2 câu)","e":["Hay nhầm: Có nhiều dân tộc khác nhau.","Hay nhầm: Có nhiều điểm chung như lịch sử, lãnh thổ.","Hay nhầm: Có nhiều khác biệt về ngôn ngữ và phong tục.","Hay nhầm: Chính sách không chỉ về kinh tế.","Hay nhầm: Chính sách không chỉ về quân sự.","Hay nhầm: Chính sách có nhiều nội dung cụ thể."],"q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 10","c":[{"t":"Phần một. Một số vấn đề chung","l":[{"t":"Bài 1. Môn Địa lí với định hướng nghề nghiệp","sum":["Địa lí là một hệ thống khoa học gồm hai phần: địa lí tự nhiên và địa lí kinh tế – xã hội. Đây là môn học tổng hợp, có nội dung thuộc cả khoa học tự nhiên lẫn khoa học xã hội.","Địa lí là một hệ thống khoa học gồm hai phần: Địa lí tự nhiên và địa lí kinh tế – xã hội.","Ở trường phổ thông, Địa lí được học từ tiểu học: Ở trung học phổ thông, Địa lí thuộc nhóm môn khoa học xã hội.","Học Địa lí giúp các em hiểu…: Học Địa lí giúp các em hiểu về thiên nhiên, con người và hoạt động sản xuất ở khắp nơi trên thế giới; hiểu vai trò của địa phương đối với thế giới;…","Kiến thức Địa lí liên quan đến…: Kiến thức Địa lí liên quan đến nhiều nghề như quy hoạch và xây dựng, du lịch, nông nghiệp, môi trường, giao thông vận tải, khí tượng – thuỷ văn,…","Từ khoá cần ghi nhớ: Địa lí tự nhiên;"],"e":["Hay nhầm: Địa lí có nội dung tự nhiên nhưng ở trung học phổ thông không xếp vào nhóm khoa học tự nhiên.","Hay nhầm: Nghệ thuật không phải nhóm môn của Địa lí.","Hay nhầm: Kĩ thuật công nghệ không phải nhóm môn của Địa lí.","Hay nhầm: Địa lí không chỉ nghiên cứu tự nhiên mà còn nghiên cứu kinh tế – xã hội.","Hay nhầm: Môn Địa lí có cả phần thực hành như đọc bản đồ, vẽ biểu đồ.","Hay nhầm: Kiến thức Địa lí liên quan đến nhiều ngành nghề khác nhau."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 1. Sử dụng bản đồ","l":[{"t":"Bài 2. Một số phương pháp biểu hiện các đối tượng địa lí trên bản đồ","sum":["Bản đồ có nội dung rất đa dạng, gồm đối tượng tự nhiên và kinh tế – xã hội. Muốn khai thác bản đồ hiệu quả, cần biết các phương pháp biểu hiện đối tượng trên bản đồ.","Khái niệm: Bản đồ có nội dung rất đa dạng, gồm đối tượng tự nhiên và kinh tế – xã hội.","Phương pháp kí hiệu: Dùng để thể hiện các đối tượng phân bố theo những điểm cụ thể (mỏ khoáng sản, nhà máy, trường học...).","Phương pháp kí hiệu đường chuyển động: Thể hiện sự di chuyển của các đối tượng, hiện tượng bằng mũi tên.","Phương pháp bản đồ – biểu đồ: Đặt biểu đồ vào từng đơn vị lãnh thổ để thể hiện giá trị tổng cộng của đối tượng (xuất nhập khẩu, số dân, sản lượng lúa theo tỉnh).","Phương pháp chấm điểm: Mỗi chấm tương ứng với một số lượng nhất định, dùng cho đối tượng phân tán nhỏ lẻ (như phân bố dân cư); chủ yếu thể hiện số lượng."],"e":["Hay nhầm: Phương pháp kí hiệu thể hiện đối tượng ở các điểm cụ thể, không dùng để thể hiện sự di chuyển.","Hay nhầm: Phương pháp chấm điểm dùng các chấm để thể hiện số lượng, không dùng mũi tên.","Hay nhầm: Phương pháp khoanh vùng thể hiện đối tượng phân bố theo vùng, không thể hiện sự di chuyển.","Hay nhầm: Màu sắc không phải là đặc điểm trọng tâm của phương pháp chấm điểm.","Hay nhầm: Độ cao địa hình thường được thể hiện bằng đường đồng mức hoặc thang màu, không phải phương pháp chấm điểm.","Hay nhầm: Ranh giới hành chính không phải là nội dung chính của phương pháp chấm điểm."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 3. Sử dụng bản đồ trong học tập và đời sống; một số ứng dụng của GPS và bản đồ số","sum":["Để sử dụng bản đồ hiệu quả: xác định rõ nội dung và yêu cầu; chọn bản đồ phù hợp; hiểu tỉ lệ, kí hiệu và phương pháp biểu hiện;","Để sử dụng bản đồ hiệu quả: Xác định rõ nội dung và yêu cầu; chọn bản đồ phù hợp; hiểu tỉ lệ, kí hiệu và phương pháp biểu hiện;","GPS (Global Positioning System) là hệ thống…: GPS (Global Positioning System) là hệ thống định vị toàn cầu, xác định vị trí của đối tượng trên bề mặt Trái Đất nhờ hệ thống vệ tinh.","Nguyên lí: Các vệ tinh bay quanh Trái Đất và phát tín hiệu có thông tin xuống; trạm thu GPS nhận tín hiệu để xác định vị trí và tính thêm tốc độ, hướng di…","Bản đồ số là tập hợp có…: Bản đồ số là tập hợp có tổ chức các dữ liệu bản đồ, lưu trên thiết bị đọc được như máy tính, điện thoại thông minh, và hiển thị dưới dạng hình ảnh…","Ứng dụng: Dẫn đường; quản lí và giám sát phương tiện có gắn thiết bị định vị; tính cước xe taxi, xe buýt; chống trộm; tìm người hoặc thiết bị bị mất;"],"e":["Hay nhầm: General Power Supply nghĩa là cung cấp điện tổng quát, không phải GPS.","Hay nhầm: Geographic Public Service không phải tên viết tắt của GPS.","Hay nhầm: Global Planet Survey không phải tên viết tắt của GPS.","Hay nhầm: Bản đồ vẽ trên giấy là bản đồ truyền thống, không phải bản đồ số.","Hay nhầm: Bản đồ số có thể thể hiện nhiều loại nội dung, không chỉ địa hình.","Hay nhầm: Bản đồ số được dùng rộng rãi trong đời sống, không giới hạn đối tượng."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 2. Trái Đất","l":[{"t":"Bài 4. Sự hình thành Trái Đất, vỏ Trái Đất và vật liệu cấu tạo vỏ Trái Đất","sum":["Trái Đất hình thành cách đây khoảng 4,5 tỉ năm, liên quan chặt chẽ đến sự hình thành Mặt Trời và hệ Mặt Trời.","Khái niệm: Trái Đất hình thành cách đây khoảng 4,5 tỉ năm, liên quan chặt chẽ đến sự hình thành Mặt Trời và hệ Mặt Trời.","Theo tài liệu nghiên cứu sóng địa chấn, Trái Đất có ba lớp đồng tâm: Ngoài cùng là vỏ Trái Đất, tiếp đến là manti, trong cùng là nhân Trái Đất.","Vỏ Trái Đất là lớp vật chất…: Vỏ Trái Đất là lớp vật chất cứng ngoài cùng, dày từ khoảng 5 km (ở đại dương) đến 70 km (ở lục địa).","Ranh giới giữa vỏ Trái Đất và manti là mặt Mô-hô: Vỏ Trái Đất chỉ chiếm khoảng 1% thể tích và 0,5% khối lượng Trái Đất nhưng có vai trò rất quan trọng.","Vật liệu cấu tạo vỏ Trái Đất là khoáng vật và đá: Theo nguồn gốc có ba nhóm đá: đá macma (hình thành do silicat nóng chảy nguội lạnh và ngưng kết), đá trầm tích (hình thành do lắng tụ và nén chặt…"],"e":["Hay nhầm: Trái Đất có ba lớp, không phải hai lớp.","Hay nhầm: Theo nghiên cứu sóng địa chấn, Trái Đất chỉ có ba lớp đồng tâm.","Hay nhầm: Trái Đất không có năm lớp đồng tâm.","Hay nhầm: Đường đứt gãy là nơi đất đá bị gãy vỡ, không phải ranh giới giữa vỏ và manti.","Hay nhầm: Đới hút chìm là nơi một mảng bị hút xuống dưới mảng khác, không phải ranh giới vỏ – manti.","Hay nhầm: Đường đẳng nhiệt nối các điểm có cùng nhiệt độ, không phải ranh giới vỏ – manti."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 5. Hệ quả địa lí các chuyển động của Trái Đất","sum":["Trái Đất có hai chuyển động chính: tự quay quanh trục (từ tây sang đông, khoảng 24 giờ một vòng) và quay quanh Mặt Trời (vận tốc trung bình khoảng 29,8 km/s, trục nghiêng khoảng 66°33′ so với mặt…","Trái Đất có hai chuyển động chính: Tự quay quanh trục (từ tây sang đông, khoảng 24 giờ một vòng) và quay quanh Mặt Trời (vận tốc trung bình khoảng 29,8 km/s, trục nghiêng khoảng…","Hệ quả của tự quay: Luân phiên ngày và đêm.","Đường chuyển ngày quốc tế là kinh tuyến 180°: Đi từ tây sang đông qua kinh tuyến này thì lùi lại một ngày lịch;","Hệ quả của chuyển động quanh Mặt Trời: Ngày đêm dài ngắn khác nhau theo mùa và theo vĩ độ ở hai bán cầu, trừ ngày 21/3 và 23/9 ngày đêm bằng nhau.","Các mùa do trục Trái Đất nghiêng…: Các mùa do trục Trái Đất nghiêng và không đổi hướng khi chuyển động quanh Mặt Trời, làm góc chiếu tia sáng và thời gian nhận ánh sáng thay đổi trong…"],"e":["Hay nhầm: Chiều từ đông sang tây là ngược với chiều tự quay thực tế của Trái Đất.","Hay nhầm: Từ bắc xuống nam không phải chiều tự quay của Trái Đất.","Hay nhầm: Từ nam lên bắc không phải chiều tự quay của Trái Đất.","Hay nhầm: Chia 12 múi, mỗi múi 30 độ không đúng với cách chia múi giờ đã học.","Hay nhầm: Mỗi múi rộng 15 độ, không phải 10 độ.","Hay nhầm: Chỉ có 24 múi giờ, không phải 36 múi."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 3. Thạch quyển","l":[{"t":"Bài 6. Thạch quyển, thuyết kiến tạo mảng","sum":["Thạch quyển gồm vỏ Trái Đất và phần cứng mỏng phía trên của manti. Thạch quyển dày khoảng 100 km và có cấu tạo bởi nhiều loại đá khác nhau.","Khái niệm: Thạch quyển gồm vỏ Trái Đất và phần cứng mỏng phía trên của manti.","Thuyết kiến tạo mảng cho rằng thạch…: Thuyết kiến tạo mảng cho rằng thạch quyển bị gãy vỡ thành các mảng kiến tạo cứng, luôn dịch chuyển trên lớp quánh dẻo của manti.","Ý tưởng ban đầu của thuyết xuất…: Ý tưởng ban đầu của thuyết xuất hiện khi người ta thấy bờ đông Nam Mỹ và bờ tây châu Phi có thể khớp nhau, từ đó cho rằng các lục địa từng là một…","Khi hai mảng lục địa xô vào…: Khi hai mảng lục địa xô vào nhau, vỏ lục địa bị nén ép, uốn nếp và hình thành các dãy núi cao, đồ sộ như Hi-ma-lay-a.","Khi hai mảng tách xa nhau, vết…: Khi hai mảng tách xa nhau, vết nứt lớn xuất hiện và macma trào lên tạo dãy núi ngầm, ví dụ sống núi ngầm giữa Đại Tây Dương, kèm theo động đất và…"],"e":["Hay nhầm: Lớp trầm tích chỉ là một phần của vỏ Trái Đất, không phải toàn bộ thạch quyển.","Hay nhầm: Toàn bộ manti và nhân Trái Đất không thuộc thạch quyển.","Hay nhầm: Khí quyển và thuỷ quyển thuộc các quyển khác, không thuộc thạch quyển.","Hay nhầm: Giữa các lục địa ổn định thường ít xảy ra động đất và núi lửa.","Hay nhầm: Dãy núi già không phải nơi tập trung động đất và núi lửa chủ yếu.","Hay nhầm: Động đất và núi lửa không chỉ xảy ra ở vùng cực."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 7. Nội lực và ngoại lực","sum":["Nội lực là lực sinh ra trong lòng Trái Đất, liên quan đến nguồn năng lượng bên trong như phân huỷ chất phóng xạ, phản ứng hoá học toả nhiệt, chuyển động tự quay và sự sắp xếp vật chất theo tỉ trọng.","Khái niệm: Nội lực là lực sinh ra trong lòng Trái Đất, liên quan đến nguồn năng lượng bên trong như phân huỷ chất phóng xạ, phản ứng hoá học toả nhiệt, chuyển…","Nội lực tác động đến địa hình qua các vận động kiến tạo: Theo phương thẳng đứng (nâng lên, hạ xuống, gây hiện tượng biển tiến, biển thoái) và theo phương nằm ngang (nén ép gây uốn nếp, kéo giãn gây đứt gãy).","Ngoại lực là lực diễn ra trên…: Ngoại lực là lực diễn ra trên bề mặt Trái Đất như gió, mưa, nước chảy, sóng biển, băng, sinh vật và con người, chủ yếu có nguồn gốc từ bức xạ Mặt…","Ngoại lực tác động qua bốn quá trình: Phong hoá (vật lí, hoá học, sinh học), bóc mòn (xâm thực do nước chảy, mài mòn do sóng biển và băng hà, thổi mòn do gió), vận chuyển và bồi tụ (tạo…","Nội lực và ngoại lực xảy ra đồng thời và đối kháng nhau: Phong hoá chuẩn bị vật liệu cho bóc mòn; chỉ bóc mòn và bồi tụ mới tạo thành địa hình."],"e":["Hay nhầm: Bức xạ Mặt Trời là nguồn gốc của ngoại lực, không phải nội lực.","Hay nhầm: Gió và mưa là các tác nhân của ngoại lực.","Hay nhầm: Hoạt động của con người thuộc nhóm ngoại lực, không phải nội lực.","Hay nhầm: Hang động đá vôi được hình thành do ngoại lực (nước hoà tan đá).","Hay nhầm: Đồng bằng châu thổ hình thành do bồi tụ, tức là ngoại lực.","Hay nhầm: Bãi bồi hình thành do bồi tụ của ngoại lực."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 8. Thực hành: Sự phân bố các vành đai động đất, núi lửa","sum":["Mục tiêu: xác định các vành đai động đất, núi lửa trên bản đồ và mối quan hệ của chúng với sự chuyển dịch các mảng kiến tạo.","Mục tiêu: Xác định các vành đai động đất, núi lửa trên bản đồ và mối quan hệ của chúng với sự chuyển dịch các mảng kiến tạo.","Các bước làm việc: Đọc chú giải để phân biệt kí hiệu động đất và núi lửa","Kết quả chung: Động đất và núi lửa tập trung nhiều nhất ở vành đai Thái Bình Dương và vành đai Địa Trung Hải – Himalaya, là những nơi có ranh giới giữa các mảng…","Khi giải thích, cần nêu rõ: Vùng tiếp xúc giữa các mảng không ổn định, khi các mảng xô vào nhau hoặc tách xa nhau thì dễ phát sinh động đất và núi lửa.","Từ khoá cần ghi nhớ: Vành đai động đất; vành đai núi lửa; ranh giới mảng; chú giải bản đồ;"],"e":["Hay nhầm: Hoang mạc là vùng ít hoạt động địa chất, không phải nơi tập trung động đất và núi lửa.","Hay nhầm: Đồng bằng châu thổ hình thành do bồi tụ, ít có động đất và núi lửa tập trung.","Hay nhầm: Vùng cực không phải nơi tập trung động đất và núi lửa.","Hay nhầm: Đại Tây Dương có sống núi ngầm nhưng không phải vành đai động đất lớn bao quanh.","Hay nhầm: Bắc Băng Dương ít hoạt động địa chất so với Thái Bình Dương.","Hay nhầm: Ấn Độ Dương có vành đai động đất riêng nhưng không phải vành đai lớn nhất."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 4. Khí quyển","l":[{"t":"Bài 9. Khí quyển, các yếu tố khí hậu","sum":["Khí quyển là lớp không khí bao quanh Trái Đất, chịu ảnh hưởng của vũ trụ, trước hết là Mặt Trời.","Khái niệm: Khí quyển là lớp không khí bao quanh Trái Đất, chịu ảnh hưởng của vũ trụ, trước hết là Mặt Trời.","Khí quyển chia làm năm tầng: Tầng đối lưu quan trọng nhất vì có liên quan đến các quá trình tự nhiên diễn ra trên bề mặt Trái Đất.","Nhiệt độ không khí giảm từ Xích đạo về hai cực: Trong tầng đối lưu, nhiệt độ trung bình giảm khoảng 0,6°C khi độ cao tăng thêm 100 m.","Khí áp là sức nén của không…: Khí áp là sức nén của không khí lên bề mặt đất; khí áp tiêu chuẩn ở mực nước biển là 1013 mb.","Các loại gió chính: Gió Mậu dịch thổi từ đai áp cao cận chí tuyến về đai áp thấp xích đạo; gió Tây ôn đới; gió Đông cực; gió mùa; gió đất và gió biển; gió phơn (vượt…"],"e":["Hay nhầm: Ô-xi chiếm khoảng 20,9%, ít hơn ni-tơ.","Hay nhầm: Hơi nước là thành phần thay đổi và chiếm tỉ lệ nhỏ.","Hay nhầm: Các-bon đi-ô-xit chiếm tỉ lệ rất nhỏ trong không khí.","Hay nhầm: 0,2°C là con số không đúng với quy luật giảm nhiệt theo độ cao.","Hay nhầm: 1°C là con số không đúng với mức giảm trung bình.","Hay nhầm: 2°C là con số không đúng với mức giảm trung bình."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 10. Thực hành: Đọc bản đồ các đới và các kiểu khí hậu trên Trái Đất; phân tích biểu đồ một số kiểu khí hậu","sum":["Bản đồ các đới khí hậu trên Trái Đất chia thành bảy đới từ Xích đạo về hai cực: đới xích đạo, đới cận xích đạo, đới nhiệt đới, đới cận nhiệt, đới ôn đới, đới cận cực và đới khí hậu cực.","Khái niệm: Bản đồ các đới khí hậu trên Trái Đất chia thành bảy đới từ Xích đạo về hai cực: đới xích đạo, đới cận xích đạo, đới nhiệt đới, đới cận nhiệt, đới ôn…","Khi đọc bản đồ, cần xác định…: Khi đọc bản đồ, cần xác định phạm vi và tên của từng đới, cho biết sự phân hoá thành các kiểu khí hậu trong mỗi đới, và xác định vị trí Việt Nam nằm…","Khi phân tích biểu đồ nhiệt độ – lượng mưa: Nhiệt độ cao nhất và thấp nhất của các tháng (biên độ nhiệt năm = nhiệt độ tháng cao nhất − nhiệt độ tháng thấp nhất); tổng lượng mưa trung bình năm…","Từ khoá cần ghi nhớ: Đới khí hậu; kiểu khí hậu; biên độ nhiệt năm; chế độ mưa; biểu đồ khí hậu; nhiệt đới gió mùa;","Điểm nhấn ghi nhớ: Biên độ nhiệt năm = cao nhất − thấp nhất."],"e":["Hay nhầm: Nhiệt độ tháng 1 không phải cơ sở để tính biên độ nhiệt năm.","Hay nhầm: Tổng nhiệt độ chia 12 là nhiệt độ trung bình năm, không phải biên độ.","Hay nhầm: Cộng nhiệt độ hai mùa không cho ra biên độ nhiệt năm.","Hay nhầm: Đới khí hậu cực nằm ở vùng cực, rất xa Việt Nam.","Hay nhầm: Đới khí hậu ôn đới nằm ở vĩ độ cao hơn Việt Nam.","Hay nhầm: Đới khí hậu xích đạo nằm sát đường Xích đạo, không phải Việt Nam."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 5. Thuỷ quyển","l":[{"t":"Bài 11. Thuỷ quyển, nước trên lục địa","sum":["Thuỷ quyển là toàn bộ lớp nước bao quanh Trái Đất, phân bố trong đại dương, trên lục địa, trong các lớp đất đá, trong khí quyển và trong cơ thể sinh vật.","Khái niệm: Thuỷ quyển là toàn bộ lớp nước bao quanh Trái Đất, phân bố trong đại dương, trên lục địa, trong các lớp đất đá, trong khí quyển và trong cơ thể sinh…","Sông được cấp nước từ nước ngầm…: Sông được cấp nước từ nước ngầm (ít biến động, điều tiết nước trong năm), nước mưa và nước băng tuyết tan (biến động rõ rệt theo mùa).","Chế độ nước sông chịu ảnh hưởng của nguồn cấp nước và đặc điểm lưu vực: Địa hình dốc làm lũ tập trung nhanh; hồ, đầm và thực vật điều tiết dòng chảy; các phụ lưu tập trung trên đoạn ngắn dễ gây lũ chồng lũ.","Hồ là vùng trũng chứa nước, không thông trực tiếp với biển: Theo nguồn gốc có hồ núi lửa (thường tròn, sâu), hồ kiến tạo (dài, sâu, như hồ Bai-can), hồ móng ngựa (nông, cong, như Hồ Tây ở Hà Nội), hồ băng hà…","Nước băng tuyết: Khi băng tích tụ và bị nén thành sông băng, sông băng di chuyển và bào mòn địa hình."],"e":["Hay nhầm: Lượng mưa là nguồn cấp nước cho sông, không phải lưu lượng.","Hay nhầm: Độ sâu lòng sông không phải là lưu lượng.","Hay nhầm: Diện tích lưu vực không phải là lưu lượng.","Hay nhầm: Hồ núi lửa hình thành từ miệng núi lửa đã tắt, không phải Hồ Tây.","Hay nhầm: Hồ kiến tạo hình thành do lún sụt, nứt vỡ của mảng kiến tạo, không phải Hồ Tây.","Hay nhầm: Hồ băng hà hình thành do sông băng bào mòn, không phải Hồ Tây."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 12. Nước biển và đại dương","sum":["Nước biển và đại dương chiếm 97,5% tổng lượng nước trong thuỷ quyển. Nước biển có độ muối trung bình khoảng 35‰;","Khái niệm: Nước biển và đại dương chiếm 97,5% tổng lượng nước trong thuỷ quyển.","Nhiệt độ trung bình bề mặt đại dương thế giới khoảng 17°C: Nhiệt độ nước biển giảm dần từ Xích đạo về hai cực: đới nóng khoảng 27–28°C, ôn đới khoảng 15–16°C, đới lạnh dưới 1°C.","Sóng biển do gió sinh ra; gió càng mạnh, sóng càng lớn: Động đất hoặc núi lửa dưới đáy biển tạo ra sóng thần, lan truyền với tốc độ lớn và có thể cao trên 20 m khi vào bờ.","Thuỷ triều là hiện tượng nước biển…: Thuỷ triều là hiện tượng nước biển dâng lên và hạ xuống theo chu kì.","Dòng biển là dòng nước chảy trong…: Dòng biển là dòng nước chảy trong biển và đại dương, sinh ra chủ yếu do gió thường xuyên hoặc chênh lệch nhiệt độ, độ muối."],"e":["Hay nhầm: 10‰ là độ muối của biển Ban-tích, không phải trung bình của nước biển.","Hay nhầm: 43‰ là độ muối của Biển Đỏ, cao hơn mức trung bình.","Hay nhầm: 50‰ không phải độ muối trung bình của nước biển.","Hay nhầm: Thuỷ triều làm nước biển dâng và rút theo chu kì, không phải nguyên nhân chính của sóng.","Hay nhầm: Dòng biển là dòng chảy trong biển, không phải nguyên nhân của sóng.","Hay nhầm: Băng tan không phải nguyên nhân chính sinh ra sóng biển."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 13. Thực hành: Phân tích chế độ nước sông Hồng","sum":["Bảng số liệu lưu lượng nước trung bình tháng của sông Hồng tại trạm Hà Nội (đơn vị m³/s) gồm 12 tháng, từ tháng 1 đến tháng 12.","Khái niệm: Bảng số liệu lưu lượng nước trung bình tháng của sông Hồng tại trạm Hà Nội (đơn vị m³/s) gồm 12 tháng, từ tháng 1 đến tháng 12.","Cách làm: Vẽ biểu đồ cột thể hiện lưu lượng nước từng tháng; tính tổng lưu lượng 12 tháng rồi chia cho 12 để có lưu lượng trung bình tháng; các tháng có lưu…","Kết quả phân tích: Theo số liệu trong bảng, mùa lũ của sông Hồng từ tháng 6 đến tháng 10; mùa cạn từ tháng 11 đến tháng 5.","Từ khoá cần ghi nhớ: Lưu lượng; lưu lượng trung bình tháng; mùa lũ; mùa cạn; biểu đồ cột; sông Hồng.","Điểm nhấn ghi nhớ: Tổng 12 tháng ÷ 12 = trung bình tháng."],"e":["Hay nhầm: km² là đơn vị diện tích, không dùng cho lưu lượng.","Hay nhầm: °C là đơn vị nhiệt độ, không dùng cho lưu lượng.","Hay nhầm: mm là đơn vị đo lượng mưa, không dùng cho lưu lượng nước sông.","Hay nhầm: Tháng 1 đến tháng 4 có lưu lượng nhỏ, thuộc mùa cạn.","Hay nhầm: Tháng 11 và 12 có lưu lượng nhỏ, thuộc mùa cạn.","Hay nhầm: Tháng 2 và 3 có lưu lượng nhỏ, thuộc mùa cạn."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 6. Sinh quyển","l":[{"t":"Bài 14. Đất trên Trái Đất","sum":["Đất là lớp vật chất mỏng bao phủ bề mặt các lục địa và đảo, được hình thành do quá trình phong hoá các loại đá.","Khái niệm: Đất là lớp vật chất mỏng bao phủ bề mặt các lục địa và đảo, được hình thành do quá trình phong hoá các loại đá.","Phẫu diện đất là mặt cắt thẳng…: Phẫu diện đất là mặt cắt thẳng đứng của đất, gồm các tầng khác nhau về màu sắc, vật liệu và độ phì: tầng chứa mùn, tầng tích tụ, tầng đá mẹ và tầng…","Đất được hình thành dưới tác động của năm nhân tố: Đá mẹ (đá mẹ chua như granit cho đất chua;","Con người không tham gia hình thành…: Con người không tham gia hình thành đất tự nhiên nhưng làm biến đổi đất, tạo ra các loại đất như đất trồng lúa nước, đất bạc màu hay đất xói mòn trơ…","Từ khoá cần ghi nhớ: Đất;"],"e":["Hay nhầm: Màu sắc là đặc điểm bên ngoài, không phải đặc trưng cơ bản của đất.","Hay nhầm: Độ cao là đặc điểm của địa hình, không phải của đất.","Hay nhầm: Độ mặn không phải đặc trưng cơ bản chung của đất.","Hay nhầm: Băng hà tạo địa hình bồi tụ, không phải quá trình trực tiếp hình thành đất.","Hay nhầm: Núi lửa phun trào tạo đá mới, không trực tiếp hình thành đất.","Hay nhầm: Thuỷ triều không phải quá trình hình thành đất."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 15. Sinh quyển","sum":["Sinh quyển là bộ phận của vỏ Trái Đất có sự sống tồn tại. Giới hạn của sinh quyển phụ thuộc vào sự tồn tại của sự sống, bao gồm phần thấp của khí quyển (tầng đối lưu), toàn bộ thuỷ quyển và phần…","Sinh quyển là bộ phận của vỏ Trái Đất có sự sống tồn tại: Giới hạn của sinh quyển phụ thuộc vào sự tồn tại của sự sống, bao gồm phần thấp của khí quyển (tầng đối lưu), toàn bộ thuỷ quyển và phần trên của…","Sinh quyển có khối lượng nhỏ so…: Sinh quyển có khối lượng nhỏ so với các quyển khác của vỏ Trái Đất; có khả năng tích luỹ năng lượng nhờ quang hợp của cây xanh; có mối quan hệ mật…","Sự phát triển và phân bố sinh…: Sự phát triển và phân bố sinh vật chịu tác động của khí hậu (nhiệt độ, ánh sáng, nước), đất (cấu trúc, độ pH, độ phì), địa hình (độ cao, độ dốc,…","Các vành đai thực vật thay đổi…: Các vành đai thực vật thay đổi theo vĩ độ, từ vùng nhiệt đới lên cực, và theo độ cao ở vùng nhiệt đới.","Từ khoá cần ghi nhớ: Sinh quyển; quang hợp; giới hạn sinh thái;"],"e":["Hay nhầm: Chiều dài sông không quyết định giới hạn của sinh quyển.","Hay nhầm: Số lượng dân cư không quyết định giới hạn của sinh quyển.","Hay nhầm: Độ cao núi không quyết định giới hạn sinh quyển.","Hay nhầm: Gió biển không trực tiếp quyết định quá trình quang hợp.","Hay nhầm: Băng hà không trực tiếp tác động đến quang hợp.","Hay nhầm: Núi lửa không trực tiếp tác động đến quang hợp."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 16. Thực hành: Tìm hiểu sự phân bố đất và sinh vật trên Trái Đất","sum":["Phân bố đất trên Trái Đất: đọc bản đồ các nhóm đất chính (đất đài nguyên, đất pốt dôn, đất đen thảo nguyên ôn đới, đất đỏ vàng nhiệt đới, đất xám hoang mạc và bán hoang mạc, đất đỏ nâu rừng và cây…","Phân bố đất trên Trái Đất: Đọc bản đồ các nhóm đất chính (đất đài nguyên, đất pốt dôn, đất đen thảo nguyên ôn đới, đất đỏ vàng nhiệt đới, đất xám hoang mạc và bán hoang mạc,…","Phân bố thảm thực vật: Đọc bản đồ các kiểu thảm thực vật chính, kể tên các thảm thực vật từ cực về Xích đạo (đài nguyên, rừng lá kim, rừng lá rộng ôn đới, thảo nguyên ôn…","Phân bố đất và sinh vật theo độ cao: Trên sườn tây dãy Cáp-ca, khi đi từ chân núi lên đỉnh thường gặp lần lượt đất pốt dôn dưới thảm rừng, đất đồng cỏ ở độ cao lớn hơn, và đất sơ đẳng…","Từ khoá cần ghi nhớ: Đất đài nguyên;","Điểm nhấn ghi nhớ: Đất và thảm thực vật thay đổi theo vĩ độ (từ cực về Xích đạo) và theo độ cao (từ chân núi lên đỉnh)."],"e":["Hay nhầm: Đất đỏ vàng nhiệt đới phân bố ở vùng nóng ẩm, vĩ độ thấp.","Hay nhầm: Đất xám hoang mạc phân bố ở vùng khô hạn, không phải vùng cực.","Hay nhầm: Đất đen thảo nguyên ôn đới phân bố ở vĩ độ trung bình.","Hay nhầm: Rừng lá kim phân bố ở vùng ôn đới lạnh, không phải vùng nhiệt đới.","Hay nhầm: Thảo nguyên ôn đới phân bố ở vùng ôn đới khô, không phải nhiệt đới ẩm.","Hay nhầm: Hoang mạc là thảm thực vật ở vùng khô hạn."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 7. Một số quy luật của vỏ địa lí","l":[{"t":"Bài 17. Vỏ địa lí, quy luật thống nhất và hoàn chỉnh của vỏ địa lí","sum":["Vỏ địa lí là lớp vỏ của Trái Đất gồm các lớp vỏ thành phần (khí quyển, thạch quyển, thuỷ quyển, sinh quyển) xâm nhập và tác động lẫn nhau, tạo nên thể tổng hợp tự nhiên thống nhất và hoàn chỉnh.","Khái niệm: Vỏ địa lí là lớp vỏ của Trái Đất gồm các lớp vỏ thành phần (khí quyển, thạch quyển, thuỷ quyển, sinh quyển) xâm nhập và tác động lẫn nhau, tạo nên…","Giới hạn của vỏ địa lí gồm…: Giới hạn của vỏ địa lí gồm toàn bộ thuỷ quyển, sinh quyển, phần trên của thạch quyển và phần khí quyển bên dưới lớp ô-dôn.","Quy luật thống nhất và hoàn chỉnh…: Quy luật thống nhất và hoàn chỉnh là quy luật về mối quan hệ quy định lẫn nhau giữa các thành phần và các bộ phận lãnh thổ trong vỏ địa lí.","Biểu hiện: Nếu một thành phần thay đổi sẽ kéo theo sự thay đổi của các thành phần khác và của toàn bộ lãnh thổ.","Ý nghĩa thực tiễn: Có thể dự báo sự thay đổi của các thành phần tự nhiên khi sử dụng chúng, nên cần nghiên cứu tỉ mỉ đặc điểm địa lí của lãnh thổ trước khi khai thác,…"],"e":["Hay nhầm: Manti không thuộc vỏ địa lí; thạch quyển chỉ là một thành phần.","Hay nhầm: Nhân Trái Đất nằm sâu, không thuộc vỏ địa lí.","Hay nhầm: Vỏ địa lí còn gồm khí quyển và thạch quyển.","Hay nhầm: 5 km là độ dày của vỏ Trái Đất ở đại dương, không phải của vỏ địa lí.","Hay nhầm: 100 km là độ dày của thạch quyển.","Hay nhầm: 2900 km gần bằng độ dày của manti, không phải vỏ địa lí."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 18. Quy luật địa đới và quy luật phi địa đới","sum":["Quy luật địa đới là sự thay đổi có quy luật của tất cả các thành phần địa lí và các cảnh quan theo vĩ độ, từ Xích đạo về cực.","Khái niệm: Quy luật địa đới là sự thay đổi có quy luật của tất cả các thành phần địa lí và các cảnh quan theo vĩ độ, từ Xích đạo về cực.","Biểu hiện của quy luật địa đới: Các vòng đai nhiệt (nóng, ôn hoà, lạnh và băng giá vĩnh cửu); các đai khí áp và các đới gió chính; bảy đới khí hậu từ Xích đạo về hai cực; các đới…","Quy luật phi địa đới là sự…: Quy luật phi địa đới là sự phân bố của các thành phần địa lí và cảnh quan không phụ thuộc vào bức xạ Mặt Trời theo vĩ độ.","Biểu hiện của quy luật phi địa đới: Địa ô (phân hoá theo kinh độ, càng vào sâu trong lục địa càng khô) và đai cao (thiên nhiên phân hoá theo độ cao; ví dụ ở miền núi Bắc Bộ, từ dưới…","Ý nghĩa: Tính địa đới có ý nghĩa đặc biệt đối với sản xuất; ví dụ máy móc dễ hoen gỉ ở miền nhiệt đới ẩm nên cần nguyên tắc nhiệt đới hoá trong chế tạo máy."],"e":["Hay nhầm: Sự phân bố lục địa và đại dương là nguyên nhân của quy luật phi địa đới.","Hay nhầm: Độ cao địa hình là nguyên nhân của đai cao, thuộc quy luật phi địa đới.","Hay nhầm: Hoạt động của con người không phải nguyên nhân của quy luật địa đới.","Hay nhầm: Số đới khí hậu theo bài không phải là năm.","Hay nhầm: Số đới khí hậu theo bài không phải là sáu.","Hay nhầm: Số đới khí hậu theo bài không phải là chín."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 8. Địa lí dân cư","l":[{"t":"Bài 19. Quy mô dân số, gia tăng dân số và cơ cấu dân số thế giới","sum":["Từ khoảng giữa thế kỉ XX, số dân thế giới tăng rất nhanh (bùng nổ dân số) nhưng gần đây tăng chậm lại.","Khái niệm: Từ khoảng giữa thế kỉ XX, số dân thế giới tăng rất nhanh (bùng nổ dân số) nhưng gần đây tăng chậm lại.","Tỉ suất sinh thô cho biết cứ…: Tỉ suất sinh thô cho biết cứ 1 000 dân có bao nhiêu trẻ em sinh ra còn sống trong năm; tỉ suất tử thô cho biết cứ 1 000 dân có bao nhiêu người chết…","Gia tăng dân số cơ học là…: Gia tăng dân số cơ học là sự chênh lệch giữa tỉ suất nhập cư và tỉ suất xuất cư.","Cơ cấu dân số gồm cơ cấu…: Cơ cấu dân số gồm cơ cấu sinh học (giới tính, tuổi) và cơ cấu xã hội (trình độ văn hoá, lao động).","Phân loại theo cơ cấu tuổi: Dân số trẻ khi người dưới 15 tuổi chiếm trên 35% và người từ 65 tuổi trở lên dưới 7%; dân số già hoá khi người từ 65 tuổi trở lên chiếm trên 7%; dân…"],"e":["Hay nhầm: Số người nhập cư trên 1 000 dân là tỉ suất nhập cư.","Hay nhầm: Tỉ suất tử thô tính trên 1 000 dân, không phải trên 100 dân.","Hay nhầm: Tổng số dân là quy mô dân số, không phải tỉ suất.","Hay nhầm: Dân số già có tháp hình chum.","Hay nhầm: Dân số vàng là cách phân loại theo tỉ lệ người trong độ tuổi lao động, không gắn với hình tháp tam giác.","Hay nhầm: Không có loại dân số \"giảm\" trong cách phân loại của bài."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 20. Phân bố dân cư và đô thị hoá trên thế giới","sum":["Dân cư thế giới phân bố không đều. Các khu vực đông dân gồm Nam Á, Đông Á, Đông Nam Á, Tây và Trung Âu; các khu vực thưa dân gồm Bắc Á, châu Đại Dương.","Dân cư thế giới phân bố không đều: Các khu vực đông dân gồm Nam Á, Đông Á, Đông Nam Á, Tây và Trung Âu; các khu vực thưa dân gồm Bắc Á, châu Đại Dương.","Phân bố dân cư chịu tác động tổng hợp của nhiều nhân tố: Nhân tố tự nhiên tạo điều kiện thuận lợi hoặc gây trở ngại cho cư trú; các khu vực có điều kiện tự nhiên thuận lợi thường đông dân.","Đô thị hoá là quá trình kinh…: Đô thị hoá là quá trình kinh tế – xã hội mà biểu hiện là sự tăng nhanh về số lượng và quy mô các điểm dân cư đô thị, sự tập trung dân cư trong các…","Các nhân tố ảnh hưởng đến đô thị hoá: Vị trí địa lí và điều kiện tự nhiên (thuận lợi hay khó khăn nhưng không quyết định); phát triển kinh tế, đặc biệt là công nghiệp gắn với khoa học –…","Ảnh hưởng tích cực của đô thị hoá: Tạo thêm việc làm, tăng năng suất lao động, phổ biến lối sống thành thị, mở rộng không gian đô thị và hạ tầng hiện đại."],"e":["Hay nhầm: Mở rộng đất nông nghiệp không phải là đô thị hoá.","Hay nhầm: Đô thị hoá làm tăng dân cư thành thị, không phải giảm.","Hay nhầm: Di dân từ thành thị về nông thôn là chiều ngược lại của đô thị hoá.","Hay nhầm: Bắc Á là khu vực thưa dân.","Hay nhầm: Châu Đại Dương là khu vực thưa dân.","Hay nhầm: Vùng Bắc Cực rất thưa dân."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 9. Các nguồn lực, một số tiêu chí đánh giá sự phát triển kinh tế","l":[{"t":"Bài 21. Các nguồn lực phát triển kinh tế","sum":["Nguồn lực phát triển kinh tế của một lãnh thổ là sức mạnh tổng hợp được tích luỹ từ vị trí địa lí, lịch sử – văn hoá, tài nguyên thiên nhiên, nguồn lao động, các tài sản hiện có và tiềm năng, kể cả…","Khái niệm: Nguồn lực phát triển kinh tế của một lãnh thổ là sức mạnh tổng hợp được tích luỹ từ vị trí địa lí, lịch sử – văn hoá, tài nguyên thiên nhiên, nguồn…","Phân loại theo phạm vi lãnh thổ: Nguồn lực bên trong lãnh thổ gồm vị trí địa lí, nguồn lực tự nhiên (đất, nước, khí hậu, sinh vật, khoáng sản, biển), nguồn lực kinh tế – xã hội…","Nguồn lực bên trong có vai trò quyết định: Vị trí địa lí tạo thuận lợi hay khó khăn cho trao đổi và hợp tác.","Nguồn lực bên ngoài tạo thêm sức…: Nguồn lực bên ngoài tạo thêm sức mạnh, đặc biệt trong thời kì kinh tế tri thức và xu hướng quốc tế hoá.","Từ khoá cần ghi nhớ: Nguồn lực phát triển kinh tế; nguồn lực bên trong; nguồn lực bên ngoài; vị trí địa lí; nguồn lao động; vốn đầu tư; khoa học – công nghệ; chính sách;…"],"e":["Hay nhầm: Vốn đầu tư nước ngoài là nguồn lực từ bên ngoài lãnh thổ.","Hay nhầm: Thị trường nước ngoài là nguồn lực từ bên ngoài lãnh thổ.","Hay nhầm: Khoa học – công nghệ nước ngoài là nguồn lực từ bên ngoài lãnh thổ.","Hay nhầm: Tài nguyên khoáng sản quan trọng nhưng không được SGK xếp là nguồn lực quan trọng nhất.","Hay nhầm: Vị trí địa lí tạo thuận lợi hoặc khó khăn cho hợp tác, không phải nguồn lực quan trọng nhất.","Hay nhầm: Vốn đầu tư nước ngoài là nguồn lực bên ngoài, bổ sung cho nguồn lực bên trong."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 22. Cơ cấu kinh tế, tổng sản phẩm trong nước và tổng thu nhập quốc gia","sum":["Cơ cấu kinh tế là tổng thể các ngành, lĩnh vực, bộ phận kinh tế có quan hệ hữu cơ tương đối ổn định hợp thành.","Khái niệm: Cơ cấu kinh tế là tổng thể các ngành, lĩnh vực, bộ phận kinh tế có quan hệ hữu cơ tương đối ổn định hợp thành.","GDP (tổng sản phẩm trong nước) là…: GDP (tổng sản phẩm trong nước) là tổng giá trị theo giá thị trường của tất cả hàng hoá và dịch vụ cuối cùng được sản xuất trong phạm vi lãnh thổ…","GNI (tổng thu nhập quốc gia) là…: GNI (tổng thu nhập quốc gia) là tổng giá trị theo giá thị trường của các sản phẩm và dịch vụ cuối cùng do công dân mang quốc tịch nước đó tạo ra, kể…","GDP và GNI bình quân đầu người…: GDP và GNI bình quân đầu người được tính bằng quy mô chia cho tổng số dân, dùng để đánh giá mức sống dân cư.","Ví dụ cơ cấu GDP Việt Nam năm 2019 theo ngành: Nông nghiệp, lâm nghiệp và thuỷ sản 15,5%; công nghiệp và xây dựng 38,3%; dịch vụ 46,2%."],"e":["Hay nhầm: Đây là cơ cấu theo thành phần kinh tế, không phải cơ cấu theo ngành.","Hay nhầm: Đây là cơ cấu theo lãnh thổ.","Hay nhầm: Thành thị và nông thôn không phải cách phân chia cơ cấu theo ngành.","Hay nhầm: Mô tả này là GNI, không phải GDP.","Hay nhầm: Thu nhập bình quân đầu người là chỉ số khác, không phải GDP.","Hay nhầm: Giá trị xuất khẩu chỉ là một bộ phận, không phải GDP."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 10. Địa lí ngành nông nghiệp, lâm nghiệp, thuỷ sản","l":[{"t":"Bài 23. Vai trò, đặc điểm, các nhân tố ảnh hưởng tới sự phát triển và phân bố nông nghiệp, lâm nghiệp, thuỷ sản","sum":["Nông nghiệp, lâm nghiệp, thuỷ sản là ngành có vai trò không ngành nào thay thế được: khai thác hiệu quả nguồn lực; cung cấp sản phẩm cho tiêu dùng và sản xuất; là thị trường tiêu thụ của nhiều…","Khái niệm: Nông nghiệp, lâm nghiệp, thuỷ sản là ngành có vai trò không ngành nào thay thế được: khai thác hiệu quả nguồn lực; cung cấp sản phẩm cho tiêu dùng…","Đặc điểm: Đất trồng và mặt nước là tư liệu sản xuất chủ yếu;","Nhân tố tự nhiên: Đất ảnh hưởng đến năng suất và phân bố cây trồng;","Nhân tố kinh tế – xã hội: Dân cư và lao động vừa là lực lượng sản xuất vừa là nguồn tiêu thụ; quan hệ sở hữu ruộng đất và chính sách; tiến bộ khoa học – công nghệ; công…","Từ khoá cần ghi nhớ: Nông nghiệp xanh; tư liệu sản xuất; tính mùa vụ; nhân tố tự nhiên; nhân tố kinh tế – xã hội; sinh vật sống; chuyên môn hoá."],"e":["Hay nhầm: Máy móc là tư liệu hỗ trợ, không phải tư liệu sản xuất chủ yếu của ba ngành.","Hay nhầm: Nguyên liệu hoá chất thuộc công nghiệp chế biến, không phải tư liệu chủ yếu của nông nghiệp.","Hay nhầm: Điện và nhiên liệu là đầu vào hỗ trợ, không phải tư liệu sản xuất chủ yếu.","Hay nhầm: Sản xuất vẫn phụ thuộc điều kiện tự nhiên, dù mức độ giảm dần.","Hay nhầm: Ngành ngày càng gắn với khoa học – công nghệ.","Hay nhầm: Sản xuất thường diễn ra trong không gian rộng."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 24. Địa lí ngành nông nghiệp","sum":["Nông nghiệp gồm hai ngành chính là trồng trọt và chăn nuôi. Trồng trọt cung cấp lương thực, thực phẩm, nguyên liệu cho công nghiệp chế biến, tạo việc làm ở nông thôn; sản xuất phụ thuộc chặt chẽ vào…","Nông nghiệp gồm hai ngành chính là trồng trọt và chăn nuôi: Trồng trọt cung cấp lương thực, thực phẩm, nguyên liệu cho công nghiệp chế biến, tạo việc làm ở nông thôn; sản xuất phụ thuộc chặt chẽ vào điều kiện…","Ba cây lương thực chính trên thế…: Ba cây lương thực chính trên thế giới là lúa gạo (ưa khí hậu nóng ẩm, chân ruộng ngập nước, đất phù sa), lúa mì (ưa khí hậu ấm, khô) và ngô (ưa đất…","Cây công nghiệp chia theo công dụng: Cây lấy đường (mía, củ cải đường), cây lấy sợi (bông, đay), cây lấy dầu (đậu tương, lạc), cây chất kích thích (chè, cà phê, ca cao), cây lấy nhựa…","Chăn nuôi cung cấp thực phẩm giàu…: Chăn nuôi cung cấp thực phẩm giàu dinh dưỡng, nguyên liệu cho công nghiệp thực phẩm và hàng tiêu dùng, thúc đẩy trồng trọt phát triển.","Từ khoá cần ghi nhớ: Trồng trọt; chăn nuôi; lúa gạo; lúa mì; ngô; cây công nghiệp; chăn nuôi gia súc lớn; gia súc nhỏ; gia cầm; nguồn thức ăn."],"e":["Hay nhầm: Mía, bông, cà phê là các cây công nghiệp.","Hay nhầm: Đậu tương, lạc, chè thuộc nhóm cây công nghiệp.","Hay nhầm: Cao su, ca cao là cây công nghiệp.","Hay nhầm: Khí hậu lạnh khô không phù hợp với lúa gạo.","Hay nhầm: Đất đá vôi khô cằn không phải điều kiện của lúa gạo.","Hay nhầm: Khí hậu ôn đới lạnh giá không phù hợp với lúa gạo."],"q":{"n":7,"lv":{"Biết":3,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 25. Địa lí ngành lâm nghiệp và ngành thuỷ sản","sum":["Ngành lâm nghiệp gồm trồng rừng, khai thác và chế biến lâm sản, bảo vệ và bảo tồn hệ sinh thái rừng.","Khái niệm: Ngành lâm nghiệp gồm trồng rừng, khai thác và chế biến lâm sản, bảo vệ và bảo tồn hệ sinh thái rừng.","Đặc điểm của lâm nghiệp là chu…: Đặc điểm của lâm nghiệp là chu kì sinh trưởng dài và phát triển chậm; sản xuất diễn ra trong không gian rộng, trên địa bàn có điều kiện tự nhiên đa…","Ngành thuỷ sản gồm khai thác, chế biến và nuôi trồng: Thuỷ sản cung cấp chất đạm dễ tiêu hoá, nguyên liệu cho công nghiệp thực phẩm, dược phẩm và là mặt hàng xuất khẩu.","Khai thác thuỷ sản chủ yếu diễn…: Khai thác thuỷ sản chủ yếu diễn ra ở biển và đại dương, cá chiếm 85–90% sản lượng.","Từ khoá cần ghi nhớ: Lâm nghiệp; trồng rừng; lâm sản; chu kì sinh trưởng dài; thuỷ sản; khai thác; nuôi trồng; nước lợ; chuỗi giá trị."],"e":["Hay nhầm: Lâm nghiệp không chỉ khai thác gỗ mà còn trồng rừng và bảo vệ rừng.","Hay nhầm: Nuôi cá thuộc ngành thuỷ sản.","Hay nhầm: Chăn nuôi gia súc thuộc ngành nông nghiệp.","Hay nhầm: Cây rừng không có chu kì sinh trưởng ngắn như vài ngày.","Hay nhầm: Lâm nghiệp gắn chặt với đất đai và điều kiện tự nhiên.","Hay nhầm: Lâm nghiệp diễn ra trong không gian rộng, không phải trong nhà kính."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 26. Tổ chức lãnh thổ nông nghiệp, một số vấn đề phát triển nông nghiệp hiện đại trên thế giới và định hướng phát…","sum":["Tổ chức lãnh thổ nông nghiệp là sự sắp xếp và phối hợp các đối tượng nông nghiệp trên một lãnh thổ cụ thể nhằm sử dụng hợp lí nhất tiềm năng tự nhiên, kinh tế, lao động để đạt hiệu quả kinh tế, xã…","Khái niệm: Tổ chức lãnh thổ nông nghiệp là sự sắp xếp và phối hợp các đối tượng nông nghiệp trên một lãnh thổ cụ thể nhằm sử dụng hợp lí nhất tiềm năng tự…","Các hình thức chủ yếu: Trang trại (mục đích sản xuất nông sản hàng hoá, quy mô tương đối lớn, có thể sử dụng lao động làm thuê); vùng nông nghiệp (lãnh thổ tương đồng về…","Nền nông nghiệp hiện đại khắc phục…: Nền nông nghiệp hiện đại khắc phục khó khăn như thu hẹp đất canh tác, biến đổi khí hậu, thoái hoá đất, ô nhiễm bằng: hình thành cánh đồng lớn;","Định hướng nông nghiệp tương lai: Thích ứng với biến đổi khí hậu; phát triển nông nghiệp công nghệ cao; phát triển nông nghiệp xanh (hữu cơ), khai thác tối đa tài nguyên sạch.","Từ khoá cần ghi nhớ: Tổ chức lãnh thổ nông nghiệp; trang trại; vùng nông nghiệp; thể tổng hợp nông nghiệp; cánh đồng lớn; công nghệ cao; nông nghiệp xanh; thích ứng biến…"],"e":["Hay nhầm: Điểm công nghiệp và khu công nghiệp là hình thức tổ chức lãnh thổ công nghiệp.","Hay nhầm: Đô thị và nông thôn là đơn vị dân cư, không phải hình thức tổ chức lãnh thổ nông nghiệp.","Hay nhầm: Cảng biển và sân bay là hạ tầng giao thông.","Hay nhầm: Điểm dân cư là nơi ở, không phải hình thức sản xuất nông sản hàng hoá.","Hay nhầm: Vùng công nghiệp là hình thức tổ chức lãnh thổ công nghiệp.","Hay nhầm: Cảng biển là hạ tầng giao thông, không phải hình thức sản xuất nông nghiệp."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 27. Thực hành: Vẽ và nhận xét biểu đồ về sản lượng lương thực của thế giới","sum":["Bảng 27 cho biết sản lượng lương thực của thế giới năm 2000 và năm 2019, đơn vị triệu tấn.","Khái niệm: Bảng 27 cho biết sản lượng lương thực của thế giới năm 2000 và năm 2019, đơn vị triệu tấn.","Cách làm: Tính cơ cấu (%) của từng loại trong tổng sản lượng bằng cách lấy sản lượng từng loại chia cho tổng rồi nhân 100; vẽ biểu đồ tròn cho cơ cấu và biểu…","Khi vẽ biểu đồ tròn, mỗi thành…: Khi vẽ biểu đồ tròn, mỗi thành phần chiếm một góc tương ứng với tỉ lệ phần trăm trên 360°.","Từ khoá cần ghi nhớ: Sản lượng lương thực; cơ cấu; biểu đồ tròn; biểu đồ cột; triệu tấn; lúa gạo; lúa mì; ngô; cây hoa màu.","Điểm nhấn ghi nhớ: Cơ cấu = phần ÷ tổng × 100."],"e":["Hay nhầm: Tỉ USD là đơn vị giá trị tiền tệ, không dùng cho sản lượng.","Hay nhầm: Héc-ta là đơn vị diện tích.","Hay nhầm: Phần trăm dùng cho cơ cấu, không phải đơn vị sản lượng.","Hay nhầm: Bản đồ hành chính không thể hiện cơ cấu sản lượng.","Hay nhầm: Bảng không có số liệu không thể thể hiện cơ cấu.","Hay nhầm: Biểu đồ đường không trục không đọc được giá trị."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 11. Địa lí ngành công nghiệp","l":[{"t":"Bài 28. Vai trò, đặc điểm, cơ cấu ngành công nghiệp, các nhân tố ảnh hưởng tới sự phát triển và phân bố công nghiệp","sum":["Công nghiệp là ngành đóng vai trò chủ đạo trong nền kinh tế quốc dân: cung cấp tư liệu sản xuất cho toàn bộ nền kinh tế, cung cấp hàng tiêu dùng và hàng xuất khẩu, tạo việc làm, khai thác hiệu quả…","Công nghiệp là ngành đóng vai trò chủ đạo trong nền kinh tế quốc dân: Cung cấp tư liệu sản xuất cho toàn bộ nền kinh tế, cung cấp hàng tiêu dùng và hàng xuất khẩu, tạo việc làm, khai thác hiệu quả tài nguyên và là hạt…","Đặc điểm sản xuất công nghiệp: Gắn liền với máy móc và công nghệ; có mức độ tập trung hoá, chuyên môn hoá và hợp tác hoá cao; tiêu thụ nhiều nguyên liệu nên thải nhiều chất thải;…","Cơ cấu ngành công nghiệp: Dựa vào tác động tới đối tượng lao động, chia thành công nghiệp khai thác (khai thác khoáng sản, nước, sinh vật để tạo nguyên liệu, nhiên liệu) và…","Nhân tố bên trong: Vị trí địa lí;","Từ khoá cần ghi nhớ: Công nghiệp khai thác; công nghiệp chế biến; cơ cấu ngành; tập trung hoá; chuyên môn hoá; hạt nhân phát triển vùng; tự động hoá; nhân tố ảnh hưởng."],"e":["Hay nhầm: Điện và nước là hai ngành trong nhóm công nghiệp, không phải hai nhóm chính.","Hay nhầm: Nội địa và xuất khẩu là cách nhìn về thị trường, không phải cách chia cơ cấu ngành.","Hay nhầm: Nhà nước và tư nhân là cách chia theo thành phần kinh tế.","Hay nhầm: Sản xuất công nghiệp cần máy móc.","Hay nhầm: Sản xuất thủ công không phải đặc điểm của công nghiệp hiện đại.","Hay nhầm: Công nghiệp có mức độ tập trung hoá cao, không phân tán hoàn toàn."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 29. Địa lí một số ngành công nghiệp","sum":["Công nghiệp khai thác than: than là nguồn năng lượng truyền thống, dùng cho nhiệt điện, luyện kim và làm nguyên liệu cho công nghiệp hoá chất.","Công nghiệp khai thác than: Than là nguồn năng lượng truyền thống, dùng cho nhiệt điện, luyện kim và làm nguyên liệu cho công nghiệp hoá chất.","Công nghiệp khai thác dầu khí: Dầu khí là nguồn năng lượng truyền thống, nguyên liệu cho hoá phẩm và dược phẩm, nguồn thu ngoại tệ lớn.","Công nghiệp khai thác quặng kim loại: Quặng gồm kim loại đen, kim loại màu, kim loại quý, kim loại hiếm; khai thác thiếu quy hoạch làm nhiều loại quặng có nguy cơ cạn kiệt và gây ô nhiễm.","Công nghiệp điện lực: Điện là nguồn năng lượng thiết yếu; sản lượng điện bình quân đầu người là thước đo trình độ phát triển;","Công nghiệp điện tử, tin học: Ngành mũi nhọn, giá trị gia tăng cao, phát triển mạnh từ cuối thế kỉ XX, ít gây ô nhiễm."],"e":["Hay nhầm: Gió là nguồn năng lượng tái tạo, không phải nhiên liệu truyền thống của nhiệt điện.","Hay nhầm: Nước ngầm là nguồn nước, không phải nhiên liệu.","Hay nhầm: Ánh sáng mặt trời là năng lượng tái tạo.","Hay nhầm: Điện không dễ tích trữ với số lượng lớn như hàng hoá khác.","Hay nhầm: Điện không được để trong kho như hàng hoá thông thường.","Hay nhầm: Điện cần hệ thống truyền tải để đưa đến người dùng."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 30. Tổ chức lãnh thổ công nghiệp","sum":["Tổ chức lãnh thổ công nghiệp là việc bố trí, sắp xếp các hình thức tổ chức lãnh thổ công nghiệp để tạo nên không gian công nghiệp, nhằm sử dụng hợp lí điều kiện tự nhiên, tài nguyên và kinh tế – xã…","Khái niệm: Tổ chức lãnh thổ công nghiệp là việc bố trí, sắp xếp các hình thức tổ chức lãnh thổ công nghiệp để tạo nên không gian công nghiệp, nhằm sử dụng hợp…","Điểm công nghiệp: Hình thức đơn giản nhất, gồm một số xí nghiệp gần nguồn nguyên liệu (hoặc vùng nông sản), ít hoặc không có mối liên hệ, gắn với một điểm dân cư;…","Khu công nghiệp: Tập trung tương đối nhiều xí nghiệp có khả năng hợp tác cao, trên khu vực có ranh giới xác định, không có dân cư sinh sống, cùng sử dụng cơ sở hạ…","Trung tâm công nghiệp: Có dân cư sinh sống, cơ sở vật chất – kĩ thuật và hạ tầng đồng bộ, gồm các xí nghiệp hạt nhân, có mối liên hệ chặt chẽ về quy trình công nghệ; là…","Từ khoá cần ghi nhớ: Tổ chức lãnh thổ công nghiệp;"],"e":["Hay nhầm: Trang trại và vùng nông nghiệp là hình thức tổ chức lãnh thổ nông nghiệp.","Hay nhầm: Đô thị và nông thôn là đơn vị dân cư.","Hay nhầm: Cảng biển và sân bay là hạ tầng giao thông.","Hay nhầm: Ranh giới xác định, không có dân cư là đặc điểm của khu công nghiệp.","Hay nhầm: Tập trung nhiều xí nghiệp liên kết chặt chẽ là đặc điểm của khu công nghiệp hoặc trung tâm.","Hay nhầm: Hạt nhân tạo vùng kinh tế là đặc điểm của trung tâm công nghiệp."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 31. Tác động của công nghiệp đối với môi trường, phát triển năng lượng tái tạo, định hướng phát triển công nghiệp…","sum":["Công nghiệp tạo ra của cải nhưng đưa vào môi trường nhiều chất thải. Khí thải gây ô nhiễm không khí; khí nhà kính, đặc biệt từ đốt năng lượng hoá thạch, gây hiệu ứng nhà kính và biến đổi khí hậu.","Khái niệm: Công nghiệp tạo ra của cải nhưng đưa vào môi trường nhiều chất thải.","Sử dụng năng lượng hoá thạch làm…: Sử dụng năng lượng hoá thạch làm cạn kiệt tài nguyên, gây ô nhiễm và biến đổi khí hậu, nên thế giới chú trọng phát triển năng lượng tái tạo: sức…","Định hướng công nghiệp tương lai là phát triển bền vững: Chuyển dần sang ngành có kĩ thuật, công nghệ cao; phát triển theo tăng trưởng xanh với quy trình ít gây ô nhiễm, tiết kiệm năng lượng và tài nguyên;","Từ khoá cần ghi nhớ: Ô nhiễm không khí;","Điểm nhấn ghi nhớ: Năng lượng hoá thạch → cạn kiệt, phát thải."],"e":["Hay nhầm: Trồng cây xanh giúp hấp thụ khí CO₂, không gây ra khí nhà kính.","Hay nhầm: Đánh bắt thuỷ sản không phải nguồn phát thải khí nhà kính chính.","Hay nhầm: Thu gom rác sinh hoạt không trực tiếp tạo khí nhà kính ở quy mô công nghiệp.","Hay nhầm: Than đá và dầu mỏ là năng lượng hoá thạch, không tái tạo.","Hay nhầm: Khí tự nhiên khai thác là năng lượng hoá thạch.","Hay nhầm: Uranium là nguyên liệu không tái tạo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 32. Thực hành: Viết báo cáo tìm hiểu một vấn đề về công nghiệp","sum":["Gợi ý nội dung: thành tựu nổi bật của một ngành công nghiệp đã học; một trung tâm hoặc khu công nghiệp thành công; tác động của một hoạt động công nghiệp tới môi trường và hướng xử lí; một lĩnh vực…","Gợi ý nội dung: Thành tựu nổi bật của một ngành công nghiệp đã học; một trung tâm hoặc khu công nghiệp thành công; tác động của một hoạt động công nghiệp tới môi…","Cách tiến hành: Phác thảo đề cương; thu thập tài liệu từ số liệu, báo cáo và các trang web đáng tin cậy của tổ chức, cơ quan trong và ngoài nước (ví dụ Ngân hàng…","Viết báo cáo theo đề cương, ngắn…: Viết báo cáo theo đề cương, ngắn gọn, nêu ý nghĩa của nội dung tìm hiểu, hiện trạng và nguyên nhân.","Từ khoá cần ghi nhớ: Báo cáo;","Điểm nhấn ghi nhớ: Đề cương trước, số liệu sau."],"e":["Hay nhầm: Kết luận chỉ viết khi đã có kết quả tìm hiểu.","Hay nhầm: In báo cáo là bước cuối cùng.","Hay nhầm: Gửi báo cáo là bước sau khi hoàn thành.","Hay nhầm: Nguồn không rõ ràng khó kiểm chứng độ tin cậy.","Hay nhầm: Tin đồn không đáng tin cậy để làm số liệu.","Hay nhầm: Ý kiến chưa kiểm chứng không đủ cơ sở khoa học."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 12. Địa lí ngành dịch vụ","l":[{"t":"Bài 33. Cơ cấu, vai trò, đặc điểm, các nhân tố ảnh hưởng đến sự phát triển và phân bố dịch vụ","sum":["Dịch vụ là những hoạt động mang tính xã hội, tạo ra sản phẩm phần lớn là vô hình (phi vật chất) nhằm thoả mãn nhu cầu trong sản xuất và đời sống.","Khái niệm: Dịch vụ là những hoạt động mang tính xã hội, tạo ra sản phẩm phần lớn là vô hình (phi vật chất) nhằm thoả mãn nhu cầu trong sản xuất và đời sống.","Vai trò: Giúp sản xuất và phân phối thông suốt, hiệu quả cao; thúc đẩy phân công lao động và hình thành cơ cấu kinh tế hợp lí; góp phần tăng thu nhập quốc…","Đặc điểm: Sản phẩm phần lớn là phi vật chất nên khó đánh giá chất lượng và quy mô hơn sản phẩm vật chất; quá trình sản xuất và tiêu dùng dịch vụ thường diễn…","Nhân tố ảnh hưởng: Vị trí địa lí (thu hút vốn, lao động chất lượng cao, tiếp cận thị trường); tự nhiên (địa hình, khí hậu tác động đến giao thông và du lịch); kinh tế…","Từ khoá cần ghi nhớ: Dịch vụ; dịch vụ kinh doanh; dịch vụ tiêu dùng; dịch vụ công; phi vật chất; hội nhập; toàn cầu hoá; trình độ phát triển kinh tế."],"e":["Hay nhầm: Nông nghiệp, công nghiệp, xây dựng là các khu vực kinh tế khác, không phải nhóm dịch vụ.","Hay nhầm: Trong nước và nước ngoài là cách phân loại theo phạm vi, không phải cách chia nhóm dịch vụ.","Hay nhầm: Thành thị và nông thôn là cách phân loại theo lãnh thổ dân cư.","Hay nhầm: Sản phẩm vật chất là đặc điểm của nông nghiệp và công nghiệp.","Hay nhầm: Hàng hoá nặng là sản phẩm vật chất, không phải đặc điểm dịch vụ.","Hay nhầm: Năng lượng than đá là sản phẩm của công nghiệp khai thác."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 34. Địa lí ngành giao thông vận tải","sum":["Giao thông vận tải là ngành dịch vụ đặc biệt, kết nối sản xuất và đời sống: vận chuyển nguyên liệu, sản phẩm, hành khách; thúc đẩy hội nhập quốc tế và tăng cường an ninh quốc phòng.","Khái niệm: Giao thông vận tải là ngành dịch vụ đặc biệt, kết nối sản xuất và đời sống: vận chuyển nguyên liệu, sản phẩm, hành khách; thúc đẩy hội nhập quốc tế…","Khối lượng dịch vụ được đánh giá…: Khối lượng dịch vụ được đánh giá bằng khối lượng vận chuyển (số lượt khách, số tấn hàng), khối lượng luân chuyển (số lượt khách.km, số tấn.km) và cự…","Đường ô tô: Linh hoạt, cơ động, dễ kết nối; tổng chiều dài tăng từ 27 803,8 nghìn km (2000) lên 38 016,5 nghìn km (2019); năm nước có chiều dài lớn nhất (Hoa…","Đường sắt ra đời đầu thế kỉ…: Đường sắt ra đời đầu thế kỉ XIX với đầu máy hơi nước; tổng chiều dài tăng từ 1 011,7 nghìn km (2000) lên 1 321,9 nghìn km (2019).","Từ khoá cần ghi nhớ: Mạng lưới giao thông; khối lượng luân chuyển; cự li vận chuyển;"],"e":["Hay nhầm: Phân bố giao thông có quy luật rõ ràng, theo mạng lưới.","Hay nhầm: Giao thông không tập trung ở một điểm duy nhất.","Hay nhầm: Giao thông không chỉ phân bố ở vùng núi.","Hay nhầm: Số km đường là chỉ tiêu hạ tầng, không phải khối lượng luân chuyển.","Hay nhầm: Số xe đăng kí không phải chỉ tiêu luân chuyển.","Hay nhầm: Số bến xe không phản ánh khối lượng luân chuyển."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 35. Địa lí ngành bưu chính viễn thông","sum":["Bưu chính viễn thông là dịch vụ cơ bản, gồm hai nhóm: bưu chính (vận chuyển thư, bưu phẩm, bưu kiện, hàng hoá) và viễn thông (gửi, truyền, nhận và xử lí thông tin giữa các đối tượng sử dụng ở khoảng…","Bưu chính viễn thông là dịch vụ cơ bản, gồm hai nhóm: Bưu chính (vận chuyển thư, bưu phẩm, bưu kiện, hàng hoá) và viễn thông (gửi, truyền, nhận và xử lí thông tin giữa các đối tượng sử dụng ở khoảng…","Phát triển của bưu chính viễn thông…: Phát triển của bưu chính viễn thông phụ thuộc vào trình độ kinh tế, mức sống dân cư, phân bố dân cư và các ngành kinh tế, và đặc biệt là khoa học –…","Bưu chính mở rộng mạng lưới bưu…: Bưu chính mở rộng mạng lưới bưu cục và có các dịch vụ mới như chuyển phát nhanh, bán hàng qua bưu điện, nhưng vẫn tập trung ở thành phố và trung tâm…","Internet ra đời từ năm 1989 đã…: Internet ra đời từ năm 1989 đã làm cuộc cách mạng trong viễn thông; năm 2019 có hơn 4,3 tỉ người sử dụng.","Từ khoá cần ghi nhớ: Bưu chính; viễn thông; thuê bao; internet; mạng di động; chuyển phát nhanh; công nghệ thông tin; hạ tầng."],"e":["Hay nhầm: Giao thông là ngành dịch vụ riêng, không thuộc bưu chính viễn thông.","Hay nhầm: Du lịch là ngành dịch vụ khác.","Hay nhầm: Thương mại và tài chính là hai ngành dịch vụ khác.","Hay nhầm: 1876 là năm phát minh điện thoại đầu tiên.","Hay nhầm: 1993 là năm mạng di động đầu tiên ra đời ở nước ta.","Hay nhầm: 1997 là năm Việt Nam kết nối internet."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 36. Địa lí ngành du lịch","sum":["Du lịch là ngành dịch vụ phát triển nhanh, thu hút hàng tỉ người tham gia. Vai trò: tạo nguồn thu ngoại tệ, thúc đẩy các ngành liên quan, tạo việc làm, đáp ứng nhu cầu tinh thần, bảo tồn giá trị văn…","Khái niệm: Du lịch là ngành dịch vụ phát triển nhanh, thu hút hàng tỉ người tham gia.","Đặc điểm: Du lịch vừa mang đặc điểm của ngành kinh tế, vừa mang đặc điểm của ngành văn hoá – xã hội; là ngành kinh tế tổng hợp, liên quan nhiều ngành nghề; có…","Các nhân tố: Tài nguyên du lịch tự nhiên và nhân văn tạo sản phẩm du lịch; thị trường khách quyết định doanh thu và cơ cấu sản phẩm; cơ sở vật chất – kĩ thuật và…","Tình hình: Số lượt khách du lịch quốc tế tăng từ 455,9 triệu (1990) lên 687,3 triệu (2000) và 1 460 triệu (2019); doanh thu đạt 1 482 tỉ USD năm 2019, khoảng…","Từ khoá cần ghi nhớ: Du lịch; tài nguyên du lịch; thị trường khách; mùa vụ; du lịch xanh; du lịch bền vững; doanh thu; khách du lịch quốc tế."],"e":["Hay nhầm: Du lịch là ngành dịch vụ, không chỉ sản xuất vật chất.","Hay nhầm: Du lịch không chỉ liên quan đến nông nghiệp.","Hay nhầm: Du lịch có liên quan trực tiếp đến xã hội và văn hoá.","Hay nhầm: Du lịch chịu ảnh hưởng lớn của điều kiện tự nhiên và thời tiết.","Hay nhầm: Hoạt động du lịch không diễn ra đều đặn như nhau quanh năm.","Hay nhầm: Du lịch gắn với giá trị văn hoá và xã hội."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 37. Địa lí ngành thương mại và ngành tài chính ngân hàng","sum":["Thương mại là quá trình trao đổi hàng hoá, dịch vụ giữa bên bán và bên mua, tạo ra thị trường; là cầu nối giữa sản xuất và tiêu dùng, điều tiết sản xuất và thúc đẩy phân công lao động.","Khái niệm: Thương mại là quá trình trao đổi hàng hoá, dịch vụ giữa bên bán và bên mua, tạo ra thị trường; là cầu nối giữa sản xuất và tiêu dùng, điều tiết sản…","Cán cân xuất nhập khẩu: Xuất siêu khi trị giá xuất khẩu lớn hơn nhập khẩu; nhập siêu khi trị giá xuất khẩu nhỏ hơn nhập khẩu.","Tài chính ngân hàng là huyết mạch của nền kinh tế: Cung cấp dịch vụ tài chính, đảm bảo đầu tư và sản xuất diễn ra liên tục, ổn định nền kinh tế và thúc đẩy toàn cầu hoá.","Các nhân tố ảnh hưởng đến thương mại và tài chính ngân hàng: Trình độ phát triển kinh tế, sức mua và nhu cầu, khoa học – công nghệ, toàn cầu hoá và hội nhập.","Từ khoá cần ghi nhớ: Nội thương; ngoại thương; xuất siêu; nhập siêu;"],"e":["Hay nhầm: Trường hợp này là nhập siêu.","Hay nhầm: Khi hai trị giá bằng nhau thì cán cân cân bằng, không gọi là xuất siêu.","Hay nhầm: Không có xuất khẩu thì không thể nói đến xuất siêu.","Hay nhầm: Ngân hàng Thế giới mới là tổ chức cho vay phát triển.","Hay nhầm: ASEAN là tổ chức kinh tế khu vực Đông Nam Á.","Hay nhầm: Quỹ Tiền tệ Quốc tế hoạt động về hợp tác tiền tệ toàn cầu."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 38. Thực hành: Viết báo cáo tìm hiểu về một ngành dịch vụ","sum":["Gợi ý: chọn một ngành dịch vụ đã học (giao thông vận tải, bưu chính viễn thông, thương mại, du lịch, tài chính ngân hàng) hoặc ngành khác như bảo hiểm, y tế, giáo dục, dịch vụ pháp lí, quảng cáo,…","Gợi ý: Chọn một ngành dịch vụ đã học (giao thông vận tải, bưu chính viễn thông, thương mại, du lịch, tài chính ngân hàng) hoặc ngành khác như bảo hiểm, y…","Tiến hành: Phác thảo đề cương; thu thập số liệu, báo cáo từ các trang web đáng tin cậy như Ngân hàng Thế giới, OECD, Liên minh Bưu chính Quốc tế, Tổ chức…","Viết báo cáo ngắn gọn theo đề…: Viết báo cáo ngắn gọn theo đề cương, nêu ý nghĩa của nội dung tìm hiểu, hiện trạng và nguyên nhân; trình bày với hình ảnh, bảng số liệu, biểu đồ để…","Từ khoá cần ghi nhớ: Ngành dịch vụ;","Điểm nhấn ghi nhớ: Chọn ngành → lập đề cương → thu thập số liệu tin cậy → viết ngắn gọn có minh hoạ."],"e":["Hay nhầm: Du lịch là ngành dịch vụ đã học nên thuộc gợi ý.","Hay nhầm: Thương mại là ngành dịch vụ đã học nên thuộc gợi ý.","Hay nhầm: Bảo hiểm là ngành dịch vụ được nêu trong gợi ý.","Hay nhầm: Bài viết không ghi nguồn khó kiểm chứng.","Hay nhầm: Tin nhắn chia sẻ không đáng tin cậy làm số liệu.","Hay nhầm: Ý kiến không có căn cứ không phù hợp làm báo cáo."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]},{"t":"Chương 13. Phát triển bền vững và tăng trưởng xanh","l":[{"t":"Bài 39. Môi trường và tài nguyên thiên nhiên","sum":["Môi trường là tập hợp các yếu tố vật chất tự nhiên và nhân tạo có quan hệ mật thiết với nhau, bao quanh con người và ảnh hưởng đến đời sống, kinh tế, xã hội.","Khái niệm: Môi trường là tập hợp các yếu tố vật chất tự nhiên và nhân tạo có quan hệ mật thiết với nhau, bao quanh con người và ảnh hưởng đến đời sống, kinh…","Vai trò của môi trường: Là không gian sống; cung cấp tài nguyên cho sản xuất và đời sống; chứa đựng chất thải do con người tạo ra; lưu giữ và cung cấp thông tin.","Suy thoái môi trường là sự suy…: Suy thoái môi trường là sự suy giảm về chất lượng, số lượng của thành phần môi trường.","Tài nguyên thiên nhiên là toàn bộ…: Tài nguyên thiên nhiên là toàn bộ giá trị vật chất có trong tự nhiên mà con người có thể khai thác, chế biến, sử dụng.","Vai trò của tài nguyên: Là nguồn lực quan trọng cho sản xuất; là cơ sở tích luỹ vốn và phát triển kinh tế."],"e":["Hay nhầm: Luật lệ và phong tục thuộc môi trường xã hội.","Hay nhầm: Cơ sở hạ tầng và đô thị thuộc môi trường nhân tạo.","Hay nhầm: Quan hệ giữa người với người thuộc môi trường xã hội.","Hay nhầm: Tài nguyên vô hạn không bị giới hạn bởi thời gian ngắn.","Hay nhầm: Tài nguyên vô hạn không bị cạn kiệt như tài nguyên hữu hạn.","Hay nhầm: Tài nguyên vô hạn là do tự nhiên tạo ra, không phải do con người."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}},{"t":"Bài 40. Phát triển bền vững và tăng trưởng xanh","sum":["Phát triển bền vững là sự phát triển đáp ứng nhu cầu của hiện tại mà không làm tổn hại khả năng đáp ứng nhu cầu của các thế hệ tương lai, trên cơ sở kết hợp hài hoà giữa tăng trưởng kinh tế, bảo đảm…","Khái niệm: Phát triển bền vững là sự phát triển đáp ứng nhu cầu của hiện tại mà không làm tổn hại khả năng đáp ứng nhu cầu của các thế hệ tương lai, trên cơ sở…","Phát triển bền vững thường được mô tả bằng ba vòng tròn lồng ghép: Kinh tế, xã hội và môi trường; phần giao của ba vòng tròn là phát triển bền vững.","Sự cần thiết: Về kinh tế, tăng trưởng GDP nhanh dẫn đến khai thác tài nguyên quá mức và chất thải lớn; về xã hội, gia tăng dân số, đô thị hoá nhanh, phân chia…","Tăng trưởng xanh là thúc đẩy tăng…: Tăng trưởng xanh là thúc đẩy tăng trưởng kinh tế đồng thời bảo tồn tài nguyên thiên nhiên và bảo vệ môi trường, lấy giảm phát thải khí nhà kính và…","Biểu hiện của tăng trưởng xanh: Xanh hoá sản xuất (sử dụng tài nguyên hiệu quả, giảm phát thải, năng lượng sạch); xanh hoá lối sống và thúc đẩy tiêu dùng bền vững; giảm bất bình…"],"e":["Hay nhầm: Công nghiệp, nông nghiệp, dịch vụ là ba khu vực kinh tế, không phải ba yếu tố của phát triển bền vững.","Hay nhầm: Vốn, lao động, đất đai là nguồn lực, không phải ba yếu tố của phát triển bền vững.","Hay nhầm: Trong nước, ngoài nước là cách phân loại phạm vi, không phải ba yếu tố.","Hay nhầm: Trồng cây xanh chỉ là một hoạt động, không phải khái niệm tăng trưởng xanh.","Hay nhầm: Khai thác tài nguyên không tái tạo đi ngược với tăng trưởng xanh.","Hay nhầm: Tăng trưởng xanh không ngừng hoạt động kinh tế mà giữ cân bằng với môi trường."],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]}]}]},{"id":"gdktpl","name":"Giáo dục kinh tế và pháp luật","b":[{"t":"Giáo dục kinh tế và pháp luật 10","c":[{"t":"Chủ đề 1. Nền kinh tế và các chủ thể của nền kinh tế","l":[{"t":"Bài 1. Các hoạt động kinh tế cơ bản trong đời sống xã hội","req":["Nêu được vai trò của các hoạt động kinh tế cơ bản trong đời sống xã hội.","Nhận biết được trách nhiệm của công dân khi tham gia các hoạt động kinh tế."],"sum":["Hoạt động kinh tế là hoạt động sử dụng nguồn lực của xã hội để tạo ra sản phẩm (hữu hình hoặc vô hình) thoả mãn nhu cầu của con người.","Khái niệm: Hoạt động kinh tế là hoạt động sử dụng nguồn lực của xã hội để tạo ra sản phẩm (hữu hình hoặc vô hình) thoả mãn nhu cầu của con người.","Từ khoá cần ghi nhớ: Hoạt động kinh tế; nền kinh tế; sản xuất; phân phối; trao đổi; tiêu dùng; sản xuất xanh; tiêu dùng xanh; bền vững.","Sản xuất là hoạt động sử dụng…: Sản xuất là hoạt động sử dụng các yếu tố sản xuất (vốn, lao động, tài nguyên, công nghệ) để tạo ra sản phẩm;","Phân phối là phân chia các yếu…: Phân phối là phân chia các yếu tố sản xuất cho các ngành, đơn vị sản xuất và phân chia kết quả sản xuất cho tiêu dùng.","Tiêu dùng là hoạt động sử dụng…: Tiêu dùng là hoạt động sử dụng sản phẩm, hàng hoá, dịch vụ để thoả mãn nhu cầu sản xuất và sinh hoạt."],"e":["Hay nhầm: Quảng cáo và thuế không phải hoạt động cơ bản.","Hay nhầm: Vận tải và bảo hiểm là hoạt động cụ thể, không phải hoạt động cơ bản.","Hay nhầm: Tín dụng và ngân sách là công cụ kinh tế.","Hay nhầm: Tiêu dùng là mục đích, không quyết định sản xuất.","Hay nhầm: Phân phối không thay thế sản xuất.","Hay nhầm: Mục đích của sản xuất là tiêu dùng."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 2. Các chủ thể của nền kinh tế","req":["Nhận biết được các chủ thể tham gia nền kinh tế và vai trò của từng chủ thể.","Xác định được vai trò của bản thân và gia đình với tư cách là chủ thể tham gia nền kinh tế.","Nhận biết được trách nhiệm công dân trong việc tham gia các hoạt động kinh tế."],"sum":["Chủ thể của nền kinh tế là những người tham gia vào các hoạt động kinh tế, gồm chủ thể sản xuất, chủ thể tiêu dùng, chủ thể trung gian và Nhà nước.","Khái niệm: Chủ thể của nền kinh tế là những người tham gia vào các hoạt động kinh tế, gồm chủ thể sản xuất, chủ thể tiêu dùng, chủ thể trung gian và Nhà nước.","Từ khoá cần ghi nhớ: Chủ thể kinh tế; chủ thể sản xuất; chủ thể tiêu dùng; chủ thể trung gian;","Chủ thể sản xuất là người sản…: Chủ thể sản xuất là người sản xuất, cung cấp hàng hoá, dịch vụ ra thị trường, gồm nhà đầu tư, sản xuất và kinh doanh.","Chủ thể tiêu dùng là người mua…: Chủ thể tiêu dùng là người mua hàng hoá, dịch vụ để thoả mãn nhu cầu sinh hoạt và sản xuất.","Chủ thể trung gian là cá nhân…: Chủ thể trung gian là cá nhân, tổ chức làm cầu nối giữa sản xuất và tiêu dùng, như nhà phân phối hàng hoá, nhà môi giới chứng khoán, môi giới bất…"],"e":["Hay nhầm: Doanh nghiệp chỉ là một chủ thể.","Hay nhầm: Người tiêu dùng chỉ là một chủ thể.","Hay nhầm: Ngân hàng không phải là bốn chủ thể cơ bản.","Hay nhầm: Chủ thể sản xuất trực tiếp tạo ra hàng hoá.","Hay nhầm: Chủ thể tiêu dùng mua hàng.","Hay nhầm: Nhà nước quản lí nền kinh tế."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 2. Thị trường và cơ chế thị trường","l":[{"t":"Bài 3. Thị trường","req":["Nêu được khái niệm thị trường.","Liệt kê được các loại thị trường và chức năng của thị trường.","Phê phán những hành vi không đúng khi tham gia thị trường."],"sum":["Thị trường ra đời và phát triển cùng kinh tế hàng hoá, là sợi dây liên kết giữa sản xuất và tiêu dùng.","Khái niệm: Thị trường ra đời và phát triển cùng kinh tế hàng hoá, là sợi dây liên kết giữa sản xuất và tiêu dùng.","Từ khoá cần ghi nhớ: Thị trường; nghĩa hẹp; nghĩa rộng; cung – cầu; giá cả; thừa nhận; thông tin;","Các yếu tố cấu thành thị trường…: Các yếu tố cấu thành thị trường gồm người mua – người bán, hàng hoá – tiền tệ, quan hệ mua – bán, giá cả – giá trị và cung – cầu.","Chức năng thừa nhận: Thị trường thừa nhận công dụng xã hội của hàng hoá và lao động đã hao phí, thông qua việc hàng hoá có bán được hay không và bán với giá nào.","Ví dụ: Trước dịch tả lợn châu Phi, giá thịt lợn giảm sâu; khi đàn lợn giảm mạnh, giá thịt lợn tăng vọt."],"e":["Hay nhầm: Chợ chỉ là một dạng thị trường.","Hay nhầm: Sản xuất không phải nơi mua bán.","Hay nhầm: Tài chính chỉ là một lĩnh vực.","Hay nhầm: Nhân sự không quyết định thừa nhận.","Hay nhầm: Địa điểm không quyết định.","Hay nhầm: Quảng cáo chỉ là hoạt động hỗ trợ."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 4. Cơ chế thị trường","req":["Nêu được khái niệm, ưu điểm và nhược điểm của cơ chế thị trường.","Nêu được khái niệm và chức năng của giá cả thị trường.","Tôn trọng tác động khách quan của cơ chế thị trường."],"sum":["Cơ chế thị trường là hệ thống các quan hệ kinh tế tự điều chỉnh theo yêu cầu của các quy luật kinh tế như quy luật cạnh tranh, cung – cầu, giá cả, lợi nhuận.","Khái niệm: Cơ chế thị trường là hệ thống các quan hệ kinh tế tự điều chỉnh theo yêu cầu của các quy luật kinh tế như quy luật cạnh tranh, cung – cầu, giá cả,…","Từ khoá cần ghi nhớ: Cơ chế thị trường; bàn tay vô hình; quy luật cạnh tranh; cung – cầu; giá cả thị trường;","Ưu điểm: Kích thích tính năng động, sáng tạo và thúc đẩy tăng trưởng; phân bổ lại nguồn lực để đáp ứng tốt hơn nhu cầu và lợi ích của các chủ thể; thoả mãn…","Nhược điểm: Tiềm ẩn rủi ro, khủng hoảng và suy thoái; phát sinh cạnh tranh không lành mạnh như làm giả thương hiệu; không tự khắc phục được phân hoá giàu –…","Giá cả hàng hoá là số tiền…: Giá cả hàng hoá là số tiền phải trả để bù đắp chi phí sản xuất và lưu thông hàng hoá."],"e":["Hay nhầm: Cơ chế thị trường không do hành chính chỉ đạo trực tiếp.","Hay nhầm: Doanh nghiệp lớn không áp đặt được cơ chế.","Hay nhầm: Nhà nước không cấm đoán cơ chế này.","Hay nhầm: Giá cố định không phải giá thị trường.","Hay nhầm: Chi phí không đồng nhất với giá thị trường.","Hay nhầm: Kích thích sáng tạo là ưu điểm."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 3. Ngân sách nhà nước và thuế","l":[{"t":"Bài 5. Ngân sách nhà nước","req":["Nêu được khái niệm, đặc điểm và vai trò của ngân sách nhà nước.","Nêu được quy định cơ bản của pháp luật về quyền và nghĩa vụ công dân trong việc thực hiện pháp luật ngân sách.","Ủng hộ những hành vi chấp hành và phê phán những hành vi vi phạm pháp luật về thu, chi ngân sách."],"sum":["Ngân sách nhà nước là toàn bộ các khoản thu, chi của Nhà nước được dự toán và thực hiện trong một khoảng thời gian nhất định do cơ quan nhà nước có thẩm quyền quyết định, để bảo đảm thực hiện các…","Khái niệm: Ngân sách nhà nước là toàn bộ các khoản thu, chi của Nhà nước được dự toán và thực hiện trong một khoảng thời gian nhất định do cơ quan nhà nước có…","Từ khoá cần ghi nhớ: Ngân sách nhà nước; tính pháp lí cao; không hoàn trả trực tiếp; quỹ dự trữ quốc gia;","Đặc điểm: Mang tính pháp lí cao (được tạo lập và sử dụng theo Luật Ngân sách nhà nước năm 2015);","Vai trò: Cung cấp nguồn tài chính duy trì bộ máy nhà nước;","Quyền và nghĩa vụ của công dân: Được sử dụng hàng hoá, dịch vụ công cộng và hỗ trợ từ ngân sách;"],"e":["Hay nhầm: Thuế chỉ là một nguồn thu.","Hay nhầm: Ngân hàng không phải chủ thể ngân sách.","Hay nhầm: Chi tiêu cá nhân không thuộc ngân sách nhà nước.","Hay nhầm: Ngân sách có quy định pháp luật cụ thể.","Hay nhầm: Nhà nước là chủ thể quyết định.","Hay nhầm: Ngân sách gắn liền với Nhà nước."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 6. Thuế","req":["Giải thích được vì sao Nhà nước phải thu thuế.","Gọi được tên một số loại thuế phổ biến.","Nêu được quy định cơ bản của pháp luật về quyền và nghĩa vụ công dân trong việc thực hiện pháp luật thuế."],"sum":["Thuế là một khoản nộp ngân sách nhà nước bắt buộc của tổ chức, hộ gia đình, hộ kinh doanh, cá nhân theo quy định của các luật thuế.","Khái niệm: Thuế là một khoản nộp ngân sách nhà nước bắt buộc của tổ chức, hộ gia đình, hộ kinh doanh, cá nhân theo quy định của các luật thuế.","Từ khoá cần ghi nhớ: Thuế; thuế trực thu; thuế gián thu; thuế thu nhập doanh nghiệp; thuế thu nhập cá nhân; thuế giá trị gia tăng; thuế tiêu thụ đặc biệt; thuế bảo vệ…","Thuế trực thu là thuế điều tiết…: Thuế trực thu là thuế điều tiết trực tiếp vào thu nhập hoặc tài sản của người nộp thuế, gồm thuế thu nhập doanh nghiệp và thuế thu nhập cá nhân.","Các loại thuế khác gồm thuế môn…: Các loại thuế khác gồm thuế môn bài, thuế tài nguyên, thuế sử dụng đất nông nghiệp và phi nông nghiệp.","Quyền và nghĩa vụ của người nộp thuế: Được hỗ trợ, hướng dẫn nộp thuế, được hưởng ưu đãi và hoàn thuế theo quy định; có nghĩa vụ khai thuế chính xác, trung thực, đầy đủ, nộp đúng hạn…"],"e":["Hay nhầm: Tiền gửi ngân hàng không phải thuế.","Hay nhầm: Thuế phục vụ nhiều lĩnh vực.","Hay nhầm: Gián thu đánh qua giá hàng hoá.","Hay nhầm: Xuất khẩu là thuế gián thu.","Hay nhầm: Bảo vệ môi trường là thuế gián thu.","Hay nhầm: Thuế này không đánh vào lương."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 4. Sản xuất kinh doanh và các mô hình sản xuất kinh doanh","l":[{"t":"Bài 7. Sản xuất kinh doanh và các mô hình sản xuất kinh doanh","req":["Nêu được vai trò của sản xuất kinh doanh.","Nhận biết được một số mô hình sản xuất kinh doanh và đặc điểm của nó.","Lựa chọn được mô hình kinh tế thích hợp trong tương lai đối với bản thân."],"sum":["Kinh doanh là việc thực hiện liên tục một, một số hoặc tất cả công đoạn của quá trình từ đầu tư, sản xuất, tiêu thụ sản phẩm hoặc cung ứng dịch vụ trên thị trường nhằm mục đích thu được lợi nhuận.","Khái niệm: Kinh doanh là việc thực hiện liên tục một, một số hoặc tất cả công đoạn của quá trình từ đầu tư, sản xuất, tiêu thụ sản phẩm hoặc cung ứng dịch vụ…","Từ khoá cần ghi nhớ: Sản xuất kinh doanh; lợi nhuận; hộ kinh doanh; hợp tác xã; liên hiệp hợp tác xã; doanh nghiệp; doanh nghiệp tư nhân; công ty hợp danh; công ty TNHH;…","Vai trò của sản xuất kinh doanh: Làm ra sản phẩm, dịch vụ đáp ứng đầy đủ, kịp thời nhu cầu xã hội; tạo việc làm và thu nhập cho người lao động, gia đình;","Hộ kinh doanh: Do cá nhân hoặc một hộ gia đình làm chủ, chỉ đăng ký kinh doanh tại một địa điểm, sử dụng dưới 10 lao động, chịu trách nhiệm bằng toàn bộ tài sản.","Doanh nghiệp là tổ chức có tên…: Doanh nghiệp là tổ chức có tên riêng, có tài sản, có trụ sở giao dịch, được thành lập hợp pháp nhằm mục đích kinh doanh."],"e":["Hay nhầm: Kinh doanh không chỉ phục vụ cá nhân.","Hay nhầm: Kinh doanh gắn với thị trường.","Hay nhầm: Kinh doanh cần thị trường.","Hay nhầm: Hộ kinh doanh chỉ có một địa điểm.","Hay nhầm: Hộ kinh doanh có giới hạn lao động.","Hay nhầm: Hộ kinh doanh cần đăng ký."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 5. Tín dụng và cách sử dụng các dịch vụ tín dụng trong đời sống","l":[{"t":"Bài 8. Tín dụng và vai trò của tín dụng trong đời sống","req":["Nêu được khái niệm, đặc điểm và vai trò của tín dụng.","Nhận biết được những vai trò tích cực của tín dụng đối với đời sống của bản thân, gia đình."],"sum":["Tín dụng là quan hệ vay mượn giữa các chủ thể trong nền kinh tế, trong đó bên cho vay chuyển giao một lượng giá trị cho bên đi vay sử dụng trong một thời hạn nhất định, bên đi vay có nghĩa vụ hoàn…","Khái niệm: Tín dụng là quan hệ vay mượn giữa các chủ thể trong nền kinh tế, trong đó bên cho vay chuyển giao một lượng giá trị cho bên đi vay sử dụng trong một…","Từ khoá cần ghi nhớ: Tín dụng; cho vay;","Đặc điểm: Tín dụng là quan hệ hoàn trả; có sự cam kết về thời hạn và lãi suất; dựa trên sự tin tưởng và khả năng trả nợ của người vay.","Vai trò của tín dụng: Thúc đẩy sản xuất kinh doanh, giúp người có vốn sinh lời và người thiếu vốn có điều kiện phát triển; góp phần thúc đẩy mọi mặt đời sống xã hội phát…"],"e":["Hay nhầm: Tín dụng không phải cho không.","Hay nhầm: Mua bán khác với tín dụng.","Hay nhầm: Đầu tư cổ phần khác với tín dụng.","Hay nhầm: Tín dụng phục vụ nhiều chủ thể.","Hay nhầm: Tín dụng không trực tiếp làm tăng thuế.","Hay nhầm: Tín dụng thúc đẩy sản xuất."],"q":{"n":8,"lv":{"Biết":3,"Hiểu":2,"Vận dụng":3}}},{"t":"Bài 9. Dịch vụ tín dụng","req":["Nhận biết và mô tả được đặc điểm một số dịch vụ tín dụng.","Nhận biết được sự chênh lệch giữa chi phí sử dụng tiền mặt và mua tín dụng.","Biết cách sử dụng có trách nhiệm một số dịch vụ tín dụng."],"sum":["Tín dụng ngân hàng là việc ngân hàng chấp nhận để khách hàng sử dụng một lượng tiền vốn trong một thời gian nhất định trên cơ sở lòng tin khách hàng có khả năng hoàn trả gốc và lãi khi đến hạn.","Khái niệm: Tín dụng ngân hàng là việc ngân hàng chấp nhận để khách hàng sử dụng một lượng tiền vốn trong một thời gian nhất định trên cơ sở lòng tin khách hàng…","Từ khoá cần ghi nhớ: Tín dụng ngân hàng; tín chấp; thế chấp; trả góp; tín dụng thương mại; tín dụng tiêu dùng; thẻ tín dụng; tín dụng nhà nước; trái phiếu chính phủ;…","Cho vay tín chấp dựa hoàn toàn…: Cho vay tín chấp dựa hoàn toàn vào uy tín của người vay, không cần tài sản bảo đảm, số tiền thường nhỏ, thời hạn ngắn, lãi khá cao.","Tín dụng thương mại là quan hệ…: Tín dụng thương mại là quan hệ tín dụng giữa các doanh nghiệp dưới hình thức mua bán chịu, mua bán trả chậm hoặc trả góp hàng hoá.","Tín dụng nhà nước gồm phát hành…: Tín dụng nhà nước gồm phát hành trái phiếu chính phủ (tín phiếu kho bạc, trái phiếu kho bạc, công trái xây dựng Tổ quốc) và cho vay ưu đãi qua ngân…"],"e":["Hay nhầm: Ngân hàng vừa nhận gửi vừa cho vay.","Hay nhầm: Ngân hàng phục vụ nhiều đối tượng.","Hay nhầm: Thế chấp mới cần tài sản.","Hay nhầm: Tín chấp vẫn phải hoàn trả.","Hay nhầm: Tín chấp dành cho nhiều đối tượng.","Hay nhầm: Thủ tục thế chấp phức tạp."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 6. Lập kế hoạch tài chính cá nhân","l":[{"t":"Bài 10. Lập kế hoạch tài chính cá nhân","req":["Nêu được khái niệm kế hoạch tài chính cá nhân, các loại kế hoạch và tầm quan trọng của việc lập kế hoạch.","Nhận biết được các bước lập kế hoạch tài chính cá nhân.","Lập được kế hoạch tài chính của cá nhân."],"sum":["Kế hoạch tài chính cá nhân là bản kế hoạch về thu chi ngân sách nhằm thực hiện các mục tiêu tài chính của cá nhân, gồm các quyết định về thu nhập, chi tiêu, tiết kiệm và đầu tư.","Khái niệm: Kế hoạch tài chính cá nhân là bản kế hoạch về thu chi ngân sách nhằm thực hiện các mục tiêu tài chính của cá nhân, gồm các quyết định về thu nhập,…","Từ khoá cần ghi nhớ: Kế hoạch tài chính cá nhân; mục tiêu tài chính; thu nhập; chi tiêu; tiết kiệm; ngắn hạn; trung hạn; dài hạn; quy tắc 80/13/7; thiết yếu.","Lập kế hoạch tài chính cá nhân…: Lập kế hoạch tài chính cá nhân giúp tính toán, cân nhắc các khoản chi thiết yếu; chủ động nắm tình hình tài chính; duy trì chi tiêu lành mạnh, không…","Bước 1: Xác định mục tiêu tài chính và thời hạn thực hiện, đánh giá năng lực tài chính để đặt mục tiêu ngắn, trung và dài hạn.","Bước 4: Tuân thủ kế hoạch, cắt giảm khoản chi không cần thiết để bù khoản chi đột xuất, và cập nhật kế hoạch khi nhu cầu hoặc thu nhập thay đổi."],"e":["Hay nhầm: Thời gian được xác định rõ.","Hay nhầm: Mua sắm không phải bước đầu.","Hay nhầm: Vay tiền không phải bước đầu.","Hay nhầm: Ghi chép là bước cần thiết.","Hay nhầm: Mục tiêu là kiểm soát chi tiêu.","Hay nhầm: Không được bỏ qua chi thiết yếu."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":4,"Vận dụng":3}}}]},{"t":"Chủ đề 7. Pháp luật nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài 11. Khái niệm, đặc điểm và vai trò của pháp luật","req":["Nêu được khái niệm, đặc điểm, vai trò của pháp luật trong đời sống xã hội.","Tự giác thực hiện các quy định pháp luật.","Phê phán các hành vi vi phạm pháp luật."],"sum":["Pháp luật là hệ thống các quy tắc xử sự có tính bắt buộc chung, do Nhà nước ban hành và được bảo đảm thực hiện bằng quyền lực nhà nước.","Khái niệm: Pháp luật là hệ thống các quy tắc xử sự có tính bắt buộc chung, do Nhà nước ban hành và được bảo đảm thực hiện bằng quyền lực nhà nước.","Từ khoá cần ghi nhớ: Pháp luật; quy tắc xử sự; tính quy phạm phổ biến; tính quyền lực; bắt buộc chung; văn bản quy phạm pháp luật; quản lí xã hội; quyền và lợi ích hợp…","Vai trò của pháp luật: Là phương tiện để Nhà nước quản lí xã hội, điều chỉnh, định hướng các quan hệ xã hội theo khuôn mẫu chung, tạo trật tự xã hội ổn định; là phương…","Văn bản quy phạm pháp luật phải…: Văn bản quy phạm pháp luật phải do cơ quan nhà nước có thẩm quyền ban hành theo trình tự, thủ tục, hình thức luật định; không được trái với Hiến…"],"e":["Hay nhầm: Pháp luật do Nhà nước ban hành.","Hay nhầm: Pháp luật có tính bắt buộc.","Hay nhầm: Pháp luật áp dụng cho mọi người.","Hay nhầm: Tính cá biệt là ngược lại.","Hay nhầm: Pháp luật có tính bắt buộc.","Hay nhầm: Tự giác là yếu tố bổ trợ."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 12. Hệ thống pháp luật và văn bản pháp luật Việt Nam","req":["Nêu được hệ thống pháp luật Việt Nam và văn bản pháp luật Việt Nam.","Kể tên được các văn bản pháp luật trong hệ thống pháp luật Việt Nam."],"sum":["Hệ thống pháp luật Việt Nam là tổng thể các quy phạm pháp luật có mối liên hệ mật thiết và thống nhất, được sắp xếp thành các ngành luật, các chế định pháp luật và được thể hiện trong các văn bản do…","Khái niệm: Hệ thống pháp luật Việt Nam là tổng thể các quy phạm pháp luật có mối liên hệ mật thiết và thống nhất, được sắp xếp thành các ngành luật, các chế…","Từ khoá cần ghi nhớ: Hệ thống pháp luật; ngành luật; chế định pháp luật; quy phạm pháp luật; văn bản quy phạm pháp luật; văn bản luật; văn bản dưới luật; văn bản áp dụng…","Văn bản quy phạm pháp luật là…: Văn bản quy phạm pháp luật là văn bản có chứa quy phạm pháp luật, do cơ quan nhà nước có thẩm quyền ban hình theo trình tự, thủ tục luật định, được…","Văn bản áp dụng pháp luật là…: Văn bản áp dụng pháp luật là văn bản chứa quy tắc xử sự cá biệt, do cơ quan, công chức có thẩm quyền ban hành để áp dụng quy phạm vào quan hệ cụ…","Hiệu lực pháp lí: Hiến pháp có hiệu lực cao nhất; văn bản dưới luật không được trái với văn bản có hiệu lực cao hơn."],"e":["Hay nhầm: Giấy tờ không phải cấu trúc.","Hay nhầm: Hình thức xử phạt không phải cấu trúc.","Hay nhầm: Tổ chức chính trị không thuộc cấu trúc.","Hay nhầm: Văn bản áp dụng là cá biệt.","Hay nhầm: Văn bản hành chính không phải quy phạm.","Hay nhầm: Hương ước không phải văn bản quy phạm."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 13. Thực hiện pháp luật","req":["Nêu được khái niệm thực hiện pháp luật và các hình thức thực hiện pháp luật.","Phân tích, đánh giá được việc thực hiện pháp luật; phê phán các hành vi vi phạm pháp luật.","Tự giác thực hiện các quy định của pháp luật."],"sum":["Thực hiện pháp luật là quá trình hoạt động có mục đích, làm cho những quy định của pháp luật đi vào cuộc sống và trở thành hành vi hợp pháp của cá nhân, tổ chức.","Khái niệm: Thực hiện pháp luật là quá trình hoạt động có mục đích, làm cho những quy định của pháp luật đi vào cuộc sống và trở thành hành vi hợp pháp của cá…","Từ khoá cần ghi nhớ: Thực hiện pháp luật; tuân thủ pháp luật; thi hành pháp luật; sử dụng pháp luật;","Tuân thủ pháp luật: Các chủ thể kiềm chế không thực hiện hành vi mà pháp luật cấm, ví dụ dừng xe đúng vạch khi đèn đỏ.","Sử dụng pháp luật: Các chủ thể thực hiện quyền và tự do pháp lí của mình, ví dụ đăng kí thành lập doanh nghiệp, khiếu nại quyết định hành chính trái pháp luật.","Ý nghĩa: Thực hiện pháp luật bảo đảm trật tự xã hội, giúp mỗi người tự giác tuân theo quy định và phê phán các hành vi vi phạm pháp luật."],"e":["Hay nhầm: Quy định là của Nhà nước.","Hay nhầm: Pháp luật bắt buộc mọi người.","Hay nhầm: Pháp luật áp dụng với mọi người.","Hay nhầm: Thi hành là chủ động làm điều bắt buộc.","Hay nhầm: Sử dụng là thực hiện quyền.","Hay nhầm: Áp dụng do cơ quan có thẩm quyền thực hiện."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 8. Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài 14. Giới thiệu về Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam","req":["Nêu được khái niệm, đặc điểm, vị trí của Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam trong hệ thống pháp luật Việt Nam.","Thực hiện nghĩa vụ tuân theo Hiến pháp bằng những hành vi cụ thể phù hợp với lứa tuổi."],"sum":["Hiến pháp là hệ thống các quy phạm pháp luật có hiệu lực pháp lí cao nhất, quy định những vấn đề cơ bản nhất về chủ quyền quốc gia, chế độ chính trị, chính sách kinh tế, văn hoá, xã hội, tổ chức…","Khái niệm: Hiến pháp là hệ thống các quy phạm pháp luật có hiệu lực pháp lí cao nhất, quy định những vấn đề cơ bản nhất về chủ quyền quốc gia, chế độ chính…","Từ khoá cần ghi nhớ: Hiến pháp;","Hiến pháp là nền tảng để ban…: Hiến pháp là nền tảng để ban hành các luật, pháp lệnh, nghị định và văn bản dưới luật.","Hiến pháp có hiệu lực lâu dài…: Hiến pháp có hiệu lực lâu dài, tương đối ổn định vì quy định những nội dung cơ bản của đất nước nên ít thay đổi."],"e":["Hay nhầm: Hiến pháp có hiệu lực cao nhất.","Hay nhầm: Hiến pháp có hiệu lực toàn quốc.","Hay nhầm: Hiến pháp có hiệu lực lâu dài.","Hay nhầm: Ngày Tuyên ngôn Độc lập, không phải ngày có hiệu lực Hiến pháp.","Hay nhầm: Ngày thông qua Hiến pháp, không phải ngày có hiệu lực.","Hay nhầm: Không đúng số chương và điều."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 15. Nội dung cơ bản của Hiến pháp về chế độ chính trị","req":["Nêu được một số nội dung cơ bản của Hiến pháp về chế độ chính trị nước Cộng hoà xã hội chủ nghĩa Việt Nam.","Có thái độ đồng tình, ủng hộ đối với các hành vi thực hiện đúng quy định của Hiến pháp về chế độ chính trị; phê phán các hành vi vi phạm.","Thực hiện nghĩa vụ tuân theo các quy định của Hiến pháp về chế độ chính trị bằng những hành vi cụ thể, phù hợp với lứa tuổi."],"sum":["Chế độ chính trị là một lĩnh vực quan trọng, được quy định ở chương đầu tiên của Hiến pháp năm 2013, gồm chính thể, chủ quyền, lãnh thổ, bản chất và sự phân chia quyền lực nhà nước, tổ chức và hoạt…","Khái niệm: Chế độ chính trị là một lĩnh vực quan trọng, được quy định ở chương đầu tiên của Hiến pháp năm 2013, gồm chính thể, chủ quyền, lãnh thổ, bản chất và…","Từ khoá cần ghi nhớ: Chế độ chính trị; chính thể cộng hoà xã hội chủ nghĩa; chủ quyền quốc gia; lãnh thổ; nhà nước pháp quyền xã hội chủ nghĩa;","Chính thể: Cộng hoà xã hội chủ nghĩa; quyền lực nhà nước tối cao thuộc về Quốc hội.","Bản chất: Nhà nước pháp quyền xã hội chủ nghĩa của Nhân dân, do Nhân dân, vì Nhân dân; tất cả quyền lực nhà nước thuộc về Nhân dân; quyền lực được phân công,…","Đường lối đối ngoại (Điều 12): Độc lập, tự chủ, hoà bình, hữu nghị, hợp tác và phát triển;"],"e":["Hay nhầm: Không phải cộng hoà tổng thống.","Hay nhầm: Lãnh thổ còn có hải đảo và biển.","Hay nhầm: Lãnh thổ còn có đất liền.","Hay nhầm: Lãnh thổ còn có vùng biển.","Hay nhầm: Không phải của một tầng lớp.","Hay nhầm: Không phải của giai cấp tư sản."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 16. Quyền con người, quyền và nghĩa vụ cơ bản của công dân trong Hiến pháp","req":["Nêu được một số nội dung cơ bản của Hiến pháp về quyền con người, quyền và nghĩa vụ cơ bản của công dân.","Có thái độ đồng tình, ủng hộ đối với các hành vi thực hiện đúng; lên án, phê phán các hành vi vi phạm.","Thực hiện các quy định về quyền con người, quyền và nghĩa vụ cơ bản của công dân bằng những hành vi cụ thể, phù hợp với độ tuổi."],"sum":["Quyền con người, quyền và nghĩa vụ cơ bản của công dân được quy định tại Chương II Hiến pháp năm 2013, gồm 36 điều (từ Điều 14 đến Điều 49).","Khái niệm: Quyền con người, quyền và nghĩa vụ cơ bản của công dân được quy định tại Chương II Hiến pháp năm 2013, gồm 36 điều (từ Điều 14 đến Điều 49).","Từ khoá cần ghi nhớ: Quyền con người; quyền công dân; nghĩa vụ công dân; bình đẳng trước pháp luật; quyền sống; quyền bầu cử; quyền ứng cử; bảo vệ Tổ quốc; nghĩa vụ quân…","Quyền chính trị, dân sự: Quyền có nơi ở hợp pháp, tự do đi lại và cư trú, tự do ngôn luận, báo chí, tiếp cận thông tin, hội họp, lập hội; công dân đủ 18 tuổi có quyền bầu…","Quyền kinh tế, văn hoá, xã hội: Bình đẳng về kinh tế, văn hoá, xã hội;"],"e":["Hay nhầm: Bộ máy nhà nước ở chương khác.","Hay nhầm: Chế độ kinh tế ở chương khác.","Hay nhầm: Đường lối đối ngoại ở chương khác.","Hay nhầm: Học tập là quyền kinh tế, văn hoá.","Hay nhầm: Công dân có quyền chính trị.","Hay nhầm: Bỏ phiếu là quyền bầu cử."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 17. Nội dung cơ bản của Hiến pháp về kinh tế, văn hoá, xã hội, giáo dục, khoa học, công nghệ, môi trường","req":["Nêu được một số nội dung cơ bản của Hiến pháp về kinh tế, văn hoá, xã hội, giáo dục, khoa học, công nghệ, môi trường.","Có thái độ đồng tình, ủng hộ đối với các hành vi thực hiện đúng; lên án, phê phán các hành vi vi phạm quy định của Hiến pháp.","Thực hiện nghĩa vụ tuân theo Hiến pháp về các lĩnh vực này bằng những hành vi cụ thể, phù hợp với lứa tuổi."],"sum":["Hiến pháp năm 2013 có 14 điều tại Chương III quy định về kinh tế, văn hoá, xã hội, giáo dục, khoa học, công nghệ và môi trường.","Khái niệm: Hiến pháp năm 2013 có 14 điều tại Chương III quy định về kinh tế, văn hoá, xã hội, giáo dục, khoa học, công nghệ và môi trường.","Từ khoá cần ghi nhớ: Kinh tế thị trường định hướng xã hội chủ nghĩa; kinh tế nhà nước giữ vai trò chủ đạo; tài sản công thuộc sở hữu toàn dân;","Kinh tế (Điều 50–56): Nhiều thành phần kinh tế (nhà nước, tập thể, tư nhân, có vốn đầu tư nước ngoài) hoạt động bình đẳng và cạnh tranh lành mạnh.","Văn hoá – xã hội (Điều 57–60): Tạo việc làm, bảo vệ quyền lợi người lao động; bảo hiểm y tế toàn dân; an sinh xã hội; xây dựng nền văn hoá Việt Nam tiên tiến, đậm đà bản sắc dân…","Giáo dục (Điều 61): Phát triển giáo dục là quốc sách hàng đầu; giáo dục tiểu học là bắt buộc và Nhà nước không thu học phí;"],"e":["Hay nhầm: Chương I quy định chế độ chính trị.","Hay nhầm: Chương II quy định quyền con người.","Hay nhầm: Chương IV quy định bộ máy nhà nước.","Hay nhầm: Không phải kế hoạch tập trung.","Hay nhầm: Không phải tự cung tự cấp.","Hay nhầm: Không chỉ có kinh tế tư nhân."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]},{"t":"Chủ đề 9. Hệ thống chính trị nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài 18. Nội dung cơ bản của Hiến pháp về bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam","req":["Nêu được một số nội dung cơ bản của Hiến pháp về bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam.","Có thái độ đồng tình, ủng hộ đối với các hành vi thực hiện đúng; không đồng tình, phê phán các hành vi vi phạm quy định của Hiến pháp về bộ máy nhà nước.","Thực hiện nghĩa vụ tuân thủ các quy định của Hiến pháp về bộ máy nhà nước bằng những hành vi cụ thể, phù hợp với lứa tuổi."],"sum":["Bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam gồm Quốc hội, Chủ tịch nước, Chính phủ, Hội đồng nhân dân, Uỷ ban nhân dân, Toà án nhân dân, Viện kiểm sát nhân dân, Hội đồng bầu cử quốc gia và…","Khái niệm: Bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam gồm Quốc hội, Chủ tịch nước, Chính phủ, Hội đồng nhân dân, Uỷ ban nhân dân, Toà án nhân dân, Viện…","Từ khoá cần ghi nhớ: Bộ máy nhà nước;","Quốc hội là cơ quan đại biểu…: Quốc hội là cơ quan đại biểu cao nhất của Nhân dân, cơ quan quyền lực nhà nước cao nhất; thực hiện quyền lập hiến, lập pháp và giám sát tối cao…","Chính phủ là cơ quan hành chính…: Chính phủ là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp, là cơ quan chấp hành của Quốc hội (Điều 94).","Toà án nhân dân là cơ quan…: Toà án nhân dân là cơ quan xét xử, thực hiện quyền tư pháp, bảo vệ công lí và quyền con người (Điều 102)."],"e":["Hay nhầm: Đó là Toà án nhân dân tối cao.","Hay nhầm: Đó là Viện kiểm sát nhân dân tối cao.","Hay nhầm: Quốc hội là cơ quan lập pháp.","Hay nhầm: Toà án là cơ quan xét xử.","Hay nhầm: Kiểm toán nhà nước là cơ quan kiểm toán.","Hay nhầm: Làm luật là chức năng của Quốc hội."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 19. Đặc điểm, cấu trúc và nguyên tắc hoạt động của hệ thống chính trị Việt Nam","req":["Nêu được đặc điểm, cấu trúc, nguyên tắc tổ chức và hoạt động của hệ thống chính trị Việt Nam.","Phê phán và đấu tranh với các hành vi chống phá hệ thống chính trị Việt Nam.","Thực hiện được nghĩa vụ công dân trong việc bảo vệ, xây dựng và hoàn thiện hệ thống chính trị ở Việt Nam bằng những việc làm cụ thể, phù hợp với quy định của pháp luật."],"sum":["Hệ thống chính trị Việt Nam gồm nhiều cơ quan, tổ chức được liên kết chặt chẽ thành một chỉnh thể thống nhất nhằm thực thi quyền làm chủ của Nhân dân.","Khái niệm: Hệ thống chính trị Việt Nam gồm nhiều cơ quan, tổ chức được liên kết chặt chẽ thành một chỉnh thể thống nhất nhằm thực thi quyền làm chủ của Nhân dân.","Từ khoá cần ghi nhớ: Hệ thống chính trị;","Nguyên tắc tổ chức và hoạt động: Đảm bảo sự lãnh đạo của Đảng (khoản 1 Điều 4); quyền lực nhà nước thuộc về Nhân dân, Nhân dân thực hiện quyền lực bằng dân chủ trực tiếp và dân chủ…","Đặc điểm: Tính nhất nguyên chính trị (chỉ có một đảng cầm quyền là Đảng Cộng sản Việt Nam); tính thống nhất về tổ chức, mục tiêu và nguyên tắc hoạt động; tính…"],"e":["Hay nhầm: Hệ thống còn có Đảng và tổ chức xã hội.","Hay nhầm: Quốc hội là một bộ phận của Nhà nước.","Hay nhầm: Doanh nghiệp không thuộc hệ thống chính trị.","Hay nhầm: Đảng cầm quyền, không đối lập.","Hay nhầm: Đảng có vai trò lãnh đạo.","Hay nhầm: Đảng không phải tổ chức doanh nghiệp."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 20. Đặc điểm, nguyên tắc tổ chức và hoạt động của bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam","req":["Nêu được đặc điểm, nguyên tắc tổ chức và hoạt động của bộ máy nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam.","Phê phán, đấu tranh với các hành vi chống phá Nhà nước.","Thực hiện nghĩa vụ của công dân trong bảo vệ, xây dựng và hoàn thiện bộ máy nhà nước bằng những hành vi phù hợp với quy định của pháp luật."],"sum":["Bộ máy nhà nước là hệ thống các cơ quan nhà nước từ trung ương đến địa phương, được tổ chức và hoạt động theo quy định của pháp luật để thực hiện chức năng, nhiệm vụ của Nhà nước.","Khái niệm: Bộ máy nhà nước là hệ thống các cơ quan nhà nước từ trung ương đến địa phương, được tổ chức và hoạt động theo quy định của pháp luật để thực hiện…","Từ khoá cần ghi nhớ: Bộ máy nhà nước; nguyên tắc tổ chức và hoạt động; sự lãnh đạo của Đảng; phân công, phối hợp, kiểm soát; quyền lực thuộc về Nhân dân; tập trung dân…","Đặc điểm của bộ máy nhà nước: Tính thống nhất (các cơ quan có mối quan hệ chặt chẽ từ trung ương đến địa phương); tính nhân dân (bộ máy do Nhân dân bầu và uỷ quyền, phục vụ lợi…","Ví dụ về tập trung dân chủ: Các quyết định quan trọng được thảo luận và biểu quyết theo tập thể, thiểu số phục tùng đa số, cấp dưới phục tùng cấp trên."],"e":["Hay nhầm: Doanh nghiệp không phải bộ máy nhà nước.","Hay nhầm: Tổ chức xã hội không phải bộ máy nhà nước.","Hay nhầm: Hội nghề nghiệp không phải bộ máy nhà nước.","Hay nhầm: Bộ máy không do một cá nhân lập.","Hay nhầm: Bộ máy liên quan trực tiếp đến Nhân dân.","Hay nhầm: Không phải cách phân chia quyền lực."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 21. Quốc hội, Chủ tịch nước, Chính phủ nước Cộng hoà xã hội chủ nghĩa Việt Nam","req":["Nêu được chức năng, cơ cấu tổ chức và hoạt động của Quốc hội, Chính phủ và Chủ tịch nước.","Phê phán, đấu tranh với những hành vi chống phá Nhà nước.","Thực hiện quyền và nghĩa vụ của công dân đối với Quốc hội, Chính phủ, Chủ tịch nước bằng những hành vi phù hợp với quy định của pháp luật."],"sum":["Quốc hội là cơ quan đại biểu cao nhất của Nhân dân, cơ quan quyền lực nhà nước cao nhất, thực hiện quyền lập hiến, lập pháp, quyết định các vấn đề quan trọng của đất nước và giám sát tối cao hoạt…","Khái niệm: Quốc hội là cơ quan đại biểu cao nhất của Nhân dân, cơ quan quyền lực nhà nước cao nhất, thực hiện quyền lập hiến, lập pháp, quyết định các vấn đề…","Từ khoá cần ghi nhớ: Quốc hội; lập hiến; lập pháp; giám sát tối cao;","Quốc hội có các chức năng: Lập hiến, lập pháp (làm và sửa đổi Hiến pháp, luật); quyết định các vấn đề quan trọng như mục tiêu phát triển kinh tế – xã hội, chính sách tài…","Chủ tịch nước là người đứng đầu Nhà nước, do Quốc hội bầu: Chủ tịch nước công bố Hiến pháp, luật, pháp lệnh;","Chính phủ là cơ quan hành chính…: Chính phủ là cơ quan hành chính nhà nước cao nhất, thực hiện quyền hành pháp, là cơ quan chấp hành của Quốc hội, chịu trách nhiệm trước Quốc hội và…"],"e":["Hay nhầm: Chính phủ là cơ quan hành chính.","Hay nhầm: Toà án là cơ quan xét xử.","Hay nhầm: Viện kiểm sát thực hiện công tố.","Hay nhầm: Lập hiến là chức năng của Quốc hội.","Hay nhầm: Giám sát tối cao là của Quốc hội.","Hay nhầm: Giám sát không chỉ ở địa phương."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 22. Toà án nhân dân và Viện kiểm sát nhân dân","req":["Nêu được chức năng, cơ cấu tổ chức và hoạt động của Toà án nhân dân và Viện kiểm sát nhân dân.","Phê phán, đấu tranh đối với các hành vi sai trái liên quan đến Toà án nhân dân, Viện kiểm sát nhân dân.","Thực hiện quyền và nghĩa vụ của công dân đối với Toà án nhân dân, Viện kiểm sát nhân dân bằng những hành vi phù hợp quy định của pháp luật."],"sum":["Toà án nhân dân là cơ quan xét xử của nước Cộng hoà xã hội chủ nghĩa Việt Nam, thực hiện quyền tư pháp.","Khái niệm: Toà án nhân dân là cơ quan xét xử của nước Cộng hoà xã hội chủ nghĩa Việt Nam, thực hiện quyền tư pháp.","Từ khoá cần ghi nhớ: Toà án nhân dân; quyền tư pháp; bảo vệ công lí; xét xử công khai; xét xử tập thể;","Cơ cấu Toà án nhân dân gồm…: Cơ cấu Toà án nhân dân gồm Toà án nhân dân tối cao, Toà án nhân dân cấp cao, Toà án cấp tỉnh, cấp huyện và Toà án quân sự.","Viện kiểm sát nhân dân thực hành…: Viện kiểm sát nhân dân thực hành quyền công tố, tức là thực hiện việc buộc tội của Nhà nước đối với người phạm tội từ khi giải quyết tố giác, tin…","Hệ thống Viện kiểm sát gồm Viện…: Hệ thống Viện kiểm sát gồm Viện kiểm sát nhân dân tối cao, cấp cao, cấp tỉnh, cấp huyện và Viện kiểm sát quân sự."],"e":["Hay nhầm: Làm luật là của Quốc hội.","Hay nhầm: Thực hành quyền công tố là của Viện kiểm sát.","Hay nhầm: Bầu cử là của Hội đồng bầu cử quốc gia.","Hay nhầm: Ban hành luật là của Quốc hội.","Hay nhầm: Ngân sách do Chính phủ và Quốc hội quyết định.","Hay nhầm: Xét xử công khai là nguyên tắc chung."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}},{"t":"Bài 23. Hội đồng nhân dân và Uỷ ban nhân dân","req":["Nêu được chức năng, cơ cấu tổ chức và hoạt động của Hội đồng nhân dân, Uỷ ban nhân dân.","Có thái độ phê phán, không đồng tình với các hành vi tiêu cực đối với Uỷ ban nhân dân và Hội đồng nhân dân.","Thực hiện quyền và nghĩa vụ công dân đối với Hội đồng nhân dân và Uỷ ban nhân dân bằng các hành vi phù hợp với quy định của pháp luật."],"sum":["Hội đồng nhân dân là cơ quan quyền lực nhà nước ở địa phương, đại diện cho ý chí, nguyện vọng và quyền làm chủ của Nhân dân địa phương, do Nhân dân địa phương bầu ra và chịu trách nhiệm trước Nhân…","Khái niệm: Hội đồng nhân dân là cơ quan quyền lực nhà nước ở địa phương, đại diện cho ý chí, nguyện vọng và quyền làm chủ của Nhân dân địa phương, do Nhân dân…","Từ khoá cần ghi nhớ: Hội đồng nhân dân;","Cơ cấu HĐND gồm Thường trực HĐND…: Cơ cấu HĐND gồm Thường trực HĐND (Chủ tịch, Phó Chủ tịch, Uỷ viên) và các Ban của HĐND.","Uỷ ban nhân dân là cơ quan…: Uỷ ban nhân dân là cơ quan hành chính nhà nước ở địa phương, là cơ quan chấp hành của HĐND cùng cấp, do HĐND bầu, chịu trách nhiệm trước HĐND và cơ…","Cơ cấu UBND gồm Chủ tịch, Phó…: Cơ cấu UBND gồm Chủ tịch, Phó Chủ tịch và các Uỷ viên phụ trách cơ quan chuyên môn như Tư pháp, Tài chính – Kế hoạch, Tài nguyên và Môi trường, Lao…"],"e":["Hay nhầm: Chính phủ là hành chính cao nhất.","Hay nhầm: Viện kiểm sát thực hành công tố.","Hay nhầm: HĐND ban hành nghị quyết.","Hay nhầm: Hội đồng bầu cử tổ chức bầu cử.","Hay nhầm: Không do một người quyết định.","Hay nhầm: Không cần toàn bộ thành viên."],"q":{"n":9,"lv":{"Biết":3,"Hiểu":3,"Vận dụng":3}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chủ đề 1. Nền kinh tế và các chủ thể của nền kinh tế","l":[{"t":"Bài tập nâng cao · Chủ đề 1. Nền kinh tế và các chủ thể của nền kinh tế (2 câu)","e":["Hay nhầm: Người tiêu dùng có tác động đến sản xuất.","Hay nhầm: Tiêu dùng có trách nhiệm thúc đẩy sản xuất bền vững.","Hay nhầm: Mọi chủ thể đều có trách nhiệm.","Hay nhầm: Nhà nước có tham gia kinh tế.","Hay nhầm: Nhà nước không chỉ là người tiêu dùng.","Hay nhầm: Nhà nước có chức năng quản lí."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 2. Thị trường và cơ chế thị trường","l":[{"t":"Bài tập nâng cao · Chủ đề 2. Thị trường và cơ chế thị trường (2 câu)","e":["Hay nhầm: Thị trường không chỉ là nơi cất giữ.","Hay nhầm: Thị trường có quan hệ chặt chẽ với tiêu dùng.","Hay nhầm: Thị trường phục vụ các chủ thể kinh tế.","Hay nhầm: Nhà nước có tác động đến giá.","Hay nhầm: Nhà nước sử dụng giá để quản lí."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 3. Ngân sách nhà nước và thuế","l":[{"t":"Bài tập nâng cao · Chủ đề 3. Ngân sách nhà nước và thuế (2 câu)","e":["Hay nhầm: Ngân sách phục vụ cả người dân.","Hay nhầm: Ngân sách có tác dụng xã hội.","Hay nhầm: Ngân sách có nhiều lĩnh vực.","Hay nhầm: Thuế áp dụng cho cả cá nhân.","Hay nhầm: Thuế có liên quan đến dịch vụ công."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 4. Sản xuất kinh doanh và các mô hình sản xuất kinh doanh","l":[{"t":"Bài tập nâng cao · Chủ đề 4. Sản xuất kinh doanh và các mô hình sản xuất kinh doanh (1 câu)","e":["Hay nhầm: Công ty cổ phần có nhiều cổ đông.","Hay nhầm: Cổ đông chịu rủi ro theo vốn góp.","Hay nhầm: Công ty cổ phần cần vốn để hoạt động."],"q":{"n":1,"lv":{"Nâng cao":1}}}]},{"t":"Chủ đề 5. Tín dụng và cách sử dụng các dịch vụ tín dụng trong đời sống","l":[{"t":"Bài tập nâng cao · Chủ đề 5. Tín dụng và cách sử dụng các dịch vụ tín dụng trong đời sống (2 câu)","e":["Hay nhầm: Tín dụng có liên quan đến đời sống.","Hay nhầm: Tín dụng thúc đẩy sản xuất.","Hay nhầm: Tín dụng phục vụ nhiều đối tượng.","Hay nhầm: Khách hàng có nhu cầu vay."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chủ đề 6. Lập kế hoạch tài chính cá nhân","l":[{"t":"Bài tập nâng cao · Chủ đề 6. Lập kế hoạch tài chính cá nhân (1 câu)","e":["Hay nhầm: Quy tắc nhằm kiểm soát chi tiêu.","Hay nhầm: Ghi chép là bước cần thiết.","Hay nhầm: Quy tắc nhằm tránh nợ nần."],"q":{"n":1,"lv":{"Nâng cao":1}}}]},{"t":"Chủ đề 7. Pháp luật nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài tập nâng cao · Chủ đề 7. Pháp luật nước Cộng hoà xã hội chủ nghĩa Việt Nam (3 câu)","e":["Hay nhầm: Pháp luật có vai trò bảo vệ công dân.","Hay nhầm: Pháp luật cũng là công cụ quản lí.","Hay nhầm: Pháp luật có tác dụng rõ rệt.","Hay nhầm: Vẫn phải áp dụng văn bản phù hợp.","Hay nhầm: Số lượng không phải mục đích.","Hay nhầm: Pháp luật có chế tài nhưng tự giác là cơ sở."],"q":{"n":3,"lv":{"Nâng cao":3}}}]},{"t":"Chủ đề 8. Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài tập nâng cao · Chủ đề 8. Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam (4 câu)","e":["Hay nhầm: Hiến pháp có nội dung cụ thể.","Hay nhầm: Hiến pháp áp dụng rộng rãi.","Hay nhầm: Quyền lực được thực hiện trong khuôn khổ pháp luật.","Hay nhầm: Bầu cử là hình thức quan trọng.","Hay nhầm: Nhà nước có quyền lực theo Hiến pháp.","Hay nhầm: Quyền có giá trị thực tế."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chủ đề 9. Hệ thống chính trị nước Cộng hoà xã hội chủ nghĩa Việt Nam","l":[{"t":"Bài tập nâng cao · Chủ đề 9. Hệ thống chính trị nước Cộng hoà xã hội chủ nghĩa Việt Nam (6 câu)","e":["Hay nhầm: Các cơ quan có liên quan đến nhau.","Hay nhầm: Số lượng không phải mục đích.","Hay nhầm: Nguyên tắc nhằm tăng hiệu quả.","Hay nhầm: Hệ thống phục vụ lợi ích nhân dân.","Hay nhầm: Có Mặt trận và các tổ chức quần chúng.","Hay nhầm: Các cơ quan có quan hệ chặt chẽ."],"q":{"n":6,"lv":{"Nâng cao":6}}}]}]}]}]};
